window.kbParts["entries-e76b887096b6265d"] = {"nodes":{"k-2ea1431b5ab948ff":{"review":{"definition":"主要矛盾是复杂事物在一定发展阶段的多种矛盾中居于支配地位、对事物发展起决定作用的矛盾。处理复杂问题时，应优先抓住主要矛盾。","explanation":"C项用树根仍在则树木可再生、水源仍在则水可复流，说明只处理眼前表现，问题还会反复。题中以树根和水源比喻解决问题的关键，用来说明办事要抓住主要矛盾。","references":[{"source":"web-0862221d6fd6fced","location":"卷七《晋语一》，“驪姬既嬖”段史苏语","quote":"伐木不自其本，必復生"}],"evidence":"伐木不自其本，必复生；塞水不自其源，必复流","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-0059fcef164b4b83":{"review":{"definition":"原题引文：“生态兴则文明兴”这一论断","explanation":"第2题为选非题，标准答案是C。习近平以原始文明、农业文明、工业文明和生态文明的演进为背景，说明生态环境对人类文明兴衰的影响。C项所配的认识与实践的具体的历史的统一，着眼于认识是否符合特定历史条件下的实践。题解另把文明兴衰整体归入社会意识，但原讲话讨论的文明演进还涉及生产方式等社会生活的物质方面。","references":[{"source":"web-30e1ce8e6d849cd0","location":"第三章第一节，社会存在和社会意识的辩证关系","quote":"社会存在决定社会意识"},{"source":"web-2e6ec1ddf52d7118","location":"2013年5月24日十八届中央政治局第六次集体学习讲话节录","quote":"生态兴则文明兴，生态衰则文明衰"}],"evidence":"“生态兴则文明兴”这一论断","disposition":"独立词条","basis":"据原题与所列资料编释。"},"sources":[{"id":"626c91234ca39205","label":"历史唯物主义 · 社会存在和社会意识的辩证关系","topic":"马克思主义哲学","category":"非时政","text":"一、社会存在和社会意识的辩证关系\n社会存在决定社会意识；\n社会意识对社会存在具有反作用；\n社会意识具有相对独立性。","source":{"doc":"3ccc56f4000d1642c2d1","first":5,"last":6,"page":5,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-b2837c1766d1a5a7":{"review":{"title":"实践与认识","type":"原理与机制","definition":"在马克思主义认识论中，实践是认识的来源和发展的动力，也是检验认识真理性的唯一标准。认识反过来指导实践，正确认识能够促进实践。","explanation":"认识与实践的具体的历史的统一，要求认识同一定时间、地点和条件下的实践相符合，并随实践的发展而发展。理论指导能否取得预期成果，还取决于实践条件和实施过程。","basis":"据关联原题及所列出处编释。","references":[{"source":"web-2e6ec1ddf52d7118","location":"2013年5月24日十八届中央政治局第六次集体学习讲话节录","quote":"生态兴则文明兴，生态衰则文明衰"},{"source":"web-90788cbf4d8cf58e","location":"1859年序言，阐述社会生产、经济结构与社会意识的段落","quote":"物质生活的生产方式制约着整个社会生活、政治生活和精神生活的过程。"},{"source":"web-c3283fe1a8c34858","location":"第五节，矛盾诸方面的同一性和斗争性","quote":"依据一定的条件，各向着其相反的方面转化"}],"examFocus":{"政治理论必刷100题#2":"逐组核对生态文明论述所说明的哲学关系，辨别论述有没有交代相应原理所需的条件。","政治理论必刷100题#7":"结合全国统一大市场建设，辨明部署、落实过程和实际成效在各项论述中的作用。"}},"aspects":[{"title":"认识与实践的具体的历史的统一","uses":[{"unit":"Q1","role":"解题依据","use":"《政治理论必刷100题》第2题要求选出对应错误的一项，所给答案为C。“生态兴则文明兴”强调生态状况对文明兴衰的影响，单凭这句话无法说明认识如何同特定历史条件下的实践相符合。原解析将文明兴衰整个归入社会意识，并断定生态环境从根本上决定文明兴衰，超出了讲话原意和唯物史观原理可以支持的范围。[2013年5月24日讲话节录](https://cpc.people.com.cn/xuexi/n1/2016/1201/c385476-28916113.html) [马克思《〈政治经济学批判〉序言》](https://www.marxists.org/chinese/marx/06.htm)\n\nA项的原论述说明生态保护能够维护生产力和经济社会发展的潜力。仅凭选项所引的一句，尚无法确定哪一方在何种条件下转化为自身的对立面，因此C是否为唯一错误项仍有疑问。[2018年5月18日讲话节录](https://www.ndrc.gov.cn/xwdt/ztzl/NEW_srxxgcjjpjjsx/jjsxyjqk/qkzk2025/202507/zyjh202507/202512/t20251229_1402687.html) [毛泽东《矛盾论》](https://www.htu.edu.cn/xsd/2021/0415/c14329a194041/page.htm)","evidence":"生态兴则文明兴——认识与实践的具体的历史的统一","qids":["政治理论必刷100题#2"]}]},{"title":"实践检验认识与认识指导实践","uses":[{"unit":"Q2","role":"直接考查","use":"《政治理论必刷100题》第7题以建设全国统一大市场为例，所给答案为C（②④）。科学认识能够指导市场建设，落实部署的过程及其成效可以检验相关经济规律性认识。部署须通过实践才能转化为现实成果，规律性认识以经济实践为基础。","evidence":"④“落实党中央部署，加强协调配合”可以检验我们对经济层面的规律性认识","qids":["政治理论必刷100题#7"]}]}],"sources":[{"id":"f2ae00df7a78f44c","label":"认识论 · 实践和认识的辩证关系","topic":"马克思主义哲学","category":"非时政","text":"三、实践和认识的辩证关系\n实践决定认识：实践是认识的来源；实践是认识发展的动力；实践是认识的目的和归宿；\n实践是检验认识真理性的唯一标准。\n认识反作用于实践：科学的认识对实践起促进作用，错误的认识对实践起阻碍作用。\n(粉笔敲黑板：在考试中，\n“实践是认识的唯一途径”经常被设计为干扰选项，考生需高\n度注意， 这个表述本身就是错误的）","source":{"doc":"3ccc56f4000d1642c2d1","first":5,"last":5,"page":5,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-92430393b020ac6e":{"review":{"definition":"事物内部的各要素以及事物之间，在一定条件下相互依存、相互影响、相互作用。","explanation":"B项用“生命共同体”说明人与自然的联系。自然环境为人类生存和发展提供条件，人类活动也会影响自然环境，因此B项对应联系的普遍性，在选非题中应排除。","references":[],"evidence":"人与自然是生命共同体——物质世界普遍联系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-53c67f5e5cf3e97a":{"review":{"definition":"整体由相互联系的部分组成，整体的状态和功能会影响各部分，各部分及其相互关系也会影响整体。","explanation":"D项把生态系统作为整体，把山、水、林、田、湖、草、沙作为相互联系的组成部分。治理其中一项可能牵动其他部分及整个系统，因此“统筹”要求从整体出发协调各部分，D项对应成立。","references":[],"evidence":"统筹山水林田湖草沙系统治理——整体与部分的辩证关系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-624d3a41b56365b8":{"review":{"definition":"原题引文：发展在特定条件下可以相互转化、相互促进的辩证关系","explanation":"第2题按标准答案选C，题解将A项视为正确对应。原讲话把保护生态环境同保护生产力联系起来，并提出推动绿色发展、循环发展和低碳发展。保护生态可以维护生产所依赖的资源环境条件，这说明保护与发展可以协同。要进一步判定为矛盾双方相互转化，还需说明两者如何在同一矛盾中转为各自的对立面。","references":[{"source":"web-c3283fe1a8c34858","location":"第五节，矛盾诸方面的同一性和斗争性","quote":"依据一定的条件，各向着其相反的方面转化"},{"source":"web-2e6ec1ddf52d7118","location":"2013年5月24日十八届中央政治局第六次集体学习讲话节录","quote":"要正确处理好经济发展同生态环境保护的关系"}],"evidence":"发展在特定条件下可以相互转化、相互促进的辩证关系","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-839eda00ecccb4ba":{"review":{"definition":"量变是事物在原有性质范围内的渐进变化，质变是事物根本性质的变化。量变积累达到一定程度才会引起质变。","explanation":"题干把从严管党治党的措施放在长期坚持的过程中，解析以持续积累的治理成效对应量变，以形成风清气正的政治生态对应预期的质变，因此选C。","references":[],"evidence":"量变是质变的必要准备。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-584226db832d2835":{"review":{"title":"物质与意识","type":"原理与机制","definition":"在辩证唯物主义中，物质决定意识，意识是对客观存在的能动反映。意识能够指导实践，并通过实践反作用于客观世界。","explanation":"物质决定意识要求人们从客观实际出发。意识的能动性体现在认识事物及其联系、指导实践两个方面。符合客观实际和规律的认识能够指导实践、促进事物发展，错误的认识若用于指导实践，则可能阻碍事物发展。","basis":"据关联原题及所列出处编释。","references":[{"source":"web-e9aa10bde33630a1","location":"第1章“信息管理理论综述”，“按信息产生领域划分”","quote":"按信息产生领域可将信息划分为自然信息与社会信息。"}],"examFocus":{"政治理论必刷100题#4":"结合宏观调控的事例，区分意识对物质的反作用与这种作用在一定条件下产生的具体效果。","政治理论必刷100题#8":"结合典故中的心理活动和实际结果，辨别意识对人的作用与意识、物质之间的决定关系。","江苏 2024 A类 行测#9":"区分蜻蜓低飞这一观察现象、由观察形成的经验和经验所反映的哲学原理。","国考 2025 副省级 申论#5":"结合旧粮仓改造等材料，论证原有条件、人的行动和转化结果之间的关系。"}},"aspects":[{"title":"意识反作用的性质与条件","uses":[{"unit":"Q1","role":"直接考查","use":"本题为选非题，答案为B。我国发展中的不平衡、不协调、不可持续问题是制定宏观调控政策的客观依据。科学的调控政策付诸实施可以推动问题解决，B项把特定条件下的促进作用概括为意识的一般作用，因而错误。","evidence":"意识对物质具有促进作用，科学的宏观调控政策可以促进问题的解决和经济社会发展","qids":["政治理论必刷100题#4"]},{"unit":"Q2","role":"直接考查","use":"本题要求选出对应错误的一项，答案为C。“画饼充饥”“望梅止渴”涉及想象或心理暗示，C项将这类影响说成意识对物质的决定作用，颠倒了二者的决定关系。","evidence":"画饼充饥，望梅止渴——意识对物质具有决定作用","qids":["政治理论必刷100题#8"]}]},{"title":"意识对客观联系的认识","uses":[{"unit":"Q4","role":"直接考查","use":"本题所给答案为C。题干问预报经验体现的哲理，C项对应人们从蜻蜓低飞与天气变化的观察中归纳联系的认识活动。D项讨论的是观察所得信息的类别。按信息产生领域划分，蜻蜓低飞所呈现的现象可视为自然信息，人们据此形成的预报经验则是对现象联系的归纳。把观察所得一概归为社会信息的说法缺乏依据，命题采用的分类口径仍待核实。[清华大学出版社《信息管理理论综述》](https://www.tup.tsinghua.edu.cn/upload/books/yz/034039-01.pdf)","evidence":"人类通过意识活动把握客观事物运动变化的规律","qids":["江苏 2024 A类 行测#9"]}]},{"title":"发挥主观能动性的客观条件","uses":[{"unit":"Q3","role":"解题依据","use":"本题要求结合材料和实际，论述人在特定条件下如何促成劣势向优势转化。今州粮仓改造以保存完好的旧仓及粮食文化为基础，通过修缮和引入展演等活动，让失去原有储粮功能的空间获得新的公共文化用途。","evidence":"事物的劣势在特定条件下可以转化为优势，这种转化往往有赖于人的主观能动性","qids":["国考 2025 副省级 申论#5"]}]}],"sources":[{"id":"8c16fff9f9ff2785","label":"唯物论 · 物质和意识的辩证关系和方法论要求","topic":"马克思主义哲学","category":"非时政","text":"三、物质和意识的辩证关系和方法论要求\n辩证关系：物质决定意识；意识对物质具有反作用。\n方法论：一切从实际出发；在尊重客观规律的基础上，充分发挥人的主观能动性。","source":{"doc":"3ccc56f4000d1642c2d1","first":2,"last":2,"page":2,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-693b5a8af5c9c5cc":{"review":{"definition":"在历史唯物主义中，生产力是社会基本矛盾运动中最基本的动力因素，是人类社会发展和进步的最终决定力量。","explanation":"题干以机器人、脑机接口等未来产业说明新质生产力的发展，并用这些产业将改变日常生活说明生产力对社会发展的推动作用，因此选B。A项把决定作用归给人工智能这一具体技术，C项把科学技术当成根本动力，而根本动力在于社会基本矛盾运动。","references":[],"evidence":"生产力是人类社会发展和进步的最终决定力量","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-253af8e175729959":{"review":{"title":"人民群众的历史主体地位","type":"原理与机制","definition":"历史唯物主义认为，人民群众是历史的创造者，是社会变革的决定力量。","explanation":"人民群众通过生产实践创造社会物质财富，通过社会实践创造精神财富，并在社会矛盾发展的过程中推动社会变革。","basis":"据关联原题和解析编释。","references":[],"related":["k-e5c94d5d20f83e29","k-1147d5c7af105768"],"examFocus":{"政治理论必刷100题#6":"从材料中找出影响事业发展和推动社会变化的力量，再判断这属于哪一类哲学原理。","国考 2024 地市级 行测#1":"从依靠谁推进、成效如何衡量和诉求怎样回应三个方面理解现代化方向的人民性。"}},"aspects":[{"title":"人民群众创造历史","uses":[{"unit":"Q1","role":"直接考查","use":"《政治理论必刷100题》第6题把党和国家事业发展的根本力量归于人民，并提出与人民一道攻坚克难，由此判断材料体现人民群众的历史主体地位，选B。","evidence":"人民群众是历史的主体，是社会变革的决定力量","qids":["政治理论必刷100题#6"]}]},{"title":"人民是推进现代化的主体力量","uses":[{"unit":"Q2","role":"直接考查","use":"2024年国考地市级行测第1题、行政执法行测第3题同题。中国共产党与世界政党高层对话会主旨讲话将人民创造历史的原理用于说明推进现代化所依靠的力量，支持第①项。其余三项分别涉及坚持以人民为中心、以人民幸福安康衡量现代化、回应人民多层次需要。两卷均选D，四项均正确。","evidence":"人民是历史的创造者，是推进现代化最坚实的根基、最深厚的力量","qids":["国考 2024 地市级 行测#1","国考 2024 行政执法 行测#3"]}]}],"sources":[{"id":"d684a6870c190aec","label":"历史唯物主义 · 人民群众是历史的主体和创造者","topic":"马克思主义哲学","category":"非时政","text":"四、人民群众是历史的主体和创造者\n人民群众是社会物质财富的创造者；\n人民群众是社会精神财富的创造者；\n人民群众是实现社会变革的决定力量。\n（粉笔敲黑板：记忆人民群众对历史的作用都有哪些方面，做题时注意判断选项正误）","source":{"doc":"3ccc56f4000d1642c2d1","first":7,"last":7,"page":7,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-593504b9413772dc":{"review":{"definition":"运动是物质的存在方式，具有绝对性。静止是运动的特殊状态，只在一定条件下、相对于一定参照物才成立。","explanation":"A项的“坐地”表示人相对于地面位置不变，“日行八万里”表示人同时随地球自转。同一个人既相对地面静止，又随地球运动，体现了绝对运动与相对静止的统一，因此A项在选非题中应排除。","references":[],"evidence":"坐地日行八万里，巡天遥看一千河——绝对运动和相对静止的辩证统一","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-50188c15ba49f33f":{"review":{"definition":"唯物辩证法认为，发展的实质是新事物的产生和旧事物的灭亡。新事物符合客观规律、具有发展前途，经过一定过程会战胜旧事物。","explanation":"D项以“沉舟”“病树”象征旧事物的衰落，以“千帆过”“万木春”象征新事物的兴起。诗句通过新旧交替表现发展的实质，因此D项对应成立。","references":[],"evidence":"沉舟侧畔千帆过，病树前头万木春——新事物必然战胜旧事物","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f9f9ac95a0ab3307":{"review":{"definition":"事物的联系具有客观性，不以人的意志为转移。人可以依据事物固有的联系，通过实践改变事物的状态或条件，建立新的联系。","explanation":"当地以已有的温泉资源为基础，通过开发休闲度假区，把生态资源同旅游、养生和康体产业结合起来，进而增加农民收入。这一过程体现了B项所说的建立新联系。新联系由实践形成，仍具有客观性，因此C项把人为事物的联系说成具有主观性是错误的。","references":[],"evidence":"可以根据事物固有的联系，改变事物的状态，建立新的联系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-95a458e4448b2cb6":{"review":{"definition":"事物普遍处在相互联系之中。具体联系能否形成、以何种方式存在和产生何种结果，取决于特定条件。","explanation":"题中以温泉资源丰富为前提，通过实际开发形成温泉资源与休闲度假产业的联系。A项把联系的普遍性扩大成生态系统中任意两个事物之间都存在必然联系，忽略了具体联系成立的条件。","references":[],"evidence":"联系同样具有条件性，事物间的联系依赖于特定条件","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0d4ccc6ba461f479":{"review":{"definition":"在马克思主义哲学中，意识是人脑的机能，是客观世界的主观映象。人能够能动地反映客观世界，对经验材料进行选择和加工。","explanation":"题中的软件可以按给定主题和要求生成连贯文字，作家则能把自身的生活体验和情感感悟融入文章。①以这种差异说明人类意识的能动性和创造性，生成文字这一表现本身不足以说明软件具有人类意识。","references":[],"evidence":"意识是人脑的机能和属性，是客观世界的主观映象","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"177ce0d26f22cba6","label":"唯物论 · 意识的本质","topic":"马克思主义哲学","category":"非时政","text":"二、意识的本质\n人脑对客观存在的主观映象。\n意识是人脑特有的机能。人脑是产生意识的物质器官。\n（粉笔敲黑板：是人脑而非大脑）","source":{"doc":"3ccc56f4000d1642c2d1","first":2,"last":2,"page":2,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-4ef68bf8fdda12c1":{"review":{"definition":"不同事物的矛盾各有特点，同一事物的矛盾在不同发展阶段也有各自的特点，因此需要具体分析。","explanation":"②把作家融入个人经历与情感的创作，同软件按给定要求生成文本作对照，借此说明两种写作方式各有特点。题中“不可相互替代”着眼于作家以亲身体验赋予作品的情感和内涵，判断范围限于材料所强调的创作特点。","references":[],"evidence":"矛盾的特殊性是指不同事物的矛盾各有其特点","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-693e1fbe51d7f57f":{"review":{"definition":"人们在实践中接触客观事物，获得形成认识的经验材料。个人可以通过学习获得间接经验，这些经验归根到底也来自实践。","explanation":"③把作家亲历生活所获得的素材和感悟视为创作灵感的来源。题中软件处理已有数据并生成文字，与作家通过亲身参与生活取得直接经验的过程不同。","references":[],"evidence":"人类作家通过亲身参与生活实践，获得丰富的素材和深刻","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-da78bd0a5c965382":{"review":{"definition":"客观世界和社会实践不断发展，人类认识也会不断拓展和深化。认识在实践与认识的反复过程中总体向前发展。","explanation":"④以智能写作软件逐渐成熟为例，说明人类在持续研究和应用中深化了对人工智能技术的认识。软件的改进是题中用来体现人类认识发展的成果，认识主体是开展研究和应用的人。","references":[],"evidence":"人类对人工智能技术的研究和应用不断深入","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9c5da84e8594c75c":{"review":{"definition":"畅通经济循环需要生产、分配、交换、消费各环节同时发力，使生产要素在各环节有机衔接、循环流转。","explanation":"《人民日报》文章指出，全国统一大市场建设仍存在堵点，供给和需求实现动态平衡需要各环节协同。第29题B项列全了生产、分配、交换、消费四个环节，并说明了生产要素如何衔接流转，因此B项表述正确，选非题中应排除。","references":[],"evidence":"使各种生产要素的组合在各环节有机衔接、循环流转","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1b74285f27479b26":{"review":{"definition":"构建新发展格局，要实现内部可循环，依托我国超大规模市场优势吸引全球资源要素，增强国内国际两个市场两种资源联动效应。","explanation":"习近平总书记在《以中国式现代化全面推进强国建设、民族复兴伟业》中，将我国超大规模市场作为吸引全球资源要素的依托。第29题D项保留了这一关系，表述正确。题目要求选不正确项，A项把原文“国内循环越顺畅”改成了“国际循环越顺畅”，因此选A。","references":[],"evidence":"增强国内国际两个市场两种资源联动效应","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d56a81095385d822":{"review":{"definition":"按《以制度型开放建设更高水平开放型经济新体制》的表述，规制开放涉及政府对涉外经济活动的监管，着力明晰政府边界、减少不必要的干预，最终指向各国监管规则的协调和一致。","explanation":"监管要求越协调，跨境经营者为适应不同监管要求付出的合规成本通常越低。B项把监管规则协调、合规成本降低和国际经济活动效率提升连在一起，符合文章的论述。","references":[],"evidence":"各国监管规则的协调和一致，降低合规成本","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e1a3e4ea85d37dc0":{"review":{"definition":"标准开放是制度型开放中推动相关标准相通相容的方面。按题中所引文章的论述，环境、劳工和数字领域等标准能为管理提供具体的衡量尺度。","explanation":"具体标准让企业能按明确要求安排生产经营。标准相通相容有助于减少企业为满足不同市场要求而作的重复调整，因此D项所说的降低合规成本和提高国际贸易适配性符合文章的论述。","references":[],"evidence":"标准开放为管理提供了更具体的衡量尺度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-fb82cf7f9abfa2a5":{"review":{"definition":"进一步全面深化改革和高水平对外开放相辅相成。改革越深入，对开放水平的要求越高，开放水平越高，对改革的促进作用越大。","explanation":"文章指出了两个方向的关系。深化改革会提高对开放水平的要求，提高开放水平又会增强开放对改革的促进作用。D项完整保留了这两个方向，属于正确表述。","references":[],"evidence":"改革越深入，对开放的水平要求就越高","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6052906762f60011":{"review":{"definition":"建设教育强国要求一体推进教育发展、科技创新和人才培养，发挥教育在培养人才和提升创新能力方面的支撑作用。","explanation":"习近平在《加快建设教育强国》中提出，以科技发展和国家战略需求为牵引，完善高校学科设置调整机制和人才培养模式，让学科建设和人才培养更好地服务创新需求。第74题A项沿用文章的政策表述，属于正确项。","references":[],"evidence":"强化教育对科技和人才的支撑作用。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7a817d8e01023095":{"review":{"definition":"习近平在2018年深入推动长江经济带发展座谈会上指出，生态环境保护的成败归根到底取决于经济结构和经济发展方式。","explanation":"产业构成和生产方式影响资源消耗与污染排放，因而会从源头影响生态环境保护成效。第76题B项用“归根到底”表明判断指向根本因素，并列出了经济结构和经济发展方式两方面，符合讲话表述。","references":[],"evidence":"生态环境保护的成败归根到底取决于经济结构和经济发展方式","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9d7db306f7ef0a23":{"review":{"definition":"习近平在2023年全国生态环境保护大会上指出，高水平保护是高质量发展的重要支撑。实现生态优先、绿色低碳的高质量发展，需要依靠高水平保护。","explanation":"第76题C项用“只有……才……”表达必要条件，所指的发展具体是“生态优先、绿色低碳的高质量发展”。这里强调的是高水平保护对这类发展的支撑作用，因此C项符合讲话表述。","references":[],"evidence":"生态优先、绿色低碳的高质量发展只有依靠高水平保护才能实现","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2a1eb8773cf05edd":{"review":{"definition":"据题目解析援引的求是网评论，高质量发展能够为实现高水平保护提供不可或缺的财政、科技、市场等支持。","explanation":"材料将这些支持与推进产业生态化、生态产业化联系起来。第76题C项讲的是高水平保护对绿色低碳发展的支撑，D项却把财政、科技、市场支持也写成从保护流向发展，颠倒了评论指出的供给方向，因此是本题要求选出的不正确项。","references":[],"evidence":"为实现高水平保护提供不可或缺的财政、科技、市场等支持","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c11c264a332ce91a":{"review":{"definition":"科学立法是前提，严格执法是关键，公正司法是防线，全民守法是基础。四个环节分别发挥提供法律依据、推动法律实施、维护公平正义和形成社会守法基础的作用。","explanation":"科学立法提供可遵循的法律规范，严格执法推动规范落实，公正司法通过司法救济维护公平正义，全民守法使法律规范成为社会成员的日常行为准则。A项的四组对应都符合题意，D项把严格执法列为“补充”，与执法在法律实施中的作用不符。","references":[],"evidence":"科学立法是前提，严格执法是关键，公正司法是防线，全民守法是基础","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1bb034046e908ee5":{"review":{"definition":"党的政策是国家法律的先导和指引。国家通过法律保障党的政策有效实施。","explanation":"党的政策为立法提供依据，也为执法司法提供重要指导。党的政策成为国家法律后，实施法律就是贯彻党的意志。第94题B项同时写出了政策对法律的指引作用和法律对政策实施的保障作用，在选非题中应排除。","references":[],"evidence":"党的政策是国家法律的先导和指引，要通过法律保障党的政策有效实施","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2be07ba9514f512b":{"review":{"definition":"粮食安全关系基本民生，是国家安全的重要基础。稳定的粮食生产和供给、充足的粮食储备是其具体体现。","explanation":"粮食供给关系居民的基本生活，稳定生产和充足储备有助于维持供给，进而支撑经济运行和社会稳定。这是第99题认定A项所述基础地位正确的理由。","references":[],"evidence":"粮食安全事关国运民生，维系经济发展和社会稳定，是国家安全的重要基础。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3b2159f43155efb0":{"review":{"definition":"生态安全指生态系统保持相对稳定和完整，能够持续支撑人类生存和发展。","explanation":"生产活动依赖生态环境提供的资源和条件。保护生态环境能够维护这些生产条件，这就是第99题C项将生态安全的基础作用与“保护生态环境就是保护生产力”联系起来的理由。","references":[],"evidence":"生态安全是人类生存发展的基本条件，保护生态环境就是保护生产力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-30a39e3f139fa9fc":{"review":{"definition":"国防安全是国家安全体系的重要组成部分，通过国防能力为国家其他安全领域提供保障。","explanation":"第99题解析列举了国防体制、国防政策、国防科技等内容。这些方面共同支撑国防能力，为抵御外部威胁和维护其他安全领域提供保障，因此D项正确。","references":[],"evidence":"国防安全是国家安全体系的重要组成部分，是维护国家其他安全领域的坚实保障","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-972fd9bafc6801f6":{"review":{"definition":"玉陵湖大桥在原址重建时采用边建边拆的方式，借助新桥结构完成旧桥拆除，以减少对周边生态环境的影响。","explanation":"大桥跨越湿地公园和饮用水源保护区。材料指出，传统爆破可能使旧桥构件坠入保护区，并产生粉尘。改建时主桥直接跨湖，湖中未设桥墩，拆除过程中也没有旧桥混凝土落入湖中，这对应《巧》的“生态友好”。","references":[],"evidence":"旧桥建新拱，新拱拆旧桥","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-708a85e0d7e31fbe":{"review":{"definition":"玉陵湖大桥采用“8”字形接线，与两条高速公路无缝衔接，新桥可连接9个村庄。","explanation":"材料指出桥梁与道路对接不良容易发生交通事故，因此设计方与公路施工方反复协调接线方式。参考答案中的“减少交通事故”概括了设计考虑的安全作用，材料给出的通达结果是新桥能连接9个村庄，两者共同说明《巧》的“交通便利”。","references":[],"evidence":"玉陵湖大桥与两条高速公路无缝连接，呈“8”字形环绕","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-3f2cab661887da7b":{"review":{"definition":"交通通达性改善可以便利人员往来、货物运输和信息交流，为沿线乡村的产业经营和消费活动创造条件。","explanation":"大通村村委会林主任把村里增添的人气、商气和财气归因于新桥。材料以村里的果蔬基地和40余家民宿、农家乐展现产业活力，画家又用桥路之间的人流、物流、信息流表现一座桥带出的经济圈，这对应《巧》的“带动发展”。","references":[],"evidence":"促进人、物、信息的流动，让附近村庄焕发出新活力，带出经济圈","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6b64b7cb17cae44e":{"review":{"definition":"开窑村的窑洞修复起初由村委会发起、专家团队负责。影像展让村民重新认识窑洞及旧建材的历史价值，促使他们从旁观转向主动参与。","explanation":"村民起初觉得用旧料费工，修完仍会灰蒙蒙。参观“发现砖石之美”影像展后，他们认识到旧砖瓦承载村庄历史和个人记忆，也更认同原有建筑风格，继而捐献旧建材、为施工出主意并参加义务劳动。这些行动解释了题中从“旁观者”到“参与者”的转变。","references":[],"evidence":"村民们从否定变成了支持，开始踊跃捐献家中的旧建材","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-7b9589140fc022b8":{"review":{"definition":"园区可通过培育研发机构增强企业开发产品和工艺的能力，并通过生产线智能化改造提升生产环节的自动化和数字化水平。","explanation":"N市园区引导企业建立研发机构、推动生产线改造，并培育扶持自主研发项目。材料分别以高端笔记本电脑和实现进口替代的芯片说明研发成果，以生产线智能化水平提升说明改造成效。乐原市可借鉴这两类做法，把扶持研发和引导智能化改造写入增强产业支撑能力的措施。","references":[],"evidence":"打造实验室经济，引导企业建立研发机构","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c69f2f4210a8ff59":{"review":{"definition":"桥梁和道路连成网络，可以改善沿线地区的可达性，便利人员往来、货物流通和信息交流，为当地产业对接外部市场创造条件。","explanation":"材料1中，玉陵湖大桥与两条高速公路无缝连接，新桥可连接9个村庄。大通村将桥路带来的人气与当地果蔬基地、民宿和农家乐等经营项目结合。这个案例可用于论证题干所说的路网如何创造发展机遇，即交通连通便利要素流动，当地产业再将客流和市场机会转化为经营收益。","references":[],"evidence":"人流、物流、信息流在此间快速流动。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0a8afe3e3b49f9a9":{"review":{"definition":"承接产业转移可以带来企业和生产环节。承接地依托自身优势完善产业配套，并推进研发和生产改造，才有条件把承接机会转化为产业升级动力。","explanation":"材料4中，N市由重工业城市切入笔记本电脑代工，随着上下游企业聚集，零部件逐步实现本地配套。园区随后引导企业建立研发机构、改造生产线，推动产业向高端延伸。作文可用这一过程说明，产业跨区域流动带来了结构转型的机会，本地配套和研发创新进一步支撑了升级。","references":[],"evidence":"上下游企业的聚集、各类设施和生产要素的完善","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-aa98a3836ad6ce0a":{"review":{"definition":"紧缩性货币政策是中央银行通过收紧货币和信贷条件来抑制总需求的宏观调控政策，常用于缓解需求过旺带来的通胀压力。","explanation":"货币和信贷条件收紧通常会推高融资成本，压低对利率敏感的投资和消费，从而抑制总需求。A项所说的刺激总需求是扩张性货币政策的作用方向。","references":[],"evidence":"使利率升高，从而达到减少投资，压缩需求的目的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8e936e947b8380a9":{"review":{"definition":"中央银行在公开市场卖出证券时，通过收取买方支付的资金回笼基础货币。这是紧缩性的货币政策操作。","explanation":"就这笔交易而言，买方付款使资金回流央行，金融机构可用资金随之减少。B项将其归为扩张性财政政策，同时弄错了政策类别和操作方向。","references":[],"evidence":"卖出证券，相应地收回一部分基础货币，减少金融机构可用资金的数量","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5c8bd609000a0a9d":{"review":{"definition":"氢燃料电池利用氢气和氧气之间的电化学反应直接将化学能转化为电能，同时生成水并释放热量。","explanation":"以题解所述的质子交换膜燃料电池为例，质子穿过膜，电子经外电路形成电流。A项的“最终排出物”按电池的氢氧反应产物理解，指水。D项把产生电能的反应说成发生在内燃机中，因此是本题要选的错误项。","references":[],"evidence":"氢燃料电池是将氢气和氧气的化学能直接转换成电能的发电装置。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b2438ad057dc45f6":{"review":{"definition":"电解水可利用电能使水分解生成氢气和氧气。生物发酵制氢利用某些微生物在发酵过程中分解有机物并产生氢气。","explanation":"B项列举的是获取氢气的两种途径，两种方法均可制氢。题干要求选出与氢燃料电池车有关的错误说法，因此排除B。","references":[],"evidence":"氢气可以通过生物发酵和电解水等方法制取","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-546f417bcf93720a":{"review":{"definition":"冬至时太阳直射南回归线。广东汕头位于其北方，当地太阳正午的太阳在南侧，竖直杆在水平地面上的影子朝北。","explanation":"当地太阳正午出现立竿无影，需要太阳直射当地。夏至时太阳直射北回归线，位于该线上的地点可以短暂出现无影现象。冬至时直射点在南回归线，汕头正午有朝北的杆影，因此选非题选C。","references":[],"evidence":"冬至时，在广东汕头竖直立杆会出现“立竿无影”的现象","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8992b3ed2bdd53a0":{"review":{"definition":"有虫食痕迹的蘑菇仍可能对人有毒。虫食痕迹无法用于判定蘑菇对人的毒性。","explanation":"昆虫等动物与人对蘑菇有毒成分的反应可以不同。解析指出，有些对人有毒的蘑菇也会被其他动物取食，足以推翻D项所说的判断方法，因此选非题选D。","references":[],"evidence":"很多对人有毒的蘑菇是其他动物的美食","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f9d74821a1a4a2a4":{"review":{"definition":"腹部磁共振采用屏气采集时，短时屏气可减少呼吸引起的腹部运动，从而减轻运动伪影，提高图像清晰度。","explanation":"呼吸会使腹部脏器在采集过程中移动，可能使图像模糊或产生伪影。屏气使脏器在采集期间的位置更稳定，因而更容易看清结构，支持A项所说的“显影更充分”。","references":[],"evidence":"运动出现伪影，影响检查的清晰度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-36e2ca936d22dcf9":{"review":{"definition":"适当施用的食用蜡可在果皮表面形成保护层，减少水分流失，并有助于减少微生物对果实的侵害。","explanation":"蜡层在果实表面提供一道物理屏障，发挥保鲜和保护作用。B项的“可以用于”说的是涂层可起到保护作用，因此B项不属于本题要选的错误说法。","references":[],"evidence":"在水果表皮打上食用蜡，不仅可以保鲜，还能防止微生物对果实进行侵害。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-fdba402eb5525dec":{"review":{"definition":"马铃薯切面接触氧气后容易发生酶促褐变。浸入清水可减少切面与空气的直接接触，延缓切面变色。","explanation":"切开后，马铃薯组织中的多酚氧化酶可在有氧条件下催化相关物质氧化，导致切面颜色加深。C项的“防止氧化”在本题中指浸水能在短时间内抑制切面的氧化褐变。","references":[],"evidence":"马铃薯切开之后浸泡到清水里能防止马铃薯氧化，避免马铃薯变黑","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3dd897b3fd2f5709":{"review":{"definition":"地球主磁场由外地核中导电液态金属的运动产生并维持。流体运动通过电磁感应产生电流，电流形成磁场。","explanation":"D项把磁场归因于液态金属围绕内地核流动。解析指出，需要把外地核的导电流体运动与产生电流联系起来，才能解释地磁场的形成。D项可凭其将镍写成铬的成分错误选出。","references":[],"evidence":"液态铁在地核的流动中产生电流，进而产生磁场。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-408f3e2c26e6ec36":{"review":{"definition":"内地核处的极高压强使富铁物质的熔化温度升高。当地温度虽高，仍低于该压强下物质的熔化温度，因此内地核呈固态。","explanation":"C项把内地核的温度与太阳表面作对照，并用巨大压强解释其固态。判断物态要比较当地温度与当地压强对应的熔化温度，由此可理解解析为何将C项判为正确。","references":[],"evidence":"但由于压强巨大，呈现为固态","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-348c8b7e47969026":{"review":{"definition":"地幔岩石在适当条件下可发生部分熔融，形成岩浆。上地幔是岩浆的重要来源。","explanation":"B项称地幔是岩浆的重要发源地。解析以上地幔中的软流层为例，指出其中的物质接近熔融条件。岩浆的形成取决于岩石达到部分熔融的条件，这解释了B项为何可判为正确。","references":[],"evidence":"温度很高，是岩浆的重要发源地","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f8a592165a5cbb0e":{"review":{"definition":"工作效率恒定时，工作量等于效率乘以时间。多人共同完成同一项工作，各自效率保持不变且完成的工作量可以相加时，合作效率等于各自效率之和。","explanation":"将工作总量设为12，甲每小时完成4个单位，乙和丙合做每小时完成3个单位。设乙每小时完成x个单位，由乙单做比甲乙合做多用4小时，列出 12/x−12/(x＋4)＝4，得正解 x＝2。丙每小时完成3−2＝1个单位，独做需要12小时。","references":[],"evidence":"则丙的效率为3-2=1","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6f2c19cca5f3e9da":{"review":{"definition":"连接三角形两边中点的线段叫作三角形的中位线。中位线平行于第三边，长度等于第三边的一半。","explanation":"在三角形AFC中，AE=EF、AD=DC，所以E、D分别是AF、AC的中点。由此得ED∥FC，且ED∶FC=1∶2。图中EC与FD交于O，利用平行线形成的等角和O处的对顶角，可判定三角形EOD与三角形COF相似，相似比为1∶2。","references":[],"evidence":"AE=EF=FB，AD=DC","disposition":"独立词条","basis":"据原题和解析编释。","title":"三角形中位线","related":[],"examFocus":{"国考 2023 副省级 行测#64":"利用边上的等分点识别三角形中位线，再借助相似三角形的边长与面积关系比较公园和人工湖的面积。","国考 2024 副省级 行测#71":"结合三角形中位线和各三角形、梯形等面积的条件，比较四角地砖的总面积与中央正方形的面积。"}},"readings":[{"origin":"k-6f2c19cca5f3e9da","title":"三角形中位线","qs":["国考 2023 副省级 行测#64"],"definition":"连接三角形两边中点的线段叫作三角形的中位线。中位线平行于第三边，长度等于第三边的一半。","explanation":"在三角形AFC中，AE=EF、AD=DC，所以E、D分别是AF、AC的中点。由此得ED∥FC，且ED∶FC=1∶2。图中EC与FD交于O，利用平行线形成的等角和O处的对顶角，可判定三角形EOD与三角形COF相似，相似比为1∶2。","evidence":"AE=EF=FB，AD=DC","doubt":"","references":[]},{"origin":"k-904e0ab6334ea1bb","title":"三角形中位线","qs":["国考 2024 副省级 行测#71"],"definition":"连接三角形两边中点的线段叫作三角形的中位线。它平行于第三边，长度等于第三边的一半。","explanation":"第71题中，按解析标记，BE、EC分别是相邻两个等腰梯形的一条腰。这两个梯形的腰分别与同一角部三角形的斜边相接，图示构型下 E 为 BC 的中点。过 E 作 EG 垂直于 AC，由于 AB 也垂直于 AC，EG 平行于 AB，因此 EG 是三角形 ABC 的中位线。取 EG＝1，便得到角部三角形的直角边 AB＝2。","evidence":"可知E为BC的中点，那么EG为等腰直角三角形ABC","doubt":"","references":[]}]},"k-abd56c7c05d2a883":{"review":{"definition":"相似三角形的面积比等于对应边长之比的平方，因为对应底边和对应高都按同一比例缩放。","explanation":"图中ED∥FC，三角形EOD与三角形COF相似，对应边ED与CF的长度比为1∶2。因此人工湖三角形EOD与三角形COF的面积比为1∶4。将人工湖面积设为1，三角形COF的面积就是4。","references":[],"evidence":"面积之比等于相似比的平方","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-11296a74810194e8":{"review":{"definition":"当两个三角形相对于各自所取底边的高相等时，它们的面积比等于这两条底边的长度比。","explanation":"三角形EOD与三角形EOF共用顶点E，底边OD、OF同在直线FD上，且OD∶OF=1∶2，所以人工湖面积为1时，三角形EOF的面积为2。再加上三角形COF的面积4，得三角形EFC的面积为6。三角形AEC、EFC、FBC共用顶点C，底边AE、EF、FB等长，因此公园总面积是三角形EFC面积的3倍，即人工湖面积的18倍。","references":[],"evidence":"高相同，底边DO：FO=1：2","disposition":"独立词条","basis":"据原题和解析编释。","title":"等高三角形的面积比","related":[],"examFocus":{"国考 2023 副省级 行测#64":"沿图中同一直线找出等高三角形，按底边之比逐步比较湖区和其余各部分面积。","国考 2023 地市级 行测#65":"用对角线上的线段比比较等高三角形的面积，再结合剩余面积、单人日修剪量和已有工人数判断需增派多少人。"}},"readings":[{"origin":"k-11296a74810194e8","title":"等高三角形的面积比","qs":["国考 2023 副省级 行测#64"],"definition":"当两个三角形相对于各自所取底边的高相等时，它们的面积比等于这两条底边的长度比。","explanation":"三角形EOD与三角形EOF共用顶点E，底边OD、OF同在直线FD上，且OD∶OF=1∶2，所以人工湖面积为1时，三角形EOF的面积为2。再加上三角形COF的面积4，得三角形EFC的面积为6。三角形AEC、EFC、FBC共用顶点C，底边AE、EF、FB等长，因此公园总面积是三角形EFC面积的3倍，即人工湖面积的18倍。","evidence":"高相同，底边DO：FO=1：2","doubt":"","references":[]},{"origin":"k-38c3527be2fcb3ca","title":"等高三角形的面积比","qs":["国考 2023 行政执法 行测#65"],"definition":"三角形面积等于底乘以对应的高的一半。两个三角形对应的高相等时，面积比等于底边长度比。","explanation":"以 AOB 的面积为 1。AOD 与 AOB 共用顶点 A，底边都在 BD 所在直线上，因此等高，面积比为 DO∶BO＝4∶2，所以 AOD 的面积为 2。分别以 B、D 为共同顶点，沿 AC 所在直线比较底边，得 BOC 的面积为 3，COD 的面积为 6。剩余三个区域的总面积是 AOB 的 11 倍，第二天共需 11 名工人，在原有 1 名工人的基础上至少增派 10 名，选 B。","evidence":"两个三角形的高相同，面积之比等于底之比","doubt":"","references":[]},{"origin":"k-e7a6ae39aff5b3a7","title":"等高三角形的面积比","qs":["国考 2023 地市级 行测#65"],"definition":"两个三角形对所选底边的高相等时，面积之比等于这两条底边的长度之比，因为面积公式中的高和二分之一可以约去。","explanation":"第65题相邻两块三角形可用同一条对角线上的两段作底，另一条对角线上的同一顶点到该底边所在直线的距离是共同的高。由AO∶CO＝1∶3、BO∶DO＝1∶2，得AOB、BOC、COD、DOA的面积比为1∶3∶6∶2。剩余面积是AOB的11倍，第二天共需11名同效率工人，在原有1名工人基础上还需增加10名。","evidence":"两个三角形的高相同，面积之比等于底之比","doubt":"","references":[]}]},"k-442e48c9c67c3602":{"review":{"title":"古典概型","type":"原理与机制","definition":"古典概型是基本结果有限且各基本结果等可能的概率模型。某事件的概率等于该事件包含的基本结果数除以全部基本结果数。","explanation":"计算时，分子和分母取自同一个等可能样本空间。逐次独立抽取时，如果每次抽取的各个结果等可能，可以把按先后次序组成的结果作为基本结果。从全部合法方案中等可能地选取一个方案时，每个合法方案就是一个基本结果。","basis":"据关联原题和解析编释。","references":[],"related":["k-a46327dbbd24e070"],"examFocus":{"国考 2023 副省级 行测#65":"按可重复抽取的条件，结合单周抽中甲办公室职工的概率，判断连续两周均抽中甲办公室职工的概率区间。","国考 2023 副省级 行测#71":"用古典概型比较满足甲、乙、丙位置限制的排法中，丁、戊相邻的排法与全部排法。","国考 2023 行政执法 行测#66":"用插板法统计每家至少分到一个名额的方案，再考虑恰有三家名额相同的方案占比。","国考 2024 地市级 行测#67":"把三人各自的完整三周行程合在一起作为一个基本结果，比较每周去处都互不相同的安排与全部安排。","国考 2024 行政执法 行测#64":"把三人各自的完整三周行程合在一起作为一个基本结果，比较每周去处都互不相同的安排与全部安排。","国考 2025 副省级 行测#79":"把每门课连续两天视为一个整体，用插空法考虑三个休息日两两不相邻的安排占比。","国考 2025 地市级 行测#74":"把每门课连续两天视为一个整体，用插空法考虑三个休息日两两不相邻的安排占比。","江苏 2023 B类 行测#63":"按三人各自选定的到岗天数，用组合计数比较三人的安排都包含周三的情形与全部安排。","江苏 2024 A类 行测#59":"把入选节目视为无序组合，用对立事件处理指定科室至少有一个节目入选的概率。"}},"readings":[{"origin":"k-442e48c9c67c3602","title":"古典概型","qs":["国考 2023 副省级 行测#65","国考 2023 行政执法 行测#64","国考 2023 行政执法 行测#66","国考 2025 地市级 行测#74"],"definition":"古典概型是基本结果有限且各基本结果等可能的概率模型。某事件的概率等于该事件包含的基本结果数除以全部基本结果数。","explanation":"计算时，分子和分母取自同一个等可能样本空间。逐次独立抽取时，如果每次抽取的各个结果等可能，可以把按先后次序组成的结果作为基本结果。从全部合法方案中等可能地选取一个方案时，每个合法方案就是一个基本结果。","evidence":"","doubt":"","references":[]},{"origin":"k-19ab1e80d8f787bb","title":"古典概型","qs":["江苏 2024 A类 行测#59"],"definition":"古典概型的基本结果个数有限且各结果等可能。任一事件的概率等于该事件包含的基本结果数除以全部基本结果数。","explanation":"第 59 题从 8 个节目中随机选出 3 个，入选顺序不影响结果，因此每个无序的三节目组合都是一个等可能的基本结果，共有 C(8,3)=56 种。从其余 6 个节目中选 3 个的 C(6,3)=20 种组合都使小张所在科室的节目全部落选。其余 36 种组合满足题意，所求概率为 36/56=9/14，对应 D 项。","evidence":"总情况是从8个节目中随机选出3个","doubt":"","references":[]},{"origin":"k-1d42b53012368790","title":"古典概型","qs":["江苏 2023 B类 行测#63"],"definition":"当试验的基本结果只有有限个且各结果等可能时，某事件的概率等于该事件包含的基本结果数除以全部基本结果数。","explanation":"本题按三人各自等可能、相互独立地选日计算，把三人的一组选日安排视为一个基本结果。小王、小李和小陈分别从5天中选2、3、4天，全部安排有10×10×5＝500种。三人都选周三时，各自还需从其余4天中选1、2、3天，符合条件的安排有4×6×4＝96种。因此所求概率为96/500＝24/125，对应C项。","evidence":"分别从下周的周一到周五中随机选2天、3天、4天去公司工作","doubt":"","references":[]},{"origin":"k-7bf5b52e5f85127d","title":"古典概型","qs":["国考 2025 副省级 行测#79"],"definition":"当基本结果数有限且各结果等可能时，事件的概率等于满足该事件条件的基本结果数除以全部基本结果数。","explanation":"本题在所有安排中等可能地选取一种。将甲、乙课程各自连续的两天视为一个整体，与三个休息日一起排列。从五个位置中选两个放课程，再确定甲、乙的顺序，共有 C(5,2)×2＝20 种安排。三个休息日要两两不相邻，只能在两门课程之前、之间和之后各放一天。甲、乙顺序有两种，因此符合条件的安排有两种，所求概率为 2/20＝1/10，对应 D。","evidence":"如在所有可能的安排中随机选择1种","doubt":"","references":[]},{"origin":"k-de42e096c9194721","title":"古典概型","qs":["国考 2023 副省级 行测#71"],"definition":"古典概型的样本空间包含有限个等可能的基本结果。某事件的概率等于该事件包含的基本结果数除以样本空间的基本结果总数。","explanation":"第71题从符合甲、乙、丙位置限制的讲解次序中等可能地选取一种。丙有2个位置可选，甲、乙在第二至第五位的其余3个位置中有3×2种排法，丁、戊、己有6种排法，共72种。丙在第三位时，甲、乙占第二和第四位或第四和第五位才会留下可供丁、戊相邻的空位。每种占位下甲、乙和丁、戊各可互换，合计8种。丙在第四位时，将次序倒排可得同样的8种。因此所求概率为16/72＝2/9，对应A项。","evidence":"在满足以上条件的次序中随机选择一个","doubt":"","references":[]},{"origin":"k-e365e01c0d0ca4ac","title":"古典概型的概率计算","qs":["国考 2024 地市级 行测#67"],"definition":"当基本结果的个数有限且每个基本结果等可能时，某事件的概率等于包含在该事件中的基本结果数除以全部基本结果数。","explanation":"第 67 题按三人各自独立、等可能地选择调研顺序理解，216 套完整安排等可能。第一周三人分去三个不同地点，有 6 种排法。以第一周甲、乙、丙分别去 A、B、C 为例，第二周三人各自必须换地点且仍要分去三个不同地点，按甲、乙、丙的顺序只有 B、C、A 和 C、A、B 两种。第三周每人去前两周未去的地点，安排随之确定，且三人去处仍各不相同。因此有利结果共 6×2＝12 套，概率为 12÷216＝1/18，对应 C 项。","evidence":"满足要求的情况数为6×2=12种情况","doubt":"","references":[]},{"origin":"k-f30178a6daf5f176","title":"古典概型的概率公式","qs":["国考 2024 行政执法 行测#64"],"definition":"当所有基本结果有限且等可能时，某事件的概率等于该事件包含的基本结果数除以全部基本结果数。","explanation":"第64题按三人各自独立、等可能地选择调研顺序理解。把三个人各自完整的三周顺序合在一起作为一个基本结果，共有216种等可能的安排。其中12种满足三周里每一周三人去处都不同，所求概率为12÷216＝1/18，对应选项C。","evidence":"如每个人随机安排顺序","doubt":"","references":[]}],"aspects":[{"title":"可重复抽取的有序结果","uses":[{"unit":"Q1","role":"解题依据","use":"两周都从同一批9名职工中独立随机抽取1人，允许重复选中。按周次计有9²种结果，其中两周均抽到甲办公室职工的有5²种，概率为25/81，约30.86%，选B。","evidence":"每周从这9名职工中随机抽取1人下沉社区担任志愿者（同一人有可能被连续、重复选中）。","qids":["国考 2023 副省级 行测#65","国考 2023 行政执法 行测#64"]}]},{"title":"正整数分配方案","uses":[{"unit":"Q2","role":"解题依据","use":"将10个相同名额分给4个不同分公司且每家至少得1个，用插板法得到84种方案。三家各得的名额可以是1、2或3个，每种情况都有4种方式确定名额不同的那家，共12种，概率为1/7，选D。","evidence":"要求在每个分公司至少分配1个名额的所有分配方案中，随机选择1个方案实施","qids":["国考 2023 行政执法 行测#66"]}]},{"title":"连续课程与间隔日","uses":[{"unit":"Q3","role":"解题依据","use":"将甲、乙各自连续的2天分别视为一个整体，与3个空闲日一起排列，共20种安排。要使3个空闲日互不相邻，两个课程整体的前、中、后三处各须安排1个空闲日，只剩甲、乙的两种先后顺序，概率为2/20，即1/10，选D。","evidence":"如在所有可能的安排中随机选择1种，不用学习的3天均不相邻的概率为：","qids":["国考 2025 地市级 行测#74"]}]}]},"k-e1fb8b1ec771e490":{"review":{"definition":"总任务量固定、各方单位成本恒定且任务可相互替代时，若各方的合计产能足以按期完工，应优先把任务分配给单位成本较低的一方。每用一份低成本产能替代一份高成本产能，总费用就减少两者的单位成本差。","explanation":"甲每份比乙便宜100元。15小时内让甲做满3000份，剩余7000份在乙的7500份产能内。18小时内让甲做满3600份，剩余6400份也在乙的9000份产能内。多出的3小时让甲多替代乙检验600份，节省600×100＝60000元，所以15小时方案的最低费用高6万元，选D。","references":[],"evidence":"每件费用可节省200-100=100元","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4c66955c8eb9a866":{"review":{"definition":"三角形的面积等于底与对应高的乘积的一半。对应高是底边所对顶点到该底边所在直线的垂直距离。","explanation":"梯形面积是三角形的 2 倍，所以三角形占正方形面积的三分之一。周长比与正方形的边长取值无关，可取边长为 3，此时三角形面积为 3。以 BE 为底，对应的高是与 BE 垂直的正方形边，长为 3，由 BE×3÷2＝3 得 BE＝2。正方形该边的剩余线段长为 1，规划线由勾股定理求得长为 √13，因此三角形与梯形的周长比为（5＋√13）∶（7＋√13），对应 D 项。","references":[],"evidence":"梯形土地的面积正好是三角形土地的2倍","disposition":"独立词条","basis":"据原题和解析编释。","title":"三角形面积公式","related":[],"examFocus":{"国考 2023 副省级 行测#67":"用三角形面积公式和勾股定理确定所需边长，比较两块土地的周长时都要计入共用的规划线。","国考 2023 行政执法 行测#62":"结合两块土地的面积关系，用三角形面积公式和勾股定理确定边长，再比较三角形与梯形的周长。","国考 2025 副省级 行测#78":"利用平行线间同底等高的三角形面积相等来处理阴影区域，注意题目以万平方米为单位。","国考 2025 行政执法 行测#73":"从图中的平行关系寻找可作等积替换的三角形，再用三角形面积公式求阴影面积，注意单位换算。"}},"readings":[{"origin":"k-4c66955c8eb9a866","title":"三角形面积公式","qs":["国考 2023 副省级 行测#67"],"definition":"三角形的面积等于底与对应高的乘积的一半。对应高是底边所对顶点到该底边所在直线的垂直距离。","explanation":"梯形面积是三角形的 2 倍，所以三角形占正方形面积的三分之一。周长比与正方形的边长取值无关，可取边长为 3，此时三角形面积为 3。以 BE 为底，对应的高是与 BE 垂直的正方形边，长为 3，由 BE×3÷2＝3 得 BE＝2。正方形该边的剩余线段长为 1，规划线由勾股定理求得长为 √13，因此三角形与梯形的周长比为（5＋√13）∶（7＋√13），对应 D 项。","evidence":"梯形土地的面积正好是三角形土地的2倍","doubt":"","references":[]},{"origin":"k-79bee3c1cd279a4f","title":"三角形面积公式","qs":["国考 2023 行政执法 行测#62"],"definition":"三角形的面积等于底与对应高的乘积的一半。直角三角形的两条直角边可以分别作为底和高。","explanation":"第62题中，梯形面积是三角形面积的2倍，所以三角形面积占正方形面积的三分之一。设正方形边长为3，则三角形面积为3。取与正方形边长相等的直角边为高，由面积公式得另一条直角边长为2。再用勾股定理求得两块土地共用的规划线长为√13，三角形与梯形的周长之比为（5＋√13）∶（7＋√13），对应D项。","evidence":"梯形土地的面积正好是三角形土地的2倍","doubt":"","references":[]},{"origin":"k-e0ebd1ede334b216","title":"三角形面积公式","qs":["国考 2025 副省级 行测#78"],"definition":"三角形的面积等于底长乘对应高的一半。任取一边为底，对应高是对顶点到底边所在直线的垂直距离，因此同底等高的三角形面积相等。","explanation":"第78题中，连接AE。由于EF与AB平行，三角形AFG与AEG同以AG为底，对应高均为BE，故面积相等。将阴影中的三角形AFG等积替换为三角形AEG，再与三角形ADG拼成三角形ADE。以AD为底，E到直线AD的垂直距离等于矩形的边长AB，所以阴影面积为240×100÷2＝12000平方米，即1.2万平方米，选A。AF的长度无需参与计算。","evidence":"AD、AB长度分别为240米、100米","doubt":"","references":[]},{"origin":"k-fcd27972a3822369","title":"三角形面积公式","qs":["国考 2025 行政执法 行测#73"],"definition":"三角形面积等于底边长度与对应高的乘积的一半。对应高是底边所对顶点到该底边所在直线的垂直距离。","explanation":"连接 AE。由于 EF∥AB，且 EB⊥AB，三角形 AFG 和 AEG 同以 AG 为底，高均为 EB，因此等面积。把阴影中的三角形 AFG 换成三角形 AEG，再与三角形 ADG 拼合。由于 E、G、D 共线，拼成三角形 ADE。以 AD 为底，E 到 AD 所在直线的垂直距离等于 AB，故阴影面积为 240×100÷2＝12000 平方米，即 1.2 万平方米，选 A。","evidence":"均以AG为底、EB为\n高，即两个三角形同底等高","doubt":"","references":[]}]},"k-pyth":{"review":{"title":"勾股定理","type":"原理与机制","definition":"直角三角形两条直角边的平方和等于斜边的平方。若两条直角边长为 a、b，斜边长为 c，则 a²＋b²＝c²。","explanation":"斜边是直角所对的边。已知两条直角边时，取平方和的正平方根可得斜边长。已知斜边和一条直角边时，取两者平方差的正平方根可得另一条直角边长。逆定理也成立，若一个三角形的最长边的平方等于其余两边的平方和，则最长边所对的角为直角。","basis":"据关联原题和解析编释。","references":[],"examFocus":{"国考 2023 副省级 行测#67":"用两块土地的面积关系确定三角形的直角边，再把公共分割线计入各自的周长。","国考 2023 行政执法 行测#62":"用两块土地的面积关系确定三角形的直角边，再把公共分割线计入各自的周长。","国考 2024 副省级 行测#70":"结合道路方位和等边三角形的角度关系，在图中寻找可用勾股定理计算道路长度的直角三角形。","国考 2024 行政执法 行测#66":"把两个联络站到道路上一点的距离之和用轴对称转成线段，再用平行和垂直方向的距离求长度。","国考 2025 副省级 行测#74":"把两船到港的方向和船间距转成直角三角形的边长关系，再用到港时间差求速度。","国考 2025 地市级 行测#73":"把两船到港的方向和船间距转成直角三角形的边长关系，再用到港时间差求速度。","江苏 2023 A类 行测#59":"在纸片折叠图中找出对应的等长线段和直角，借勾股定理确定三角形的底和高。","江苏 2023 B类 行测#62":"在纸片折叠图中找出对应的等长线段和直角，借勾股定理确定三角形的底和高。","江苏 2024 A类 行测#58":"从两种圆台纸杯的轴截面确定母线长度，再结合上下口半径比较侧面积。","江苏 2025 A类 行测#65":"沿底面对角线作竖直截面，辨认截面中决定罩体最小半径的线段。","江苏 2025 B类 行测#67":"沿底面对角线作竖直截面，辨认截面中决定罩体最小半径的线段。","江苏 2025 C类 行测#65":"沿底面对角线作竖直截面，辨认截面中决定罩体最小半径的线段。"}},"aspects":[{"title":"由面积条件求分割线长度","uses":[{"unit":"Q1","role":"解题依据","use":"国考 2023 副省级 行测第67题。设正方形边长为3，梯形面积为三角形面积的2倍，因此三角形面积为3，两条直角边分别长3和2。公共分割线长为√13，周长比为（5＋√13）∶（7＋√13），选D。","evidence":"且梯形土地的面积正好是三角形土地的2倍。","qids":["国考 2023 副省级 行测#67"]},{"unit":"Q2","role":"解题依据","use":"国考 2023 行政执法 行测第62题。面积条件确定直角三角形的两条直角边分别为正方形边长及其2/3。将求得的公共分割线长度分别计入两块土地的周长，得（5＋√13）∶（7＋√13），选D。","evidence":"将其分割为三角形和梯形两块土地，且梯形土地的面积正好是三角形土地的2倍。","qids":["国考 2023 行政执法 行测#62"]}]},{"title":"结合等边三角形求道路长度","uses":[{"unit":"Q3","role":"直接考查","use":"国考 2024 副省级 行测第70题。由AB垂直BC及AB＝100米、AC＝200米，求得BC＝100√3米，且∠ACB＝30°。题图中A和D位于BC两侧，等边三角形给出∠BCD＝60°，所以∠ACD＝90°。以AC和CD为直角边，求得AD＝100√7米，选C。","evidence":"其中AB、BC分别为正南北向和正东西向道路，AB、AC分别长100米和200米。且BCD为正三角形","qids":["国考 2024 副省级 行测#70"]}]},{"title":"用轴对称转化最短折线","uses":[{"unit":"Q4","role":"解题依据","use":"国考 2024 行政执法 行测第66题。将甲站关于道路作对称，工作站取对称点与乙站的连线和道路的交点时，距离和最小。该连线的平行和垂直分量分别为10千米、24千米，由勾股定理求得最小距离和为26千米，选D。","evidence":"甲、乙两个联络站相距10千米。一条道路与甲、乙联络站连线相平行，且与两联络站连线的垂直距离为12千米。","qids":["国考 2024 行政执法 行测#66"]}]},{"title":"由垂直方位和船间距求航程","uses":[{"unit":"Q5","role":"解题依据","use":"国考 2025 副省级 行测第74题。两船从A港正东和正南出发，到港航程分别为n海里和√3乘以n海里，船间距120海里是斜边。据此求得甲船航程60海里，再由速度倍数和3小时时差求得甲船速度为10海里/小时，选A。","evidence":"两船相距120海里，同时出发向A港匀速行驶。","qids":["国考 2025 副省级 行测#74"]},{"unit":"Q6","role":"解题依据","use":"国考 2025 地市级 行测第73题。以两船到港的垂直航程为直角边，以120海里的船间距为斜边，求得甲船航程60海里。乙船的航程与速度分别为甲船的√3倍和2√3倍，所以乙船用时为甲船的一半。由3小时时差得甲船速度为10海里/小时，选A。","evidence":"甲船在A港正东n海里，乙船在A港正南","qids":["国考 2025 地市级 行测#73"]}]},{"title":"结合折叠等长关系求三角形面积","uses":[{"unit":"Q7","role":"解题依据","use":"江苏 2023 A类 行测第59题。由AB＝10厘米、BC＝8厘米求得AC＝6厘米。折叠后C落在AB上的C′点，BC′＝4厘米，且DC′＝DC。在直角三角形BC′D中列边长方程，得BD＝5厘米，△ABD面积为15平方厘米，选A。","evidence":"纸片ABC的形状为直角三角形，AB=10厘米，BC=8厘米。","qids":["江苏 2023 A类 行测#59"]},{"unit":"Q8","role":"解题依据","use":"江苏 2023 B类 行测第62题。先求得原纸片的直角边AC＝6厘米，再设CD＝x厘米。折叠使DC′＝x厘米，且DC′垂直AB，因而有（8−x）²＝4²＋x²。解得x＝3，△ABD面积为15平方厘米，选A。","evidence":"若将纸片沿AD折叠，直角边AC恰好与斜边AB重叠","qids":["江苏 2023 B类 行测#62"]}]},{"title":"由圆台的高和半径差求母线","uses":[{"unit":"Q9","role":"解题依据","use":"江苏 2024 A类 行测第58题、B类 行测第58题。两款圆台纸杯的高分别为80、60毫米，上下口半径差分别为10、7.5毫米。各以高度和半径差为直角边，求得母线长度之比为4∶3，再乘以上下口半径和之比60∶52.5，得侧面积比32∶21，两卷均选B。","evidence":"已知M型纸杯的上、下口直径分别为70毫米、50毫米，高为80毫米；N型纸杯的上、下口直径分别为60毫米、45毫米，高为60毫米。","qids":["江苏 2024 A类 行测#58","江苏 2024 B类 行测#58"]}]},{"title":"由底面中心到上顶点的距离求罩体半径","uses":[{"unit":"Q10","role":"解题依据","use":"江苏 2025 A类 行测第65题。按所附解析采用的摆放方式，器物竖直高度为60厘米，罩口与器物底面共面。用底面半对角线和高度求得最小半径70厘米，只计半球曲面得0.98π平方米，对应所附答案C。","evidence":"测得其长、宽、高分别为60cm、40cm、60cm。","qids":["江苏 2025 A类 行测#65"]},{"unit":"Q11","role":"解题依据","use":"江苏 2025 B类 行测第67题。按所附解析，以60厘米为竖直高度，罩口与器物底面共面。球心取底面中心时，到四个上顶点的最大距离最小。由勾股定理得半径70厘米，只计半球曲面得0.98π平方米，对应所附答案C。","evidence":"则该保护罩（厚度忽略不计）的表面积至少为","qids":["江苏 2025 B类 行测#67"]},{"unit":"Q12","role":"解题依据","use":"江苏 2025 C类 行测第65题。按所附解析，以60厘米为竖直高度，罩口与器物底面共面。最小半径的平方为30²＋20²＋60²＝4900平方厘米，只计半球曲面得0.98π平方米，对应所附答案C。","evidence":"测得其长、宽、高分别为60cm、40cm、60cm。","qids":["江苏 2025 C类 行测#65"]}]}]},"k-dba2f598313639fa":{"review":{"title":"分步乘法计数原理","type":"原理与机制","definition":"若每个结果恰好对应一条完整的选择路径，且无论此前怎样选择，第i步都有nᵢ种选法，那么结果总数为n₁×n₂×…×nₖ，其中k为步骤数。","explanation":"前面的选择可以改变后续的可选对象，只要各步的可选数量保持固定，就可以直接相乘。若后续选法数随前面的选择而变，可以按前面的选择划分互不重叠的情形，在各情形内分别计数，再将结果相加。","basis":"据关联原题及所列出处编释。","references":[{"source":"count","location":"13.5 计数原理"}],"related":["k-e9c35702da80f9b6","k-63c2d85fb3976c99"],"examFocus":{"国考 2023 副省级 行测#68":"用满租条件确定各类租户占用的铺位，再分步计算店铺顺序和租户安排。","江苏 2025 A类 行测#64":"首尾节目单独安排，分开核对相邻节目组的内部顺序与小品、魔术的间隔限制。","国考 2023 行政执法 行测#67":"按三个时段分别选人和排序，核对每次安排会怎样限制后续时段的同校学者。","国考 2024 行政执法 行测#70":"先处理甲地对批次的限制，再按其余两地均须接待的条件分配剩余批次。","江苏 2024 A类 行测#62":"先按不同级别城市的派员要求确定人数，再分步统计不同专员的去向。","江苏 2023 A类 行测#60":"按首日限制和相邻两天的展品关系逐日计数，再检查哪些安排遗漏了某类文物。"}},"aspects":[{"title":"相邻限制下的排序","uses":[{"unit":"Q1","role":"解题依据","use":"铺位全部租出时，恰有一家餐厅占用相邻两铺。将它视为一个租户位置，同类租户间隔要求使餐厅和水果店只能交替排列。占双铺的餐厅、交替顺序、餐厅次序和水果店次序各有2种选择，共16种，对应D项。（国考 2023 副省级 行测第68题）","evidence":"且相同类型的两个租户之间至少要间隔1个铺位","qids":["国考 2023 副省级 行测#68"]},{"unit":"Q6","role":"解题依据","use":"两首歌分占首尾有2种排法，相邻的舞蹈和杂技有2种内部次序，小品和魔术分居相邻节目组两侧有2种排法。三步相乘得8种，对应A项。（江苏 2025 A类 行测第64题、江苏 2025 B类 行测第64题、江苏 2025 C类 行测第64题）","evidence":"2×2×2=8种节目演出的排列顺序。","qids":["江苏 2025 A类 行测#64","江苏 2025 B类 行测#64","江苏 2025 C类 行测#64"]}]},{"title":"分时段选人并排序","uses":[{"unit":"Q2","role":"解题依据","use":"上午从3所高校各选1人并排序，有192种排法。下午必须安排上午未出现高校的1人，否则该校两人都会留到晚上。再从上午出现的3所高校中选出2所，各安排剩下的1人，与下午已选的学者一起排序，有36种排法。晚上剩下的两人来自不同高校，有2种排法。三段相乘得13824种，对应C项。（国考 2023 行政执法 行测第67题）","evidence":"则这8人的报告次序共有192×36×2=13824种不同的安排方式，在C项范围内。","qids":["国考 2023 行政执法 行测#67"]}]},{"title":"按目的地分步分配","uses":[{"unit":"Q3","role":"解题依据","use":"第一、二批不能去甲地。选定后面哪些批次去甲地后，再把其余批次分到乙、丙，且两地各至少一批。甲地接待1、2、3批时，两步分别相乘得42、18、2种，再合计为62种，对应B项。（国考 2024 行政执法 行测第70题）","evidence":"每个地方至少安排一批。受接待能力影响，第一、二批不去甲地","qids":["国考 2024 行政执法 行测#70"]},{"unit":"Q5","role":"解题依据","use":"两个二线城市各派1人，两个一线城市因此分别派2人和1人。确定一线城市的人员安排有60种，每种安排下剩下两人分到两个二线城市均有2种排法，相乘得120种，对应C项。（江苏 2024 A类 行测第62题、江苏 2024 C类 行测第62题）","evidence":"分步用乘法，则不同的派出方法共有60×2=120种。","qids":["江苏 2024 A类 行测#62","江苏 2024 C类 行测#62"]}]},{"title":"逐日计数并扣除漏展","uses":[{"unit":"Q4","role":"解题依据","use":"先暂缓执行五类文物都要展出的要求。首日从青铜器、瓷器、书法中选两类，此后每天从前一天未展出的三类中选两类，每天均有3种选法，共81种。再扣除9种漏展方案，得72种，对应A项。（江苏 2023 A类 行测第60题、江苏 2023 B类 行测第60题）","evidence":"故满足条件的情况数=总情况数-不满足条件的情况数=81-6-3=72种。","qids":["江苏 2023 A类 行测#60","江苏 2023 B类 行测#60"]}]}]},"k-e9c35702da80f9b6":{"review":{"title":"分类加法计数原理","type":"原理与机制","definition":"若每个可能结果恰好属于一个类别，则结果总数等于各类结果数之和。","explanation":"分类须覆盖全部结果，且类别之间互不重叠。还可以在一类内部按另一条件继续细分，先汇总各子类，再汇总各大类。","basis":"据关联原题及所列出处编释。","references":[{"source":"sets","location":"1.4 · 不相交并集的计数"}],"related":["k-dba2f598313639fa","k-63c2d85fb3976c99"],"examFocus":{"国考 2023 副省级 行测#69":"按预算所允许的高价礼包份数分类，逐类核对优先发放条件下可选的领取对象。","国考 2024 行政执法 行测#70":"按三地接待批数的分布分类，在每一类中核对甲地能接待哪些批次。"}},"aspects":[{"title":"按分配数量分类","uses":[{"unit":"Q1","role":"解题依据","use":"1250元预算决定150元礼包只能买0至5份。按高价礼包份数分成六类，优先在3户孤寡老人中确定发放对象，超过3份时再从其余7户中选补足的户数。六类方案数相加得36种，对应C项。（国考 2023 副省级 行测第69题、国考 2023 地市级 行测第63题）","evidence":"分类用加法，共有1+3+3+1+7+21=36种不同的发放方式。","qids":["国考 2023 副省级 行测#69","国考 2023 地市级 行测#63"]},{"unit":"Q2","role":"解题依据","use":"5批分到3地且各地至少接待1批，批数分布只有（1、2、2）和（1、1、3）两类。各类中再按甲地接待的批数细分，并排除第一、二批去甲地的安排。两大类分别有36种和26种，相加得62种，对应B项。（国考 2024 行政执法 行测第70题）","evidence":"综上，题目所求情况数共有36+26=62种。","qids":["国考 2024 行政执法 行测#70"]}]}]},"k-4f89a981c8bc89ff":{"review":{"definition":"两个集合的并集人数等于两个集合的人数之和减去交集人数。在给定总人数中，两项均未参加的人数等于总人数减去并集人数。","explanation":"分别统计两项培训人数时，两项都参加的人被计入两次，所以求并集时要减去一次交集。也可以直接把三个互不重叠的部分相加。本题只参加防病培训的有100人，只参加育种培训的有45人，两项都参加的有121人，故两项均未参加的有287−(100+45+121)=21人，对应A项。","references":[],"evidence":"总数-只参加防病培训的人数-只参加育种培训的人数","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d1d0fba52f66abbc":{"review":{"definition":"两个正整数的比化为互质整数之比后，两个原数分别是对应比值项的同一正整数倍。","explanation":"若正整数X、Y之比为互质的a∶b，则bX=aY。由于a与b互质，b整除Y，因此Y=kb、X=ka。本题中，在参加防病培训的人里，参加育种培训的比未参加育种培训的多21%，所以两项都参加的人数与只参加防病培训的人数之比为121∶100。只参加防病培训的人数至少为100，若达到200，两项都参加的就有242人，仅防病培训的总人数就超过287人。因此只参加防病培训的有100人，两项都参加的有121人。","references":[],"evidence":"参加防病培训的养殖人员中，参加育种培训的人数比未参加的多21%","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c7fdbb32c610a4e7":{"review":{"definition":"液体对物体的浮力等于物体排开液体的重力，即液体密度、排液体积和重力加速度三者的乘积。物体仅受重力和浮力并保持漂浮时，浮力等于物体重力。","explanation":"同一个圆锥体在两种液体中均漂浮，重力相同，浮力也相同。因此排液体积与液体密度成反比，密度为1.5的液体B中的排液体积是密度为1的液体A中的三分之二。A中浸没部分是高为0.9x的相似圆锥，占总体积的72.9%，所以B中浸没部分占48.6%。尖部朝上时，露出的圆锥体积占51.4%，略大于0.8³＝0.512，故露出高度超过0.8x，对应A项。","references":[],"evidence":"两种放置方式所受浮力相等","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0cc9056af06dee6e":{"review":{"definition":"植物蒸腾时，植物体内的水以水蒸气的形式散失。水由液态变为气态，组成保持不变，这一相变属于物理变化。","explanation":"B项用光照和温湿度作为条件，观测叶片蒸腾的强度和效率，研究对象是水分散失。煤块燃烧、面粉发酵和铁制品生锈三项的研究对象均涉及化学反应，其中A项在温度相同的条件下比较表面积不同的煤块的燃烧速率。题目要求选出没有体现化学动力学研究的一项，故选B。","references":[],"evidence":"水从液态变成了气态，没有生成新的物质，所以是物理变化","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3ab6d19b8ffc8157":{"review":{"definition":"在基于模式匹配的语音识别流程中，系统先从语音信号中提取用于区分语音的特征，再把这些特征与参考模式进行比较，依据匹配结果判定输入的语音内容。","explanation":"题干的“语音识别”在这组词中指前两步完成后得到识别结果。B项同样按操作、处理、结果排列，先提交资料，再审核资格，最后报名成功。A项的网上挂号应排在接诊病人之前，与选项给出的次序相反。","references":[],"evidence":"先特征提取，再模式匹配，最后语音识别","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c5bb3b0ac84314fc":{"review":{"definition":"花粉可在易感人群中诱发春季过敏，打喷嚏是可能出现的症状之一。","explanation":"题干按“过敏情况、诱发因素、症状”排列，花粉是诱发因素，喷嚏是过敏表现。B项中乙型脑炎、病毒、发热分别对应这三个位置。A项把咳嗽这一症状放在第二位，把支原体这一病原体放在第三位，次序与题干相反。","references":[],"evidence":"花粉可能会导致春季过敏，前两词为因果关系；打喷嚏是春季过敏的症状","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-97f3250c83ae7e9e":{"review":{"definition":"月均增长量是某一时段内平均每月的净变化量，等于该时段末的存量减去该时段开始前的存量，再除以该时段包含的月数。","explanation":"第116题的统计时段包含2021年1月和2月，共两个月，起点为2020年12月末。用2021年12月末的53579万户减去全年净增的5224万户，得起点存量48355万户。2021年2月末为49222万户，两个月共净增867万户，月均净增433.5万户，约为434万户，选C。选项A的867万户是两个月的累计净增量。","references":[],"evidence":"53579-5224=48355万户","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-13c6bfbdef792622":{"review":{"definition":"在同一统计口径下，如果各类别互不重叠且覆盖全部对象，剩余类别的数量等于总量减去其余各类别的数量之和。","explanation":"第119题按接入方式将固定互联网宽带接入用户分为xDSL用户、光纤用户和其他用户。两期分别用总用户数减去xDSL和光纤用户数，得出2021年末其他用户有2745万户，2021年6月末有2703万户。年末比6月末增加42万户，对应A项“增加了不到200万户”。","references":[],"evidence":"按接入方式划分，固定互联网宽带接入用户可分为xDSL用户、光纤用户和其他用户","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-605159868e5cfda1":{"review":{"definition":"基期量和期末量均为正时，跨 n 年的年均增长率等于期末量与基期量之比开 n 次方后减 1。年份跨度相同，期末量与基期量之比越大，年均增长率越高。","explanation":"对正数开相同次数的方再减 1，会保持原有的大小顺序。第124题以2016年为基期、2021年为期末，四地均跨5年。甘肃、浙江、广东、上海的期末量与基期量之比分别约为3.26、3.11、2.46、1.53，因此年均增速从高到低为①④②③，对应C项。","references":[],"evidence":"当年份差n相同时","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-10c78f5272e0889f":{"review":{"definition":"如果某项规模每年增加的数额相同，那么经过 n 年后的规模等于起始年份的规模加上 n 倍的年增量。","explanation":"以2021年为起点，第三方互联网超算服务商的市场规模为13.8亿元，比第三方独立超算服务商的18.3亿元少4.5亿元。按2021年的同比增量推算，两者每年分别增加4.3亿元和3.3亿元，差距每年缩小1亿元。题干要求首次严格超过，因此经过的整年数 n 须满足 n＞4.5，最早为2026年，对应B项。","references":[],"evidence":"现期量=基期量+n×增长量","disposition":"独立词条","basis":"据原题和解析编释。","title":"固定年增量下的规模推算","related":[],"examFocus":{"国考 2023 副省级 行测#129":"以2021年为起点，按两类超算服务商各自的同比增量推算，比较两者市场规模何时首次出现严格反超。","国考 2023 地市级 行测#119":"根据两类超算服务商2021年的市场规模和各自的同比增量，按固定年增量推算并比较两者的规模。"}},"readings":[{"origin":"k-10c78f5272e0889f","title":"固定年增量下的规模推算","qs":["国考 2023 副省级 行测#129"],"definition":"如果某项规模每年增加的数额相同，那么经过 n 年后的规模等于起始年份的规模加上 n 倍的年增量。","explanation":"以2021年为起点，第三方互联网超算服务商的市场规模为13.8亿元，比第三方独立超算服务商的18.3亿元少4.5亿元。按2021年的同比增量推算，两者每年分别增加4.3亿元和3.3亿元，差距每年缩小1亿元。题干要求首次严格超过，因此经过的整年数 n 须满足 n＞4.5，最早为2026年，对应B项。","evidence":"现期量=基期量+n×增长量","doubt":"","references":[]},{"origin":"k-6ba1fcd95cf4cf83","title":"固定年增量下的规模推算","qs":["国考 2023 地市级 行测#119"],"definition":"当某项规模每年增加的数额相同时，基准年之后第 n 年的规模等于基准年规模加上 n 倍的年增量，其中 n 为自基准年起经过的整年数。","explanation":"本题以2021年为基准。按解析所列数据，第三方互联网超算服务商和第三方独立超算服务商的市场规模分别为13.8亿元和18.3亿元，2021年同比增量分别为4.3亿元和3.3亿元。若各自保持该年增量，前者每年缩小1亿元差距。首次超过要求累计缩小的差距严格大于初始差距4.5亿元，因此最少经过5年，即2026年，选B。","evidence":"现期量=基期量+n×增长量","doubt":"","references":[]}]},"k-01e62c91bad01ee7":{"review":{"definition":"间隔增长率是某期数值相对于隔一期的基期数值的增长率。若连续两期的增长率分别为 r₁ 和 r₂，则间隔增长率为 (1＋r₁)(1＋r₂)－1。","explanation":"后一段的增长以前一段变化后的数值为基数，因此两段的增长倍数相乘。第131题中，2021年全国服装出口额是2019年的1.16倍，也是2020年的1.24倍，所以2020年比2019年的增长率为 1.16÷1.24－1≈－6.45%，即下降了不到10%，选D。","references":[],"evidence":"服装出口1702.8亿美元，同比增长24.0%，较2019年增长16.0%。","disposition":"独立词条","basis":"据原题和解析编释。","title":"间隔增长率","related":[],"examFocus":{"国考 2023 副省级 行测#131":"把2021年服装出口额相对2019年和2020年的增速换成出口额之比，再反推2020年相对2019年的增速。","国考 2023 行政执法 行测#126":"把2021年相对2019年的服装出口额之比写成两个相邻年份之比的乘积，再用已知增速反推缺少的那一项。"}},"readings":[{"origin":"k-01e62c91bad01ee7","title":"间隔增长率","qs":["国考 2023 副省级 行测#131"],"definition":"间隔增长率是某期数值相对于隔一期的基期数值的增长率。若连续两期的增长率分别为 r₁ 和 r₂，则间隔增长率为 (1＋r₁)(1＋r₂)－1。","explanation":"后一段的增长以前一段变化后的数值为基数，因此两段的增长倍数相乘。第131题中，2021年全国服装出口额是2019年的1.16倍，也是2020年的1.24倍，所以2020年比2019年的增长率为 1.16÷1.24－1≈－6.45%，即下降了不到10%，选D。","evidence":"服装出口1702.8亿美元，同比增长24.0%，较2019年增长16.0%。","doubt":"","references":[]},{"origin":"k-74991a7be3bc84ae","title":"间隔增长率","qs":["国考 2023 行政执法 行测#126"],"definition":"间隔增长率是跨过中间一期的两个时期之间的相对变化率。对同一指标，跨两期的增长因子（1＋间隔增长率）等于两个相邻期增长因子的乘积。","explanation":"把末期值与起期值的比值拆成「末期值÷中间期值」和「中间期值÷起期值」的乘积，中间期值就会约去。第126题中，2021年全国服装出口额较2019年增长16.0%，较2020年增长24.0%，因此2020年较2019年的增长率为 1.16÷1.24－1≈−6.45%，即下降了不到10%，选D。","evidence":"服装出口1702.8亿美元，同比增长24.0%，较2019年增长16.0%。","doubt":"","references":[]}]},"k-390bcee7fbd6727d":{"review":{"definition":"GEP（生态产品总值）是生态系统提供的生态产品价值总和。核算报告可帮助地方识别有优势的生态资源，据此选择适合当地条件的开发项目。","explanation":"碧澜乡根据溪流水质好、水流形态丰富的特点开发水域救援培训项目。云瀑乡从报告中发现峡谷、瀑布和云海在全市具有竞争力，随后与企业合作开发探险和梯田观光项目。两例都体现了A市用核算结果判断资源优势并选择开发方向的做法。","references":[],"evidence":"GEP核算报告让我们知道生态资源究竟好在哪儿","disposition":"独立词条","basis":"据原题和解析编释。","title":"GEP核算指导生态资源开发","related":[],"examFocus":{"国考 2023 地市级 申论#1":"从资料1中碧澜乡和云瀑乡的案例里，提取与GEP核算和生态资源开发有关的做法。","国考 2023 行政执法 申论#1":"从资料1的项目案例中，找出体现A市如何运用GEP核算结果的具体做法。"}},"readings":[{"origin":"k-390bcee7fbd6727d","title":"GEP核算指导生态资源开发","qs":["国考 2023 地市级 申论#1"],"definition":"GEP（生态产品总值）是生态系统提供的生态产品价值总和。核算报告可帮助地方识别有优势的生态资源，据此选择适合当地条件的开发项目。","explanation":"碧澜乡根据溪流水质好、水流形态丰富的特点开发水域救援培训项目。云瀑乡从报告中发现峡谷、瀑布和云海在全市具有竞争力，随后与企业合作开发探险和梯田观光项目。两例都体现了A市用核算结果判断资源优势并选择开发方向的做法。","evidence":"GEP核算报告让我们知道生态资源究竟好在哪儿","doubt":"","references":[]},{"origin":"k-b6566008b37c2707","title":"GEP核算指导生态资源开发","qs":["国考 2023 行政执法 申论#1"],"definition":"GEP核算通过评估生态产品价值，帮助地方识别生态资源的具体优势，据此选择与资源条件相匹配的开发项目。","explanation":"碧澜乡的溪流水质好、水流形态丰富，适合开展水域救援培训。云瀑乡从核算报告中发现峡谷、瀑布、云海在全市具有竞争力，进而合作开发探险和梯田观光项目。这两例说明核算结果怎样指导项目选择，对应参考答案的生态资源开发要点。","evidence":"GEP核算报告让我们知道生态资源究竟好在哪儿","doubt":"","references":[]}]},"k-233289bbb72d1a61":{"review":{"definition":"当企业的生产条件或产品质量对周边环境有较高要求时，优质生态环境可以成为企业选址的优势。地方可根据GEP核算报告识别生态优势和短板，为产业发展提供依据。","explanation":"材料中的黄教授提出，各地可根据报告强优势、补短板。A市的医药企业则从选址需求说明了这种优势如何发挥作用，生产高品质医药容器对环境要求严格，良好的生态环境是企业选择A市的根本原因。这对应本题的“吸引产业转入”。","references":[],"evidence":"生产高品质的医药容器对环境有着严格的要求","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ff79548d5d458b85":{"review":{"definition":"在A市的案例中，“两山银行”向乡镇购入湿地碳汇，再将碳汇量出售给有需求的单位。交易收益可用于湿地保护和修复。","explanation":"A市“两山银行”先购入明渚乡湿地碳汇，再向市农商银行等9家单位出售。这是A市将GEP核算应用到碳汇市场的首次尝试。材料还提出，可用收益开展湿地绿化扩面和修复，进一步提升湿地的碳汇能力。","references":[],"evidence":"这也是A市将GEP核算应用到碳汇市场的首次尝试","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-3c1054a93b0f98a4":{"review":{"definition":"取得企业授权后，银行可利用可获取的经营相关数据评估信贷申请，从而减少人工提交材料和线下调查环节，缩短审批时间。","explanation":"F银行的“小企快贷”通过水电费、税款等开支数据辅助判断经营情况，缓解部分小微企业难以提供流水的问题。服务餐饮企业的“美食贷”则经企业授权，通过行业协会获取相关数据。短评可用这两个事例说明银行怎样回应小微企业“短、频、急”的资金需求。","references":[],"evidence":"只需授权F银行查阅相应数据即可。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9e00b5c22927fe65":{"review":{"definition":"居民把原本可能用于当期消费的资金存入银行，会将一部分购买力推迟到以后使用。当商品供应相对紧张时，这有助于缓解即期需求压力。","explanation":"第7题B项的措辞是“有助于”。储蓄将一部分购买力从即期商品市场移开，有助于缓解商品供应与当期购买力之间的压力，B项因此成立。","references":[],"evidence":"实现货币购买力和商品供应量的平衡，调节货币流通","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1e6fe4c72f2fb9a5":{"review":{"definition":"蚊虫叮咬时，进入皮肤的唾液成分可触发局部免疫反应，引起红肿和瘙痒。","explanation":"B项所述的叮咬后皮肤发痒是常见的局部过敏表现。蚊虫唾液成分诱发的反应主要出现在叮咬部位，可同时表现为红肿。","references":[],"evidence":"蚊虫叮咬引起的过敏症状有皮肤出现红肿、瘙痒","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-abfdb2511698cad1":{"review":{"definition":"当地太阳位于头顶正上方时，竖直立杆在水平地面上没有侧向投影。当地太阳正午的杆影方向与太阳所在方向相反。","explanation":"冬至时太阳直射南回归线。汕头位于直射点以北，当地太阳正午的太阳在南侧，杆影朝北，因此声称此时“立竿无影”的C项错误。北回归线上出现这一现象的时刻是夏至当地太阳正午。","references":[],"evidence":"冬至时，太阳直射南回归线","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-232eaaa60c5f1a41":{"review":{"definition":"硅化木是埋藏的木材经二氧化硅矿化形成的木化石，通常保留木材原有的组织结构和纹理。","explanation":"木材被埋藏后，地下水携带的二氧化硅可逐渐置换原有木质成分，同时保存木纹等结构。这一过程支持B项关于硅化木由树木埋入地下后形成的说法。","references":[],"evidence":"硅化木是树木埋入地下后形成的化石","disposition":"独立词条","basis":"据原题和解析编释。","title":"硅化木","related":[],"examFocus":{"国考 2023 地市级 行测#18":"辨析硅化木形成所需的条件及形成过程中发生的物质变化。"}},"readings":[{"origin":"k-232eaaa60c5f1a41","title":"硅化木","qs":["国考 2023 地市级 行测#18"],"definition":"硅化木是埋藏的木材经二氧化硅矿化形成的木化石，通常保留木材原有的组织结构和纹理。","explanation":"木材被埋藏后，地下水携带的二氧化硅可逐渐置换原有木质成分，同时保存木纹等结构。这一过程支持B项关于硅化木由树木埋入地下后形成的说法。","evidence":"硅化木是树木埋入地下后形成的化石","doubt":"","references":[]},{"origin":"k-9b16c16dce4db364","title":"硅化木","qs":["国考 2023 行政执法 行测#17"],"definition":"硅化木是埋藏的木材经二氧化硅充填或交代形成的木化石，往往保留木材的原有结构和纹理。","explanation":"树木埋藏后，地下水携带的二氧化硅可以在木材组织中沉淀，填充孔隙或逐步替代原有成分，使木纹得以保存。这说明了B项所述树木埋入地下后形成木化石的过程。","evidence":"地下水中的二氧化硅替换","doubt":"","references":[]}]},"k-3941eb78632b15f1":{"review":{"definition":"蘑菇中的毒素对不同动物的影响可能不同。虫子能够取食某种蘑菇，无法据此判断这种蘑菇对人体的毒性。","explanation":"解析举出对人有毒的白毒伞也有虫啮记录，说明对人有毒的蘑菇同样可能留下取食痕迹。D项把虫子取食痕迹当作辨毒依据，因此是本题要求选出的错误说法。","references":[],"evidence":"白毒伞也有被虫啮食的记录","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-216fb68de7a89297":{"review":{"definition":"同一销售方案中，每件商品的实际售价和单位成本相同时，总利润等于（实际售价－单位成本）×销量。","explanation":"第61题设每件定价为x元、成本为y元。原价卖1件、打八折卖2件、每件降价120元后卖3件的总利润相同，因此有x－y＝2(0.8x－y)＝3(x－120－y)。由原价与八折方案相等得y＝0.6x，由原价与降价方案相等得x－y＝180，故定价为450元。","references":[],"evidence":"x-y=（80%x-y）×2","disposition":"独立词条","basis":"据原题和解析编释。","title":"销售总利润","related":[],"examFocus":{"国考 2023 副省级 行测#61":"用单件利润乘以销量，比较原价、打八折和每件降价三种卖法的总利润。"}},"readings":[{"origin":"k-216fb68de7a89297","title":"销售总利润","qs":["国考 2023 地市级 行测#61"],"definition":"同一销售方案中，每件商品的实际售价和单位成本相同时，总利润等于（实际售价－单位成本）×销量。","explanation":"第61题设每件定价为x元、成本为y元。原价卖1件、打八折卖2件、每件降价120元后卖3件的总利润相同，因此有x－y＝2(0.8x－y)＝3(x－120－y)。由原价与八折方案相等得y＝0.6x，由原价与降价方案相等得x－y＝180，故定价为450元。","evidence":"x-y=（80%x-y）×2","doubt":"","references":[]},{"origin":"k-d5e89c66ba9c01d0","title":"销售总利润","qs":["国考 2023 副省级 行测#61"],"definition":"同一批商品按统一单价销售、每件成本相同，且其他费用已计入成本或忽略时，销售总利润等于单位售价减去单位成本，再乘以销量。","explanation":"设每件定价为x元、成本为y元。题中按原价卖1件、打八折卖2件、每件降价120元卖3件的总利润相等，因此有 x−y＝2(0.8x−y)＝3(x−120−y)。用前两项和第一、第三项分别列方程，解得定价为450元/件。","evidence":"x-y=（80%x-y）×2","doubt":"","references":[]}]},"k-46946a2a390ef27d":{"review":{"title":"两集合容斥原理","type":"原理与机制","definition":"两个有限集合的并集元素数等于两个集合各自的元素数之和减去交集的元素数，即 |A∪B|＝|A|＋|B|－|A∩B|。","explanation":"同时属于两个集合的元素在相加时被计入两次，因此要减去一次。若两个集合都包含在同一有限总体内，用总体元素数减去并集元素数，即得两个集合都不属于的元素数。","basis":"据关联原题及所列出处编释。","references":[{"source":"sets","location":"1.4 · 并集和交集"}],"examFocus":{"国考 2023 地市级 行测#62":"分开记录两项都参加、仅参加防病、仅参加育种和均未参加的人数，辨清题中两次比较各涉及哪些人。","国考 2025 副省级 行测#69":"区分两项参与比例之和与至少参与一项的比例，再辨明重叠人数和未参与人数在总人数中的关系。"}},"aspects":[{"title":"由交集与单独人数求两项均未参加人数","uses":[{"unit":"Q1","role":"解题依据","use":"根据多21%和多76人的条件，确定只参加防病、只参加育种、两项都参加的人数分别为100、45、121。从287人中分别扣除，得两项均未参加的有21人。","evidence":"287-100-45-121=21人","qids":["国考 2023 地市级 行测#62"]}]},{"title":"由参与比例和两类人数差求总体","uses":[{"unit":"Q2","role":"解题依据","use":"A、B项目的参与比例之和为105%，超出100%的5个百分点对应两项都参与与两项都不参与的人数差2人，因此小组共有40人。","evidence":"0.6x+0.45x-（y+2）=x-y","qids":["国考 2025 副省级 行测#69"]}]}]},"k-15b3148c470f85ea":{"review":{"definition":"从n个不同对象中选出k个，选取顺序不影响结果时，选法数为C(n,k)＝n!÷[k!(n－k)!]，其中0≤k≤n。","explanation":"第63题每户领一份，确定150元礼包的领取户就确定了整种方案。10份都按100元购买需1000元，每换一份150元礼包多花50元，预算允许换0至5份。换0至3份时从3户孤寡老人中选，分别有1、3、3、1种。换4或5份时先给这3户，再从其余7户中选1户或2户，有7、21种。各类相加得36种。","references":[],"evidence":"优先在3户孤寡老人中选择发放对象","disposition":"独立词条","basis":"据原题和解析编释。","title":"组合数","related":[],"examFocus":{"国考 2023 地市级 行测#63":"根据预算确定高价礼包的份数范围，再按份数分类，用组合数统计符合优先发放条件的领取户选法。","国考 2024 副省级 行测#68":"按甲课题的团队数分类，用组合数统计分组方式，再把每组符合编号限制的负责人选法计入。","国考 2024 行政执法 行测#70":"按甲地接待的批数分类，用组合数从符合条件的批次中选出去甲地的批次，再考虑其余批次怎样分到乙、丙两地且两地都有安排。","江苏 2024 C类 行测#59":"遇到“至少一个”的概率题，可以用组合数分别统计全部选法和一个也未入选的选法。"}},"readings":[{"origin":"k-15b3148c470f85ea","title":"组合数","qs":["国考 2023 地市级 行测#63"],"definition":"从n个不同对象中选出k个，选取顺序不影响结果时，选法数为C(n,k)＝n!÷[k!(n－k)!]，其中0≤k≤n。","explanation":"第63题每户领一份，确定150元礼包的领取户就确定了整种方案。10份都按100元购买需1000元，每换一份150元礼包多花50元，预算允许换0至5份。换0至3份时从3户孤寡老人中选，分别有1、3、3、1种。换4或5份时先给这3户，再从其余7户中选1户或2户，有7、21种。各类相加得36种。","evidence":"优先在3户孤寡老人中选择发放对象","doubt":"","references":[]},{"origin":"k-17243e0375090389","title":"组合数","qs":["国考 2024 副省级 行测#68"],"definition":"组合数 C(n,k) 表示从 n 个不同对象中选出 k 个对象的选法数。只要选出的对象相同，选取顺序不同也算同一种选法。","explanation":"甲、乙是两个指定课题。固定甲课题的团队数后，从 6 个团队中无序选出甲的成员，剩下的团队就归乙。甲有 2、3、4 个团队时，分组数分别为 15、20、15。每组恰好排除编号最小的团队，其余团队都可担任负责人，因此三类分别有 15×1×3、20×2×2、15×3×1 种完整安排，共 170 种，对应 D。","evidence":"甲课题由2个团队参与","doubt":"","references":[]},{"origin":"k-37a943982682b530","title":"组合数","qs":["国考 2024 行政执法 行测#70"],"definition":"组合数是从 n 个不同对象中选出 k 个对象且不计选取顺序的选法总数，记作 C(n,k)。","explanation":"第一、二批不能去甲地，因此甲地接待两批时，只能从第三、第四、第五批中选两批。先选第三批再选第四批与反过来选是同一种安排，所以甲地的批次有 C(3,2)=3 种选法。剩余三批还要分到乙、丙两个可区分的地点，且两地都至少有一批。先确定哪一地只接待一批，再选出这一批，共有 2×3=6 种分法，因此甲地接待两批的情形共有 18 种。","evidence":"先从后三批中选2批去甲地","doubt":"","references":[]},{"origin":"k-6a323eacdb434672","title":"组合数","qs":["江苏 2024 C类 行测#59"],"definition":"从 n 个不同对象中选出 k 个，只按选中的对象区分结果时，选法数为组合数 C(n,k)。","explanation":"本题每种选法由入选的 3 个节目确定，全部选法有 C(8,3)＝56 种。若小张所在科室的 2 个节目均未入选，3 个节目都须从其他科室的 6 个节目中选出，因此有 C(6,3)＝20 种选法。","evidence":"从8个节目中随机选出3个","doubt":"","references":[]},{"origin":"k-c27151ef854c856b","title":"组合数","qs":["国考 2024 地市级 行测#64"],"definition":"从 n 个不同元素中选出 k 个，只按所选元素区分方案时，选法总数称为组合数，记作 C(n,k)。","explanation":"本题确定甲课题的团队集合后，剩余团队便归乙课题。调换同一课题内所选团队的排列顺序仍是同一种分组，所以甲选 2、3、4 队分别有 C(6,2)＝15、C(6,3)＝20、C(6,4)＝15 种。负责团队在分组确定后另行选择。","evidence":"乙课题由剩余的3个团队参与","doubt":"","references":[]}]},"k-633dda86fead0d4c":{"review":{"title":"分段工作量","type":"原理与机制","definition":"效率在某段时间内保持不变时，该段工作量等于效率乘以持续时间。","explanation":"两支施工队并行且工作量可加时，可相加同一时段的效率。中途调速或停工，应分段计算。","basis":"按公式或逻辑关系推导；适用条件见释义与诠释。","references":[],"basisGroup":"工作量、效率与时间","related":["k-2b2e3707c004545c","k-6031af086dcc5d6a"]}},"k-a24ddb618deb5e16":{"review":{"definition":"匀加速直线运动中，任一时段的平均速度等于该时段初速度与末速度的算术平均值。","explanation":"加速度恒定时，速度随时间线性变化，因此时段内的平均速度可由两个端点求得。本题设甲出发时速度为1、乙的恒定速度为2。8：00至10：00两人用时相同，且甲在10：00追上乙，故两人这段路程相同，甲的平均速度为2，10：00的速度为3。甲的速度每小时增加1，11：00的速度为4，因此A、B两地相距3×(1+4)÷2＝7.5个距离单位。乙用时7.5÷2＝3.75小时，于11：45到达，选B。","references":[],"evidence":"10：00时甲的速度为2×2-1=3","disposition":"独立词条","basis":"据原题和解析编释。","title":"匀加速直线运动的平均速度","related":[],"examFocus":{"国考 2023 副省级 行测#72":"结合追上时两人的路程关系，用匀加速运动的平均速度分析甲从出发到终点的路程。"}},"readings":[{"origin":"k-a24ddb618deb5e16","title":"匀加速直线运动的平均速度","qs":["国考 2023 地市级 行测#66"],"definition":"匀加速直线运动中，任一时段的平均速度等于该时段初速度与末速度的算术平均值。","explanation":"加速度恒定时，速度随时间线性变化，因此时段内的平均速度可由两个端点求得。本题设甲出发时速度为1、乙的恒定速度为2。8：00至10：00两人用时相同，且甲在10：00追上乙，故两人这段路程相同，甲的平均速度为2，10：00的速度为3。甲的速度每小时增加1，11：00的速度为4，因此A、B两地相距3×(1+4)÷2＝7.5个距离单位。乙用时7.5÷2＝3.75小时，于11：45到达，选B。","evidence":"10：00时甲的速度为2×2-1=3","doubt":"","references":[]},{"origin":"k-d5433df717dca546","title":"匀加速直线运动的平均速度","qs":["国考 2023 副省级 行测#72"],"definition":"匀加速直线运动中，任一时段的平均速度等于该时段初速度和末速度的算术平均值。","explanation":"速度随时间线性增加，因此可以用时段两端的速度求平均速度。设甲、乙出发时的速度分别为1和2。10：00甲追上乙，两人在前两小时走过的路程相同，所以甲在这段时间的平均速度为2，10：00的速度为3。甲每小时速度增加1，11：00到达B地时速度为4。全程路程为3×(1+4)÷2＝7.5，乙用时7.5÷2＝3.75小时，于11：45到达，对应B项。","evidence":"该时段甲的平均速度=乙的速度","doubt":"","references":[]}]},"k-0603bd874be76ea7":{"review":{"title":"等差数列通项公式","type":"原理与机制","definition":"从第2项起，每一项减去前一项都等于同一个常数 d 的数列叫等差数列，d 为公差。首项为 a₁ 时，第 n 项为 aₙ＝a₁＋(n－1)d，其中 n 为正整数。","explanation":"任意两项满足 aₙ－aₖ＝(n－k)d，因为从第 k 项到第 n 项的变化由两项之间的间隔数和公差决定。公差为正、为负或为零时，数列分别递增、递减或保持不变。","basis":"据关联原题及所列出处编释。","references":[{"source":"arith","location":"13.2 通项公式"}],"related":[],"examFocus":{"国考 2023 地市级 行测#67":"用等差数列求和公式处理第一周和第三周的总产量关系，用通项公式处理日产量达到目标的时间。","国考 2024 副省级 行测#65":"用等差数列的通项和求和公式，联系两条生产线第5天的当日产量、前5天的累计产量和首日产量。","江苏 2025 A类 行测#57":"用直径的等差关系确定6至6.9环对应的环带，比较环带面积与未脱靶的有效面积。","江苏 2025 B类 行测#57":"用直径的等差关系确定6环及以上的命中范围，比较该范围与成绩非零的有效命中范围的面积。"}},"readings":[{"origin":"k-0603bd874be76ea7","title":"等差数列通项公式","qs":["国考 2023 地市级 行测#67","国考 2024 副省级 行测#65","江苏 2025 B类 行测#57","江苏 2025 C类 行测#57"],"definition":"从第2项起，每一项减去前一项都等于同一个常数 d 的数列叫等差数列，d 为公差。首项为 a₁ 时，第 n 项为 aₙ＝a₁＋(n－1)d，其中 n 为正整数。","explanation":"任意两项满足 aₙ－aₖ＝(n－k)d，因为从第 k 项到第 n 项的变化由两项之间的间隔数和公差决定。公差为正、为负或为零时，数列分别递增、递减或保持不变。","evidence":"","doubt":"","references":[{"source":"arith","location":"13.2 通项公式"}]},{"origin":"k-1bc337518ec26106","title":"等差数列通项公式","qs":["江苏 2025 A类 行测#57"],"definition":"相邻两项之差恒为公差 d 的数列，其第 n 项为 aₙ＝a₁＋(n－1)d。","explanation":"从首项到第 n 项要累加 n－1 次公差。本题按环数从外向内给各圆编号，1 环外缘直径为 45.5 毫米，每往内一环直径减少 5 毫米。由此算出 6 环和 7 环外缘的直径分别是 20.5 毫米和 15.5 毫米，两者界定了 6.0 至 6.9 环所在的圆环。","evidence":"相邻两个圆的直径均相差5mm","doubt":"","references":[]}],"aspects":[{"title":"由指定项值求项号","uses":[{"unit":"Q1","role":"解题依据","use":"先由第一周与第三周总产量的关系求得首日产量2200件，再按每天增加200件列通项，求得日产量第40天首次达到1万件。","evidence":"2200+（n-1）×200=10000","qids":["国考 2023 地市级 行测#67"]}]},{"title":"由已知项反推首项","uses":[{"unit":"Q2","role":"解题依据","use":"两条生产线第5天产量相同。倒推到第1天，甲减去4m，乙加上8m，再结合前5天的累计产量关系，得乙首日产量为甲的4倍。","evidence":"甲生产线产量为x-4m=8m-4m=4m件，乙生产线产量为x+8m=8m+8m=16m件","qids":["国考 2024 副省级 行测#65"]}]},{"title":"由环序号确定圆的直径","uses":[{"unit":"Q3","role":"解题依据","use":"按题设尺寸求得6环外边界圆的直径为20.5 mm。在题设的面积概率模型下，用该圆面积除以最大圆面积，所得概率介于0.15和0.25之间。","evidence":"6环所处同心圆的直径为45.5+（6-1）×（-5）=20.5mm","qids":["江苏 2025 B类 行测#57"]},{"unit":"Q4","role":"解题依据","use":"按题设尺寸确定6环与7环的边界直径分别为20.5 mm和15.5 mm。在题设的面积概率模型下，用两圆之间的圆环面积除以最大圆面积，所得概率小于0.1。","evidence":"靶纸上10个同心圆的直径构成首项为45.5mm、公差为-5mm的等差数列。","qids":["江苏 2025 C类 行测#57"]}]}]},"k-4295561e641ea3cf":{"review":{"definition":"项数为奇数的等差数列，其各项之和等于中间项乘以项数。","explanation":"与中间项等距的两项之和等于中间项的两倍，所以整段数列的平均值就是中间项。本题每周生产7天，日产量每天增加200件，因此周产量等于该周第4天的产量乘以7。第一周与第三周的中间项分别是第4天和第18天，产量相差14×200＝2800件。第三周总产量是第一周的2倍，所以第4天产量为2800件，首日产量为2200件。再增加39次恰好达到1万件，故首次达到目标的是第40天，选D。","references":[],"evidence":"第三周第四天的产量（即第18天）","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3ab4c2989862405c":{"review":{"definition":"两个平面区域的并集面积等于两块区域各自面积之和减去它们的重叠面积，因为重叠部分在相加时被计了两次。","explanation":"沿水平折痕向下折时，c 的投影完全落在 b 内，d 的投影完全覆盖 a 并伸出原三角形底边。再沿竖直折痕向右折，b 的投影完全覆盖 a，且到原底边为止。因此，面积分别为 b 和 d 的两块投影恰好在 a 处重叠，总投影面积为 b+d−a，选 D。","references":[],"evidence":"后面积为：d+b-a。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-92b992eeaf65c246":{"review":{"definition":"春季接触花粉可能诱发过敏反应，打喷嚏是花粉引起的过敏性鼻炎的常见表现之一。","explanation":"题干把春季过敏放在首位，花粉是可能的诱因，喷嚏是可能的症状，构成“病症、诱因、症状”的词序。B项同样把致病因素放在第二位、症状放在第三位，A项的两者顺序相反。","references":[],"evidence":"花粉可能会导致春季过敏","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-654b1289fbbb1524":{"review":{"definition":"乙型脑炎是由乙型脑炎病毒引起的疾病，发热是其可能出现的症状。","explanation":"B项中的“病毒”按乙型脑炎的病原理解，发热是临床表现。第二、第三词的角色依次对应题干中的花粉和喷嚏。A项把症状咳嗽放在第二位，把可能的病原支原体放在第三位。","references":[],"evidence":"发热是乙型脑炎的症状","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-484bd793f96d3d75":{"review":{"definition":"若前件成立必然后件成立，那么后件不成立时，前件也不成立。前件一旦成立，就必须满足后件所述条件。","explanation":"题组要求研发部门一旦值班，其后一天就须由后勤部门值班。题设排除了整个假期的后勤值班，因此研发也无法值班。财务已被题设排除，第二天又按题组规则不能安排法务，而每天必须有一人值班，所以第二天只能由销售或人事部门的人值班，C项一定正确。","references":[],"evidence":"若安排研发部门的人值班，则只能安排在后勤部门的人值班的前一天。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b4be6d3b12f772a4":{"review":{"title":"同一总体下的比重差","type":"原理与机制","definition":"当两个部分共用同一非零总体时，两者的比重之差等于部分量之差除以总体量。","explanation":"若总体为 200，两部分为 60 和 40，占比相差 (60－40)/200＝0.10，即 10 个百分点。","basis":"按公式或逻辑关系推导；适用条件见释义与诠释。","references":[],"basisGroup":"部分量和总体量","related":["k-58db2e624f2d2295","k-8a483b0a14a1001d"]}},"k-58db2e624f2d2295":{"review":{"title":"两期比重差","type":"原理与机制","definition":"两期比重差是同一统计口径下的现期比重减去基期比重。设现期比重为 s，部分量和总体量从基期到现期的增长率分别为 a 和 b，则两期比重差为 s(a−b)/(1+a)。","explanation":"两期总体量均须大于零。根据现期量和增长率还原基期量，可得基期比重为 s(1+b)/(1+a)，其中基期部分量须大于零，且 a≠−1。在这些条件下，部分量增速高于、等于或低于总体量增速时，比重分别上升、持平或下降。比重和增长率均用小数代入，所得差乘以 100 后以百分点表示。若基期部分量大于零而现期部分量降至零，则比重下降的幅度等于基期比重。","basis":"据关联原题和解析编释。","references":[],"related":["k-b4be6d3b12f772a4","k-8a483b0a14a1001d"],"examFocus":{"国考 2023 地市级 行测#127":"用两期比重差公式判断H省实物商品网上零售额占网上零售总额的比重升降，并将变动幅度与3个百分点比较。","国考 2025 副省级 行测#132":"以业务笔数为口径，结合小额批量支付系统和清算总中心系统的同比增速，判断占比变动的方向及幅度是否达到2个百分点。","国考 2025 地市级 行测#129":"利用全国外贸进出口总额及其同比增量求整体增速，再结合东部地区的增速和现期占比判断两期比重差。","国考 2025 行政执法 行测#127":"用现期占比和两组业务笔数的同比增速还原上年同期占比，再比较两期占比的升降和百分点差。","江苏 2023 B类 行测#123":"按同一统计口径确定两年的机器人销售总额，再比较特种机器人销售额在各年所占的比重。","江苏 2025 B类 行测#124":"以核心片区过夜游客人次为部分量、全市过夜游客人次为整体量，用两期比重差判断变动幅度落在哪个区间。","江苏 2025 C类 行测#119":"分别用同比增速还原核心片区和全市上年的过夜游客人次，再用两年占比的百分点差判断区间。"}},"readings":[{"origin":"k-58db2e624f2d2295","title":"两期比重差","qs":["国考 2023 地市级 行测#127","国考 2025 副省级 行测#132"],"definition":"两期比重差是同一统计口径下的现期比重减去基期比重。设现期比重为 s，部分量和总体量从基期到现期的增长率分别为 a 和 b，则两期比重差为 s(a−b)/(1+a)。","explanation":"两期总体量均须大于零。根据现期量和增长率还原基期量，可得基期比重为 s(1+b)/(1+a)，其中基期部分量须大于零，且 a≠−1。在这些条件下，部分量增速高于、等于或低于总体量增速时，比重分别上升、持平或下降。比重和增长率均用小数代入，所得差乘以 100 后以百分点表示。若基期部分量大于零而现期部分量降至零，则比重下降的幅度等于基期比重。","evidence":"","doubt":"","references":[]},{"origin":"k-0d3d65a965cdcde5","title":"两期比重差","qs":["江苏 2025 C类 行测#119"],"definition":"两期比重差是现期比重减去基期比重，通常用百分点表示。在两期统计口径一致且相关比值有定义时，两期比重差＝现期比重×（部分量增长率－整体量增长率）÷（1＋部分量增长率）。","explanation":"将现期部分量和整体量分别除以各自的增长倍数，可还原基期比重。因此，基期比重等于现期比重乘以（1＋整体量增长率）再除以（1＋部分量增长率）。第119题中，核心片区是部分，全市是整体。现期比重为8326÷10190，代入核心片区的增长率99.9%和全市的增长率88.1%，得到比重提高约4.82个百分点，落在C项的4.5至7.3个百分点之间。","evidence":"2023年M市核心片区接待过夜游客人次占全市接待过夜游客人次的比重比上年提高的幅度：","doubt":"","references":[]},{"origin":"k-938730e99fe91d67","title":"两期比重差","qs":["国考 2025 地市级 行测#129"],"definition":"两期比重差是现期比重减去基期比重。将两期比重写成百分数时，差值用百分点表示。","explanation":"设现期比重为 p，部分和总体相对同一基期的增长率分别为 a 和 b。在基期部分量、基期总体量和现期总体量均为正时，基期比重为 p×(1+b)/(1+a)，所以两期比重差为 p×(a−b)/(1+a)，升降方向由 a−b 决定。第129题中，全国上年同期外贸进出口总额为 9.89−0.45＝9.44 万亿元，全国同比增速约为 0.45÷9.44＝4.77%，高于东部地区的 2.9%。代入东部地区的现期比重 7.75÷9.89，可得比重约下降 1.42 个百分点，选 D。","evidence":"2023年一季度，我国外贸进出口总额为9.89万亿元，同比增加0.45万亿元。","doubt":"","references":[]},{"origin":"k-b3fb7c66388d36e6","title":"两期比重差","qs":["国考 2025 行政执法 行测#127"],"definition":"在基期部分量和整体量均为正、两期整体量均为正的情况下，两期比重差（现期比重减基期比重）等于现期比重乘以（部分量增速减整体量增速），再除以（1＋部分量增速）。比重用百分数表示时，差值用百分点表示。","explanation":"基期的部分量和整体量分别等于各自的现期量除以（1＋各自的增速），因此基期比重等于现期比重乘以（1＋整体量增速）再除以（1＋部分量增速）。第127题中，小额批量支付系统的业务笔数是部分量，人民银行清算总中心系统的业务总笔数是整体量。现期比重为11.51÷54.79，约为21.01%。部分量增速5.73%高于整体量增速0.92%，代入公式得比重同比上升约0.96个百分点，选D。","evidence":"小额批量支付系统处理业务11.51亿笔，金额46.69万亿元，同比分别增长5.73%和10.03%","doubt":"","references":[]},{"origin":"k-eccffc2ef7eef94c","title":"两期比重差","qs":["江苏 2023 B类 行测#123"],"definition":"两期比重差等于现期比重减去基期比重。各期比重均用当期部分量除以当期整体量，两个百分比相减的结果用百分点表示。","explanation":"第123题的部分量是特种机器人销售额，整体量是全部机器人销售额。2021年比重为90.7÷839.0≈10.81%，2020年比重为66.5÷（422.5＋222.2＋66.5）≈9.35%。两期相减，2021年比上年提高约1.46个百分点，最接近C项的1.5个百分点。解析写作约1.4个百分点，按表中数据计算仍选C。","evidence":"2021年我国特种机器人销售额占机器人销售额的比重比上年提高","doubt":"","references":[]},{"origin":"k-efa50d12943613c2","title":"两期比重差","qs":["江苏 2025 B类 行测#124"],"definition":"两期比重差是现期比重减去基期比重。设现期部分量和整体量分别为 A、B，二者相对同一基期的增长率分别为 a、b，且两期比重均有定义，则两期比重差为 (A/B) × (a−b)/(1+a)，比重用百分数表示时，差值以百分点计。","explanation":"用现期量除以 1 加各自的增长率，可还原基期量，因此基期比重为 [A/(1+a)]/[B/(1+b)]。本题中，核心片区接待过夜游客 8326 万人次，增长 99.9%，全市接待 10190 万人次，增长 88.1%。代入得 (8326/10190) × (0.999−0.881)/(1+0.999)，即比上年提高约 4.82 个百分点，落在 C 项的 4.5 至 7.3 个百分点区间。","evidence":"核心片区接待过夜游客人次占全市接待过夜游客人次的比重比上年提高的幅度","doubt":"","references":[]}],"aspects":[{"title":"比重变动的方向和幅度","uses":[{"unit":"Q1","role":"直接考查","use":"国考 2023 地市级 行测第127题。2021年H省实物商品网上零售额同比增长10.1%，低于网上零售总额的12.5%。按现期占比和两项增速计算，比重下降约1.79个百分点，选A。","evidence":"2021年，H省实物商品网上零售额占网上零售额的比重比上年同期：","qids":["国考 2023 地市级 行测#127"]},{"unit":"Q2","role":"直接考查","use":"国考 2025 副省级 行测第132题。2023年三季度，小额批量支付系统业务笔数同比增长5.73%，高于人民银行清算总中心系统业务总笔数的0.92%。按现期占比和两项增速计算，比重上升约0.96个百分点，选D。","evidence":"2023年三季度，人民银行清算总中心系统处理支付业务中，小额批量支付系统处理业务笔数的占比同比：","qids":["国考 2025 副省级 行测#132"]}]}]},"k-4a8a9cb48cdc6cf4":{"review":{"definition":"以符合融资条件的生态产品使用经营权作为质押担保，可以为缺少实体抵押物的项目筹措建设资金。","explanation":"芳草镇生态强村公司没有实体抵押物。2022年3月，芳草镇以调节服务类和文化服务类生态产品的使用经营权作质押担保，取得500万元“GEP贷”，用于解决“溪游记”旅游项目的建设资金需求。本题据此归纳GEP核算应用催生金融产品的做法。","references":[],"evidence":"以生态产品的使用经营权作为质押担保，解决旅游项目资金需求。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-04b5473c4a150c71":{"review":{"definition":"在景叶县未来科技岛的合作模式中，生态产品价值被作为生产要素纳入合作企业的利润分配，以取得经济收益。","explanation":"未来科技岛吸引高新技术企业落户后，把生态产品价值纳入与合作企业的利润分配。本题把这项做法归入产业转入要点，说明地方在吸引企业后还能通过合作经营，将生态产品价值转化为收入。","references":[],"evidence":"把生态产品价值作为生产要素参与合作企业的利润分配","disposition":"题内说明","basis":"据原题和解析编释。","title":"生态产品价值参与利润分配","related":[],"examFocus":{"国考 2023 地市级 申论#1":"从材料1中景叶县两山转化发展中心工作人员的介绍里，提取当地在引入企业和开展合作时实现生态产品价值的做法。","国考 2023 行政执法 申论#1":"阅读材料1中关于未来科技岛的段落，留意企业落户后有哪些合作安排，以及这些安排怎样体现生态产品价值。"}},"readings":[{"origin":"k-04b5473c4a150c71","title":"生态产品价值参与利润分配","qs":["国考 2023 行政执法 申论#1"],"definition":"在景叶县未来科技岛的合作模式中，生态产品价值被作为生产要素纳入合作企业的利润分配，以取得经济收益。","explanation":"未来科技岛吸引高新技术企业落户后，把生态产品价值纳入与合作企业的利润分配。本题把这项做法归入产业转入要点，说明地方在吸引企业后还能通过合作经营，将生态产品价值转化为收入。","evidence":"把生态产品价值作为生产要素参与合作企业的利润分配","doubt":"","references":[]},{"origin":"k-081dc425761934b3","title":"生态产品价值参与利润分配","qs":["国考 2023 地市级 申论#1"],"definition":"在A市景叶县未来科技岛的探索中，生态产品价值作为生产要素参与合作企业的利润分配，由此形成经济收入。","explanation":"景叶县两山转化发展中心工作人员介绍，当地吸引高新技术企业落户，并在与企业合作中把生态产品价值纳入利润分配。本题把这项探索归在产业转化路径下，具体的价值实现环节是合作中的利润分配。","evidence":"把生态产品价值作为生产要素参与合作企业的利润分配","doubt":"","references":[]}]},"k-87d57fc24f9c946d":{"review":{"definition":"湿地碳汇可通过收储和出售实现交易收益。所得资金可用于湿地扩面和修复，进一步提升湿地的碳汇能力。","explanation":"A市将GEP核算应用于碳汇市场，由“两山银行”收储明渚乡的一万吨湿地碳汇量，再向市农商银行等9家单位分别出售碳汇量。材料还提出可将交易收益用于湿地建设，本题据此概括促成碳汇交易和收益反哺生态的做法。","references":[],"evidence":"通过“两山银行”储售碳汇，交易资金反哺生态建设。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-83da3b8148d5b762":{"review":{"definition":"居民把原可用于当期消费的一部分收入存入银行，会推迟这部分购买力的使用。当商品需求相对供给偏旺时，这有助于缓解当期供求压力。","explanation":"B项的“有助于”说的是调节作用。在商品供应量给定时，储蓄使一部分购买力暂缓进入商品市场，从需求端缓解压力，因此B项成立。","references":[],"evidence":"开展储蓄业务有助于实现货币购买力和商品供应量的平衡","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2d959977392c5935":{"review":{"definition":"狐尾藻是沉水植物，能够吸收水中的氮、磷，可用于富营养化水体的生态修复。","explanation":"氮、磷是引起水体富营养化的主要营养元素。狐尾藻生长时吸收这些营养元素，有助于减轻水体的营养盐负荷，因此A项给出的修复理由成立。","references":[],"evidence":"狐尾藻可用于富营养化水体的生态修复是因其可吸收氮磷","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-81c617453b749ffb":{"review":{"definition":"生石灰的主要成分是氧化钙，遇水放热并生成氢氧化钙，形成强碱性环境，可使部分微生物失活。","explanation":"高温和强碱可使蛋白质变性，强碱性环境也会影响细菌的正常生理活动。这解释了B项所述生石灰可用于生态塘沿岸土壤消毒。","references":[],"evidence":"生成强碱，可以使细菌的蛋白质失去活性从而起到杀菌消毒的作用。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-21747906925c95b4":{"review":{"definition":"黑臭污水流经芦苇湿地时，芦苇可吸收水中的营养物质，并吸附或富集部分污染物，有助于改善水质。","explanation":"解析以污水流经芦苇湿地为例，说明芦苇吸收营养物质并富集部分重金属等污染物的作用。这支持C项所说的“可以改善”，实际效果取决于湿地条件和污染负荷。","references":[],"evidence":"芦苇能从污水中吸收营养物质加以利用，并能吸附和富集重金属及一些有毒有害物质","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9589b1cfe16ca0df":{"review":{"definition":"氢燃料电池通过氢与氧的电化学反应，将化学能直接转化为电能，同时生成水并释放热量。","explanation":"以解析中的质子交换膜燃料电池为例，氢在阳极失去电子，电子经外电路流向阴极，形成电流。电能来自燃料电池内的电化学反应，D项把发电过程放在内燃机中，因此本题选D。","references":[],"evidence":"利用氢气和氧气产生电化学反应释放出电能和热能","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c77898d9b1804533":{"review":{"definition":"太阳位于当地天顶时，竖直立杆在水平地面上没有可见的投影。夏至日太阳直射北回归线，冬至日太阳直射南回归线。","explanation":"冬至日，太阳直射点位于汕头以南。汕头当地太阳正午时，太阳在南方天空，竖杆的影子投向北方。本题要求选出错误说法，因此声称冬至汕头会出现“立竿无影”的C项当选。","references":[],"evidence":"冬至时，太阳直射南回归线","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e242ea6b96ecb09c":{"review":{"definition":"蚊虫叮咬时进入皮肤的唾液成分可引起局部免疫反应，常见表现包括瘙痒和红肿。","explanation":"题中B项所说的皮肤发痒，是蚊虫叮咬处常见的轻度过敏表现。题干要求选出正确说法，因此选B。","references":[],"evidence":"蚊虫叮咬引起的过敏症状有皮肤出现红肿、瘙痒","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b4e8197069be3999":{"review":{"definition":"把 n 个相同物品分给 k 个不同对象，每个对象至少分得 1 个。若 n≥k，分配方案数等于从 n−1 个相邻间隙中选出 k−1 个放置隔板的组合数。","explanation":"先给分配对象排定顺序，隔板分出的各段依次对应各对象。隔板插在不同的内部间隙里，每段至少有一个物品，每种分配方案也唯一确定一组隔板位置。第66题把10个名额分给4个分公司，从9个间隙选3个，得到84种等可能方案。三个分公司的名额相同，数量只能是1、2或3，第四个分公司相应得到7、4或1个名额。每种数量组合都有4种选择第四个分公司的方式，因此所求概率为12/84＝1/7，对应D项。","references":[],"evidence":"每个分公司至少分配1个名额，可使用插板法解","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-849847b0024dde7f":{"review":{"definition":"直线运动中，加速度恒定且运动方向不变时，该段的平均速度等于初速度与末速度的算术平均值。","explanation":"加速度恒定时，速度随时间线性变化，因此按时间求平均可直接取两个端点速度的算术平均。本题中，汽车以40千米/小时结束匀速段，随后匀加速至80千米/小时，该段平均速度为60千米/小时。接着从80千米/小时匀减速至停车，该段平均速度为40千米/小时。","references":[],"evidence":"匀变速运动的平均速度公式","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-dc8886b0ac55b408":{"review":{"definition":"两段路程等长且各段平均速度为正时，全程平均速度是两段平均速度的调和平均数，即 2v₁v₂/(v₁+v₂)。","explanation":"设每段路程为 s，两段耗时分别为 s/v₁ 和 s/v₂，用总路程除以总时间即可得到公式。本题的匀加速段和匀减速段各占全程四分之一，两段平均速度分别为60和40千米/小时，合得后半程平均速度为48千米/小时。前后半程也等长，用前半程的40千米/小时和后半程的48千米/小时再算一次，得全程平均速度约43.64千米/小时，低于44千米/小时，选A。","references":[],"evidence":"根据等距离平均速度公式","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c7384adfdc90f983":{"review":{"definition":"圆柱的体积为 πr²h，圆锥的体积为 πr²h/3。r 是底面半径，h 是高。","explanation":"底面半径加倍，底面积变为原来的 4 倍。第 70 题中，设两零件的共同高度为 h，则圆柱 A 的底面半径为 h，圆锥 B 的底面半径为 2h。代入公式得 A 的体积为 πh³，B 的体积为 4πh³/3，因此 B 的体积是 A 的 4/3 倍。","references":[],"evidence":"A的底面半径和高相同，B的底面半径是高的2倍，两个零件的高相同","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8fb67b9aa2e83ab2":{"review":{"definition":"密度等于质量除以体积，即 ρ＝m/V。质量相同时，密度与体积成反比。","explanation":"第 70 题中，圆柱 A 由甲合金制成，圆锥 B 由乙合金制成。两零件质量相同，所以甲合金与乙合金的密度比等于 B 与 A 的体积比。B 的体积是 A 的 4/3 倍，因此甲合金的密度是乙合金的 4/3 倍，对应选项 A。","references":[],"evidence":"质量=密度×体积","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-be11cd8252c48e66":{"review":{"definition":"两个平面区域的并集面积等于各自面积之和减去重叠部分的面积。相加时重叠部分计了两次，因此须减去一次。","explanation":"本题沿水平折痕向下折，再沿竖直折痕向右折。c 折下后落在 b 内，a 被折下的 d 覆盖，两块都没有增加最终投影的范围。图中 b 向右翻折后的投影和 d 向下翻折后的投影都覆盖原 a 所在的矩形，两者的共同部分恰好是这个矩形。因此投影面积为 b+d−a，选 D。","references":[],"evidence":"后面积为：d+b-a。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c4cdf273c849813c":{"review":{"definition":"对花粉过敏的人接触空气中的花粉后，可出现打喷嚏等症状。春季有植物散播花粉，花粉是春季过敏的一种诱因。","explanation":"题干依次列出过敏、诱因和症状。B项依次列出乙型脑炎、致病因素病毒和症状发热。A项的咳嗽是症状，支原体是可能的致病因素，后两项的顺序与题干相反。","references":[],"evidence":"花粉可能会导致春季过敏，前两词为因果关系；打喷嚏是春季过敏的症状","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4aa308d0488924b5":{"review":{"title":"否定后件式","type":"原理与机制","definition":"否定后件式是由“若P则Q”和“Q不成立”推出“P不成立”的有效推理形式。","explanation":"在“若P则Q”中，Q是P成立的必要条件。用“只有Q，才P”表述时，条件关系同样是“若P则Q”。Q成立时，P仍可能成立或不成立。","basis":"据关联原题和解析编释。","references":[],"related":["k-3a208c42ed1b69b4"],"examFocus":{"国考 2023 行政执法 行测#110":"结合部门间值班的先后关系和日期限制，判断部分部门不值班时哪些排班仍然可行。","江苏 2023 A类 行测#105":"在每人点两道菜且搭配互异的条件下，检验一道菜没点时会怎样约束其他选菜。"}},"aspects":[{"title":"由必要条件不成立排除前件","uses":[{"unit":"Q1","role":"解题依据","use":"本题 中，安排研发值班要求次日安排后勤值班。六天均未安排后勤，因此排除研发。再排除财务和第二天不能值班的法务，可知第二天只能安排销售或人事，对应C项。","evidence":"若安排研发部门的人值班，则只能安排在后勤部门的人值班的前一天。","qids":["国考 2023 行政执法 行测#110"]},{"unit":"Q2","role":"解题依据","use":"本题 中，假设丙没点清蒸鲈鱼，依条件（4）可排除丙点芹菜肉丝和毛豆仔鸡，丙便凑不够两道菜。因而丙、乙、丁都点清蒸鲈鱼，甲没点。由条件（1）再排除丁点芹菜肉丝，结合乙还点毛豆仔鸡和每人搭配互异，丙只能搭配芹菜肉丝，对应C项。","evidence":"根据甲不点清蒸鲈鱼以及条件（1），可以推出丁不点芹菜肉丝","qids":["江苏 2023 A类 行测#105"]}]}]},"k-134e8d3f6a5cdbbf":{"review":{"definition":"当基期量和末期量均为正、增长间隔年数相同时，末期量与基期量的比值越大，年均增速越高。对各比值开同样次数的方再减 1，大小顺序保持不变。","explanation":"四地均比较 2016 至 2021 年的集成电路产量，增长间隔都是 5 年。直接比较 2021 年产量与 2016 年产量之比，甘肃 643÷197≈3.26，浙江 230÷74≈3.11，广东 539÷219≈2.46，上海 365÷238≈1.53，因此从高到低为①④②③，对应 C 项。","references":[],"evidence":"当年份差n相同时","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-65513b70ecd2968b":{"review":{"definition":"整车企业销售承压时，对配套发动机的采购需求可能随之下降。供应商的业务越集中于受影响的客户或产品，就越难靠其他业务弥补损失。","explanation":"2021年前后，新能源汽车市场快速扩大，A公司所依托的合资车企面临销售压力，业务单一的A公司也受到冲击。业务萎缩和同批同事相继离职，让小李担心裁员会轮到自己，解释了他想转行的一面。","references":[],"evidence":"业务单一的A公司也“一损俱损”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7abd42f3d3e3ebc0":{"review":{"definition":"整合分散地块，可为经营主体集中承租和规模化种植创造条件。流转后，农户可以获得土地租金，有务工机会时还可增加工资收入。","explanation":"长平县有村庄在土地整理前每亩租金700元也无人承租。改造整合后，每亩租金升至1000元，土地很快被种粮大户承租并用于规模化种植。村民还可以通过务工增加收入，这一案例支撑汇报中的农户增收成果。","references":[],"evidence":"分散的土地被统一整合","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-be0407994ebcc946":{"review":{"definition":"改善灌溉等农田基础设施，可以为各地依据自身生产条件发展特色种养、调整农业产业结构创造条件。","explanation":"长平县实施高标准农田建设后，农田基础设施条件改善，各乡因地制宜发展稻油、稻鱼、稻虾、稻蛙等特色产业，农业综合效益随之提升。汇报可据此概括产业结构优化的成果。","references":[],"evidence":"各乡因地制宜推进产业结构调整","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7155f18f3d3b19c8":{"review":{"definition":"央行逆回购是指央行向公开市场业务一级交易商买入有价证券，并约定在未来特定日期将证券卖还给交易商。操作当期，央行支付资金，向市场投放流动性。","explanation":"逆回购开始时，资金从央行流向交易商。到期时，交易商付资金买回证券，资金流向央行。B项把开展逆回购时的流动性变化写成减少，方向写反，因此应选B。","references":[],"evidence":"其目的主要是向市场释放流动性","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ac64ccba2f0cdb85":{"review":{"definition":"短日照花卉通常需要日长低于一定临界值、连续黑暗达到一定时长，才容易发生花芽分化。临界值因种类和品种而异。","explanation":"在昼夜周期固定时，日照延长会缩短连续黑暗时间，可能抑制花芽分化，使开花推迟或无法开花。D项把一般的开花反应说成植株死亡，因此错误。","references":[],"evidence":"光照时间过长，短日照花卉不能分化花芽","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8d7c2f07160355d1":{"review":{"definition":"铁件表面的锌层可阻隔水和氧气。在存在电解质且锌与铁仍保持电接触时，锌也可优先腐蚀，为铁提供牺牲阳极保护。","explanation":"完整锌层可减少铁表面与水和氧气的接触。局部划损且有水膜等电解质时，活泼性较强的锌可先被氧化，减缓裸露铁的腐蚀。这两种作用支持B项所说的镀锌能增强铁质器具的抗腐蚀性。","references":[],"evidence":"锌的金属活动性比铁高","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3587c793cfafdcc0":{"review":{"definition":"洋葱的辛辣刺激性气味主要来自挥发性有机硫化合物。切开或咀嚼洋葱时，组织受损，这类物质更容易释放到空气中。","explanation":"切洋葱时较易闻到刺激性气味，与有机硫化合物的挥发有关。D项判断的是气味来源的化学类别，认定为有机硫化合物是正确的。","references":[],"evidence":"洋葱的辛辣刺激性气味的来源是其含有的有机硫化物","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bbc8dcbec95016b5":{"review":{"definition":"同一类对象的每单位量相同时，该类对象的总量等于每单位量乘以单位数。各类的单位量有差异时，先分开计算，再按题意相加或比较。","explanation":"设M型、N型灯带分别有x条、y条。按每条灯珠数算得30x＝2×60y，按单价算得20x−30y＝30000。联立得x＝2400、y＝600，共3000条。","references":[],"evidence":"有30灯珠/条的M型和60灯珠/条的N型两种规格，单价分别是20元/条和30元/条","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-949be1c5de1089db":{"review":{"definition":"盈余等于收入减支出。比较两个期间时，收入相同，盈余增加多少，支出就减少多少。","explanation":"本题两年收入均为1200万元，今年盈余增加172万元，所以今年全年支出比去年的960万元少172万元，为788万元。172万元也就是上下半年支出减少额之和，可用来建立第二个方程。","references":[],"evidence":"全年收入与去年相同，总体盈余（收入-支出）比去年增加172万元","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-63c2d85fb3976c99":{"review":{"title":"分类加法与分步乘法计数原理","type":"原理与机制","definition":"把所有方案分成互不重复且合起来覆盖全部方案的类别时，总数等于各类方案数之和。若每个方案由各步选择唯一确定，且每一步在此前任一种可行选择下都有固定数量的选法，则方案数等于各步选法数之积。","explanation":"两条原理可以结合使用。先按影响后续选法数的条件分类，再在满足乘法条件的类别内逐步计数。若同类中后续选法数仍随前一步的结果而变，可以继续细分，再将各分支的方案数相加。","basis":"据关联原题及所列出处编释。","references":[{"source":"count","location":"13.5 乘法计数"}],"related":["k-dba2f598313639fa","k-e9c35702da80f9b6"],"examFocus":{"国考 2024 副省级 行测#68":"按两个课题各分到几队分类，分别计算分组方式和各组符合编号限制的负责人选法。","国考 2025 地市级 行测#70":"按每一步累计得分判断下一题能否答对或答错，再计数始终满足得分下限的序列。"}},"aspects":[{"title":"按分组人数确定负责人选法","uses":[{"unit":"Q1","role":"解题依据","use":"本题选D。甲、乙课题各至少分到2队，按甲组为2队、3队、4队分三类。分组确定后，每组须排除编号最小的队伍，再分别选负责人。三类各有45、80、45种，共170种。","evidence":"每个课题安排一个团队负责，且负责团队不能是该课题所有参与团队中编号最小的团队。","qids":["国考 2024 副省级 行测#68"]}]},{"title":"按累计得分确定后续选法","uses":[{"unit":"Q2","role":"解题依据","use":"本题选B。五道判断题每答完一道都至少得1分，前两题必须答对。第三题答对时，后两题各有两种选择，共4种。第三题答错时，第四题必须答对，第五题有两种选择，共2种。两类合计6种。","evidence":"答完每道题时当前的得分都不低于1分","qids":["国考 2025 地市级 行测#70"]}]}]},"k-3667cf795ad674c9":{"review":{"definition":"在直角三角形中，30°角所对的直角边等于斜边的一半。反过来，长度等于斜边一半的直角边所对的锐角为30°。","explanation":"锐角的正弦等于对边与斜边的长度之比，且30°的正弦为1/2。本题中，AB与BC垂直，AC是斜边。AB长100米，恰为AC的一半，因此AB所对的∠ACB为30°。","references":[],"evidence":"AB、AC分别长100米和200米。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ef1bea8b38dfe8d9":{"review":{"definition":"等边三角形又称正三角形，三条边长度相等，三个内角均为60°。","explanation":"等边对等角，三个相等的内角之和为180°。本题中，BC由勾股定理求得为100√3米，所以CD也长100√3米，且∠BCD为60°。图中A与D位于BC两侧，故∠ACD为∠ACB与∠BCD之和，即90°。在直角三角形ACD中再用勾股定理，得AD长100√7米，对应C项。","references":[],"evidence":"BCD为正三角形","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7825dc63a27a04ce":{"review":{"definition":"三角形面积等于底乘对应高的一半，梯形面积等于两条平行底边的长度之和乘高的一半。高取垂直距离。","explanation":"第71题中，取梯形高为1，角部等腰直角三角形的两条直角边均为2，单块面积为2。设梯形短底为 x，两条斜腰沿45°方向展开，长底两端各比短底多伸出1，所以长底为 x＋2。由梯形与三角形等面积，得 (x＋x＋2)×1÷2＝2，解得短底为1，长底为3。四块三角形的地砖总面积为8。","references":[],"evidence":"且所有三角形和梯形面积均相等。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-dd692ac05d261347":{"review":{"definition":"正方形的面积等于边长的平方。","explanation":"正方形的长和宽相等，因此面积可用同一边长相乘求得。第71题中，中央正方形的边就是相邻梯形的长底，长度为3，木地板面积为9。四块角部三角形的面积合计为8，所以地砖和木地板的面积比为8∶9，对应 C 项。","references":[],"evidence":"中间正方形区域的边EM=EF＋FH＋HM=3","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a53a52cf5642478d":{"review":{"definition":"若集合A是集合B的子集，属于A的元素必定也属于B，因此 A∩C 等于 A∩B∩C。","explanation":"会俄语的人都在会英语的集合内，所以会俄语且会法语的50人恰好是三种语言都会的人。俄语组另一半50人只会俄语和英语，因而只会英语和法语的有100－50＝50人。会英语且会法语的共100人，是英语组的一半，所以会英语的有200人，其中只会英语的有50人。只会一种语言的150人中，其余100人只会法语，故会法语的共200人，选B。","references":[],"evidence":"会俄语的学生包含于会英语的学生","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a46327dbbd24e070":{"review":{"title":"等可能组合与事件概率","type":"原理与机制","definition":"从有限个对象中选取固定数量的对象，各种成员组合等可能时，事件的概率等于符合条件的组合数除以全部组合数。不同的选取顺序得到同一组成员时，只计一个组合。","explanation":"若事件与其对立事件恰好覆盖全部结果，所求概率等于1减去对立事件的概率。若多次选取相互独立，且要求每次选取都满足各自的条件，则联合概率等于各次满足条件的概率之积。","basis":"据关联原题及所列出处编释。","references":[{"source":"prob","location":"13.7 概率与计数"}],"related":["k-442e48c9c67c3602"],"examFocus":{"国考 2024 副省级 行测#74":"先用各组人数的约束找出第二大组的规模，再比较该组全部成员组合与甲、乙均未入组的成员组合。","江苏 2023 A类 行测#63":"分别比较每人选中周三的选法与全部选法，再按独立事件的乘法计算同时到岗的概率。"}},"aspects":[{"title":"至少一人入组的概率","uses":[{"unit":"Q1","role":"直接考查","use":"由总人数、各组人数互异及最大与最小组的人数倍数限制，确定六组人数依次为3、4、5、7、8、9。按符合约束的分组等可能计算，第二大组的8名成员组合等可能。甲、乙至少一人入组的概率为1−C(34,8)/C(36,8)＝40%，对应B。","evidence":"从剩余34人中选8人分到该小组","qids":["国考 2024 副省级 行测#74"]}]},{"title":"独立选取均包含指定对象的概率","uses":[{"unit":"Q2","role":"解题依据","use":"三人分别从5个工作日中等可能选2、3、4天。对每人固定周三后，从其余4天选足所需天数，再与各自的全部选法比较，得到选中周三的概率分别为2/5、3/5、4/5。按三人独立选取计算，三人周三都到公司的概率为24/125，对应C。","evidence":"分别从下周的周一到周五中随机选2天、3天、4天去公司工作","qids":["江苏 2023 A类 行测#63"]}]}]},"k-35e750c2c76ce267":{"review":{"title":"三点确定平面","type":"原理与机制","definition":"空间中，经过三个不共线的点，有且只有一个平面。","explanation":"其中两点确定一条直线，直线与线外的第三点共同确定平面。若三点共线，则有无数个平面经过该直线。用三点确定切割平面后，多面体的截面由该平面与多面体的交集决定。","basis":"据关联原题及所列出处编释。","references":[{"source":"three","location":"空间中的点、直线和平面 · 公理2"}],"examFocus":{"国考 2024 副省级 行测#81":"由图上三个顶点确定切割平面，核对截面穿过哪些方块以及相应的灰白分布。","国考 2024 地市级 行测#75":"由图上三个顶点确定切割平面，核对截面的轮廓及各色方块的相对位置。","国考 2024 行政执法 行测#77":"由图上三个顶点确定切割平面，核对截面穿过哪些方块以及相应的灰白分布。","国考 2025 副省级 行测#87":"用三个指定顶点定位切割平面，沿切割平面与各外表面的交线辨认截面轮廓。","国考 2025 地市级 行测#80":"用三个指定点定位切割平面，比较平面切过阶梯和斜坡后的边界形状。","国考 2025 行政执法 行测#80":"用三个指定点定位切割平面，比较平面切过阶梯和斜坡后的边界形状。"}},"aspects":[{"title":"彩色方块组合体的截面","uses":[{"unit":"Q1","role":"解题依据","use":"2024年国考副省级第81题。A、B、C确定切割平面，从下往上看截面，核对中排两个灰格及上排中间的灰格，对应B项。","evidence":"从下往上看即可得到如下截图：","qids":["国考 2024 副省级 行测#81"]},{"unit":"Q2","role":"解题依据","use":"2024年国考地市级第75题。按该卷图中的A、B、C确定切割平面，依解析从右往左观察转正后的截面。截面左列中间缺一格，两个灰格位于中列上部，对应B项。","evidence":"左图为13个白色正方体和5个灰色正方体组合而成的多面体，现用经A、B、C三个顶点的平面对该多面体进行切割，正确的截面是：","qids":["国考 2024 地市级 行测#75"]},{"unit":"Q3","role":"解题依据","use":"2024年国考行政执法第77题。用图中的A、B、C定位切割平面，从下往上看，截面上下两排各有三格，中排右侧缺一格，三处灰格的分布对应B项。","evidence":"从下往上看即可得到如下截图：","qids":["国考 2024 行政执法 行测#77"]}]},{"title":"阶梯形多面体的截面轮廓","uses":[{"unit":"Q4","role":"解题依据","use":"2025年国考副省级第87题。切割平面经过高处的棱PQ和较低台阶的顶点R，所得截面轮廓为矩形，对应B项。","evidence":"左边为给定的多面体，现用经P、Q、R三个顶点的平面对其进行切割，问哪个选项是其切面？","qids":["国考 2025 副省级 行测#87"]},{"unit":"Q5","role":"解题依据","use":"2025年国考地市级第80题。P、Q位于前部斜坡底边，R位于右侧平台顶角，三点确定的平面截出主体和前方相连的凸部，对应A项。","evidence":"左边为给定的多面体，现用经P、Q、R三点的平面对其进行切割，问哪个选项是其切面？","qids":["国考 2025 地市级 行测#80"]},{"unit":"Q6","role":"解题依据","use":"2025年国考行政执法第80题。由斜坡底边上的P、Q和右侧平台顶角R定位切割平面，所得连通截面的主体呈矩形，前缘有一处凸出，对应A项。","evidence":"左边为给定的多面体，现用经P、Q、R三点的平面对其进行切割，问哪个选项是其切面？","qids":["国考 2025 行政执法 行测#80"]}]}]},"k-50182d02b2f38541":{"review":{"definition":"花朵释放的气味分子进入空气后，因持续的无规则运动而向周围扩散。","explanation":"气味分子从花朵附近扩散到周围，人在一定距离外也可能闻到花香。第98题的“花香四溢：分子运动”由此构成现象与形成原理的对应。","references":[],"evidence":"花香四溢的原理是分子运动","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-efa55f0d7403b610":{"review":{"definition":"波光粼粼是起伏的水面反射光线时呈现的闪动亮光。","explanation":"水面波动使各处反射光的方向不断变化，进入观察者眼中的亮光也随之变化。第98题A项给出的是现象与形成原理的对应，和题干的“花香四溢：分子运动”一致。","references":[],"evidence":"波光粼粼：光的反射","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-651e7e8588f9a706":{"review":{"definition":"“只有A，才B”表示B成立必须有A。这个命题与“如果没有A，就没有B”等价。","explanation":"题干把扎根人民设为创作获得取之不尽、用之不竭的源泉的必要条件，所以不扎根人民就得不到这样的源泉，B项成立。题干把走进实践深处和观照人民生活一同列为对文艺工作者的要求，A项额外加上了必要条件关系。","references":[],"evidence":"只有扎根人民，创作才能获得取之不尽、用之不竭的源泉","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-fac85f086d6b21bb":{"review":{"definition":"若“A或B”能推出C，则C不成立时，A和B都不成立。这里的“或”表示至少一个成立，否定“至少一个”就得到“两个都不”。","explanation":"按三条预测同时成立推理。若甲、乙至少一人通过，条件（3）就推出丙通过、丁不通过。由丁不通过对条件（2）作逆否推理，又得出乙、丙都未通过，与丙通过矛盾。因此甲、乙均未通过，由条件（1）得丙通过，再由条件（2）得丁通过，选A。","references":[],"evidence":"如果乙、丙至少有1人通过，则丁也通过","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7ae6d024e5988a21":{"review":{"definition":"总体量为正时，部分量占总体量的比重超过某一阈值，等价于部分量大于总体量乘以该阈值。比重恰好等于阈值时，不计入超过阈值的情形。","explanation":"不等式两边同乘正的总体量，不等号方向不变。本题先按指标加总东北三省的数据，再分别与该指标全国合计的10%比较。新增恢复灌溉面积为24.6万亩，低于26.48万亩。改善灌溉面积为110.1万亩，低于116.84万亩。新增粮食生产能力为12474.3万公斤，高于12191.89万公斤。新增节水能力为13263.4万立方米，高于12128.36万立方米。超过10%的指标有2个，选B。","references":[],"evidence":"东北三省占全国比重超过10%的指标有几个？","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0974335ea09aad53":{"review":{"definition":"合并两部分后，某类量占合计总体量的比重，等于该类量在两部分中各自比重的加权平均，权重为各部分占合计总体量的份额。两部分总体量均为正时，若各自比重不同，混合比重严格介于两者之间，若相同则保持不变。","explanation":"本题按各部分的储能总能量加权，2022年末累计总能量由2021年末累计总能量和2022年新增总能量组成。因此，只要某类电池在2022年新增电站中的能量占比高于其在2022年末累计电站中的能量占比，就能推出该类电池的年末累计占比较上年末上升。液流电池的新增占比为5.6%，高于累计占比3.7%。磷酸铁锂电池和铅酸/铅碳电池的新增占比分别为86.5%和2.7%，均低于各自的累计占比88.7%和4.0%。新增锂离子电池全部为磷酸铁锂电池，因此三元锂电池的新增占比为0，低于其累计占比0.3%。故仅④符合，选B。","references":[],"evidence":"混合后总体比重居中","disposition":"独立词条","basis":"据原题和解析编释。","title":"混合比重","related":[],"examFocus":{"国考 2024 副省级 行测#129":"用混合比重比较同一类电池在2022年新增投运和当年末累计投运中的能量占比，判断累计占比的变化方向。","国考 2024 行政执法 行测#124":"按储能总能量计算比重，逐类比较2022年新增投运的能量占比与当年末累计投运的能量占比。","江苏 2024 A类 行测#125":"从第一季度和上半年累计的出口占比入手，用混合比重分析两季度出口占比的变化，再比较出口额与进出口总额的环比增速。"}},"readings":[{"origin":"k-0974335ea09aad53","title":"混合比重","qs":["国考 2024 副省级 行测#129"],"definition":"合并两部分后，某类量占合计总体量的比重，等于该类量在两部分中各自比重的加权平均，权重为各部分占合计总体量的份额。两部分总体量均为正时，若各自比重不同，混合比重严格介于两者之间，若相同则保持不变。","explanation":"本题按各部分的储能总能量加权，2022年末累计总能量由2021年末累计总能量和2022年新增总能量组成。因此，只要某类电池在2022年新增电站中的能量占比高于其在2022年末累计电站中的能量占比，就能推出该类电池的年末累计占比较上年末上升。液流电池的新增占比为5.6%，高于累计占比3.7%。磷酸铁锂电池和铅酸/铅碳电池的新增占比分别为86.5%和2.7%，均低于各自的累计占比88.7%和4.0%。新增锂离子电池全部为磷酸铁锂电池，因此三元锂电池的新增占比为0，低于其累计占比0.3%。故仅④符合，选B。","evidence":"混合后总体比重居中","doubt":"","references":[]},{"origin":"k-6143d6f6d89c8e9c","title":"混合比重","qs":["国考 2024 行政执法 行测#124"],"definition":"混合比重是将同一统计口径下的各组部分量相加，再除以各组总体量之和所得的比重，等于以各组总体量为权重计算的加权平均。两组总体量均为正且比重不同时，混合比重严格介于两组比重之间。","explanation":"第124题将2022年末累计投运的电站总能量视为2021年末累计总能量与2022年新增总能量之和。对同一种电池，判断2022年末累计能量占比是否高于2021年末，只需看2022年新增能量占比是否高于2022年末累计占比。液流电池为5.6%对3.7%，符合条件。磷酸铁锂电池为86.5%对88.7%，铅酸/铅碳电池为2.7%对4.0%，新增占比均较低。新增投运的锂离子电池能量全部来自磷酸铁锂电池，三元锂电池新增占比为0，低于其年末累计占比0.3%。因此仅④符合，选B。","evidence":"混合后总体比重居中","doubt":"","references":[]},{"origin":"k-f2ce07c0e4efbe09","title":"混合比重","qs":["江苏 2024 A类 行测#125"],"definition":"将若干组的部分量相加、总体量相加，再用两者相除，得到混合比重。它等于以各组总体量为权重的加权平均，两组总体量均为正且比重不同时，混合比重严格介于两组比重之间。","explanation":"本题上半年的进出口总额由第一、第二季度相加，两季总额均为正。第一季度出口占比为57.8%，低于上半年累计占比58.1%，因此第二季度出口占比必然高于58.1%，也高于第一季度。这个推导确定了B项所需的占比变化方向。","evidence":"混合后居中","doubt":"","references":[]}]},"k-1cb22e7f8a8f4b40":{"review":{"definition":"隆金公司把自动化设备、数字化车间等生产能力，与整车厂的管理体系及汽车行业质量管理要求结合起来，协调管理开发、供应和产能。","explanation":"汽车门把手由多个部件组成，生产涉及市场定位、设计研发、调试生产和质量审核。材料通过这些严格程序，以及开发、供应和产能的同步管理，具体说明隆金公司为何管理严格科学。","references":[],"evidence":"同步实现开发、供应和产能的精益化管理","disposition":"题内说明","basis":"据原题和解析编释。","title":"隆金公司的精益化管理","related":[],"examFocus":{"国考 2024 地市级 申论#2":"从给定资料2对汽车门把手生产流程和管理方式的描述中，提取隆金公司形成市场优势的原因。","国考 2024 行政执法 申论#2":"从给定材料2中有关门把手生产、整车厂管理和质量奖申报的段落，归纳支撑隆金公司取得市场优势的做法。"}},"readings":[{"origin":"k-1cb22e7f8a8f4b40","title":"隆金公司的精益化管理","qs":["国考 2024 地市级 申论#2"],"definition":"隆金公司把自动化设备、数字化车间等生产能力，与整车厂的管理体系及汽车行业质量管理要求结合起来，协调管理开发、供应和产能。","explanation":"汽车门把手由多个部件组成，生产涉及市场定位、设计研发、调试生产和质量审核。材料通过这些严格程序，以及开发、供应和产能的同步管理，具体说明隆金公司为何管理严格科学。","evidence":"同步实现开发、供应和产能的精益化管理","doubt":"","references":[]},{"origin":"k-bca6bef1aa3aaca1","title":"隆金公司的精益化管理","qs":["国考 2024 行政执法 申论#2"],"definition":"隆金公司将自身的自动化设备和数字化车间与整车厂管理体系、汽车行业质量管理要求相结合，对开发、供应和产能实施精益化管理。","explanation":"从市场定位、设计研发到调试生产和质量审核，门把手的生产要经过一套严格程序。结合整车厂管理体系体现了开发、供应和产能的协同，申获“市长质量奖”的过程也推动了经营和质量管理改进。这些事实共同回答企业为何能凭严格、科学的管理取得市场优势。","evidence":"同步实现开发、供应和产能的精益化管理","doubt":"","references":[]}]},"k-a54f711c7d28095a":{"review":{"definition":"江平县部分乡镇卫生院以服务质量、服务数量和服务效益为核心开展绩效考核，并依据考核结果拉开收入差距。","explanation":"青蒲分院过去干多干少收入一样，骨干医师流失，急诊、重症也难以招人。材料记载，绩效改革后医护人员士气逐步提振。起草实施意见时，这一做法归入“稳定现有人才队伍”。","references":[],"evidence":"以服务质量、服务数量和服务效益为核心的考核体系","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-3f72dd15b3136ac4":{"review":{"definition":"江平县与大医院合作，通过专家工作站和“师带徒”工作室培养基层卫生人才，并依托区域性远程会诊、影像诊断和心电诊断中心向乡镇提供专业支持。","explanation":"小湾镇中心卫生院的血透室得到上级医院专家定期指导，体现了现场带教对基层医护的支持。区域远程中心则让乡镇获得会诊或诊断支持。本题可在“完善人才培养机制”下写入两项协作措施，并分别说明带教和诊断服务的作用。","references":[],"evidence":"建立区域性远程会诊、远程影像诊断、远程心电诊断等中心","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-1fe6451b4ade03d7":{"review":{"definition":"相关性描述两个变量在观测数据中的关联程度。因果关系指一个变量的变化会引起另一个变量发生变化。","explanation":"两个变量可能因受同一因素影响而高度相关。题中①仅凭相关程度高就认定存在因果关系，证据不足，因此①错误。","references":[],"evidence":"两个变量相关程度很高，不一定说明两者存在因果关系。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7e108ee514ec0a3a":{"review":{"definition":"易吸湿的化肥应放在干燥、阴凉处，按肥料特性采取密封等防潮措施。储存容器的材质要与肥料相容。","explanation":"硝酸铵吸湿后容易结块、潮解，碳酸氢铵贮存时需要密封防潮。过磷酸钙等具有腐蚀性的化肥应避免接触金属器具。A项把防潮密封的要求推成了普遍适用的金属容器建议，因此是本题所选的错误项。","references":[],"evidence":"尤其碳酸氢铵贮存时包\n装要密封牢固","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5a52a3472d75dc04":{"review":{"definition":"细菌肥料含有发挥作用的活菌，一般应避光保存，以减少光照对活菌存活的影响。","explanation":"日光中的紫外线会使部分活菌失活。避光有助于维持肥料中的有效活菌数量，因此C项所说的“一般应避光保存”成立。","references":[],"evidence":"细菌肥料一般应避光保存","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a2f184f85c20931b":{"review":{"definition":"滴灌施肥是让溶于灌溉水的肥料随水经滴头送至作物根部的施肥方式。水溶性肥料可配成肥液，适合这种施肥方式。","explanation":"滴灌管道和滴头以输送水和肥液为主。肥料能充分溶于水，就能随灌溉水输送，也有助于减少未溶颗粒堵塞滴头的风险，因此D项成立。","references":[],"evidence":"把需施用的肥料溶于水中进行此方式的灌溉即成滴灌施肥","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-96bb96f144d96fe8":{"review":{"definition":"电能表用来计量消耗的电能。家庭电能表装在各用电支路分出之前的干路上。","explanation":"各支路用电时都经过总表的计量范围，因此干路上的电能表能够记录全家的用电量。A项给出的安装位置正确。","references":[],"evidence":"电能表安装在家庭电路的干路上","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5f1e1d1724d4dad4":{"review":{"definition":"家用空气开关是一种断路器，过载或短路达到其脱扣条件时会自动断开电路。","explanation":"空气开关靠自身的脱扣机构切断电路，保险丝靠熔断切断电路。空气开关单独即可提供过电流保护，B项所说的“需要搭配保险丝”有误，是本题所选的错误项。","references":[],"evidence":"空气开关需要搭配保险丝使用才能起到保护电路的作用","disposition":"独立词条","basis":"据原题和解析编释。","title":"空气开关的过电流保护","related":[],"examFocus":{"国考 2024 地市级 行测#20":"比较空气开关和保险丝的过电流保护原理及各自发挥保护作用的条件。"}},"readings":[{"origin":"k-5f1e1d1724d4dad4","title":"空气开关的过电流保护","qs":["国考 2024 地市级 行测#20"],"definition":"家用空气开关是一种断路器，过载或短路达到其脱扣条件时会自动断开电路。","explanation":"空气开关靠自身的脱扣机构切断电路，保险丝靠熔断切断电路。空气开关单独即可提供过电流保护，B项所说的“需要搭配保险丝”有误，是本题所选的错误项。","evidence":"空气开关需要搭配保险丝使用才能起到保护电路的作用","doubt":"","references":[]},{"origin":"k-68a4e70fb67c877f","title":"空气开关的过电流保护","qs":["国考 2024 行政执法 行测#19"],"definition":"空气开关是一种断路器。当过电流达到其动作条件时，空气开关会自动切断电路。","explanation":"第19题中，空气开关靠自身的脱扣机构断开电路，保险丝则靠熔体熔断来断开电路。空气开关发挥过电流保护作用无需搭配保险丝，因此B项把搭配使用说成必要条件，符合题目要求选出的错误说法。","evidence":"空气开关需要搭配保险丝使用才能起到保护电路的作用","doubt":"","references":[]}]},"k-5f198804e582f3a1":{"review":{"definition":"普通家用插线板的各插座接在同一对供电端之间，接在不同插座上的电器构成并联支路。","explanation":"各支路两端电压相同。在插线板电源接通、供电正常时，关闭或拔掉其中一台电器，其余支路仍可通电，因此C项正确。","references":[],"evidence":"使用同一插线板供电的家用小电器之间是并联连接方式","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ed864b02a0513be9":{"review":{"definition":"电流通过白炽灯的灯丝时产生热量，将灯丝加热到白炽状态。高温灯丝发出的热辐射中有一部分是可见光。","explanation":"电流的热效应使灯丝达到发光所需的温度，因此D项所说的白炽灯利用电流热效应工作是正确的。","references":[],"evidence":"将灯丝通电加热到白炽状态，利用热辐射发出可见光","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-265c463fe31ea392":{"review":{"definition":"两个百分比以同一数量为基数时，对应量的差等于该基数乘以百分比之差。","explanation":"税收优惠额和原预计亏损额都以当年营业额为基数。优惠抵消亏损后，盈利为营业额的 2%－0.8%＝1.2%。300 万元等于 0.03 亿元，故营业额为 0.03÷1.2%＝2.5 亿元。","references":[],"evidence":"0.8%x=1.2%x=300万元=0.03亿元","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f498435064049a36":{"review":{"definition":"两人沿同一段路线从两端同时相向匀速运动，首次相遇前各自所走的路程之和等于这段路线的长度，即速度和乘以相遇时间。","explanation":"本题所用的是甲沿顺时针方向从 A 到 B 的弧长。甲走这段弧共用 35 秒，相遇前走了 15 秒，所以乙用 15 秒走过的弧长等于甲用 20 秒走过的弧长，乙速为甲速的 4/3。甲跑一圈用 80 秒，乙用 60 秒，故甲回到 A 时乙距第二次回到 B 还有 2×60－80＝40 秒。","references":[],"evidence":"甲跑15秒后与乙相遇，又跑了20秒后到达B点","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-70bad10183e006e0":{"review":{"definition":"两个正整数之比化为互质的 a∶b 后，这两个整数可分别写成 ax 和 bx，其中 x 为同一个正整数。","explanation":"甲比乙多 26%，所以甲、乙人数比为 126∶100＝63∶50。丙调 3 人给乙后两队相等，说明丙原有 50x＋6 人。总人数 163x＋6 在 300 与 400 之间，故 x＝2，此时甲有 126 人，丙调出后有 103 人。甲调出 49 人时，丙为 152 人，少于甲剩余 77 人的两倍。调出 50 人时，丙为 153 人，超过甲剩余 76 人的两倍。两倍门槛取严格超过或包含等于，最少均为 50 人。","references":[],"evidence":"设乙的人数为50x人，则甲的人数为63x人","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0f8b6933187ecedc":{"review":{"definition":"按同一口径逐年比较，固定的 n 个人每过一年各增一岁，年龄总和便增加 n 岁。","explanation":"由 2023 年和 2025 年的倍数关系及 2030 年的等式，可得 2030 年张、李、王分别为 32、23、55 岁，总和为 110 岁。三人每过一年合计增加 3 岁，2033 年合计 119 岁，2034 年合计 122 岁，因此 2034 年第一次超过 120 岁。","references":[],"evidence":"110+3n>120","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c35f137e8fd1b25a":{"review":{"definition":"将 n 个互不相同的元素各用一次排成一列，共有 n! 种不同的排列。","explanation":"从第一位排到最后一位，每排定一个元素，下一位的可选元素就少一个，因此将各位置的选择数相乘。第 67 题中，每个人在 3 周内各去 A、B、C 一次，其调研顺序有 3×2×1＝6 种。计算全部安排时，三人的顺序可分别选定，因此共有 6³＝216 套安排。","references":[],"evidence":"情况数均为6种情况","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2e84af61a019e22a":{"review":{"definition":"若集合A是集合B的子集，则A∩B＝A。对任意集合C，也有A∩B∩C＝A∩C。","explanation":"本题中，会俄语的学生都会英语，所以同时会俄语和法语的学生恰好是三种语言都会的50人。这50人占会俄语学生的一半，另一半50人只会俄语和英语。只会两种语言的共有100人，余下50人只会英语和法语。英法交集因此有100人，按会英语者中一半会法语可得会英语者共200人，其中50人只会英语。只会一种语言的150人中，余下100人只会法语。会法语的共50＋50＋100＝200人，选B。","references":[],"evidence":"会俄语的学生包含于会英语的学生","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-47d878f249ba0f93":{"review":{"title":"多边形内角和","type":"原理与机制","definition":"在平面上，边界不自相交的 n 边形（n≥3）的内角和为（n−2）×180°。","explanation":"沿多边形内部互不相交的对角线，可将它分成 n−2 个三角形。各三角形的内角合起来恰好组成原多边形的各内角。该公式也适用于凹多边形，凹顶点按大于 180° 的内部角计入。","basis":"据关联原题和解析编释。","references":[],"examFocus":{"国考 2024 地市级 行测#70":"用五边形内角和辨认道路图中缺少的转角条件，再结合已知路长比较周长区间。","国考 2024 行政执法 行测#69":"用五边形内角和辨认道路图中缺少的转角条件，再结合已知路长比较周长区间。"}},"aspects":[{"title":"由五边形内角和求未知转角","uses":[{"unit":"Q1","role":"解题依据","use":"小区道路围成五边形，页图标明 ∠A、∠C、∠E 均为 90°，∠B 为 135°。从 540° 中减去这四个内角，得 ∠D 为 135°。据此作等腰直角三角形，结合三段已知路长求得周长约为 214.1 米，选 B。","evidence":"因五边形内角和为","qids":["国考 2024 地市级 行测#70"]},{"unit":"Q2","role":"解题依据","use":"同一小区道路周长题，页图中的四个已知内角与 Q1 一致。由五边形内角和确定 D 处转角，为计算缺失路段长度提供角度条件，答案同为 B。","evidence":"根据多边形内角和公式","qids":["国考 2024 行政执法 行测#69"]}]}]},"k-e9764cd121f5885b":{"review":{"definition":"有一个锐角为45°的直角三角形是等腰直角三角形，两条直角边与斜边的长度比为1∶1∶√2。","explanation":"五边形内角和为540°。扣除A、C、E处的三个直角及B处的135°，可得D处的内角也是135°。延长AB和ED，从C分别向两条延长线作垂线，垂足为F和G。B、D处的外角均为45°，所以三角形BFC和DGC都是等腰直角三角形。由CD＝50米得DG＝CG＝25√2米，由BF＝FC得BC＝√2·FC。","references":[],"evidence":"为等腰直角三角形，CD=50米","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b116e56f7a228808":{"review":{"definition":"矩形的两组对边分别等长。","explanation":"延长AB和ED，从C分别向两条延长线作垂线，垂足为F和G。AB和ED均垂直于AE，F、C、G在同一直线上，因此AFGE为矩形。由FG＝AE得FC＋CG＝60米，由AF＝EG得40＋BF＝ED＋DG。代入BF＝FC及DG＝CG＝25√2米，得ED＝100－50√2米、BC＝60√2－50米。整圈道路长200＋10√2米，约214.14米，选B。","references":[],"evidence":"因AF=EG，则AB+BF=ED+DG","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5ada9fdee7dc4ab7":{"review":{"definition":"两个分数的分子相同且为正数、分母均为正数时，分母越大，分数越小。若共同分子为零，两个分数都等于零。","explanation":"通分后，两项的分子分别等于原分子乘以对方的分母，所以原分子为正时，原分母较小的一项反而较大。本题的共同分子是文献流通数，流通率的分母至多等于利用率的分母，因此在两个分母均为正时，A项用“一定不低于”同时涵盖了大于和等于的情形。","references":[],"evidence":"二者的分子相同","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9329c718106058b4":{"review":{"definition":"轮作是按一定顺序在同一地块种植不同作物，休耕是让耕地在一定时期内暂停耕种。合理安排轮作休耕，有助于保护和恢复耕地生产能力。","explanation":"题干中的“轮作休耕”着眼于耕地质量，“严禁占用”着眼于防止耕地被占用。按题面表述，首尾两项分别是保护方式，中间的“耕地保护”是共同目的。","references":[],"evidence":"轮作休耕和严禁占用的目的都是耕地保护","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-579ea219c86979ce":{"review":{"definition":"碳中和是指在一定时间和范围内，碳排放与碳吸收、移除或抵消相平衡，净排放为零。植树造林可增加碳吸收，节能减排可减少相关碳排放。","explanation":"A项从增加碳汇和降低排放两端列举实现碳中和的途径。其首尾两项分别指向中间的共同目标，与题干中轮作休耕和严禁占用共同服务于耕地保护的关系一致。","references":[],"evidence":"植树造林和节能减排的目的都是实现碳中和","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ab487b39f209cd4a":{"review":{"definition":"样本代表性是指样本在与调查结论相关的特征上反映目标总体的程度。若入样者集中于具有某种相关特征的人群，调查结果外推到总体的依据就会减弱。","explanation":"题中的90%体验率和每年体验3～4次者的比例逐年升高，都来自近万名受访者。A项指出受访者几乎都是了解或喜爱冰雪旅游的年轻人，而兴趣和年龄可能影响参与频次。即使样本接近万人，这种人群集中仍会削弱用受访者的消费频次推断H地区居民整体需求和消费趋势的依据。","references":[],"evidence":"参与调查的受访者几乎都是了解或喜爱冰雪旅游的年轻人","disposition":"独立词条","basis":"据原题和解析编释。","title":"样本代表性","related":[],"examFocus":{"国考 2024 副省级 行测#107":"用调查数据推断H地区的冰雪旅游需求时，要检查受访者的选取方式是否影响样本对目标人群的代表性。"}},"readings":[{"origin":"k-ab487b39f209cd4a","title":"样本代表性","qs":["国考 2024 地市级 行测#101"],"definition":"样本代表性是指样本在与调查结论相关的特征上反映目标总体的程度。若入样者集中于具有某种相关特征的人群，调查结果外推到总体的依据就会减弱。","explanation":"题中的90%体验率和每年体验3～4次者的比例逐年升高，都来自近万名受访者。A项指出受访者几乎都是了解或喜爱冰雪旅游的年轻人，而兴趣和年龄可能影响参与频次。即使样本接近万人，这种人群集中仍会削弱用受访者的消费频次推断H地区居民整体需求和消费趋势的依据。","evidence":"参与调查的受访者几乎都是了解或喜爱冰雪旅游的年轻人","doubt":"","references":[]},{"origin":"k-b74248321b3a61c7","title":"样本代表性","qs":["国考 2024 副省级 行测#107"],"definition":"样本代表性指样本在与调查指标相关的特征上反映目标总体的程度。若样本集中在行为倾向与总体可能不同的群体，用样本推断总体的依据就会减弱。","explanation":"若A项为真，近万名受访者几乎都是了解或喜爱冰雪旅游的年轻人，这些特征与是否消费、消费频率有关。受访者中90%曾体验过冰雪旅游，且每年体验3至4次的比例逐年升高，这些数据外推到H地区人群的依据因此减弱。","evidence":"参与调查的受访者几乎都是了解或喜爱冰雪旅游的年轻人","doubt":"","references":[]}]},"k-c085bb664bf7966c":{"review":{"definition":"同一地区、同一时期的第一、第二、第三产业增加值合计为该地区生产总值。第一、第二产业增加值的合计占比等于100%减去第三产业增加值占比。","explanation":"第120题②中，天津第三产业增加值占比从2013年到2022年提高7.2个百分点，因此2013年的占比为61.3%−7.2%=54.1%。2013年天津地区生产总值约为1.6÷1.6=1.0万亿元，乘以第一、第二产业合计占比45.9%，可得两者增加值之和约为0.459万亿元。因此②能够推出。","references":[],"evidence":"2013年天津第三产业增加值占比为61.3%-7.2%=54.1%","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cdf583495ea95878":{"review":{"definition":"当分子和分母在基期、现期均为正时，两者采用同一基期计算增长率。分子增速大于分母增速，比值上升；两者增速相等，比值不变；分子增速小于分母增速，比值下降。","explanation":"现期比值与基期比值之比等于（1＋分子增速）÷（1＋分母增速）。第122题的单位面积产量等于产量除以播种面积。2018、2020、2021、2022年均为产量同比增加、播种面积同比减少，单位面积产量随之上升。2019年产量由1798万吨降至1778万吨，同比下降约1.11%，播种面积由476万公顷降至467万公顷，同比下降约1.89%。产量降幅更小，单位面积产量也同比上升。因此共有5个年份，选D。","references":[],"evidence":"当分子增速（a）大于分母增速（b）时，平均数上升","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a0fe4dc4afa8bbcf":{"review":{"definition":"每期增量固定时，第 n 期末的数值等于起点数值加上 n 倍的每期增量。比较两个量何时首次超过，可用两者的每期增量之差推算差距何时由负变正。","explanation":"2021 年末，蜂窝物联网终端用户数比移动电话用户数少 2.45 亿户。按题设，两者 2022 年的月增量分别固定，因此蜂窝物联网终端用户数每月追近 (4.47−0.40)÷12＝4.07÷12 亿户。首次超过要求累计追近量严格大于 2.45 亿户，即 n＞2.45×12÷4.07≈7.22。最小整数 n 为 8，对应 8 月，属于第三季度，选 C。","references":[],"evidence":"现期量=基期量+增长量×n","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-dfc8c6e9f4e68999":{"review":{"definition":"石油分馏利用原油中各组分沸点的差异，经加热汽化和分段冷凝分离出不同沸程的馏分，属于物理分离。","explanation":"较易挥发的组分在较低温度下汽化，可在分馏塔上部较低温区域收集较轻的馏分。A项关于分离依据的前半句正确，后半句把汽油和柴油馏分的沸程高低说反了，因此整项是本题所选的错误说法。","references":[{"source":"web-e9fd571fdd23aa1e","location":"编制说明第2.1.1节及表2","quote":"可将原油分成不同沸程的若干个馏分"}],"evidence":"石油分馏是将石油中几种不同沸点的混合物分离的一种方法","disposition":"独立词条","basis":"据原题和解析编释。","title":"石油分馏","related":[],"examFocus":{"国考 2024 副省级 行测#20":"核对石油分馏所依据的物理性质，并比较汽油与柴油馏分的沸程。"}},"readings":[{"origin":"k-dfc8c6e9f4e68999","title":"石油分馏","qs":["国考 2024 行政执法 行测#18"],"definition":"石油分馏利用原油中各组分沸点的差异，经加热汽化和分段冷凝分离出不同沸程的馏分，属于物理分离。","explanation":"较易挥发的组分在较低温度下汽化，可在分馏塔上部较低温区域收集较轻的馏分。A项关于分离依据的前半句正确，后半句把汽油和柴油馏分的沸程高低说反了，因此整项是本题所选的错误说法。","evidence":"石油分馏是将石油中几种不同沸点的混合物分离的一种方法","doubt":"","references":[]},{"origin":"k-94bc3f9fc1cfb31a","title":"石油分馏","qs":["国考 2024 副省级 行测#20"],"definition":"原题引文：汽油比柴油沸点高","explanation":"汽油和柴油馏分都是混合物，比较时看沸程。生态环境标准编制说明正文举例将汽油馏分划在170℃以下，轻柴油划在230～270℃，重柴油划在270～350℃。同一文件的表2采用较宽的分类范围，汽油为50～200℃，柴油为180～350℃。两种口径都支持汽油馏分的沸程总体较低，所以A项前半句成立，后半句把高低说反，本题选A。","evidence":"汽油比柴油沸点高","doubt":"已核实分馏原理和汽油、柴油馏分的相对顺序。仍需找到本题解析的完整版本，核对三个空缺数值及所用教材口径。","references":[{"source":"web-e9fd571fdd23aa1e","location":"编制说明第2.1.1节及表2","quote":"可将原油分成不同沸程的若干个馏分"}]}]},"k-428b16ae80dc1409":{"review":{"definition":"原题引文：石油分馏利用了组分间的沸点差异，汽油比柴油沸点高","explanation":"A项前半句正确，后半句把汽油和柴油的沸程高低写反，因此本题选A。生态环境部公开的标准编制说明列举过一组原油馏分划分示例，汽油馏分低于170℃，轻柴油馏分为230～270℃，重柴油馏分为270～350℃。同一说明还列出另一套馏分区间，三组示例数字应按所引划分口径理解。","references":[{"source":"web-f711ad1cdd421363","location":"正文，常压馏分的划分","quote":"具有不同沸点范围的组分"},{"source":"web-e9fd571fdd23aa1e","location":"第2.1.1节“总石油烃的理化性质”，表2前一段","quote":"轻柴油馏分（230℃-270℃）"}],"evidence":"石油分馏利用了组分间的沸点差异，汽油比柴油沸点高","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-8a23921ed4b4620c":{"review":{"definition":"两个量都按同一基数的百分比计算时，先把这两个百分比相加或相减，再乘以该基数，就得到这两个量的和或差。","explanation":"优惠额和原预计亏损额都以A工厂当年的营业额为基数。优惠先抵消亏损，余额才是盈利，所以盈利占营业额的2%−0.8%＝1.2%。用300万元除以1.2%，得预计营业额2.5亿元，对应D项。","references":[],"evidence":"2%x-\n0.8%x=1.2%x","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-28a64fbd137e383f":{"review":{"definition":"从同一时点起每经过相同的整年数，每个人的年龄都增加相同的岁数，人与人之间的年龄差保持不变。","explanation":"设甲、乙、丙现在分别为3x、4x、5x岁。8年后三人的年龄各加8，甲乙年龄之和因此加16，列得(3x＋8)＋(4x＋8)＝1.5×(5x＋8)，解得x＝8。8年后甲、乙、丙分别为32、40、48岁，由四人平均43岁可知丁为52岁。从该时点再过15年，四人分别为47、55、63、67岁，超过60岁的只有丙和丁，对应C项。","references":[],"evidence":"丁年龄为52+15=67岁","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e688ded1a928378c":{"review":{"definition":"如果同一总体中的每个成员都恰好归入一组，各组以该总体为分母计算的占比之和就是100%。","explanation":"面试的100人中，甲校占40%，丙校50人即占50%，所以乙校占10%。乙校从笔试到面试下降了15个百分点，因此笔试时乙校占25%。再以笔试全体为总体，从100%中扣去甲校的50%和乙校的25%，得丙校占25%，三校人数比为2∶1∶1，对应A项。","references":[],"evidence":"1-40%-50%=10%","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bbc70b145e27e097":{"review":{"definition":"完成一项安排需要依次进行若干步。如果每一步在前面各步选定后都有固定数量的可选方式，且一组选择唯一对应一种完整安排，则总数等于各步可选方式数的乘积。","explanation":"第64题中，每人把三个地点排入三周，各有6种顺序。计算全部安排时，依次选定三人的顺序，得到6×6×6＝216种。计算符合要求的安排时，第一周有6种分配方式。对任一第一周分配，第二周每人都须换地点且三人去处互异，只有两种轮换方式。第三周每人去自己尚未去过的地点，三人的去处也互异，因此符合要求的安排有6×2×1＝12种。","references":[],"evidence":"总情况数为6×6×6=216种情况","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6425921eacf614c3":{"review":{"definition":"两个正整数的比化为最简整数比后，两个数分别等于对应的比值项乘以同一个正整数。","explanation":"最简比的两项互质，因此实际人数必须分别是对应比值项的整数倍。甲比乙多26%，甲、乙人数之比为126∶100＝63∶50，可分别设为63x和50x。丙调3人去乙后人数相等，所以丙原有50x＋6人。三队总人数为163x＋6，由“300多人”确定x＝2。此时甲有126人、丙有103人，甲调49人后丙有152人，低于甲人数的两倍154人。甲调50人后丙有153人，达到要求。","references":[],"evidence":"设乙的人数为50x人，则甲的人数为63x人","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6d966e1bff9e9de9":{"review":{"definition":"两点之间的线段长度不大于经第三点连接这两点的两段长度之和。当第三点在线段上时，两者相等。","explanation":"把工作站视为道路上的点，将甲联络站沿道路所在直线反射。道路上任一点到甲站和到其对称点的距离相等。甲站的对称点和乙站分居道路两侧，所以把工作站建在两点连线与道路的交点，两段距离之和就等于两点间的直线距离。两点沿道路方向相差10千米，垂直道路方向相差24千米，由勾股定理得最短距离为26千米。","references":[],"evidence":"根据两点之间线段最短，可知将工作站建在O点时，距离甲、乙联络站的距离之和最小","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cd978eb6a9d1cd16":{"review":{"definition":"等腰直角三角形的两条直角边与斜边的长度比为 1∶1∶√2。已知斜边时，除以 √2 即得任一条直角边的长度。","explanation":"两条直角边等长，由勾股定理可知斜边是直角边的 √2 倍。第 69 题中，AB 与 ED 平行，∠B 为 135°，所以 BC 与水平方向成 45°。又因 ∠C 为直角，CD 也与水平方向成 45°。从 C 向 AB、ED 的延长线作垂线，即得到以 BC、CD 为斜边的两个等腰直角三角形。CD 长 50 米，其水平和竖直投影均为 25√2 米。两条斜边的竖直投影之和等于 EA 的 60 米，据此可求得 BC 为 60√2−50 米，再由水平投影求得 ED 为 100−50√2 米。整圈周长为 200+10√2 米，约 214.14 米，选 B。","references":[],"evidence":"为等腰直角三角形，CD=50米","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a52fff3bbf608741":{"review":{"definition":"按题干定义，知名品牌用于与原产品不同类型的产品时，如果新品与原产品相对立或容易引起反感，消费者可能因原有品牌印象与新品用途产生矛盾，进而只购买其中一类或两类都不买，影响原有品牌形象。","explanation":"D项中，消费者原先喜爱的是厨卫清洁品牌，后来却要接受同一品牌推出的可饮用产品。清洁用品与饮料的用途形成反差，消费者「一时难以接受」，最直接体现题干所说的心理冲突。B项写的是奢侈手提包品牌推出百元包后，部分消费者放弃该品牌，题面只交代了他们的选择，未明确呈现他们对两类产品的矛盾感受。","references":[],"evidence":"如果品牌延伸到一个与原产品相对立或易引起消费者反感的产品上，就会对消费者造成心理冲突。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a6f3f70e779f6184":{"review":{"definition":"在本题设定的计数法中，右边是高位，左边是低位。比较两位数时，先按右位的符号顺序比较，右位相同才按左位的符号顺序比较。","explanation":"A、C的右位都是◆，B、D的右位都是◇。右位◆大于◇，因此先排除B、D。再比较A、C的左位，A的◆大于C的■，所以A最大。本题左右两位的符号排序相反。","references":[],"evidence":"右边数位大的数字更大","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-3c95584065148938":{"review":{"definition":"气味分子进入空气后持续做无规则热运动，在存在浓度差时会从浓度较高处向浓度较低处净扩散。","explanation":"花朵释放出的气味分子在空气中扩散，到达人鼻处便可能被嗅到。因此，“花香四溢”是可感知的现象，“分子运动”解释了这种现象，与A项用光的反射解释水面波光的关系一致。","references":[],"evidence":"花朵的气味分子进入空气，扩散到周围环境中","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-23bc3164fbf656fd":{"review":{"definition":"光照到起伏的水面时，朝向不同的水面会把光反射到不同方向。随着水面起伏，反射光进入观察者眼睛的位置不断变化，形成闪动的亮斑。","explanation":"A项用光的反射解释“波光粼粼”，与题干的“现象—成因”关系一致。C项的石头露出是因为水位降到了石头顶部以下，选项所配的浮力解释不了这一现象。","references":[],"evidence":"波光粼粼的原理是光的反射","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c37a8aa0fb085553":{"review":{"definition":"在本题所述的红酒生产流程中，发酵和灌装都是生产环节。先通过发酵酿成酒，再将酒灌入容器。","explanation":"第95题的题干同时要求两层关系：前两项都属于第三项所指的过程，而且第一项在第二项之前。A项的摇晃和搅拌没有固定的先后顺序，C项的养殖属于销售对虾之前的生产环节，两项各缺少一层关系。","references":[],"evidence":"且先发酵再灌装","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-47b17ad40948044b":{"review":{"definition":"在本题所述的信封制作流程中，先折叠纸张，使待粘合的边对齐，再粘合这些边以固定形状。","explanation":"第95题D项的折叠和粘合都属于制作信封的工序，且顺序固定，与题干中先发酵再灌装的两层关系一致。B项的下载和打印可发生在找到资料之后，属于后续处理环节，因此不符合题干的组成关系。","references":[],"evidence":"且先折叠再粘合","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-7007c359e86ab288":{"review":{"definition":"放养过密和饲喂不当是两类养殖管理问题，各自都可能促使鱼病发生。","explanation":"第98题把放养过密和饲喂不当作为并列的可能原因，分别指向鱼病发生。D项则是市场饱和先导致利润下降，再由利润下降导致分红减少，前两项之间已构成因果关系。","references":[],"evidence":"二者都是导致“鱼病发生”的原因","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-0bb1a81453b5d623":{"review":{"definition":"按第98题设定，地基下沉和结构老化是两类建筑问题，各自都可能导致房屋倾斜。","explanation":"C项的前两项并列，分别与第三项构成因果关系，对应题干中放养过密和饲喂不当分别可能引发鱼病。B项的材料审核、实地考核在本题中是评估通过的条件。","references":[],"evidence":"二者都是导致“房屋倾斜”的原因","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-cd24b2b6c51ba6fc":{"review":{"definition":"总体量为正时，部分量占总体量的比重超过给定比例，等价于部分量超过总体量与该比例的乘积。","explanation":"比重等于部分量除以总体量，不等式两边同乘正的总体量，大小关系保持不变。本题逐项将东北三省合计与全国对应指标的10%比较。新增恢复灌溉面积24.6万亩低于26.48万亩，改善灌溉面积110.1万亩低于116.84万亩，新增粮食生产能力12474.3万公斤高于12191.89万公斤，新增节水能力13263.4万立方米高于12128.36万立方米。超过10%的有2项，选B。","references":[],"evidence":"万亩<264.8万亩×10%","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0bffd37680ddf145":{"review":{"definition":"各组成部分可以相加且基期量均为正时，合计同比增长率是各部分同比增长率以各自基期量为权重的加权平均。各部分增速有差异时，合计增速严格介于最低和最高增速之间。","explanation":"合计增速等于各部分同比增量之和除以各部分基期量之和，而每部分的同比增量等于其基期量乘以同比增速。本题中，2023年一季度机器人设备进口金额由1至2月和3月两部分相加得到。3月同比增长68.5%，高于一季度的55.1%，因此1至2月合计同比增速必低于55.1%，也低于3月，故B项正确。","references":[],"evidence":"根据混合增长率口诀“混合居中”可知","disposition":"独立词条","basis":"据原题和解析编释。","title":"混合增长率","related":[],"examFocus":{"国考 2024 行政执法 行测#130":"用混合增长率的居中关系，对照一季度累计与3月单月的机器人设备进口额同比增速，判断3月与1至2月合计增速的相对高低。","江苏 2025 B类 行测#125":"将东北、东南片区接待过夜游客人次的同比增速按各自基期人次加权，再与题设的增速上限比较。","江苏 2025 C类 行测#120":"把东北、东南片区接待过夜游客人次的同比增速按各自的基期人次加权，再与题设上限比较。"}},"readings":[{"origin":"k-0bffd37680ddf145","title":"混合增长率","qs":["国考 2024 行政执法 行测#130"],"definition":"各组成部分可以相加且基期量均为正时，合计同比增长率是各部分同比增长率以各自基期量为权重的加权平均。各部分增速有差异时，合计增速严格介于最低和最高增速之间。","explanation":"合计增速等于各部分同比增量之和除以各部分基期量之和，而每部分的同比增量等于其基期量乘以同比增速。本题中，2023年一季度机器人设备进口金额由1至2月和3月两部分相加得到。3月同比增长68.5%，高于一季度的55.1%，因此1至2月合计同比增速必低于55.1%，也低于3月，故B项正确。","evidence":"根据混合增长率口诀“混合居中”可知","doubt":"","references":[]},{"origin":"k-267cd2d2a60e35e6","title":"混合增长率","qs":["江苏 2025 C类 行测#120"],"definition":"若干可加总部分的混合增长率等于其合计增长量除以合计基期量。各部分基期量均为正时，这相当于以各部分基期量为权重，对各部分增长率求加权平均。","explanation":"各部分的增长量等于基期量乘以增长率，因此基期量越大，该部分的增长率在合计增速中的权重越大。第120题中，东北片区和东南片区的基期接待量分别为1125÷1.382≈814.04万人次和739÷1.701≈434.45万人次。两片区合计增速偏向东北片区较低的38.2%，按基期量加权约为49.30%，低于D项的54.2%，所以D项可以推出。","evidence":"混合后居中，偏向基期较大的（一般用现期量代替基期量）","doubt":"","references":[]},{"origin":"k-ac4cffaa16d463cb","title":"混合增长率","qs":["江苏 2025 B类 行测#125"],"definition":"各部分可以相加、增长时期相同且基期量均为正时，合计增长率等于各部分增长率以各自基期量为权重的加权平均。","explanation":"合计增长率等于各部分增长量之和除以基期量之和，而各部分增长量等于各自的基期量乘以增长率。题中，东北、东南片区的基期量分别为1125÷1.382≈814.04万人次和739÷1.701≈434.45万人次。用这两个基期量对38.2%和70.1%加权，得到合计增长率约49.3%，低于54.2%，所以D项可以推出。现期量可以用于粗估，本题用还原后的基期量核验上限。","evidence":"东北片区接待过夜游客1125万人次，增长38.2%；东南片区接待过夜游客739万人次，增长70.1%。","doubt":"","references":[]}]},"k-2b01bdf0bdadd547":{"review":{"definition":"实体的原型黄河是数字孪生黄河和模型黄河的共同基础。数字孪生系统提供预报、预警、预演、预案支持，实体模型试验提供物理参数和技术依据，两者共同服务原型黄河治理。","explanation":"材料以“2+N”智能业务应用体系和“模型黄河”试验基地说明协同怎样落实。前者以流域防洪和水资源管理为建设重点，借助监测感知数据开展防汛推演和巡查处置。后者通过洪水预演、水土流失和水库淤积等试验，为防洪部署、水土保持和工程运行提供依据。","references":[],"evidence":"原型黄河是数字孪生黄河和模型黄河的基础。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-efeb214026caefff":{"review":{"definition":"当AI的数据处理能力足以承担部分基础标注任务时，这些任务可以逐步由自动标注完成，相应的人工标注需求可能减少。","explanation":"祥云公司总经理于波涛据此判断，公司的基础标注订单将逐渐减少。本题可将其归入“订单减少”的原因，并据此提出引入AI辅助标注、拓展专业细分业务的建议。于波涛的判断针对基础性任务，材料另指出金融、医疗、智能制造等领域仍有标注需求。","references":[],"evidence":"基础性的人工标注会逐步被AI自动标注取代","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-79e0edf8ee695e1d":{"review":{"definition":"矛盾双方相互依存，并可在一定条件下向各自的对立面转化。人可以在尊重客观规律的基础上，通过实践促成转化所需的条件。","explanation":"本题要求论证劣势如何转化为优势。以今州粮仓为例，原有储粮功能衰退，但保存下来的仓体和粮食文化为转化提供了基础。项目组保留历史风貌，增设展陈和公共文化空间，使闲置粮仓有了新的用途。写作时要把已有条件、人的行动和转化结果连起来。","references":[],"evidence":"事物的劣势在特定条件下可以转化为优势","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1147d5c7af105768":{"review":{"title":"人民群众与社会财富的创造","type":"原理与机制","definition":"历史唯物主义认为，人民群众是社会物质财富和精神财富的创造者。","explanation":"人民群众通过生产劳动创造物质生活资料，也直接参与精神财富的创造。群众的社会实践为精神生产提供素材和经验，实践经验经过总结和提炼可以形成新的理论成果。","basis":"据关联原题及所列出处编释。","references":[{"source":"people","location":"社会历史发展的动力 · 人民群众的作用"}],"related":["k-253af8e175729959","k-e5c94d5d20f83e29"],"domain":"哲学","examFocus":{"国考 2025 副省级 行测#1":"结合人民创造性实践的论述，核对谁创造物质和精神财富、理论成果从何而来。"}},"aspects":[{"title":"人民群众创造财富与推动理论创新","uses":[{"unit":"Q1","role":"直接考查","use":"题干援引习近平在2023年6月30日二十届中共中央政治局第六次集体学习时的论述。①概括人民创造两类财富的作用，③指出党的理论成果源于人民的智慧、探索和创造，因此选B。②把首创精神归于理论工作者，并颠倒了从实践经验到理论成果的顺序。④把《必须坚持人民至上》中身处实践最前沿的主体由人民群众换成了各级领导干部。","evidence":"①人民不仅是物质财富的创造者，也是精神财富的创造者","qids":["国考 2025 副省级 行测#1","国考 2025 地市级 行测#1"]}]}]},"k-bb17c512e6276ac6":{"review":{"definition":"人民群众的创造性实践为马克思主义理论创新不断提供经验和智慧。从实践中总结新鲜经验，将其上升为理性认识，可以提炼出新的理论成果。","explanation":"①关于人民创造物质财富和精神财富的表述，以及③关于党的创新理论源于人民智慧、探索和创造的表述，都符合题干论述。②把首创主体换成理论工作者，还颠倒了从实践中总结经验、提炼理论的方向。④把身处实践最前沿的人民群众换成各级领导干部。故选①③，对应B。","references":[],"evidence":"人民的创造性实践是马克思主义理论创新的不竭源泉。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bbfcc1599e79a235":{"review":{"title":"矛盾的普遍性、特殊性和客观性","type":"原理与机制","definition":"在唯物辩证法的对立统一规律中，矛盾的普遍性指矛盾贯穿一切事物的发展过程，体现为共性。特殊性指具体矛盾各有特点，体现为个性。客观性指矛盾的存在不以人的意志为转移。","explanation":"共性寓于个性之中。不同事物、同一事物的不同发展阶段以及同一矛盾的不同方面，各有具体特点。分析这些特点是认识事物性质和发展规律的基础。","basis":"据关联原题和解析编释。","references":[],"examFocus":{"国考 2025 副省级 行测#2":"比较各项陈述对矛盾性质、存在条件及其与人的认识关系的界定。"}},"aspects":[{"title":"矛盾的共性、个性与客观存在","uses":[{"unit":"Q1","role":"直接考查","use":"题干以问题导向引出矛盾的普遍性和客观性。C项正确对应共性与个性。A项把具体矛盾随条件变化的特点归给普遍性，B项把客观存在归于主观认知，D项把矛盾特殊性在区分事物性质中的作用归给了普遍性和客观性。","evidence":"矛盾的普遍性是矛盾的共性，矛盾的特殊性是矛盾的个性","qids":["国考 2025 副省级 行测#2","国考 2025 地市级 行测#2","国考 2025 行政执法 行测#2"]}]}],"sources":[{"id":"c394cdef1420fc60","label":"辩证法 · 三大规律","topic":"马克思主义哲学","category":"非时政","text":"二、三大规律\n1.对立统一规律\n（1）含义：对立统一规律是唯物辩证法的实质和核心；对立统一规律揭示了事物发展\n的源泉和动力。\n（2）矛盾的基本属性\n同一性是指矛盾双方相互依存、相互贯通，在一定条件下可以相互转化。\n斗争性是指矛盾双方相互排斥的属性，体现着对立双方相互分离的倾向和趋势。\n（3）矛盾的普遍性和特殊性\n矛盾的普遍性是指时时有矛盾、事事有矛盾，矛盾的普遍性要求我们运用矛盾分析法分\n析一切事物。\n矛盾的特殊性是指具体事物包含的矛盾以及每一矛盾的各个方面都有其特点，矛盾的特\n殊性要求我们要具体问题具体分析。\n（粉笔敲黑板：通俗来讲，普遍性强调的是“都有”，特殊性强调的是“不一样”\n）\n（4）矛盾的不平衡性\n①主要矛盾和次要矛盾\n主要矛盾是指在诸多矛盾中处于支配地位、对事物发展起决定作用的矛盾；次要矛盾是\n指处于从属地位、对事物发展不起决定作用的矛盾。\n②矛盾的主要方面和次要方面\n矛盾的主要方面是一个矛盾中处于支配地位、起主导作用的方面；矛盾的次要方面是处\n于被支配地位的方面。\n矛盾发展的不平衡性要求我们做到两点论和重点论的统一。\n（4）内因和外因的关系\n内因是事物变化发展的根据和第一位原因。\n外因是事物变化发展的条件，外因通过内因起作用。\n事物的发展是内外因共同作用的结果。\n（粉笔敲黑板：对立统一规律属于马克思主义哲学中的重要考点，要求能够理解相关哲\n学原理，且能够通过选项案例判断哲理是否对应正确）\n2.质量互变规律\n质量互变规律揭示了事物发展的形式和状态。\n辩证关系：量变是质变的前提和必要准备；质变是量变的必然结果。\n方法论：坚持适度原则；重视量的积累；不失时机地促成质变，实现事物的飞跃。\n3.否定之否定规律\n否定之否定规律揭示了事物发展的方向和道路。\n任何事物的发展都要经历“肯定→否定→否定之否定”的过程。\n事物的发展是前进性和曲折性的统一。\n（粉笔敲黑板：本考点主要结合古语和案例考查，“前进性”强调的是方向美好，曲折\n性强调的是“道路曲折”）","source":{"doc":"3ccc56f4000d1642c2d1","first":3,"last":5,"page":3,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-labor":{"review":{"title":"劳动二重性","type":"原理与机制","definition":"生产商品的同一劳动具有具体劳动和抽象劳动两个方面。具体劳动创造商品的使用价值，抽象劳动形成商品的价值。","explanation":"具体劳动是以特定方式进行的有用劳动，如织布和制衣。抽去这些具体形式，商品生产中的劳动可以作为无差别的一般人类劳动来考察。商品价值量由生产该商品的社会必要劳动时间决定。","basis":"据关联原题及所列出处编释。","references":[{"source":"book","location":"第一章第二节"}],"examFocus":{"国考 2025 副省级 行测#3":"核对劳动二重性与商品属性的关系，并区分价值量和货币职能各自的适用条件。"}},"aspects":[{"title":"同一劳动的两个方面及其作用","uses":[{"unit":"Q1","role":"直接考查","use":"D项把具体劳动与使用价值、抽象劳动与价值正确对应。C项把同一商品生产劳动的两个方面说成不同商品生产过程中的不同劳动。","evidence":"具体劳动创造商品的使用价值，抽象劳动形成商品的价值","qids":["国考 2025 副省级 行测#3","国考 2025 地市级 行测#3","国考 2025 行政执法 行测#3"]}]}],"sources":[{"id":"8b483b708f211e74","label":"商品经济理论 · 劳动二重性","topic":"马克思主义政治经济学","category":"非时政","text":"二、劳动二重性\n商品是劳动产品，生产商品的劳动可区分为具体劳动和抽象劳动。\n1.具体劳动：各种形式的有用劳动，生产使用价值。\n2.抽象劳动：无差别的人类劳动，形成价值实体。","source":{"doc":"3ccc56f4000d1642c2d1","first":8,"last":8,"page":8,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-7a9c4e72b481a4bc":{"review":{"title":"真理尺度与价值尺度的辩证统一","type":"原理与机制","definition":"真理尺度衡量实践是否遵循客观规律，价值尺度衡量实践是否满足主体的需要。二者的统一体现为在遵循客观规律的基础上实现一定的价值目标。","explanation":"客观条件和规律制约价值目标的实现方式，价值目标则影响实践的方向。分析价值尺度时，需要明确所涉及的主体及其利益。","basis":"据关联原题和解析编释。","references":[],"examFocus":{"国考 2025 副省级 行测#4":"辨清引文每一层论述所回答的问题，再核对哪个哲学观点能够解释整段论述。"}},"aspects":[{"title":"遵循社会发展规律与维护人民利益","uses":[{"unit":"Q1","role":"直接考查","use":"题干把马克思主义科学真理所揭示的人类社会发展规律和最广大人民的根本利益共同作为中国共产党人理想信念的基础，分别体现真理尺度和价值尺度，对应A项。","evidence":"我们坚定，是因为我们遵循的是规律。我们坚定，是因为我们代表的是最广大人民根本利益。","qids":["国考 2025 副省级 行测#4","国考 2025 地市级 行测#4","国考 2025 行政执法 行测#4"]}]}]},"k-4b8cb4d2a75c3ce7":{"review":{"definition":"太阳直射北半球时，在同一天有日出和日落的北半球地区，纬度越高，昼越长，夜越短。","explanation":"受地轴倾斜影响，太阳直射北半球时，北半球纬度越高的地点随地球自转经过白昼一侧的时间越长。第26题给出我国两座城市在夏季同一天的日出和日落时刻。左图从06:31到21:56，昼长15小时25分。右图从04:55到19:02，昼长14小时07分。左图城市昼长多78分钟，因此纬度更高，A项正确。","references":[],"evidence":"在夏季，北半球纬度越高，昼越长，夜越短","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c0d88c18841228fe":{"review":{"definition":"X射线造影利用造影剂改变局部对X射线的衰减，使目标结构与周围组织在影像上形成更明显的对比。","explanation":"题中B项的“密度的区别”按解析指造影剂与周围组织在X射线影像上产生的对比。造影剂使血管或腔道的影像轮廓更清楚。按X射线造影这一范围理解，B项成立。","references":[],"evidence":"利用造影剂与人体组织在X射线下的密度差异来形成对比","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-186b809ac5e2cfb6":{"review":{"definition":"磁共振成像（MRI）利用磁场和射频脉冲获取人体组织信号，检查本身不使用电离辐射。","explanation":"题中C项的“没有放射性”指没有X射线检查那样的电离辐射暴露。孕妇、婴幼儿在有临床需要且符合检查条件时可以采用磁共振成像，具体仍需评估检查指征和方案。按这一范围理解，C项成立。","references":[],"evidence":"利用磁场和无线电波进行成像","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3bf5185b01878be2":{"review":{"definition":"酵母菌属于真菌，在酒精发酵中可将可发酵糖转化为乙醇和二氧化碳。乳酸菌是一类以产乳酸为特征的细菌。","explanation":"果酒中的乙醇主要来自酵母菌的酒精发酵。A 项用乳酸菌酿造果酒来说明古人利用真菌发酵食物，混淆了微生物类别和主要发酵产物，因此应选 A。","references":[],"evidence":"酒精发酵是由活的酵母菌引起的","disposition":"独立词条","basis":"据原题和解析编释。","title":"酵母菌的酒精发酵","related":[],"examFocus":{"国考 2025 副省级 行测#32":"核对果酒酿造涉及的微生物类别及其主要发酵产物。"}},"readings":[{"origin":"k-3bf5185b01878be2","title":"酵母菌的酒精发酵","qs":["国考 2025 副省级 行测#32"],"definition":"酵母菌属于真菌，在酒精发酵中可将可发酵糖转化为乙醇和二氧化碳。乳酸菌是一类以产乳酸为特征的细菌。","explanation":"果酒中的乙醇主要来自酵母菌的酒精发酵。A 项用乳酸菌酿造果酒来说明古人利用真菌发酵食物，混淆了微生物类别和主要发酵产物，因此应选 A。","evidence":"酒精发酵是由活的酵母菌引起的","doubt":"","references":[]},{"origin":"k-cc656a36cef5cef7","title":"酵母菌的酒精发酵","qs":["国考 2025 地市级 行测#29"],"definition":"酵母菌属于真菌，可通过酒精发酵将糖转化为乙醇和二氧化碳。","explanation":"果酒中的乙醇主要由酵母菌的酒精发酵产生。第29题A项举例时把这一作用归给乳酸菌，因此是应选的错误表述。","evidence":"酒精发酵是由活的酵母菌引起的","doubt":"","references":[]}]},"k-054d85a68659a007":{"review":{"definition":"菌根共生是植物根与真菌形成的共生关系。真菌的菌丝可帮助植物吸收水分和矿质养分，真菌则从植物获得糖类等有机物。","explanation":"菌丝向根周围的土壤延伸，扩大了植物可利用的吸收范围。D 项描述的正是菌丝从土壤吸收水分和无机盐并供给植物这一方向，因此表述正确。","references":[],"evidence":"菌丝吸收水分、无机盐等供给植物","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-88703075b5a71d8e":{"review":{"definition":"在作物适宜的温度范围内，夜间适当降温通常能减弱作物的呼吸作用，减少有机物消耗。","explanation":"作物夜间仍通过呼吸作用消耗有机物。适当降温可减慢这一过程，使白天形成的有机物在夜间保留得更多，因此A项成立。这里的降温以维持作物正常生长为前提。","references":[],"evidence":"夜间降低温室内的温度，可以减少农作物营养物质的消耗","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ca13105551fcf3ea":{"review":{"definition":"温室透光率是进入温室的光照量占室外光照量的百分比。本题按常见情况比较，玻璃温室的透光率通常高于普通塑料温室。","explanation":"B项的“阳光更容易进入”指温室透光率较高。本题采用两类常见温室的一般比较。具体温室的透光率还受覆盖材料的实际透光性能和骨架遮挡等因素影响。","references":[],"evidence":"相比普通塑料温室大棚，玻璃温室可以让阳光更容易进入","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-ea790c55298699b1":{"review":{"definition":"二氧化碳是作物进行光合作用的原料。当光照等条件适宜且二氧化碳供应限制光合作用时，适量补充二氧化碳可促进有机物合成，并有助于增产。","explanation":"D项说的是栽培过程中通入“适量”的二氧化碳。在有足够光照且作物能利用新增二氧化碳的条件下，补充原料可提高光合速率，有利于产量增加，因此D项成立。","references":[],"evidence":"在作物栽培过程中通入适量的二氧化碳可以提高作物产量","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7fef516a0fb2d5c9":{"review":{"definition":"对遵循欧姆定律的电阻器，电流I、电压U和电阻R满足I=U/R。电阻R恒定时，电流与电压成正比。","explanation":"①按电阻恒定处理同一电阻器，因此电流与电压的比例系数固定为1/R，符合正比例关系。","references":[],"evidence":"通过某一电阻器的电流与其两端的电压","disposition":"独立词条","basis":"据原题和解析编释。","title":"欧姆定律","related":[],"examFocus":{"国考 2025 副省级 行测#34":"用欧姆定律判断电流与电压是否成正比时，注意电阻是否保持不变。"}},"readings":[{"origin":"k-7fef516a0fb2d5c9","title":"欧姆定律","qs":["国考 2025 副省级 行测#34"],"definition":"对遵循欧姆定律的电阻器，电流I、电压U和电阻R满足I=U/R。电阻R恒定时，电流与电压成正比。","explanation":"①按电阻恒定处理同一电阻器，因此电流与电压的比例系数固定为1/R，符合正比例关系。","evidence":"通过某一电阻器的电流与其两端的电压","doubt":"","references":[]},{"origin":"k-e3f8523569c1529e","title":"欧姆定律","qs":["国考 2025 行政执法 行测#30"],"definition":"在电阻保持恒定时，通过电阻器的电流与其两端的电压成正比，关系式为 I=U/R。","explanation":"题中①取同一电阻器，按电阻恒定处理。两端电压变为原来的两倍时，电流也变为原来的两倍，因此①符合正比例关系，与③组成D项。","evidence":"通过某一电阻器的电流与其两端的电压","doubt":"","references":[]}]},"k-e838d649693b04db":{"review":{"definition":"物体浸在流体中时，所受浮力等于它排开的流体所受的重力。在流体密度和重力加速度固定时，浮力与排开的流体体积成正比。","explanation":"②给的是物体总体积。在同一均匀液体中完全浸没时，排液体积等于物体总体积，此时两者可成正比。题目未限定浸没情况，排液体积占物体总体积的比例可能变化，所以②无法确立正比例关系。","references":[],"evidence":"等于物体排开的液体所受的重力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-90788618c5f1d8fb":{"review":{"definition":"两人沿同一环形跑道持续反向前进，从同一点出发到首次再次相遇，或从一次相遇到紧邻的下一次相遇，两人所跑路程之和等于一圈。","explanation":"两人的相对位移以各自路程之和累积，合满一圈时再次相遇，中途加速也适用。设甲、乙最初每分钟分别跑2和1个长度单位，则3分钟共跑9个单位，即一圈长9个单位。第二次相遇前乙正好跑半圈，甲也跑半圈，以原速度跑4.5个单位需2.25分钟，即2分15秒。","references":[],"evidence":"又是一圈，而乙正好跑了半圈，则甲跑的路程也为半圈","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4fb3c24c603a03d9":{"review":{"definition":"按同一年龄口径比较同一个人在相隔整年的两个时点的年龄，年龄增量等于相隔的年数。","explanation":"按本题的整岁口径，2034年甲比2024年大10岁。等式两边消去甲在2024年的年龄，得到乙、丙年龄之和为10。乙比丙大，所以乙至少6岁。又因甲比乙大得比乙比丙大更多，甲的年龄须满足甲＞2×乙－丙＝3×乙－10。乙取最小值6时，丙为4，甲必须大于8，取9岁即满足全部条件。","references":[],"evidence":"甲+乙+丙=甲+（2034-2024）","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6031af086dcc5d6a":{"review":{"title":"恒定效率下的工作时间","type":"原理与机制","definition":"对可按工作量计量的单项任务，效率恒定且大于零时，所需时间等于工作量除以效率。","explanation":"收割面积以亩计、效率以亩每小时计，所得时间为小时。停机时段若计入住场时间，须单独相加。","basis":"按公式或逻辑关系推导；适用条件见释义与诠释。","references":[],"basisGroup":"工作量、效率与时间","related":["k-633dda86fead0d4c","k-2b2e3707c004545c"]}},"k-1a1835a35ce67416":{"review":{"definition":"把全部方案分成互不重叠的类别时，各类方案数相加。构成一个方案必须依次完成若干步骤，且每一步的可选数对任一合法的前序选择都相同时，各步可选数相乘。","explanation":"每答完一题都要至少有1分，因此前两题必须都对。第三题对时已有3分，后两题各有两种选择，即使连错也能保有1分，共有2×2＝4种。第三题错时只剩1分，第四题必须答对，第五题仍可对可错，共有1×2＝2种。第三题对或错的两类方案互斥且穷尽，共有4＋2＝6种。","references":[],"evidence":"分类用加法，即共有4+2=6种情况。","disposition":"独立词条","basis":"据原题和解析编释。","title":"加法计数原理与乘法计数原理","related":[],"examFocus":{"国考 2024 地市级 行测#64":"按甲、乙课题的团队数分类，用乘法计算各类内分组并选负责人的方式数，再把各类结果相加。","国考 2025 副省级 行测#72":"按固定题序逐步检查每答完一题的累计得分，再用分类计数统计符合分数下限的作答序列。"}},"readings":[{"origin":"k-1a1835a35ce67416","title":"加法计数原理与乘法计数原理","qs":["国考 2025 副省级 行测#72"],"definition":"把全部方案分成互不重叠的类别时，各类方案数相加。构成一个方案必须依次完成若干步骤，且每一步的可选数对任一合法的前序选择都相同时，各步可选数相乘。","explanation":"每答完一题都要至少有1分，因此前两题必须都对。第三题对时已有3分，后两题各有两种选择，即使连错也能保有1分，共有2×2＝4种。第三题错时只剩1分，第四题必须答对，第五题仍可对可错，共有1×2＝2种。第三题对或错的两类方案互斥且穷尽，共有4＋2＝6种。","evidence":"分类用加法，即共有4+2=6种情况。","doubt":"","references":[]},{"origin":"k-cb9e0fe38b585a4c","title":"加法计数原理与乘法计数原理","qs":["国考 2024 地市级 行测#64"],"definition":"完整方案能划入互斥且穷尽的类别时，将各类方案数相加。逐步完成一项安排时，若每一步在此前任一选法下都有固定数量的选法，将各步选法数相乘。","explanation":"甲、乙课题有区分，人数分配为（2，4）、（4，2）、（3，3），三类互斥且覆盖全部。每组排除组内编号最小的团队后，k 个团队有 k－1 种负责人选法。各类先乘分组选法数和两组负责人选法数，再相加，得到 15×1×3＋15×3×1＋20×2×2＝170。","evidence":"分类用加法，满足条件的共有45+45+80=170种不同的安排方式。","doubt":"","references":[]}]},"k-6565cf5a5e9a8a37":{"review":{"definition":"一个生产者生产某种产品的机会成本低于另一生产者，就在该产品上具有比较优势。机会成本可用生产一单位该产品所放弃的另一种产品产量来衡量。","explanation":"甲每生产1个A模块少产0.5个B模块，乙则少产2个B模块，因此由甲优先生产A。把每天的产量折为B模块当量，每个A计0.5、每个B计1，甲每天最多产3个当量，乙最多产2个。120个A和80个B共需140个当量，至少要28天。前20天甲生产120个A、乙生产40个B，随后两车间合产8天补足40个B，达到这个下限。","references":[],"evidence":"甲车间生产A模块的相对效率更高","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-45392942e1591512":{"review":{"title":"按销量计算总利润","type":"原理与机制","definition":"单件利润等于售价减去成本。每件商品的利润相同时，总利润等于单件利润乘以销量。","explanation":"原题比较打折前后的总利润。打折改变了售价和销量，两个时期要用各自的单件利润和销量分别计算。","basis":"按公式或逻辑关系推导；适用条件见释义与诠释。","references":[],"basisGroup":"利润与成本","related":["k-9ca0533b7efae951","k-14599d5c611e3b87","k-90c98a86d3b2a861"]}},"k-f2b96384a4ff6acb":{"review":{"title":"同底等高的三角形面积相等","type":"原理与机制","definition":"两个三角形共用一条底边，且各自的第三个顶点到这条底边所在直线的距离相等，则这两个三角形的面积相等。","explanation":"三角形的面积等于底与对应高乘积的一半。共底的两个三角形，如果各自的第三个顶点在同一条平行于底边的直线上，对应高就相等。底边分别位于不同线段上时，只要两底等长、对应高相等，面积也相等。","basis":"据关联原题及所列出处编释。","references":[{"source":"geof","location":"附录 C · Triangle，据面积公式推导"}],"related":["k-b120634ad58217c5","k-f1024cecb86a7a82"],"examFocus":{"国考 2025 副省级 行测#78":"在组合图中找共用底边且顶点落在同一条平行于底边的直线上的三角形，用等面积关系重组阴影。","国考 2025 行政执法 行测#73":"在组合图中找共用底边且顶点落在同一条平行于底边的直线上的三角形，用等面积关系重组阴影。"}},"aspects":[{"title":"用平行线判定等高并替换面积","uses":[{"unit":"Q1","role":"解题依据","use":"国考 2025 副省级 行测第78题。直角梯形中，EF∥AB，E、F到共同底边AG所在直线的距离都等于EB，因此可用三角形EAG等面积替换阴影中的三角形FAG。","evidence":"即两个三角形同底等高","qids":["国考 2025 副省级 行测#78"]},{"unit":"Q2","role":"解题依据","use":"国考 2025 行政执法 行测第73题，同题。沿用三角形FAG与EAG的等面积替换。E、G、D共线，替换后的两块拼成三角形EAD，以240米的AD为底，对应高为100米，面积为1.2万平方米，选A。","evidence":"即两个三角形同底等高","qids":["国考 2025 行政执法 行测#73"]}]}]},"k-d73cb19a60baeb11":{"review":{"title":"圆锥与圆柱的体积关系","type":"原理与机制","definition":"等底面积、等高的圆锥体积为圆柱体积的三分之一。","explanation":"底面积同为 S 时，圆锥体积为 Sh锥/3，圆柱体积为 Sh柱。若两者体积相等，则圆锥的高是圆柱的三倍。","basis":"参照所列资料编释；例子和推演用于说明适用条件。","references":[{"source":"geof","location":"附录 C · Cylinder、Cone"}],"basisGroup":"初等几何计算","related":["k-6f0505868fc927aa","k-d9f880b35a6045f2","k-aea49d91fefa42d5"]}},"k-1eae7415f4c11df2":{"review":{"definition":"选择或然率理论用“报偿的保证÷费力的程度”解释受众选择大众传播内容的倾向。报偿的保证指内容满足受众需要的程度，费力的程度指获取内容和使用传播途径的难度。","explanation":"按题给公式，在另一项不变时，内容越能满足受众需求，或获取内容越省力，选择或然率就越高。视频号推荐符合用户偏好的视频，既提高了内容的吸引力，又省去了部分查找时间，所以选A。片前插入两分钟广告增加了等待时间，先注册登录再观看增加了操作步骤。调整畅销商品的摆放位置则属于商品销售安排，超出本题所说的大众传播内容选择的范围。","references":[],"evidence":"选择或然率=报偿的保证/费力的程度","disposition":"独立词条","basis":"据原题和解析编释。","title":"选择或然率理论","related":[],"examFocus":{"国考 2025 副省级 行测#93":"先判断各行为是否涉及受众选择大众传播内容，再按公式比较报偿的保证和费力的程度如何变化。"}},"readings":[{"origin":"k-1eae7415f4c11df2","title":"选择或然率理论","qs":["国考 2025 副省级 行测#93"],"definition":"选择或然率理论用“报偿的保证÷费力的程度”解释受众选择大众传播内容的倾向。报偿的保证指内容满足受众需要的程度，费力的程度指获取内容和使用传播途径的难度。","explanation":"按题给公式，在另一项不变时，内容越能满足受众需求，或获取内容越省力，选择或然率就越高。视频号推荐符合用户偏好的视频，既提高了内容的吸引力，又省去了部分查找时间，所以选A。片前插入两分钟广告增加了等待时间，先注册登录再观看增加了操作步骤。调整畅销商品的摆放位置则属于商品销售安排，超出本题所说的大众传播内容选择的范围。","evidence":"选择或然率=报偿的保证/费力的程度","doubt":"","references":[]},{"origin":"k-407d3242e837e819","title":"选择或然率理论","qs":["国考 2025 行政执法 行测#87"],"definition":"选择或然率理论用“选择或然率=报偿的保证/费力的程度”解释受众对大众传播内容的选择。报偿的保证指内容满足受众需要的程度，费力的程度指获取内容和使用传播途径的难度。","explanation":"依照题给公式，其他条件相同时，内容越符合受众需要，或获取内容越省力，选择或然率就越高。A项按用户偏好推荐视频，既提高内容与需求的匹配度，也省去部分查找 effort。B项的片前广告和D项的注册登录都增加了观看前的步骤或等待时间。C项优化的是商品购买流程，题给公式的对象是大众传播内容。","evidence":"选择或然率=报偿的保证/费力的程度","doubt":"","references":[]}]},"k-fd8bf3a6c75a3668":{"review":{"definition":"相容析取“P或Q”在至少一个支命题为真时为真，只有两个支命题都为假时才为假。","explanation":"甲、乙若都说假话，东面和南面就各有一人说真话，违反全桌只有一人说真话的条件。因此唯一说真话的人在甲、乙之中，丙的“我坐在西面或者北面”为假，西面和北面都可以排除。若丙坐东面，按顺时针顺序丁就坐南面，甲、乙的陈述会同时为真。故丙坐南面，甲坐北面，选A。","references":[],"evidence":"丙说假话意味着，丙不坐在西面也不坐在北面","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b01315126a87f4fb":{"review":{"definition":"如果P能推出Q，Q又能推出R，那么P能推出R。若R由多个并列条件组成，这些条件都随P成立而成立。","explanation":"按题干，能为企业参与出口竞争提供真正的市场根基，就必须具备完备的商业规则环境。要形成这种环境，又必须推进全方位开放并建立全国统一大市场，且加强执法效率和司法保障。串联这两层必要条件，可知其中任一要求未满足，就无法提供题述市场根基，对应D项。C项的要素流动和配置效率要求属于市场体系这条推导链，题干没有给出从商业规则环境推出这些要求的条件。","references":[],"evidence":"将①④串联可得到⑥","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-85d8698fca94eb62":{"review":{"definition":"当“如果P，那么Q”为真且前件P成立时，可以推出后件Q成立。","explanation":"戊、己、庚至少有两人获奖，而庚只有一人，所以戊、己中至少有一人获奖，第（3）条的前件“乙、戊、己至少有1人获奖”随之成立。按原题，第（3）条的后件是“丁获奖而丙不获奖”，因此丁一定获奖，选D。解析第一步把这一后件写成了“丁获奖 且     丙获奖”，后续推理使用的是原题中的“丙不获奖”。","references":[],"evidence":"如果乙、戊、己至少有1人获奖，则丁获奖而丙不获奖。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-69eeda451ea4ac5d":{"review":{"definition":"在统计口径和累计起点一致、各期互不重叠的条件下，后一个时点的累计量等于前一个时点的累计量加上两时点之间各期的发生量之和。","explanation":"第116题求截至2014年末的累计申请量，应从2023年末的累计申请量中扣除2015至2023年各年的申请量。国家知识产权局统计月报表10的“申请”行显示，这九年合计82030件。用题给的93147件减去82030件，得11117件，约1.11万件，落在A项的0.8万至1.5万件之间。","references":[{"source":"web-0a7e11a18e4a6098","location":"第10页，表10，“申请”行，2015年至2023年各列","quote":"集成电路布图设计登记统计表"}],"evidence":"截至2023年末，我国集成电路布图设计登记累计申请93147件","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-a72a1d8ae12a2016":{"review":{"definition":"两个数以同一个非零数为基准时，若已知其中一个数相对基准的倍数，可将该倍数乘以另一个数与已知数的比值，得到另一个数相对基准的倍数。","explanation":"第10届和第15届CMC都以首届参赛人数为基准。将两届各自相对首届的倍数相除，首届参赛人数可以约去。因此，用第10届参赛人数13.88万人除以第15届的28.84万人，再乘以第15届相对首届的倍数10.85，得到约5.22倍，最接近B项的5倍。","references":[],"evidence":"第15届CMC参赛人数是首届的10.85倍，问第10届CMC参赛人数是首届参赛人数的多少倍？","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d80002112469681a":{"review":{"definition":"相邻两期的增量恒定时，从起始期往后推 n 期，预测量等于起始量加上每期增量乘以 n。","explanation":"本题假设以后每届都沿用第15届的环比增量，即每届增加 28.84－23.18＝5.66 万人。以第15届为起点，第18届为 45.82 万人，第19届为 51.48 万人。由于人数逐届增加，第19届首次严格超过 50 万人，对应 A 项。","references":[],"evidence":"28.84+5.66×n>50","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2131d8122d4eaf04":{"review":{"definition":"平均数的同比增长量等于现期平均数减去上年同期平均数。设总量和份数的同比增速分别为 a 和 b，则同比增长量等于现期平均数乘以 (a−b)/(1+a)。","explanation":"把现期总量和份数分别除以 1+a 和 1+b，可还原上年同期数据，因此上年同期平均数等于现期平均数乘以 (1+b)/(1+a)。本题中，支付总金额增长 6.97%，低于业务笔数的增速 12.59%，所以平均每笔金额下降。现期平均每笔金额为 3151.37 万亿元除以 3358.88 亿笔，约为 9382 元，乘以 (6.97%−12.59%)/(1+6.97%)，得到同比减少约 493 元，选 A。","references":[],"evidence":"支付系统共处理支付业务3358.88亿笔，金额3151.37万亿元，同比分别增长12.59%和6.97%。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ae419c6fcf2d8561":{"review":{"title":"平均数同比增长率","type":"原理与机制","definition":"平均数同比增长率是本期平均数相对上年同期平均数的变动比例。平均数等于总量除以单位数，总量和单位数的同比增长率分别为 a 和 b 时，平均数同比增长率为 (a－b)/(1＋b)。","explanation":"计算时，两期总量和单位数须采用一致的统计口径，两期单位数须为正，且上年同期总量须非零。由于 1＋b 为正，平均数是上升、下降还是持平，取决于 a－b 的符号。比较不同对象的平均数同比增速时，各对象的 1＋b 可能不同，须比较完整的比值。","basis":"据关联原题和解析编释。","references":[],"related":["k-7d44fefcbaab9e38"],"examFocus":{"国考 2025 副省级 行测#134":"用四个支付系统各自的业务金额和笔数同比增速，比较平均每笔金额的同比变化。","国考 2025 副省级 行测#135":"根据支付系统的业务金额和笔数变化，区分笔数增速、金额增速与平均每笔金额增速，并核对给定阈值。"}},"aspects":[{"title":"比较平均每笔金额的同比增速","uses":[{"unit":"Q1","role":"直接考查","use":"用2023年三季度四个支付系统各自的业务金额和笔数同比增速计算，①至④的平均每笔业务金额同比增速依次约为－13.71%、－10.44%、1.26%和44.04%，从高到低为④③②①，选C。","evidence":"按2023年三季度平均每笔业务金额同比增速从高到低排列","qids":["国考 2025 副省级 行测#134"]}]},{"title":"核验平均每笔金额的同比增速是否超过给定值","uses":[{"unit":"Q2","role":"解题依据","use":"网上支付跨行清算系统2023年三季度的业务金额同比增长5.38%，笔数同比下降0.03%，平均每笔金额同比增长约5.41%，因此A项可以推出。本题要求选出不能推出的一项，大额实时支付系统的业务金额占人民银行清算总中心系统业务总金额约94.73%，故选C。","evidence":"网上支付跨行清算系统处理业务平均每笔金额同比增长了5%以上","qids":["国考 2025 副省级 行测#135"]}]}]},"k-6f8d0994e0958479":{"review":{"definition":"宣化葡萄漏斗架是一种架身向上倾斜、呈放射状展开的传统栽培架式，整体呈内方外圆的漏斗形。","explanation":"据材料，放射状架式能充分利用空间、增强光合作用，从而提高果实品质。漏斗结构还有助于抵抗风沙、减弱雨水对地表的冲击，从而保护水土、涵养水源。本题据此概括传统栽培技艺在果实生产和水土保护两方面的作用。","references":[],"evidence":"形成“内方外圆”的漏斗架","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-5d18c8ddef827886":{"review":{"definition":"宣化葡萄园的冠层吸收和反射太阳辐射，葡萄叶通过蒸腾向空气释放水分，共同形成低辐射、低气温、高湿度的庭园小环境。","explanation":"架下阴凉湿润，适宜种植喜阴植物，可为果农增加收入。材料还指出，葡萄架本身占地少，架下可以留出较大的活动空间。本题的“利用小环境气候”要点涵盖了架下种植和庭园活动两种用途。","references":[],"evidence":"创造出低辐射、低气温、高湿度的小环境","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-c8d6eb725f5b7377":{"review":{"definition":"多年生葡萄藤可在存活期间将一部分碳长期保存在植株中。修剪物和凋落物回归土壤，可向土壤补充有机碳。","explanation":"材料中的葡萄藤寿命可达数十年乃至数百年，植株寿命越长，体内储存的碳就有可能保留越久。修剪物和凋落物归土则补充土壤有机碳损失。本题据此从植株储碳和土壤有机碳补充两个方面归纳葡萄园的碳库作用。","references":[],"evidence":"寿命长意味着植物体内储存的碳能够保留更长时间","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-27fb2b8595135822":{"review":{"definition":"虑远科技研发的城市排涝指挥控制系统可实时监测泵站运行，并向监控人员推送数据和预警。智慧河道云平台则可向“企业河监”自动报警，并将已上报的污染信息分送有关责任部门。","explanation":"企业针对人工观测泵站费时且精度不足的问题研发排涝系统，得到区政府肯定。智慧河道云平台由企业受政府委托开展数据采集并开发，在万仑河试用成功后，新杭市决定向全市推广。两项实践共同支撑本题“合作建设智慧系统”的要点。","references":[],"evidence":"系统就会把信息分别传送给相关责任部门","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-f6786866c10fd4e5":{"review":{"definition":"雨污分流是在排水源头采用分开的管网输送雨水和污水，从而减轻雨水进入污水管道和截污设施造成的负荷。","explanation":"万仑河原先采用末端截污，专家实地调研发现，暴雨时管道截不住污水。虑远科技参与研讨并综合专家意见，提出从源头实行雨污分流，埠西区政府再次组织专家论证后决定实施改造。这一过程体现了本题中企业提案、政府论证并组织实施的协作方式。","references":[],"evidence":"建议从源头抓起，实现雨污分流","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3f87be7b67fe1931":{"review":{"definition":"村集体提供林地资源，国有林场发挥专业种植、抚育和管护能力，双方按约分享经营收益。对管护不足的林地，专业化经营有助于提高出材量和经营效益。","explanation":"新坡村瓦司坑山场原先抚育、管护不到位，村集体把山场交由国有林场合作经营，约定新坡村获得85%的收益分红。江口村农户万名忠与国有林场合作后，首轮采伐售出300多立方米木材，自家分得6万多元。前一事例交代经营方式和收益分配，后一事例提供实际增收的依据，对应本题的“提升经营效益”。","references":[],"evidence":"通过合作，林地的经营效益能大大提高。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-79315705b1928158":{"review":{"definition":"科研为科普提供科学知识、方法和成果。科普在帮助公众理解科学、促进成果推广的同时，也能通过双向交流把公众的疑问和需求反馈给科研人员，为研究提供线索。","explanation":"材料中庚以玉米秸秆高效合成人造淀粉和单细胞蛋白质为例，说明科普中遇到的公众困惑可以启发科研，研究成果也可借科普增进公众了解。提案据此建议通过线上对话、线下讲座等方式，让公众有机会向科学家提出问题和表达需求。","references":[],"evidence":"正是缘于科普过程中公众困惑所带来的启\n示","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d9b3d8f3644a35c2":{"review":{"definition":"互补是指事物或主体发挥各自的特点与优势，在相互作用中补足彼此的不足、激发彼此的潜力，从而促进共同发展。","explanation":"本题要求论证互补如何产生增益。以材料2为例，治水需求促使虑远科技明确数字治水的发展方向，企业提供的排查数据和技术方案又提升了政府的治水能力。写作时可沿着这两条作用链展开，说明各方分别提供了什么、对方由此获得了什么。","references":[],"evidence":"互相作用、互相激发、互相促进的机制","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e5c94d5d20f83e29":{"review":{"title":"人民的创造性实践与理论创新","type":"原理与机制","definition":"人民群众在社会实践中创造物质财富和精神财富。人民的创造性实践是马克思主义理论创新的不竭源泉。","explanation":"习近平在2023年6月30日二十届中央政治局第六次集体学习时强调，要尊重人民首创精神，从人民的创造性实践中总结新鲜经验，将其上升为理性认识，提炼出新的理论成果。","basis":"据关联原题及所列出处编释。","references":[{"source":"ideology","location":"人民的创造性实践"}],"related":["k-253af8e175729959","k-1147d5c7af105768"],"domain":"哲学","examFocus":{"国考 2025 地市级 行测#1":"依据题干论述，辨别实践中的首创主体，以及实践经验与理论创新之间的先后和来源关系。"}},"aspects":[{"title":"理论创新的实践源泉","uses":[{"unit":"Q1","role":"直接考查","use":"①确认人民群众创造物质财富和精神财富，③将毛泽东思想、中国特色社会主义理论体系和习近平新时代中国特色社会主义思想的源泉归于人民的智慧、探索和创造。②把首创主体换成理论工作者，并颠倒从实践经验到理论成果的顺序。④把身处实践最前沿的主体由人民群众换成各级领导干部。选B（①③）。","evidence":"人民的创造性实践是马克思主义理论创新的不竭源泉。","qids":["国考 2025 地市级 行测#1","国考 2025 行政执法 行测#1"]}]}]},"k-acc5d65138a2d1be":{"review":{"definition":"安培假设物质微粒内部存在环形电流，即分子电流，使微粒表现得像微小磁体。","explanation":"按这一假说，分子电流取向杂乱时，各微粒的磁效应可相互抵消。取向趋于一致时，物体可表现出宏观磁性。第27题B项用微粒内部的环形电流解释微粒磁性，与安培的观点对应正确。","references":[],"evidence":"分子电流假说是安培提出的电磁学理论","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-940d02176bad177c":{"review":{"definition":"两个质点沿连心线相互吸引，引力大小与两者质量的乘积成正比，与质点间距离的平方成反比。","explanation":"质量不变时，距离变为原来的两倍，引力变为原来的四分之一。第27题C项的质量乘积和距离平方关系对应牛顿的万有引力定律，其中比例关系以两个质点为表述对象。","references":[],"evidence":"这种力的大小与它们质量的乘积成正比，与它们之间的距离的平方成反比","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e93b36ad4839b5bc":{"review":{"definition":"伽利略通过斜面实验和推理指出，物体可以在没有力维持的情况下保持运动，阻力会使运动的物体减速。","explanation":"斜面实验的推理把物体最终停下归因于阻力。第27题D项所说的运动无需力来维持、物体因受阻而停止，与伽利略的观点对应正确。","references":[],"evidence":"运动的物体之所以会停下来，是因为受到了阻力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a3a53f22cea89a37":{"review":{"definition":"人民币对美元贬值时，兑换同样多的美元需要更多人民币。因此，美元金额固定的支出折算成人民币后会增加。","explanation":"第28题C项中的“人民币汇率降低”，按解析指人民币对美元贬值。美国学校以美元计收的学费金额若保持不变，留学生兑换学费所需的人民币就会增加，因此C项所说的学费降低在这一条件下不成立。","references":[],"evidence":"人民币贬值，美元相对升值","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d6f88a4c4154fd57":{"review":{"definition":"增值税以流转环节的增值额为征税对象。在适用进项税额抵扣的情形下，应纳税额按销项税额减去可抵扣的进项税额计算。","explanation":"抵扣使上游环节已征税的部分在下游环节避免重复征税。营业税按营业额计征。第28题D项把避免重复征税的特点归给营业税，颠倒了两种税的区别。","references":[],"evidence":"它只对每个环节的增值部分征税。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-02af7d6a17a69018":{"review":{"definition":"尿素呼气试验通过检测呼气中的标记二氧化碳，判断是否存在当前的幽门螺杆菌感染。","explanation":"幽门螺杆菌产生的尿素酶可分解标记尿素，生成能在呼气中检出的标记二氧化碳。血清抗体在感染消除后仍可能持续存在，单凭抗体阳性难以区分既往感染与现症感染，因此D项将血清检查称为判断感染的最佳方法有误。","references":[],"evidence":"如C-13或C-14尿素呼气试验","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f5db52e381dadaae":{"review":{"definition":"动能是物体因运动而具有的能，重力势能与物体在重力场中的位置有关。物体质量一定时，速度越大，动能越大。在近地面采用同一参考面时，高度越高，重力势能越大。","explanation":"按解析采用的皮筏下行、降低高度并加速的情形，皮筏的重力势能减少、动能增大，A项把转化方向说反了。本题要求选错误项。实际顺流航行时，皮筏的速度变化还取决于水流和阻力等条件。","references":[],"evidence":"皮筏在顺流而下的过程中动能转化为重力势能","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4f0ccba171d29d0b":{"review":{"definition":"已知总量和各部分之比，且这些部分合起来等于总量时，各部分的量等于总量乘以该部分份数占总份数的比例。","explanation":"员工只在部门之间调动，总人数仍为210。调动后的甲、丙、丁共占10份，每份21人，因此甲63人、丁84人。甲人数未变，原丁比甲少10人，原有53人。乙并入丁的人数为84−53＝31，再加上调到丙的20人，原乙共有51人。","references":[],"evidence":"甲、丙、丁三个部门的员工数之比为3：3：4","disposition":"独立词条","basis":"据原题和解析编释。","title":"按比例分配","related":[],"examFocus":{"国考 2023 副省级 行测#73":"把公司总利润、可分配利润和个人分红分开，利用分配比例固定的条件比较各年利润和甲的分红。","国考 2025 地市级 行测#67":"用总人数和调动后的比例确定各部门现有人数，再比较调动前后的人数，追踪原乙部门员工的去向。"}},"readings":[{"origin":"k-4f0ccba171d29d0b","title":"按比例分配","qs":["国考 2025 地市级 行测#67"],"definition":"已知总量和各部分之比，且这些部分合起来等于总量时，各部分的量等于总量乘以该部分份数占总份数的比例。","explanation":"员工只在部门之间调动，总人数仍为210。调动后的甲、丙、丁共占10份，每份21人，因此甲63人、丁84人。甲人数未变，原丁比甲少10人，原有53人。乙并入丁的人数为84−53＝31，再加上调到丙的20人，原乙共有51人。","evidence":"甲、丙、丁三个部门的员工数之比为3：3：4","doubt":"","references":[]},{"origin":"k-a4296054a0813f27","title":"按比例分配","qs":["国考 2025 行政执法 行测#67"],"definition":"已知总量和各部分的比时，先用总量除以总份数求出每份的量，再乘以各部分对应的份数。","explanation":"员工调动只改变部门归属，总人数仍为210人。调动后甲、丙、丁共有3＋3＋4＝10份，每份21人，甲有63人，丁有84人。甲的人数未变，原来比丁多10人，所以原丁有53人。丁增加的31人与调到丙的20人都来自乙，因此原乙有51人，选C。","evidence":"甲、丙、丁三个部门的员工数之比为3：3：4","doubt":"","references":[]},{"origin":"k-b186dfe3d16fad0d","title":"按比例分配","qs":["国考 2023 地市级 行测#68"],"definition":"按比例分配时，个人所得等于可分配总量乘以个人在分配依据中所占的比例。","explanation":"按本题约定，个人分红等于当年利润乘以40%，再乘以个人投资占比。甲各年的分配系数相同，因此其第二年分红是第三年的一半，意味着第二年利润也是第三年的一半。第三年比第二年多300万元，故两年利润分别为600万元和300万元，第一年利润为600÷3＝200万元。第二年比第一年多出的100万元利润中，有40万元用于分配，甲从中多得20万元，故甲的投资占比为50%，乙的投资占比也为50%，选B。","evidence":"40%按二人投资比例分配","doubt":"","references":[]},{"origin":"k-ce58fd32d8d4d9e9","title":"按比例分配","qs":["国考 2023 副省级 行测#73"],"definition":"按比例分配时，个人所得等于可分配总量乘以个人所占比例。若只拿出总量的一部分分配，先按约定比例求出可分配总量。","explanation":"本题每年只拿出利润的40%分红，甲的投资占比也固定，所以甲的分红始终等于当年利润乘以同一个系数。甲第二年的分红是第三年的一半，第二年利润也就是第三年的一半。结合两年利润相差300万元，得第二年和第三年利润分别为300万元和600万元，第一年利润为200万元。前两年可分配利润相差40万元，甲多分得20万元，故甲、乙各占50%，对应B项。","evidence":"40%按二人投资比例分配","doubt":"","references":[]}]},"k-a8ceef62476bb9dd":{"review":{"definition":"按销量分段计价且各段单价固定时，累计销售收入等于各段已售数量与对应单价乘积之和。以销量为横轴、累计销售收入为纵轴，每段图线的斜率等于该段单价。","explanation":"第68题中，销量为0时收入为0。每个区间内，收入随销量匀速增加，图线在60千克和120千克处连续衔接。三段单价依次为原单价的20%、50%和100%，所以图线由三段越来越陡的直线组成，对应A项。","references":[],"evidence":"出售60千克该种试剂打2折的收入一定低于打5折的收入","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2855a7e496b811b6":{"review":{"definition":"把一个集合划分为互不重叠且合起来覆盖全体的若干部分，集合的总人数等于各部分人数之和。","explanation":"全单位三项认证都没有的有65×20%=13人。「没有甲认证」与「有乙认证」两组人数相等，且都包含仅有乙、仅有乙和丙这两部分。消去这两部分后，前一组剩下仅有丙的3人和三项都没有的13人，后一组剩下仅有甲和乙的人以及三项都有的6人。因此仅有甲和乙的有3+13−6=10人，选A。","references":[],"evidence":"没有甲认证的职工与有乙认证的职工人数一样多","disposition":"独立词条","basis":"据原题和解析编释。","title":"集合的互斥分区计数","related":[],"examFocus":{"国考 2024 行政执法 行测#67":"按掌握语言的组合划分互斥区域，结合包含关系和两个“一半”的条件，确定会法语的人数应汇总哪些区域。","国考 2025 地市级 行测#69":"用至少持有一项认证的比例确定三项都没有的人数，再按互斥区域比较“没有甲”和“有乙”两组的构成。"}},"readings":[{"origin":"k-2855a7e496b811b6","title":"集合的互斥分区计数","qs":["国考 2025 地市级 行测#69"],"definition":"把一个集合划分为互不重叠且合起来覆盖全体的若干部分，集合的总人数等于各部分人数之和。","explanation":"全单位三项认证都没有的有65×20%=13人。「没有甲认证」与「有乙认证」两组人数相等，且都包含仅有乙、仅有乙和丙这两部分。消去这两部分后，前一组剩下仅有丙的3人和三项都没有的13人，后一组剩下仅有甲和乙的人以及三项都有的6人。因此仅有甲和乙的有3+13−6=10人，选A。","evidence":"没有甲认证的职工与有乙认证的职工人数一样多","doubt":"","references":[]},{"origin":"k-558a3350b0f6e48a","title":"集合的互斥分区计数","qs":["国考 2024 行政执法 行测#67"],"definition":"把有限集合划分为彼此不重叠且合起来覆盖全体的若干部分，总人数等于各部分人数之和。","explanation":"会俄语者都在英语集合内，且其中一半会法语，因此三语都会的50人对应只会俄语和英语的50人。在只会两种语言的100人中，其余50人只会英语和法语。会英语且会法语的共100人，占会英语者的一半，所以会英语的共200人，其中只会英语的有50人。只会一种语言的150人扣除这50人，剩下100人只会法语。把只会法语、只会英语和法语、三语都会这三个互斥分区相加，得到会法语的共有200人。","evidence":"会法语的学生有100+50+50=200人","doubt":"","references":[]}]},"k-5dc6f7bab5ea7821":{"review":{"definition":"两个立体几何图形相似时，体积比等于对应长度之比的立方。","explanation":"液面尚在倒立圆锥段内时，水体与整个圆锥共顶点，液面平行于圆锥底面，两者是相似圆锥。1分钟时水深6厘米，是锥高12厘米的一半，所以此时水量是整个锥段容积的1/8。按恒定流量注水，锥段从空到满共需8分钟。","references":[],"evidence":"在立体几何中，体积比等于相似比的立方","disposition":"独立词条","basis":"据原题和解析编释。","title":"相似立体的体积比","related":[],"examFocus":{"国考 2023 副省级 行测#75":"用漂浮平衡比较圆锥在两种液体中的浸没体积，再用相似圆锥的体积比联系尖部朝上时的露出高度。","国考 2025 副省级 行测#80":"用相似圆锥的体积比把初始水深换成水量，再根据恒定流量区分锥段和柱段的注水时间。"}},"readings":[{"origin":"k-5dc6f7bab5ea7821","title":"相似立体的体积比","qs":["国考 2025 地市级 行测#75"],"definition":"两个立体几何图形相似时，体积比等于对应长度之比的立方。","explanation":"液面尚在倒立圆锥段内时，水体与整个圆锥共顶点，液面平行于圆锥底面，两者是相似圆锥。1分钟时水深6厘米，是锥高12厘米的一半，所以此时水量是整个锥段容积的1/8。按恒定流量注水，锥段从空到满共需8分钟。","evidence":"在立体几何中，体积比等于相似比的立方","doubt":"","references":[]},{"origin":"k-7bd0239dc6dddb58","title":"相似立体的体积比","qs":["国考 2025 副省级 行测#80"],"definition":"两个相似立体的体积比等于对应长度之比的立方。","explanation":"注水1分钟后，水在倒立圆锥内形成高6厘米的小圆锥，与高12厘米的整个圆锥相似。高度比为1∶2，体积比即为1∶8。匀速注水时，注入体积与用时成正比，因此注满圆锥共需8分钟，余下23分钟用于注满圆柱。圆锥与圆柱底面积相等，而圆锥体积等于底面积乘高的三分之一，所以圆柱高为(12÷3)×(23÷8)=11.5厘米，容器总高23.5厘米，选D。","evidence":"体积比等于相似比的立方","doubt":"","references":[]},{"origin":"k-8f4f2cb30a136f36","title":"相似立体的体积比","qs":["国考 2023 副省级 行测#75"],"definition":"两个相似立体的体积比等于对应长度之比的立方。已知体积比时，可开立方求对应长度之比。","explanation":"题设圆锥轴线竖直，液面与底面平行，液面截出的带尖部分与整个圆锥相似。尖部朝下时，液面下的小圆锥高为0.9x，体积占0.9³＝0.729。按两种液体的密度和漂浮平衡换算，尖部朝上时浸没体积占0.486，露出的小圆锥体积占0.514。由于0.514大于0.8³＝0.512，露出高度超过0.8x，对应A项。","evidence":"其与实心圆锥零件整体相似","doubt":"","references":[]}]},"k-140ee985f068dbf7":{"review":{"definition":"单位时间注入的体积恒定时，各时段的注水体积与该时段的时长成正比。","explanation":"从开始注水到注满共31分钟。锥段注满用8分钟，柱段用23分钟，两段容积之比为8∶23。两段的底面积相同，12厘米高的圆锥容积等于同底、4厘米高的圆柱容积，因此上部圆柱高4×23÷8=11.5厘米，容器总高23.5厘米，选D。","references":[],"evidence":"现匀速向容器中注入水，1分钟后液面高6厘米，又过30分钟后注满。","disposition":"独立词条","basis":"据原题和解析编释。","title":"恒定流量下的注水体积","related":[],"examFocus":{"国考 2025 副省级 行测#80":"用相似圆锥的体积关系比较锥段不同液面下的水量，再用匀速注水的时间关系比较锥段和柱段的容积。"}},"readings":[{"origin":"k-140ee985f068dbf7","title":"恒定流量下的注水体积","qs":["国考 2025 地市级 行测#75"],"definition":"单位时间注入的体积恒定时，各时段的注水体积与该时段的时长成正比。","explanation":"从开始注水到注满共31分钟。锥段注满用8分钟，柱段用23分钟，两段容积之比为8∶23。两段的底面积相同，12厘米高的圆锥容积等于同底、4厘米高的圆柱容积，因此上部圆柱高4×23÷8=11.5厘米，容器总高23.5厘米，选D。","evidence":"现匀速向容器中注入水，1分钟后液面高6厘米，又过30分钟后注满。","doubt":"","references":[]},{"origin":"k-50b1a8f4b93c6fec","title":"恒定流量下的注水体积","qs":["国考 2025 副省级 行测#80","江苏 2024 C类 行测#58"],"definition":"体积流量恒定时，注入体积等于体积流量乘以时间。","explanation":"体积流量以升每分钟等单位表示。若同时排水，应使用净流量求容器中增加的水量；水面上升速度还取决于截面积。","evidence":"","doubt":"","references":[]}]},"k-f3209d8bfe96ded2":{"review":{"definition":"各期增加的数量相同时，经过若干期后的数值等于起始量加上期数乘以每期增量。","explanation":"2023年的同比增量为93.55－81.24＝12.31万件。以2023年的93.55万件为起点，每年增加12.31万件。题目要求“首次超过”，因此要找使93.55＋12.31n＞150成立的最小整数期数。4年后为142.79万件，5年后为155.10万件，所以首次超过150万件的是2028年，选C。","references":[],"evidence":"现期量=基期量＋n×增长量","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-401178f443db6efc":{"review":{"definition":"A市设立市级科技成果转化专班，主动对接高校院所，组织开展科研成果的发现、挖掘、策划和转化工作。","explanation":"专班常态化走访高校和实验室，及早发现有应用潜力的成果，并把成果挖掘和转化策划衔接起来。方教授团队研发的自动化生产线可用于新能源汽车锂电池回收，团队借助专班支持推动成果走向市场。这个案例对应参考答案中的“促成科技成果转化”。","references":[],"evidence":"深度对接市内外高校院所，全力做好科技成果发现、挖掘、策划、转化工作。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-95474fd31b47800c":{"review":{"definition":"龙腾工业互联网平台通过定期推送成果转化项目、对接产业链供需，帮助A市获取项目来源，推动优质项目洽谈和落地。","explanation":"定期推送让A市持续获得项目线索，供需对接则为筛选重点项目、安排洽谈提供渠道。远达信息技术有限公司经平台牵线接触A市，随后正式入驻，说明本题为什么把搭建平台概括为促进科技招商的做法。","references":[],"evidence":"成果转化项目定期推送、产业链供需互促对接机制","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-8c7eb34006157fbd":{"review":{"definition":"产业园区集群通过园区建设促进同一行业或相关产业的企业集聚，为企业开展分工协作和共享基础设施、配套服务创造条件。","explanation":"企业集聚便于上下游对接、形成产业链，有助于提高竞争力和创新能力。共享园区设施和服务可以减少企业各自建设和维护配套的支出。A市建设了健康大数据产业园、生物医药园等园区，作答时可将园区建设、企业协同和共享配套归入同一做法。","references":[],"evidence":"企业可以共享园区提供的基础设施和配套服务，大大降低了成本。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6f0c9645422163f1":{"review":{"definition":"源头减量是通过改进生产工艺、调整投入材料等方式，减少废物的产生。资源循环利用是让可回用的资源再次投入使用，减少新增资源消耗。","explanation":"申论第4题中，西瑞药业循环使用大部分生产用水，每日用水量节约一半以上，体现了资源循环利用。制瓶工艺优化后废气产生量下降，替换滤料后废活性炭减少，体现了生产源头减排减废。谈话提纲可把这些写成已取得的成效，生产用水100%回收利用和制瓶工序不产生废气则仍是拟实现的目标。","references":[],"evidence":"生产用水大部分能循环使用，每天用水量节约一半以上。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a34bcf0437195dd3":{"review":{"definition":"马克思主义历史观认为，人民群众是社会历史的主体，是物质财富和精神财富的创造者。人民群众的创造性实践为理论创新提供经验和智慧。","explanation":"行测第1题问与题干论述相符的说法。①直接体现人民群众创造物质财富和精神财富，③把党的理论成果同人民的智慧、探索和创造联系起来，所以选B。②把首创主体换成理论工作者，并颠倒了从人民实践中总结经验、提炼理论的方向。④把身处实践最前沿的主体换成各级领导干部。","references":[],"evidence":"人民不仅是物质财富的创造者，也是精神财富的创造者","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5c6f76b55ea1004a":{"review":{"definition":"商品价值量是商品价值的大小，由生产该商品的社会必要劳动时间决定。社会必要劳动时间是在现有社会正常生产条件下，以社会平均劳动熟练程度和劳动强度生产某种使用价值所需的时间。","explanation":"同一种商品的生产者可能各有不同的实际耗时，商品价值量以社会通常生产条件下所需的劳动时间为准。第3题A项把决定因素写成个别劳动时间，因此错误。","references":[],"evidence":"由生产商品的社会必要劳动时间决定的","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"14620c148b758944","label":"商品经济理论 · 商品价值量","topic":"马克思主义政治经济学","category":"非时政","text":"三、商品价值量\n商品的价值量是指商品价值的大小，是由社会必要劳动时间决定的。\n单位商品的价值量与生产该商品的社会必要劳动时间成正比，与社会劳动生产率成反比。","source":{"doc":"3ccc56f4000d1642c2d1","first":8,"last":8,"page":8,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-44971555426a027d":{"review":{"definition":"太阳直射北半球时，在仍有日出和日落的北半球地区，同一天纬度越高，昼越长、夜越短。这是因为纬度越高，一天中随地球自转经过受光区域的时间越长。","explanation":"用日落时刻减去日出时刻，左图城市从06:31到21:56，昼长15小时25分。右图城市从04:55到19:02，昼长14小时07分。题设为我国两地的同一个夏日，左图城市昼长多1小时18分，因此纬度更高，A项正确。","references":[],"evidence":"在夏季，北半球纬度越高，昼越长，夜越短。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ae3f24e15811b60c":{"review":{"definition":"在弹簧的线性弹性范围内，使弹簧伸长的拉力大小与伸长量成正比，关系式为 F=kx，其中 k 是弹簧的劲度系数。","explanation":"题中③给出“弹性限度内”的条件，按胡克定律适用的范围理解。同一弹簧的劲度系数固定，拉力变为原来的两倍时，相对于原长的伸长量也变为原来的两倍，因此③符合题意。","references":[],"evidence":"弹性限度内弹簧的伸长量与其所受拉力","disposition":"独立词条","basis":"据原题和解析编释。","title":"胡克定律","related":[],"examFocus":{"国考 2025 副省级 行测#34":"用胡克定律判断拉力与伸长量的关系时，要核对弹簧的适用条件，并区分伸长量和弹簧总长度。"}},"readings":[{"origin":"k-ae3f24e15811b60c","title":"胡克定律","qs":["国考 2025 行政执法 行测#30"],"definition":"在弹簧的线性弹性范围内，使弹簧伸长的拉力大小与伸长量成正比，关系式为 F=kx，其中 k 是弹簧的劲度系数。","explanation":"题中③给出“弹性限度内”的条件，按胡克定律适用的范围理解。同一弹簧的劲度系数固定，拉力变为原来的两倍时，相对于原长的伸长量也变为原来的两倍，因此③符合题意。","evidence":"弹性限度内弹簧的伸长量与其所受拉力","doubt":"","references":[]},{"origin":"k-d87d534043ced99f","title":"胡克定律","qs":["国考 2025 副省级 行测#34"],"definition":"在线性弹性范围内，同一弹簧的伸长量x与使它伸长的拉力大小F成正比，即F=kx，其中k为弹簧的劲度系数。","explanation":"③按教材题常用的理想弹簧模型处理，题中的“弹性限度内”按胡克定律适用的范围理解，伸长量与拉力的比例系数为1/k，所以③成立。对实际弹簧，严格的正比关系取决于形变是否仍在线性范围内。","evidence":"弹性限度内弹簧的伸长量与其所受拉力","doubt":"","references":[]}]},"k-a4da0e61ebb55c7c":{"review":{"definition":"在同一统计范围内，至少满足一项条件与所有条件均不满足是互补的两种情况。两类人数之和等于总人数，占比之和为100%。","explanation":"本题65名职工中，至少拥有一项认证的占80%，所以三项认证均无的有65×20%=13人。把“没有甲认证”和“有乙认证”两组中的共同人员扣除，前一组剩下仅有丙认证的3人和三项认证均无的13人，后一组剩下仅有甲、乙两项认证的人和三项认证都有的6人。两组人数相等，所以仅有甲、乙两项认证的有3+13−6=10人，选A。","references":[],"evidence":"拥有甲、乙、丙三项认证中至少一项的职工正好占80%","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e20d279329469aaa":{"review":{"definition":"长方体一个面的面积等于该面两条相邻棱长的乘积。若三个方向的棱长依次为 a≥b≥c，则三种面的面积满足 ab≥ac≥bc。","explanation":"本题最小面的长和宽分别为 b、c，所求是 b/c。最大面面积 ab 是最小面面积 bc 的 3 倍，因此两者的面积平均值为 2bc。次大面面积 ac 是这个平均值的 9/16，即 9bc/8。最大面和次大面共用棱长 a，面积相除即可求得 b/c＝ab/ac＝8/3，对应 C 项。","references":[],"evidence":"最大面的面积为ab、次大面的面积为ac","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a34373d73f5dc71e":{"review":{"definition":"每期增量固定时，从起点经过 n 期的数量等于起点数量加上 n 倍的单期增量，其中 n 为非负整数。","explanation":"每过一年都加上同一个增量，因此累计增量等于年数乘以单年增量。本题以 2023 年的 93.55 万件为起点，按 2023 年同比增量 93.55－81.24＝12.31 万件逐年推算。题干要求首次超过 150 万件，因此取使 93.55＋12.31×n＞150 成立的最小整数 n。2027 年为 142.79 万件，2028 年为 155.10 万件，故选 C。","references":[],"evidence":"93.55＋n×12.31>150","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-71ea02242be9917b":{"review":{"definition":"饼状图中，每个扇区的圆心角等于其对应部分占总体的比重乘以360°。各部分共用同一总体时，数量越大，对应扇区越大。","explanation":"第125题以五批次公示的上市企业合计882家为总体。第四批有282家，数量最多，白色扇区应最大。第五批有134家，少于第二批的198家，网格扇区应小于横线扇区。B项还符合五个扇区的近似占比，按批次依次约为4%、22%、26%、32%和15%。","references":[],"evidence":"根据第四批次公示上市企业数量（282家）最多，可知第四批次（白色）占比最大","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1affb1ac8e1f545e":{"review":{"definition":"两期平均数的差值是现期平均数减去基期平均数。若平均数等于总量除以数量，总量和数量相对同一基期的增速分别为 a 和 b，则两期差值等于现期平均数乘以 (a−b)/(1+a)。","explanation":"将现期总量除以 1+a、现期数量除以 1+b，可还原基期的总量和数量。因此，基期平均数等于现期平均数乘以 (1+b)/(1+a)，用现期值减去基期值即可得到差值。第126题中，金额同比增长 6.97%，低于笔数的 12.59%，所以平均每笔金额下降。将万亿元除以亿笔后乘以 10000，得到现期平均每笔约 9382 元，再代入公式得差值约为 −493 元，对应 A 项“下降了不到1000元”。","references":[],"evidence":"支付系统共处理支付业务3358.88亿笔，金额3151.37万亿元，同比分别增长12.59%和6.97%。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7d44fefcbaab9e38":{"review":{"title":"平均数的增长率","type":"原理与机制","definition":"平均数的增长率是现期平均数相对基期平均数的变化比例。若两期统计口径一致，且分子、分母在两期均为正，分子和分母的增长率分别为 a 和 b，则平均数增长率为 (a−b)/(1+b)。","explanation":"由于 1+b 为正，a 大于、等于或小于 b 分别对应平均数上升、持平或下降。下降率以负值代入。比较多个对象的平均数增长率时，各对象的 1+b 可能不同，须比较完整的比值。","basis":"据关联原题和解析编释。","references":[],"related":["k-ae419c6fcf2d8561"],"examFocus":{"国考 2025 行政执法 行测#129":"用各支付系统的总金额和总笔数同比增速推算每笔金额同比增速，再按推算值排序。","国考 2025 行政执法 行测#130":"用同一支付系统的金额和笔数同比增速推算每笔金额的增速，再与题设阈值比较。"}},"aspects":[{"title":"平均数增长率排序","uses":[{"unit":"Q1","role":"直接考查","use":"以业务金额为分子、业务笔数为分母，算得①至④的平均每笔业务金额同比增速约为 −13.71%、−10.44%、1.26%和44.04%。④的金额和笔数均下降，且笔数降幅更大，每笔金额增速居首。降序为④③②①，选C。","evidence":"按2023年三季度平均每笔业务金额同比增速从高到低排列","qids":["国考 2025 行政执法 行测#129"]}]},{"title":"平均数增长率的阈值核验","uses":[{"unit":"Q2","role":"解题依据","use":"网上支付跨行清算系统的业务金额同比增长5.38%，笔数同比下降0.03%，每笔金额同比增长约5.41%，所以A项可以推出。本题要求选出不能推出的一项，C项所述占比实际约为94.73%，低于95%，故选C。","evidence":"网上支付跨行清算系统处理业务平均每笔金额同比增长了5%以上","qids":["国考 2025 行政执法 行测#130"]}]}]},"k-ae81e4878609c2ca":{"review":{"definition":"农业文化遗产中的生产体系和传统技术依赖当地自然条件和社会经济条件。活态传承允许在保有遗产系统基本结构与功能的前提下作适当调整。","explanation":"遗产系统中的物种、农业景观和水土资源管理技术与当地条件相互配合。D项说当地居民至今仍在使用这种生产方式，体现活态传承。C项把当地可持续使用的具体体系说成能在各地直接照搬，忽略了适用条件，因此是本题应选的不正确项。","references":[],"evidence":"而不能普遍地直接推广应用","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b5ddb378c57bf659":{"review":{"definition":"公共服务标准化是通过制定和实施统一标准，明确公共服务的内容、流程和质量要求，使服务提供有共同依据。","explanation":"江苏 2023 A类行测第14题中，统一后的“马”字保留了秦国字形的主要特征。秦以已有文字为基础规范通行写法，解决各地书写不一致给治理带来的困难。对应到公共服务，就是把服务提供什么、应达到什么要求明确为共同标准，因此选D。D项的“以规范服务内容为核心”概括的是本题类比。“马”字图示无法证明增加服务环节是必经阶段，也无法据字形的易辨性或美观程度确定标准化的根本导向或最终目标。","references":[],"evidence":"说明公共服务标准化以规范服务内容为核心","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-a7258b048ebe44d3":{"review":{"definition":"从整体目标出发，分析各部分之间以及整体与环境之间的相互作用，据此判断各部分对整体的影响。","explanation":"图中两条上游河道在丙处汇合后共用下游河道，丙处的通水状况关系到两条上游河道来水汇合后的排泄。专家从整个河段的治水需要出发，依据各河段的连通关系选定丙处疏浚，体现了系统思维，因此选A。","references":[],"evidence":"注意各河段的联系和相互影响，抓关键部分的系统思维","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a392a55d9c6499f8":{"review":{"definition":"单位量固定时，总量等于单位量乘以对应数量。已知总量和单位量，可用总量除以单位量求对应数量，计算前应统一计量单位。","explanation":"按题设，先把四种食物每100克的热量换算为每克热量，再分别乘以食用克数并相加，得到792大卡。按每30分钟消耗132大卡计算，需要6个30分钟，共3小时，对应B项。","references":[],"evidence":"快走每30分钟可以消耗热量132大卡","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e556a045ee04f9b4":{"review":{"title":"增长率与现期倍数","type":"原理与机制","definition":"基期量为正时，现期量是基期量的 1＋r 倍，其中 r 为相对于基期的增长率。","explanation":"增长 150% 表示增加量为基期量的 1.5 倍，因此现期量为基期量的 2.5 倍。","basis":"按公式或逻辑关系推导；适用条件见释义与诠释。","references":[],"basisGroup":"增长率与基期换算","related":["k-a73e31fef601c55e","k-17810c9f5dfc628e"]}},"k-a0e2239aaa80f668":{"review":{"definition":"已知总量和各部分的比例时，某部分的数量等于总量乘以该部分份数占总份数的比值。","explanation":"所求是人数比，可按解析把三专业总人数设为200人，按8∶7∶5分得80、70、50人。按全院男女比3∶1算出女生共50人，再按甲、乙各自的男女比算出女生为24人和10人。相减得丙专业女生16人，进而得男生34人，男女比为17∶8，对应D项。","references":[],"evidence":"学生人数之比是8：7：5","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a7834d1bb916a026":{"review":{"definition":"若正整数m与整数a互素，且m整除整数乘积ay，则m也整除y。","explanation":"以24份盲盒都按康乃馨的3元计为基准，实际多花了127－24×3＝55元。玫瑰每份多2元，百合每份多5元，因此玫瑰人数y、百合人数z满足2y＋5z＝55。5整除2y，且2与5互素，所以y须为5的倍数。24人以内最大的5的倍数是20，取20份玫瑰、3份百合和1份康乃馨恰好花127元，因此上限可以达到，对应B。","references":[],"evidence":"因为5z和55都是5的倍数，所以2y也应是5的倍数","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6f0505868fc927aa":{"review":{"title":"半球体积","type":"原理与机制","definition":"半径为 r 的半球体积为 2πr³/3。","explanation":"球体体积为 4πr³/3。过球心的平面把球体分成两个体积相等的半球，故取一半。","basis":"参照所列资料编释；例子和推演用于说明适用条件。","references":[{"source":"geof","location":"附录 C · Sphere，半球由球体平分得出"}],"basisGroup":"初等几何计算","related":["k-d9f880b35a6045f2","k-aea49d91fefa42d5","k-d73cb19a60baeb11"]}},"k-5390be50d683de51":{"review":{"definition":"图形沿一条直线翻折时，折痕上的点位置不变，对应线段等长，对应角相等。","explanation":"第59题中，沿AD翻折后，C落在AB上的C′，A和D位置不变，因此AC′=AC、DC′=DC，且∠AC′D仍为直角。由勾股定理得AC=6厘米，所以BC′=4厘米。设DC=x厘米，则BD=8−x厘米。在直角三角形BC′D中，由(8−x)²=4²+x²得x=3，因此BD=5厘米。以BD为底、AC为高，△ABD的面积为15平方厘米，对应A项。","references":[],"evidence":"若将纸片沿AD折叠，直角边AC恰好与斜边AB重叠","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b120634ad58217c5":{"review":{"title":"三角形的面积","type":"原理与机制","definition":"三角形的面积等于底与该底对应的高之积的一半。","explanation":"高是对顶点到底边所在直线的垂直距离。钝角三角形的垂足可能位于底边的延长线上。","basis":"参照所列资料编释；例子和推演用于说明适用条件。","references":[{"source":"geof","location":"附录 C · Triangle"}],"basisGroup":"初等几何计算","related":["k-f2b96384a4ff6acb","k-f1024cecb86a7a82"]}},"k-4266ddfa58bd3be9":{"review":{"definition":"在给定的计数范围内，满足某条件的情况数等于总情况数减去不满足该条件的情况数。分多类扣除时，要避免重复计数。","explanation":"本题先保留每天展出两类、相邻两天不重复、第1天不展出玉器和国画的限制，暂时放宽五类均须展出的要求。第1天从其余三类中选两类，之后每天从前一天未展出的三类中选两类，共有3⁴＝81种。任意相邻两天已展出四个不同类别，所以至多遗漏一类。指定遗漏一类后，剩下四类中，第1天一旦选定，后续每天只能展出前一天未展出的两类。若遗漏玉器或国画，第1天各有3种选法，共6种。若遗漏青铜器、瓷器或书法，第1天各只有1种选法，共3种。因此符合全部条件的安排有81－6－3＝72种，选A。","references":[],"evidence":"满足条件的情况数=总情况数-不满足条件的情况数=81-6-3=72种。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-897e8abb53f8681a":{"review":{"definition":"工作效率恒定时，完成的工作量等于工作效率乘以实际工作时间。多队合作完成同一项工程时，各队完成的工作量相加得到工程总量。","explanation":"本题按各队各自的工作与休息周期计算出勤。甲先开工时，甲经过23天、实际出勤18天，乙经过21天、实际出勤15天。乙先开工时，甲经过15天、实际出勤12天，乙经过27天、实际出勤20天。两种安排完成的是同一项工程，因此有18×甲的日工效＋15×乙的日工效＝12×甲的日工效＋20×乙的日工效，得到甲、乙日工效之比为5∶6。代回得甲单独完成需要实际工作36天，最后一个工作日一结束就完工，期间有11个休息日，合计47天，选C。","references":[],"evidence":"18甲+15乙=12甲+20乙","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8c06c72575da4818":{"review":{"definition":"两种浓度不同的溶液混合时，若溶质和溶液的质量均守恒，混合浓度就是两种原溶液浓度按质量加权的平均值。两种原溶液的质量之比，等于它们各自与混合浓度之差的绝对值的反比。","explanation":"低浓度溶液相对混合浓度少含的溶质质量，恰好等于高浓度溶液相对混合浓度多含的溶质质量，所以两侧的质量与浓度差的乘积相等。本题先把72%和78%的溶液视为一份76%的溶液。68%与76%的溶液混成74%，质量比为(76－74)∶(74－68)＝1∶3，因此76%的混合液有180克。再按(78－76)∶(76－72)＝1∶2分配这180克，得72%的溶液有60克，选D。","references":[],"evidence":"浓度之差与酒精溶液质量成反比","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c1f5ee0d422f71f0":{"review":{"definition":"若若干事件相互独立，则它们同时发生的概率等于各事件发生概率的乘积。","explanation":"解析按三人各自独立、等可能地选择到岗日期来计算。从周一到周五任选 k 天，五天被选中的机会相同，因此周三被选中的概率为 k/5。小王、小李和小陈分别选 2 天、3 天和 4 天，三人周三都到岗的概率为 (2/5)×(3/5)×(4/5)=24/125，对应 C 项。","references":[],"evidence":"根据分步用乘法","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d1f79b0e13f1817a":{"review":{"definition":"立方体有三组相对面。从同一角度同时看到三个面时，每组恰好可见一面。从每组各选一面，选出的三个面必交于同一顶点，可从该顶点一侧同时看到。","explanation":"若每组相对面都能选出一个没有圆的面，这三个面就构成一个看不到圆的三面视角。若至少有一组相对面都画有圆，任一三面视角都会看到其中一个圆。A 项展开图横排从左数第一格和第三格折叠后相对，两格都画有圆，因此选 A。","references":[],"evidence":"当能同时看到3个面时，相对面能且只能出现一个","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3ea3404a21228e30":{"review":{"definition":"在“如果P，那么Q”中，P是Q的充分条件。肯定P可以推出Q，否定Q可以推出非P，单凭否定P或肯定Q无法确定另一端是否成立。","explanation":"“欲事立，须是心立”把“心立”设为想成事的必要条件。A项由“不想事立”推出“无须心立”，是否定前件，无法推出，符合题目“不能由以上陈述推出”的要求。B项由“骨头”不硬推出理想信念不坚定，是否定后件，可以推出。","references":[],"evidence":"否前得不到确定性结论","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-71c30efc16f31b66":{"review":{"definition":"在统计口径可比、起止年份相同且部分与整体的基期值均为正时，部分的年均增长率低于整体，部分占整体的比重就下降。部分增长更快则比重上升，两者增速相同则比重不变。","explanation":"期末比重等于基期比重乘以部分与整体累计增长倍数之比。两者跨越相同年数时，年均增速越高，累计增长倍数越大。本题按材料给出的增速比较2012年至2021年的变化，制造业增加值年均增长6.4%，低于国内生产总值的6.6%。其余三项的年均增速分别为9.2%、7.4%和11.6%，均高于6.6%，所以选A。","references":[],"evidence":"制造业增加值年均增长6.4%","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a524b0960dd79113":{"review":{"definition":"原题引文：度为30毫克/立方米，比2015年下降34.8%","explanation":"第118题中，2021年的PM2.5年均浓度比2015年下降34.8%，因此现期量是基期量的65.2%。用30÷65.2%得约46.0，数值对应标准答案C。所给题组截图及选项文字使用“毫克/立方米”，国家统计局报告使用“微克/立方米”。按官方数据回算，2015年的浓度约为46微克/立方米。","references":[{"source":"web-9eba3e62eacb4fd2","location":"第二部分（二）“环境质量持续改善”，第一段","quote":"PM2.5年均浓度30微克/立方米，比2015年下降34.8%"}],"evidence":"度为30毫克/立方米，比2015年下降34.8%","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-8a483b0a14a1001d":{"review":{"title":"由比重还原部分量","type":"原理与机制","definition":"部分量等于总体量乘以该部分所占的比重。","explanation":"原题调查了 1 181 位 60 岁以上老年人，其中 36.2% 使用智能手机没有困难。用 1 181 乘以 36.2%，约为 428 人。","basis":"按公式或逻辑关系推导；适用条件见释义与诠释。","references":[],"basisGroup":"部分量和总体量","related":["k-58db2e624f2d2295","k-b4be6d3b12f772a4"]}},"k-d3539073b599c780":{"review":{"definition":"同一总体中，两个集合的交集占比至少为两者占比之和减去100%与0中的较大值。已知人数时，交集人数的下界为两集合人数之和减去总体人数与0中的较大值。","explanation":"两集合的人数相加时，交集中的人被计入两次，因此两集合人数之和超过总体人数的部分，至少来自交集。本题以2022年的1107名受访者为同一总体，按表中保留一位小数的比例可还原出71~80岁受访者268人、使用线上支付的受访者869人。未使用线上支付的238人即使全是71~80岁，该年龄组仍有30人使用线上支付，所以30人是可达到的下界。只有D项的30~39人包含这一可能人数。","references":[],"evidence":"24.2%+78.5%=102.7%＞100%","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2b9389370b9b29bb":{"review":{"definition":"多选调查的人均选择项数等于所有选项的选择总次数除以受访者总人数。各选项的选择率以同一批受访者的总人数为分母时，人均选择项数等于各项选择率之和。","explanation":"同一人选了几项，就在选择总次数中计几次。第129题图2的14项改进需求占比均以2022年的1107名受访者为分母。把各项选择人数相加再除以1107，等价于直接加总图中的14项占比。按图示数值，合计494.9%，折合人均约4.95项，符合C项“不少于4项”。","references":[{"source":"web-fe896524f4b8e93e","location":"调查样本说明、图3","quote":"希望智能手机适老化在哪些方面作出改进（多选）"},{"source":"web-1a160ba5e52d78ad","location":"第26页图2、第27页第129题","quote":"2022年受访者对智能手机适老化的改进需求（多选）"}],"evidence":"图2所列的14个改进需求项目中，2022年受访者的人均需求","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-6530391f8a8ffb57":{"review":{"definition":"同一总体中，若有两类特征的人群占比分别为 p 和 q，则只具有第一类特征的人群占比至少为 p−q 与 0 中的较大值。","explanation":"只具有第一类特征的人群占比等于 p 减去两类人群的重叠占比。重叠占比最多等于较小的一类，因此两类重叠最多时，差集占比最小。本题中，假设有“放大图标”需求的受访者同时都有“放大字体”需求，只有“放大字体”需求而无“放大图标”需求的人数达到最小。按材料所列比例估算，下界约为 1107×（55.6%−33.9%）≈240 人，足以推出 B 项的“不少于230人”。","references":[],"evidence":"有放大字体、放大图标需求的受访者的占比分别为55.6%、33.9%","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-678209b6a2ed01c8":{"review":{"definition":"已知现期量及其相对于基期的增长率，且1＋增长率不为0时，基期量＝现期量÷（1＋增长率）。","explanation":"增长量等于基期量乘以增长率，因此现期量是基期量的（1＋增长率）倍。第131题中，2021年我国对外贸易总额为6.9万亿美元，“比上年增长30.2%”意味着2020年是基期。用6.9÷1.302≈5.30万亿美元，选B。","references":[],"evidence":"2021年，我国对外贸易总额为6.9万亿美元，比上年增长30.2%","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f8f754fb74661858":{"review":{"definition":"根据居民消费需求和摊贩经营需求安排经营场所，并通过设摊规则、日常监督和便民服务维护经营秩序。","explanation":"本题参考答案把S市便民市场和T县“摊有序”的成效归在同一方面。S市让摊主代表参与选址，固定摊位使经营更稳定、摊主间少了争抢。T县用预约、积分和群众监督规范摆摊，材料记载占道经营投诉由月均42件降至5件。执法人员认领商贩的“微心愿”、协助申请暖心摊位，则有助于缓和执法人员与摊贩的对立情绪。","references":[],"evidence":"对流动商贩占道经营的投诉量从之前的月均42件下降到5件。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-dd2c72440f5c2df1":{"review":{"definition":"通过直播呈现垃圾分类执法，把执法过程转化为向公众普及垃圾分类知识、引导公众自觉分类的教育场景。","explanation":"本题要求归纳执法做法产生的积极效应。参考答案给出的成效是普及垃圾分类知识、强化公众教育、增强群众主动参与分类的意识。直播是做法，公众从了解分类要求到更愿意自觉分类是应归纳的成效。现有题内依据为参考答案中的成效概括。","references":[],"evidence":"教育作用，提升群众行动自觉","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-e28611011fe8f226":{"review":{"definition":"根据违法情节、社会危害等情况选择相称的监管方式，在引导企业纠正轻微违法行为的同时，减少执法给经营带来的负担。","explanation":"B市市场监管部门负责人以企业宣传用语不准确、台账记录不完整等问题为背景，指出处罚可能给企业带来经济损失和信用影响，抗风险能力弱的中小企业尤其容易受到冲击。本题应概括的成效是通过区分情节、边纠偏边帮扶来降低经营风险，同时发挥监管的约束和规制作用。材料中的清单例子针对不予实施行政强制措施。","references":[],"evidence":"让执法既有精度，也有温度，更有利于实现约束和规制作用","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-fd49fb29ca088d96":{"review":{"definition":"由统一协调机构组织负有不同职责的部门共同参与监管和执法，协调分工和行动，补足单一部门的执法力量与职责覆盖。","explanation":"漾湖毗邻五个县市区，原来仅靠渔政人员巡查，力量有限。H市由党政一把手担任禁捕退捕工作领导小组组长，办公室设在漾湖管理局，并将农业农村、市场监管、公安等部门纳入小组。本题可从这项安排提炼出统一统筹、依托主管部门协调、多部门共同参与的执法启示。","references":[],"evidence":"领导小组办公室（市禁捕办）设在漾湖管理局","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2f48c58340d4ba39":{"review":{"definition":"将禁捕监管从水面巡查延伸到岸上、市场和消费环节，及时汇集并移交各环节发现的线索，查处非法捕捞及其关联行为。","explanation":"漾湖管理局负责人提出把禁捕防线延伸到岸上、市场和餐桌。禁捕办的信息线索通报机制让捕捞、销售、消费任一环节发现的线索都能迅速交由相关职能部门查处，“打非断链”等专项联合执法则集中打击团伙化犯罪。本题应提炼出多环节发现问题、及时移交线索、联合查处的做法。","references":[],"evidence":"在捕捞端、销售端、消费端哪个环节发现问题线索","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0c6943a9a3b565ff":{"review":{"definition":"将人员巡护、现场处置与设备持续监测、辅助取证结合起来，扩大监管覆盖，并衔接发现问题与现场处置。","explanation":"漾湖沿岸的视频监控和雷达系统全天运行，无人机辅助取证，退捕渔民则加入护渔员队伍，协助渔政人员巡护水面、制止违法捕捞。本题可提炼出两项相互配合的执法启示：用技术装备增强全天候监测能力，吸纳熟悉当地情况的群众参与现场巡护。","references":[],"evidence":"86名退捕渔民加入护渔员队伍","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1cad48d02f74120c":{"review":{"definition":"农业文化遗产是当地居民仍在使用的农业生产系统。保护时应维持其基本结构和功能，并根据自然和社会经济条件的变化适当调整具体生产方式。","explanation":"农业景观、物种资源和水土资源管理方式都与当地条件相关，借鉴具体生产体系时需要考虑这些条件。C项把具体生产体系和知识技术体系说成可以“普遍地直接推广应用”，忽略了适用条件，因此是本题应选的错误说法。","references":[],"evidence":"而不能普遍地直接推广应用","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-180a9d5910511421":{"review":{"definition":"数字经济可以通过数据和数字技术与实体产业的生产经营深度融合，改善资源配置，推动实体经济提质增效。","explanation":"实体企业可以用数据改善生产调度，用数字技术优化工序。C项把这种作用概括为“促进实体经济虚拟化发展”，偏离了题目所强调的实体经济数字化转型，因此是本题选出的不正确说法。","references":[],"evidence":"促进实体经济虚拟化发展","disposition":"独立词条","basis":"据原题和解析编释。","title":"数字经济赋能实体经济","related":[],"examFocus":{"江苏 2023 A类 行测#8":"辨析数字经济对组织结构、资源配置和实体经济的影响，注意生产方式的变化与经济活动性质的变化是两个判断维度。"}},"readings":[{"origin":"k-180a9d5910511421","title":"数字经济赋能实体经济","qs":["江苏 2023 B类 行测#9"],"definition":"数字经济可以通过数据和数字技术与实体产业的生产经营深度融合，改善资源配置，推动实体经济提质增效。","explanation":"实体企业可以用数据改善生产调度，用数字技术优化工序。C项把这种作用概括为“促进实体经济虚拟化发展”，偏离了题目所强调的实体经济数字化转型，因此是本题选出的不正确说法。","evidence":"促进实体经济虚拟化发展","doubt":"","references":[]},{"origin":"k-f5acd200e0e2e3cf","title":"数字经济赋能实体经济","qs":["江苏 2023 A类 行测#8"],"definition":"党的二十大提出把发展经济的着力点放在实体经济上。题目解析据此指出，数字经济应通过与实体经济深度融合，支持实体产业发展并推动经济高质量发展。","explanation":"深度融合强调数据和数字技术服务于实体产业的生产经营与转型升级。C项把这种发展方向表述为“促进实体经济虚拟化发展”，与题目所据的政策导向不符，因此是选非题的答案。","evidence":"更好地赋能实体经济，推动经济高质量发展","doubt":"","references":[]}]},"k-572fa79fbffc491c":{"review":{"definition":"单位量固定时，总量等于单位量乘以计量单位数。已知总量和单位量，可以用总量除以单位量求计量单位数。","explanation":"按题给数据，把每100克的热量换算为每克的热量，再分别乘以四种食物的质量并相加，得到84×0.2＋120×3.88＋40×6.12＋120×0.54＝792大卡。快走每30分钟消耗132大卡，因此需要792÷132＝6个30分钟，即3小时，选B。","references":[],"evidence":"快走每30分钟可以消耗热量132大卡","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-98416c8723944824":{"review":{"definition":"半径为r的圆，面积为πr²。两圆面积相除时，π约去，面积比等于半径比的平方。","explanation":"本题按圆形计算基站覆盖面积。把A型基站的半径换算为1000～3000米后，用A型最小半径除以B型最大半径求面积比的下限，得(1000÷200)²＝25。用A型最大半径除以B型最小半径求上限，得(3000÷100)²＝900，选D。","references":[],"evidence":"根据圆的面积公式","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a4a9745ebf3b3506":{"review":{"definition":"按题设只计进货成本时，销售利润等于折扣后的实际销售收入减去已售商品的进货成本。","explanation":"每件衬衫原价销售的利润为50元。两件一单优惠20元，每单利润为80元。三件一单优惠50元，每单利润为100元。设两类顾客分别有x、y人，促销当天售出2x＋3y件，前一天售出一半。由利润倍数得80x＋100y＝1.5×50×(2x＋3y)÷2，解得x∶y＝5∶2，选A。","references":[],"evidence":"每购买两件优惠20元，每购买三件优惠50元","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-236694d878de6522":{"review":{"definition":"原题引文：若学生在该运动场上排成方阵","explanation":"第55题中，最短中心距离给出短半轴 b=20 米，最远两点相距80米给出长半轴 a=40 米。对边长为 s 的任意正方形，四个顶点的 x²/a²+y²/b² 的平均值等于其中心的归一化平方距离加上 s²(1/a²+1/b²)/4，且平均值至多为1。取同心、边平行于椭圆轴的正方形可以达到面积上界。因此方阵若取正方形，最大面积为1280平方米，对应A。给定解析按一般矩形计算，得到最大面积2ab=1600平方米，对应D。公开整理卷保留了“方阵”的措辞，定义范围仍需原卷或官方说明确认。","references":[{"source":"web-10a36d849191080b","location":"PDF第13页，第55题","quote":"上排成方阵，则所排成方阵面积的最大值为"}],"evidence":"若学生在该运动场上排成方阵","disposition":"独立词条","basis":"据原题与所列资料编释。","title":"椭圆内正方形的最大面积","related":[],"examFocus":{"江苏 2023 A类 行测#55":"由题给的两个距离确定椭圆的半轴长度，再考虑椭圆边界对方阵面积的限制。"}},"readings":[{"origin":"k-236694d878de6522","title":"椭圆内正方形的最大面积","qs":["江苏 2023 B类 行测#55"],"definition":"原题引文：若学生在该运动场上排成方阵","explanation":"第55题中，最短中心距离给出短半轴 b=20 米，最远两点相距80米给出长半轴 a=40 米。对边长为 s 的任意正方形，四个顶点的 x²/a²+y²/b² 的平均值等于其中心的归一化平方距离加上 s²(1/a²+1/b²)/4，且平均值至多为1。取同心、边平行于椭圆轴的正方形可以达到面积上界。因此方阵若取正方形，最大面积为1280平方米，对应A。给定解析按一般矩形计算，得到最大面积2ab=1600平方米，对应D。公开整理卷保留了“方阵”的措辞，定义范围仍需原卷或官方说明确认。","evidence":"若学生在该运动场上排成方阵","doubt":"未查到可核验的命题机关原卷、官方答案或勘误，需确认原题有无附图或队列形状的补充限定。","references":[{"source":"web-10a36d849191080b","location":"PDF第13页，第55题","quote":"上排成方阵，则所排成方阵面积的最大值为"}]},{"origin":"k-4de287bd688dd4ba","title":"椭圆内正方形的最大面积","qs":["江苏 2023 A类 行测#55"],"definition":"原题引文：若学生在该运动场上排成方阵，则所排成方阵面积的最大值","explanation":"题给短半轴20米、长轴全长80米，故长半轴为40米。设正方形边长为s，其四个顶点的椭圆式x²/1600+y²/400都不超过1。四个值的平均数等于正方形中心处的椭圆式加上s²(1/1600+1/400)/4，因此s²最多为1280。同心且边平行于两轴的正方形可取到这一上限，按所给题干应选A。给定解析的1600平方米是矩形面积上限，取到该值的矩形长宽之比为2∶1。","evidence":"若学生在该运动场上排成方阵，则所排成方阵面积的最大值","doubt":"按所给题干推得A，与给定答案D冲突。尚未查到可核实的官方原卷、原始答案或勘误，需确认原卷的“方阵”措辞及有无补充图示或条件。","references":[]}]},"k-1c10bbd0da8969c7":{"review":{"definition":"两组的总体平均数等于各组平均数乘以各组人数后求和，再除以总人数。两组均值分居总体均值两侧时，组人数与该组均值到总体均值的距离成反比。","explanation":"本题总体平均分为26÷16＝1.625分。若有x人得分超过1分，这组每人至多得3分，其余16－x人每人至多得1分，总分至多为3x＋(16－x)＝16＋2x。要达到26分，至少需要5人超过1分。5人各得3分、11人各得1分恰好可得26分，选A。","references":[],"evidence":"距离与量成反比","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6abee2c045f03a32":{"review":{"definition":"各队工作效率恒定且完成的工作量可以相加时，工程总量等于各队工作效率与各自实际工作时间的乘积之和。按周期轮休时，休息日不计入实际工作时间。","explanation":"按各队从开始工作起的轮休周期折算，甲先开工时，甲、乙分别实际工作18天和15天。乙先开工时，两队分别实际工作12天和20天。同一工程总量相等，因此甲、乙的日工作效率之比为5∶6。取甲每天完成5份、乙每天完成6份，总工程量为180份，甲独做须实际工作36天。完成前经历11个工作3天、休息1天的完整周期，最后再工作3天即完工，共47天，选C。","references":[],"evidence":"18甲+15乙=12甲+20乙","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-43d5fbc5ac9d1aaf":{"review":{"definition":"图形沿一条直线作轴对称变换后，对应线段等长，对应角相等。对称轴上的点位置不变。","explanation":"第62题中，折痕AD是对称轴，A、D位置不变，C落到斜边AB上的C′。由勾股定理得AC＝6厘米，所以AC′＝6厘米，BC′＝4厘米。原来的直角∠ACD变为直角∠AC′D，且C′D＝CD。设CD＝x厘米，则BD＝8－x厘米。在直角三角形BC′D中，4²＋x²＝(8－x)²，解得CD＝3厘米，BD＝5厘米。以BD为底、AC为高，△ABD的面积为15平方厘米，对应A项。","references":[],"evidence":"若将纸片沿AD折叠，直角边AC恰好与斜边AB重叠","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-73e198d9883a03d3":{"review":{"definition":"将两种质量分数不同的同种溶质溶液混合，若溶质和溶液的总质量均守恒，两种原溶液的质量之比等于各自浓度与混合浓度之差的绝对值的反比。","explanation":"以混合浓度为基准，低浓度溶液的溶质差额等于高浓度溶液的溶质盈余，因此两边的溶液质量与对应浓度差的乘积相等。本题先把72%和78%的两份溶液视为一份76%的混合液。68%溶液与76%混合液配成74%，质量比为(76%−74%)∶(74%−68%)＝1∶3，因此76%混合液有180克。再按(78%−76%)∶(76%−72%)＝1∶2拆分，72%溶液占180克的三分之一，即60克，对应D项。","references":[],"evidence":"浓度之差与酒精溶液质量成反比","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d6b396bca4211d79":{"review":{"definition":"等差数列前 n 项的和等于项数乘以首项与第 n 项的平均数，即 Sₙ = n(a₁ + aₙ)/2。","explanation":"把前 n 项正序、倒序各列一遍，对应项相加都等于首项与末项之和。本题中，各行的数字个数依次为 1、3、5、……，第 29 行有 57 个数，故前 29 行共有 29×(1+57)/2 = 841 个数。第 30 行有 59 个数，中间是本行第 30 个，也就是从 2022 起倒数排列的第 871 个数，数值为 2022−870 = 1152，选 B。","references":[],"evidence":"每行的个数是首项为1、公差为2的等差数列","disposition":"独立词条","basis":"据原题和解析编释。","title":"等差数列求和公式","related":[],"examFocus":{"国考 2024 副省级 行测#65":"用等差数列的通项和求和公式，分别比较两条生产线第5天的当日产量和前5天的累计产量。","国考 2025 副省级 行测#76":"用等差数列求和计算折后累计销量，再按各自的销量和单位利润比较折前、折后的总利润。","江苏 2023 B类 行测#65":"用等差数列求和确定前面各行共占多少位置，再结合本行的居中位置和整数的降序排列定位。","江苏 2025 B类 行测#59":"用等差数列求和把总盆数与首排盆数、排数联系起来，再按盆数和排数的取值条件筛选摆法。"}},"readings":[{"origin":"k-d6b396bca4211d79","title":"等差数列求和公式","qs":["江苏 2023 B类 行测#65"],"definition":"等差数列前 n 项的和等于项数乘以首项与第 n 项的平均数，即 Sₙ = n(a₁ + aₙ)/2。","explanation":"把前 n 项正序、倒序各列一遍，对应项相加都等于首项与末项之和。本题中，各行的数字个数依次为 1、3、5、……，第 29 行有 57 个数，故前 29 行共有 29×(1+57)/2 = 841 个数。第 30 行有 59 个数，中间是本行第 30 个，也就是从 2022 起倒数排列的第 871 个数，数值为 2022−870 = 1152，选 B。","evidence":"每行的个数是首项为1、公差为2的等差数列","doubt":"","references":[]},{"origin":"k-ead87dd2376bb9ae","title":"等差数列求和公式","qs":["国考 2025 行政执法 行测#72"],"definition":"等差数列的前若干项之和等于这几项的首项与末项的平均数乘以项数。","explanation":"等差数列中，距首尾同样远的两项之和等于首末两项之和，因此这些项的平均数等于首末两项的平均数。本题从打折第一天起每天比前一天多卖10件，所以首日卖50件，第15天卖190件，15天共卖（50＋190）÷2×15＝1800件。打折前20天共卖800件。设定价为10、成本为x，由两段总利润相同可得1800（8－x）＝800（10－x），解得x＝6.4，成本是定价的64%，选B。","evidence":"开始打折第一天起，每天都比前一天多卖10件","doubt":"","references":[]},{"origin":"k-2a1b0713ed703395","title":"等差数列前n项和","qs":["国考 2024 副省级 行测#65"],"definition":"等差数列前n项和等于项数乘以首项与第n项的平均数，即Sₙ＝n(a₁＋aₙ)/2。首尾对称位置的两项之和恒等于a₁＋aₙ，所以前n项的平均数等于首尾两项的平均数。","explanation":"设第5天两条线的产量均为x件。往前推4天，甲、乙首日产量分别为x−4m和x＋8m。用前5项和公式计算累计产量，乙为甲的2倍，得到2x＋8m＝2(2x−4m)。解得x＝8m，乙首日产量16m是甲首日产量4m的4倍。","evidence":"第5天两条生产线的当日产量相同，且前5天乙的累计产量是甲的2倍","doubt":"","references":[]},{"origin":"k-7cc307c4deba174c","title":"等差数列求和","qs":["国考 2025 副省级 行测#76"],"definition":"等差数列前n项的和等于首项与第n项的平均值乘以n，即 Sₙ＝n(a₁＋aₙ)/2。","explanation":"等差数列中，与首、末项等距的两项之和恒等于首尾两项之和，所以全体项的平均值等于首尾平均值。本题折前最后一天售40件，折后第1天售50件，第15天售190件，因此折后15天共售15×(50＋190)÷2＝1800件。折前20天共售800件，设定价为p、单位成本为c，由1800(0.8p－c)＝800(p－c)得c＝0.64p。","evidence":"每天都比前一天多卖10件","doubt":"","references":[]},{"origin":"k-90f8d9f39082d494","title":"等差数列求和","qs":["江苏 2025 B类 行测#59"],"definition":"有限等差数列的和等于项数乘以首项与末项的平均值。","explanation":"将数列正序和倒序逐项相加，每对的和都是首项加末项。本题设首排有a盆，共n排，则末排有a+n−1盆，所以n(2a+n−1)=84。首排至少1盆，故n(n+1)≤84，且题意要求至少2排。检验范围内84的因数，只有n=3、4、7时a为正整数，共3种摆法。","evidence":"每一排的菊花盆数都比前一排多1盆","doubt":"","references":[]}]},"k-6479508a66be3067":{"review":{"definition":"汽油是汽油发动机使用的燃料，燃烧释放的能量可用于驱动车辆。","explanation":"“越野汽车”按用途分类，“国产汽车”按产地分类，两类汽车有交集。汽油可为两类中使用汽油发动机的车辆行驶供能，因此第三项与前两项都能形成供能关系。","references":[],"evidence":"汽油可以维持汽车的行驶","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-96a1565eb08b3591":{"review":{"definition":"由“如果P，那么Q”和“P不成立”，无法确定Q是否成立。该条件只规定了P成立时Q必须成立。","explanation":"“欲事立，须是心立”把“心立”作为想要成事的必要条件。A项从“不想事立”推出“无须心立”，否定前件后否定后件，超出了原句给出的条件关系。题目问哪项不能推出，因此选A。","references":[],"evidence":"欲事立，须是心立。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d413fa9da91efecd":{"review":{"definition":"“只有P，才Q”表示P是Q成立的必要条件，即Q成立必有P成立。因此，P不成立时，可以推出Q也不成立。","explanation":"丙若不点清蒸鲈鱼，按条件（4）也不能点芹菜肉丝和毛豆仔鸡，只剩一道菜，无法点满两道。因此丙点清蒸鲈鱼，乙和丁也点。由于四人不能都点同一道菜，甲不点清蒸鲈鱼，进而由条件（1）推出丁不点芹菜肉丝。乙按条件（3）点毛豆仔鸡。四人的两道菜组合互不相同，丁只能给清蒸鲈鱼搭配糖醋排骨，丙则只能搭配芹菜肉丝，因此选C。","references":[],"evidence":"只有甲点清蒸鲈鱼，丁才点芹菜肉丝","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-57e522a7d0c4a9a1":{"review":{"definition":"部分量和整体量的基期值均为正，且年均增速对应同一起止时期时，部分量的年均增速低于整体量，比重下降。部分量的年均增速高于整体量，比重上升。两者相等时，比重不变。","explanation":"同一时期内，年均增速越高，按相同年数复合得到的累计增长倍数就越大。末期比重等于基期比重乘以部分量与整体量的累计增长倍数之比。第117题中，制造业增加值年均增长6.4%，低于国内生产总值的6.6%，所以其占比在2021年比2012年下降，选A。规模以上装备制造业、服务业和规模以上高技术制造业的年均增速分别为9.2%、7.4%和11.6%，均高于6.6%。","references":[],"evidence":"当部分增长率\n<整体增长率时，比重下降","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-71c4db1c83f4ef71":{"review":{"definition":"在两期统计口径一致、人数均大于零且基期总量大于零时，现期人均量是基期的多少倍，等于总量的跨期倍数除以人数的跨期倍数。","explanation":"人均量等于总量除以人数，所以两期人均量相除，可将两期总量和两期人数分别作比。本题中，2021年移动互联网接入总流量是2012年的252倍，上网人数增长83.0%，即为2012年的1.83倍。因此人均接入流量约为2012年的252 ÷ 1.83 ≈ 138倍，对应D项。","references":[],"evidence":"是2012年的252倍；互联网上网人数10.3亿人，比2012年增长\n83.0%。","disposition":"独立词条","basis":"据原题和解析编释。","title":"人均量的跨期倍数","related":[],"examFocus":{"江苏 2023 A类 行测#119":"用接入总流量的跨期倍数除以上网人数的跨期倍数，得到人均接入流量的跨期倍数。","江苏 2023 B类 行测#119":"用接入总流量的跨期倍数除以上网人数的跨期倍数，得到人均接入流量的跨期倍数。"}},"readings":[{"origin":"k-71c4db1c83f4ef71","title":"人均量的跨期倍数","qs":["江苏 2023 B类 行测#119"],"definition":"在两期统计口径一致、人数均大于零且基期总量大于零时，现期人均量是基期的多少倍，等于总量的跨期倍数除以人数的跨期倍数。","explanation":"人均量等于总量除以人数，所以两期人均量相除，可将两期总量和两期人数分别作比。本题中，2021年移动互联网接入总流量是2012年的252倍，上网人数增长83.0%，即为2012年的1.83倍。因此人均接入流量约为2012年的252 ÷ 1.83 ≈ 138倍，对应D项。","evidence":"是2012年的252倍；互联网上网人数10.3亿人，比2012年增长\n83.0%。","doubt":"","references":[]},{"origin":"k-c678b1a94ea605fd","title":"人均量的跨期倍数","qs":["江苏 2023 A类 行测#119"],"definition":"各期人均量等于当期总量除以当期人数。两期统计口径一致且基期人均量非零时，人均量的跨期倍数等于总量的跨期倍数除以人数的跨期倍数。","explanation":"第119题中，2021年移动互联网接入流量是2012年的252倍。互联网上网人数比2012年增长83.0%，即为2012年的1.83倍。用总量倍数除以人数倍数，得252÷1.83≈137.7，因此选D（138倍）。","evidence":"人均移动互联网接入流量是2012年的","doubt":"","references":[]}]},"k-441b1ba4a7f41342":{"review":{"definition":"在同一总体中，两个集合的交集占比至少为两者占比之和减去100%与0%中的较大值。","explanation":"两集合的并集占比至多为100%，而两者占比相加时，交集被计算了两次。本题的总体是2022年的1107名受访者，71~80岁者占24.2%，使用线上支付者占78.5%。按占比保留一位小数反推，两类分别有268人和869人，至少重合268＋869－1107＝30人。当两类合计覆盖全部受访者时，恰好重合30人，因此只有D项的30~39人区间可能成立。","references":[],"evidence":"24.2%+78.5%=102.7%＞100%","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8a091d569af64019":{"review":{"definition":"原题引文：图2所列的14个改进需求项目中，2022年受访者的人均需求","explanation":"同一受访者每选一项就在该项计一次。各项人数相加得到总选择人次，再除以受访者总人数，等价于直接相加各项比例。第129题图2的14项改进需求均以2022年的1107名受访者为分母。按图示比例复算，合计494.9%，即人均约4.95项，符合C项“不少于4项”。","references":[{"source":"web-fe896524f4b8e93e","location":"正文首段的调查样本与第二节图3","quote":"希望智能手机适老化在哪些方面作出改进（多选）"}],"evidence":"图2所列的14个改进需求项目中，2022年受访者的人均需求","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-ad956494f7404c0d":{"review":{"definition":"只属于集合 A 的人数等于 A 的人数减去两集合的交集人数。若只知道两集合各有多少人，交集最多等于较小集合的人数，因此只属于 A 的人数最少为两集合人数之差与零中的较大值。","explanation":"题解给出，2022年1107名受访者中，55.6%有放大字体需求，33.9%有放大图标需求。即使有放大图标需求的人都同时有放大字体需求，仍约有1107×（55.6%－33.9%）≈240人有放大字体需求而没有放大图标需求。两类需求的重叠越少，这部分人数就越多，所以可以推出B项所说的“不少于230人”。","references":[],"evidence":"有放大字体、放大图标需求的受访者的占比分别为55.6%、33.9%。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-731b7d1ed8ef31b2":{"review":{"definition":"湿地中的有机碳可经生物呼吸和微生物分解，以二氧化碳、甲烷等形式释放。积水造成的缺氧环境有利于微生物产甲烷，氨挥发则是独立的氮释放过程。","explanation":"施用氮肥的淹水稻田可观测到氨挥发。水体铵浓度和pH较高时，氨挥发更值得关注。天然潮汐盐沼的实测研究也将退潮后裸露地表的排放识别为当地氨浓度的可能来源。本题是选非题，参考答案选C，但C项表述为湿地“会排放出甲烷、氨气”，并未将氨列为碳释放产物。题目未限定湿地类型和条件，单凭碳释放主要涉及二氧化碳和甲烷，无法判定C项错误。","references":[{"source":"web-651dc7ccb5eb5e72","location":"田间试验结果，IRRI试验田氮肥段","quote":"The NH₃ volatilization losses were highest when all the N was broadcast into the water"},{"source":"web-63ad01b12a6b46de","location":"讨论与结论，退潮时的局地氨来源","quote":"fluxes from the land surface exposed as the tide recedes"}],"evidence":"碳释放以二氧化碳和甲烷为主。","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-73e1b05438a88734":{"review":{"definition":"本题按城市数据的使用程度，将智慧城市建设依次划分为数字化、网络化、智能化和智慧化四个阶段。","explanation":"电子政务先推动政务信息和流程数字化，一网通办再连通不同部门的系统。数字化决策利用已汇集、联通的数据辅助分析和判断，城市运行中心则将数据应用扩展到城市运行的综合监测与统筹管理。按题设框架排序为③—②—④—①，对应A项。","references":[],"evidence":"按照从数据汇集到数据使用的顺序","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-5b844341a016ace2":{"review":{"title":"密度、质量与体积","type":"原理与机制","definition":"物体的质量等于其平均密度与体积的乘积，即 m＝ρV。","explanation":"密度用千克每立方米时，体积应取立方米。密度不均匀时，可用整体平均密度求总质量。","basis":"参照所列资料编释；适用条件和推演见辅助诠释。","references":[{"source":"density","location":"1.4 · Density"}],"basisGroup":"量纲与单位换算","domain":"科技"}},"k-3c21be114abc5d80":{"review":{"title":"相向运动的接近速度","type":"原理与机制","definition":"两个物体沿同一直线相向运动时，间距缩小的速率等于两者速率之和。","explanation":"两者均匀速时，用初始间距除以速率之和得到相遇时间。列车从相遇到完全交会，还须计入相应车长。","basis":"按公式或逻辑关系推导；适用条件见释义与诠释。","references":[],"basisGroup":"相对运动"}},"k-a657ef915e112ebf":{"review":{"definition":"从车头到达某个可视为点的参照物，到车尾离开这个点，列车相对该点移动的路程等于车长。列车与参照点沿平行路线匀速相向运动时，相对速度等于两者速度之和。","explanation":"第52题忽略窗户长度，车窗就是随动车移动的参照点。3.6秒内经过车窗的是420米长的高速列车，动车的210米车长不进入计算。相对速度为420÷3.6米/秒，即420千米/小时，减去动车的180千米/小时，得到240千米/小时。","references":[],"evidence":"相遇距离即为平行列车的车长","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2b2e3707c004545c":{"review":{"title":"并行作业的合计效率","type":"原理与机制","definition":"多个作业主体同时工作、工作量可加且互不影响时，合计效率等于各自效率之和。","explanation":"若单独完成同一单位任务分别需 6 和 4 分钟，每分钟合计完成 1/6＋1/4。应相加单位时间产出，不能直接相加耗时。","basis":"按公式或逻辑关系推导；适用条件见释义与诠释。","references":[],"basisGroup":"工作量、效率与时间","related":["k-633dda86fead0d4c","k-6031af086dcc5d6a"]}},"k-f9391abc9ba589ec":{"review":{"definition":"等差数列中，一项离首项有几项，取另一项离末项同样远，这两项之和等于首项与末项之和。两项相对首尾的增量和减量相等，恰好抵消。","explanation":"第56题中，四个年龄的首尾两项和中间两项各合计142÷2=71岁。47岁高于平均年龄35.5岁，位于较大的两项中。选项给出的最大年龄均大于47岁，因此47岁应是第二大年龄。另一中间项为24岁，公差为23岁，最大年龄为70岁。","references":[],"evidence":"第二大和第三大的年龄和为","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-29e9c0af495985be":{"review":{"definition":"单价固定时，总价等于单价乘以数量。同一笔预算恰好买某种商品若干件时，每件单价是预算除以可买件数。","explanation":"第57题中，同一笔经费恰好买18个计算器、30个订书机或50个档案盒。买6个计算器和8个订书机分别用掉预算的6/18和8/30，剩余1−6/18−8/30=2/5。全额经费能买50个档案盒，剩余经费就能买20个。","references":[],"evidence":"a=18x=30y=50z","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-155bca4a341c70d6":{"review":{"definition":"圆台的侧面积为π(R+r)l，其中R、r为两底半径，l为侧面的母线长。母线长、高和两底半径之差组成直角三角形，故l=√[h²+(R−r)²]。","explanation":"第58题给的是直径，换成半径后，M型杯的半径和与半径差分别为60毫米和10毫米，N型杯分别为52.5毫米和7.5毫米。两型杯的高与半径差之比都为8∶1，所以母线长之比等于高之比4∶3。侧面积之比为(60÷52.5)×(4÷3)=32∶21。","references":[],"evidence":"其中r和R分别为上、下底面的半径，l为侧面母线长","disposition":"独立词条","basis":"据原题和解析编释。","title":"圆台侧面积公式","related":[],"examFocus":{"江苏 2024 A类 行测#58":"把杯口直径换算成半径，用杯高和两口半径差确定母线长，再按圆台侧面积公式比较两种纸杯。"}},"readings":[{"origin":"k-155bca4a341c70d6","title":"圆台侧面积公式","qs":["江苏 2024 A类 行测#58"],"definition":"圆台的侧面积为π(R+r)l，其中R、r为两底半径，l为侧面的母线长。母线长、高和两底半径之差组成直角三角形，故l=√[h²+(R−r)²]。","explanation":"第58题给的是直径，换成半径后，M型杯的半径和与半径差分别为60毫米和10毫米，N型杯分别为52.5毫米和7.5毫米。两型杯的高与半径差之比都为8∶1，所以母线长之比等于高之比4∶3。侧面积之比为(60÷52.5)×(4÷3)=32∶21。","evidence":"其中r和R分别为上、下底面的半径，l为侧面母线长","doubt":"","references":[]},{"origin":"k-645884f5180450ae","title":"圆台侧面积","qs":["江苏 2024 B类 行测#58"],"definition":"正圆台的侧面积为π(R＋r)l，其中R、r为两底面的半径，l为母线长。母线、高和两底半径之差构成直角三角形，因此l＝√[h²＋(R−r)²]。","explanation":"M、N两款纸杯的两底半径之和分别为60毫米和52.5毫米，半径之差分别为10毫米和7.5毫米。两杯的高度80毫米和60毫米也成4∶3，所以对应的母线长之比为4∶3。将半径之和的比8∶7与母线长的比4∶3相乘，得到侧面积之比32∶21。","evidence":"l为侧面母线长","doubt":"","references":[]}]},"k-c2a017f28723f9c8":{"review":{"definition":"两个集合中，任一集合的总人数等于仅属于该集合的人数加上同时属于两个集合的人数。已知其中两项，即可求出第三项。","explanation":"甲、乙活动的参加人数分别为180×60%＝108人和180×50%＝90人，两项人数都包含同时参加两项活动的会员。甲活动的108人中有80人只参加甲，所以两项都参加的有28人。从乙活动的90人中扣除这28人，只参加乙的有62人，选C。","references":[],"evidence":"甲、乙两项活动都参加的会员人数为108-80=28人","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2635cec85be6ea27":{"review":{"definition":"沿正六边形周边每隔一个顶点取一个顶点，连接所得的三个顶点，得到等边三角形。","explanation":"正六边形相邻顶点所对的圆心角均为60°，因此弦AC、CE、EA各对120°的圆心角。等圆心角所对的弦等长，所以△ACE是等边三角形，可以利用它的对称性确定内切圆的圆心。","references":[],"evidence":"由于ABCDEF是正六边形，可得AC=CE=EA","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9f9340cde299dcf9":{"review":{"definition":"等边三角形的内心是三条内角平分线的交点，外心是三边垂直平分线的交点。等边三角形的每条内角平分线所在直线也是对边的垂直平分线，因此两点重合。","explanation":"A、C、E都在正六边形的外接圆上，因此该圆的圆心也是△ACE的外心。由于△ACE是等边三角形，这个圆心就是内切圆的圆心O，O到边CE的垂直距离就是所求半径。","references":[],"evidence":"内切圆的圆心O即为正六\n边形ABCDEF的中心","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d712e8622fb24a97":{"review":{"definition":"半径为r的圆，其面积S＝πr²。","explanation":"本题圆O内切于△ACE。取CE的中点H，则OH垂直于CE，OH就是内切圆的半径。OC等于正六边形的边长2，而∠COH是∠COE的一半，为60°，所以OH＝2cos60°＝1，圆面积为π，对应A项。","references":[],"evidence":"则圆O的面积是","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f0f861209604b498":{"review":{"title":"牙齿磨损与年龄估计","type":"原理与机制","definition":"牙齿在咀嚼等长期使用过程中会发生磨损，磨损程度可作为估计年龄的辅助线索。","explanation":"饮食、咬合状况和个体差异都会影响磨损的速度。磨损程度相近的人可能年龄不同，因此需要结合其他线索估计年龄。","basis":"据关联原题和解析编释。","references":[],"examFocus":{"江苏 2024 A类 行测#75":"将两个备选词一同代入，比较两组词之间的联系和方向是否一致。"}},"aspects":[{"title":"磨损程度反映年龄","uses":[{"unit":"Q1","role":"解题依据","use":"本题 均选 A。前一组由牙齿磨损程度推测年龄大小，与后一组由用电总量观察经济活力的方向一致。","evidence":"牙齿磨损程度可以反映年龄大小","qids":["江苏 2024 A类 行测#75","江苏 2024 B类 行测#75"]}]}]},"k-3b8ccc9f0353daa4":{"review":{"title":"用电量与经济活动","type":"原理与机制","definition":"用电量是一定时期内使用的电能总量。生产经营活动会带来用电需求，因此用电量可以间接反映经济活动状况。","explanation":"气温、产业结构和能源效率也会影响用电量。比较不同地区或时期的经济活动时，需要同时考虑这些因素。","basis":"据关联原题和解析编释。","references":[],"domain":"经济","examFocus":{"江苏 2024 A类 行测#75":"将两个备选词一同代入，比较两组词之间的联系和方向是否一致。"}},"aspects":[{"title":"用电总量反映经济活力","uses":[{"unit":"Q1","role":"解题依据","use":"本题 均选 A。把用电总量填入后一组，形成由可观察的用电指标指向经济活力的关系，与前一组类比成立。","evidence":"用电总量大小可以反映经济活力","qids":["江苏 2024 A类 行测#75","江苏 2024 B类 行测#75"]}]}]},"k-4ae19671882e0f38":{"review":{"definition":"正方体的三个不同面共用一个顶点，当且仅当它们两两共用一条棱。等价地，这三个面中不能有任何一对相对面。","explanation":"正方体有三对相对面，从每对各取一面，三个面就会在唯一一个顶点相交。第88题中，三个不同数字之和为8的组合只有1、2、5和1、3、4。将选项C的展开图折叠后，1、2、5所在的三个面两两相邻，因此共用一个顶点。A、B的两组候选分别含有相对面1与4、2与5，D的两组候选分别含有相对面1与5、3与4。","references":[],"evidence":"面1、面2和面5两两相邻，即三个面存在公共点","disposition":"独立词条","basis":"据原题和解析编释。","title":"正方体三面共顶点的判定","related":[],"examFocus":{"江苏 2024 A类 行测#88":"先按面上数字的和筛选三面组合，再用展开图中的相对面关系判断它们能否共用一个顶点。","江苏 2024 C类 行测#88":"结合三面数字的和与折叠后的相对面关系，判断哪组三个面能共用一个顶点。"}},"readings":[{"origin":"k-4ae19671882e0f38","title":"正方体三面共顶点的判定","qs":["江苏 2024 A类 行测#88"],"definition":"正方体的三个不同面共用一个顶点，当且仅当它们两两共用一条棱。等价地，这三个面中不能有任何一对相对面。","explanation":"正方体有三对相对面，从每对各取一面，三个面就会在唯一一个顶点相交。第88题中，三个不同数字之和为8的组合只有1、2、5和1、3、4。将选项C的展开图折叠后，1、2、5所在的三个面两两相邻，因此共用一个顶点。A、B的两组候选分别含有相对面1与4、2与5，D的两组候选分别含有相对面1与5、3与4。","evidence":"面1、面2和面5两两相邻，即三个面存在公共点","doubt":"","references":[]},{"origin":"k-7f273f880bf77bfa","title":"正方体三面共顶点的判定","qs":["江苏 2024 C类 行测#88"],"definition":"正方体上三个不同的面共用一个顶点，当且仅当它们两两共边。等价地，三个面中只要有一对相对面，就无法共用一个顶点。","explanation":"正方体的六个面分为三对相对面。从每对中各取一个面，就分别确定了顶点在长、宽、高三个方向上的位置。第88题中，从1至6选出三个不同数字，和为8的组合只有1、2、5和1、3、4。B项折叠后，面1、面2、面5两两相邻。A、C、D两项组合各自都含有一对相对面，因此只有B符合题意。","evidence":"面1、面2和面5两两相邻，存在同一个公共顶点","doubt":"","references":[]}]},"k-8b7425ce10958bbe":{"review":{"definition":"如果甲是乙成立的必要条件，那么乙成立必有甲成立。等价地，甲不成立时，乙也不成立。","explanation":"题干的“除非……否则不能”把两翼健壮且能合力推动身体设为飞向天空的必要条件。②从能飞推出两项条件都满足，③从至少一项条件不满足推出不能飞，所以选B。①把两项条件都满足当成能飞的充分条件，④从不能飞倒推至少一项条件不满足，题干都推不出。","references":[],"evidence":"除非两翼健壮并以共同的力量来推动身体，否则它不能飞向天空","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0aee97d9c02682b6":{"review":{"definition":"否定“两项都成立”等价于断定“至少一项不成立”，即“甲且乙”的否定是“非甲或非乙”。","explanation":"题干要求两翼健壮和能合力推动身体同时成立。对这一组合条件取否定，只要两翼不健壮或不能合力推动身体，整个条件就不成立。③用“或”连接两种情形，正好表达不能飞的逆否推理所需的前提。","references":[],"evidence":"两翼不健壮或不能以共同的力量来推动身体","disposition":"独立词条","basis":"据原题和解析编释。","title":"德摩根律（合取的否定）","related":[],"examFocus":{"江苏 2024 A类 行测#91":"先辨清“除非……否则……”中谁是谁的必要条件，再用德摩根律处理逆否推理中对复合条件的否定。"}},"readings":[{"origin":"k-0aee97d9c02682b6","title":"德摩根律（合取的否定）","qs":["江苏 2024 A类 行测#91"],"definition":"否定“两项都成立”等价于断定“至少一项不成立”，即“甲且乙”的否定是“非甲或非乙”。","explanation":"题干要求两翼健壮和能合力推动身体同时成立。对这一组合条件取否定，只要两翼不健壮或不能合力推动身体，整个条件就不成立。③用“或”连接两种情形，正好表达不能飞的逆否推理所需的前提。","evidence":"两翼不健壮或不能以共同的力量来推动身体","doubt":"","references":[]},{"origin":"k-4faa58330495d65f","title":"德摩根律（合取的否定）","qs":["江苏 2024 B类 行测#91"],"definition":"否定“A且B”等价于“非A或非B”。两个条件中至少有一个不成立，合取命题就不成立。","explanation":"题干把“两翼健壮”和“以共同的力量来推动身体”同时成立作为飞向天空的必要条件。对这一条件关系作逆否推理，只要两翼不健壮或不能以共同的力量推动身体，就不能飞向天空，因此③可以推出。②直接重述题干的条件关系，①和④都不能由此推出，故选B。","evidence":"两翼不健壮或不能以共同的力量来推动身体","doubt":"","references":[]},{"origin":"k-cbf1b0dfd4ea84e2","title":"德摩根律（合取的否定）","qs":["江苏 2024 C类 行测#91"],"definition":"否定“甲且乙”等价于“非甲或非乙”，即至少有一个条件不成立，两者也可以都不成立。","explanation":"第91题把“两翼健壮”和“能以共同的力量来推动身体”同时成立作为飞向天空的必要条件。任一条件不成立，就能推出鸟不能飞向天空，故③可由②逆否推出，标准答案为B。","evidence":"两翼不健壮或不能以共同的力量来推动身体","doubt":"","references":[]}]},"k-be0ee108da6b65e8":{"review":{"definition":"如果甲成立必推出乙成立，乙成立又必推出丙成立，那么甲成立必推出丙成立。","explanation":"“只有乙参加，甲才参加”给出甲参加必有乙参加。再接上乙参加必有丙参加、丙参加必有丁不参加，可推出甲参加时丁一定不参加。题目问哪项不可能为真，所以选甲和丁同时参加的C项。","references":[],"evidence":"甲参加时丁一定不参加","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0eac07e8da149ea8":{"review":{"definition":"两种商品可满足同一用途时，在其他条件相近的情况下，一方相对另一方降价，可能使部分购买者转向相对便宜的一方。","explanation":"V国巴沙鱼原先凭较低的加工成本占有优势。A项指出国产黑鱼随产、供、销体系完善而降价，原料采购支出的下降可缩小两者用于制作酸菜鱼的成本差距，因此能同时解释巴沙鱼需求减弱和黑鱼份额上升。预制菜销售份额下降只解释了巴沙鱼的一部分需求为何减少。","references":[],"evidence":"随着国产黑鱼产、供、销体系完善，其价格降低","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-82c7b89123523601":{"review":{"definition":"总量等于两项之和时，总量的变化等于两项变化之和。若总量下降而其中一项上升，另一项必然下降，且降幅大于上升项的增量。","explanation":"按本题的两项可加模型，若B项所说的锻炼时长增加带来活动能量消耗上升，静息代谢就必须下降才能使总量下降。因此B项能加强观点。若D项的降幅按同单位的绝对量比较，活动项比总量降得更多，静息项须上升以抵消部分降幅，方向与待支持的观点相反。原解析称D项下另一项的变化无法确定，这在上述可加模型和比较口径下有误。","references":[],"evidence":"总能量代谢水平下降幅度比活动能量代谢水平下降幅度小","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0066ec1d357e1853":{"review":{"definition":"在“如果甲，那么乙”成立的前提下，确认前件甲成立，就能推出后件乙成立。","explanation":"B项给出研发部录用博士生，按小王的预测可推出生产部也录用博士生，违反三个部门录用人员学历各不相同的要求。A、D两项中的财务部录用本科生也会推出研发部录用本科生，同样违反要求。C项中财务部补为硕士生，恰好与研发部录用本科生相容。","references":[],"evidence":"如果研发部录用博士生，那么生产部录用博士生","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9bcaaaad82e3d941":{"review":{"definition":"在“如果甲，那么乙”成立的前提下，确认后件乙不成立，就能推出前件甲不成立。因为甲若成立，乙就必须成立。","explanation":"研发部只录用一人，已录用硕士生就排除了录用本科生。这否定了第③条预测的后件，因此财务部录用本科生或硕士生的前件也不能成立。题目问哪项不符合预测，所以选财务部录用硕士生的D项。","references":[],"evidence":"如果财务部录用本科生或者硕士生，那么研发部录用本科生","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-47a0525895bf8c94":{"review":{"definition":"否定“至少一项成立”等价于断定“两项都不成立”，即“甲或乙”的否定是“非甲且非乙”。","explanation":"研发部录用硕士生后，第③条预测的后件“研发部录用本科生”不成立，因而前件“财务部录用本科生或者硕士生”整体不成立。用德摩根律可分别排除财务部录用本科生和录用硕士生两种情形。三种候选学历中只剩博士生，因此D项不符合预测。","references":[],"evidence":"财务部没有录用本科生 且 财务部没有录用硕士生","disposition":"独立词条","basis":"据原题和解析编释。","title":"德摩根律（析取的否定）","related":[],"examFocus":{"江苏 2024 A类 行测#98":"把有关研发部和财务部的预测写成条件命题，再用逆否推理和德摩根律检验录用情形是否相容。","江苏 2024 B类 行测#98":"把有关研发部和财务部的预测写成条件命题，再用逆否推理和德摩根律检验录用情形是否相容。"}},"readings":[{"origin":"k-47a0525895bf8c94","title":"德摩根律（析取的否定）","qs":["江苏 2024 A类 行测#98"],"definition":"否定“至少一项成立”等价于断定“两项都不成立”，即“甲或乙”的否定是“非甲且非乙”。","explanation":"研发部录用硕士生后，第③条预测的后件“研发部录用本科生”不成立，因而前件“财务部录用本科生或者硕士生”整体不成立。用德摩根律可分别排除财务部录用本科生和录用硕士生两种情形。三种候选学历中只剩博士生，因此D项不符合预测。","evidence":"财务部没有录用本科生 且 财务部没有录用硕士生","doubt":"","references":[]},{"origin":"k-cd3e25385056c388","title":"德摩根律（析取的否定）","qs":["江苏 2024 B类 行测#98"],"definition":"否定“A或B”等价于“非A且非B”。只要有一个分命题成立，相容析取就成立，因此否定整个析取必须否定每个分命题。","explanation":"研发部只录用一人，录用硕士生就排除了录用本科生。由预测（3）的后件不成立，可推出前件“财务部录用本科生或者硕士生”不成立。把这个析取的否定展开，可同时排除财务部录用本科生和硕士生。材料只给出三类学历，因此财务部只能录用博士生，D项不符合预测。","evidence":"财务部没有录用本科生 且 财务部没有录用硕士生","doubt":"","references":[]}]},"k-40ce7c543296ce50":{"review":{"definition":"原题引文：所有参加跳远的运动员都没有参加跳高","explanation":"800米跑运动员都参加100米跑，100米跑运动员都参加跳高，所以A项成立。跳远与跳高的参赛者互斥，这一互斥关系也适用于跳高参赛者中的100米跑和800米跑群体，因此C项成立、D项必假。公开回忆版的设问确为“不能推出”，而B项也缺少全称结论所需的前提，故题干支持排除D所述可能性，却无法支持D是唯一不能推出的选项。","references":[],"evidence":"所有参加跳远的运动员都没有参加跳高","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-544d25335373ed63":{"review":{"definition":"原题引文：“有的”无法推出“所有”","explanation":"题干中的“有些跳远运动员投掷链球”可换位为“有些投掷链球运动员参加跳远”。因为跳远运动员均不参加跳高，所以至少有一名链球运动员没参加跳高。其余链球运动员仍可能参加跳高，故B项的“所有”无法推出。公开回忆版维持B项的全称措辞，参考解析虽指出B可能为真也可能为假，仍只选了与题干矛盾的D。","references":[],"evidence":"“有的”无法推出“所有”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3ea7c9ed39935cbe":{"review":{"definition":"每人次平均金额等于同一时期、同一统计范围内的总金额除以总人次。同一人发生多次业务时，每次均计入人次。","explanation":"第117题将2023年第二季度住院费用跨省联网直接结算减少的个人垫付总额354.3亿元，除以同期同类结算的282.6万人次。亿元除以万人次，单位为万元每人次，结果约为1.25万元每人次，对应C项。","references":[],"evidence":"住院费用跨省联网直接结算282.6万人次，减少个人垫付354.3亿元","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0ba792186ee1e494":{"review":{"definition":"当两期总量和对应的单位数均为正时，总量增速高于单位数增速，平均数上升；低于则下降，相等则持平。","explanation":"本题用减少个人垫付总额除以直接结算人次，得到每结算人次减少的垫付金额。本期平均数与上期平均数之比等于（1＋总额环比增速）÷（1＋人次环比增速）。门诊慢特病相关治疗费用的这两个增速分别为97.9%和89.5%，比值大于1。门诊费用整体、普通门诊和定点零售药店的总额增速分别为40.1%、36.8%和24.6%，均低于对应的人次增速47.6%、49.6%和39.0%，因此只有D项的平均金额环比增加。","references":[],"evidence":"当分子的增长率大于分母的增长率时，平均数上升","disposition":"独立词条","basis":"据原题和解析编释。","title":"两期平均数比较","related":[],"examFocus":{"国考 2024 副省级 行测#123":"判断马铃薯单位面积产量的同比变化，可逐年比较总产量和播种面积的同比增速。","江苏 2024 A类 行测#119":"判断人均减少垫付金额的环比变化，要在同一结算类别内比较减少个人垫付总额与直接结算人次的环比增速。","江苏 2024 B类 行测#119":"判断人均减少垫付金额的环比变化，要在同一结算类别内比较减少个人垫付总额与直接结算人次的环比增速。","江苏 2025 A类 行测#129":"判断柴油机和汽油机的进出口均价变化，要按产品和进出口方向分别比较金额与台数的同比增速。","江苏 2025 C类 行测#129":"判断柴油机和汽油机的进出口均价变化，要按产品和进出口方向分别比较金额与台数的同比增速。"}},"readings":[{"origin":"k-0ba792186ee1e494","title":"两期平均数比较","qs":["江苏 2024 A类 行测#119"],"definition":"当两期总量和对应的单位数均为正时，总量增速高于单位数增速，平均数上升；低于则下降，相等则持平。","explanation":"本题用减少个人垫付总额除以直接结算人次，得到每结算人次减少的垫付金额。本期平均数与上期平均数之比等于（1＋总额环比增速）÷（1＋人次环比增速）。门诊慢特病相关治疗费用的这两个增速分别为97.9%和89.5%，比值大于1。门诊费用整体、普通门诊和定点零售药店的总额增速分别为40.1%、36.8%和24.6%，均低于对应的人次增速47.6%、49.6%和39.0%，因此只有D项的平均金额环比增加。","evidence":"当分子的增长率大于分母的增长率时，平均数上升","doubt":"","references":[]},{"origin":"k-1b47eb7ebcaae46d","title":"两期平均数比较","qs":["国考 2024 副省级 行测#123"],"definition":"当两期的分子和分母均为正数时，分子增速高于分母增速，比值上升。两者增速相等时，比值不变。分子增速低于分母增速时，比值下降。","explanation":"本年比值是上年比值的（1＋分子同比增速）÷（1＋分母同比增速）倍，所以只需比较两个增速。马铃薯单位面积产量等于总产量除以播种面积。2018、2020、2021、2022年总产量上升、播种面积下降，单产均增长。2019年总产量从1798万吨降至1778万吨，降约1.11%，播种面积从476万公顷降至467万公顷，降约1.89%，总产量的降幅较小，单产仍然增长。2018至2022年共有5年同比增长，选D。","evidence":"当分子增速（a）大于分母增速（b）时，平均数上升","doubt":"","references":[]},{"origin":"k-3187824e10525ab3","title":"两期平均数比较","qs":["江苏 2024 B类 行测#119"],"definition":"平均数等于总量除以份数。两期的总量与份数均为正且统计口径一致时，总量增速大于份数增速，平均数上升。两者相等时平均数持平，总量增速较小时平均数下降。","explanation":"本期平均数与上期平均数之比，等于（1＋总量增速）除以（1＋份数增速）。第119题以减少个人垫付总额为分子、直接结算人次为分母。门诊慢特病的垫付减少额环比增长97.9%，高于结算人次的89.5%。其余三项的金额增速均低于各自的人次增速，因此只有D项的人均减少垫付金额环比上升。","evidence":"当分子的增长率大于分母的增长率时，平均数上升","doubt":"","references":[]},{"origin":"k-8eb0b848f0555462","title":"两期平均数比较","qs":["江苏 2025 C类 行测#129"],"definition":"对于用总量除以数量得到的平均数，在两期总量和数量均为正、统计口径一致的条件下，总量同比增速高于数量同比增速时，平均数上升。两者增速相等时，平均数持平。总量同比增速较低时，平均数下降。","explanation":"本期平均数与上年平均数之比，等于（1＋总量同比增速）÷（1＋数量同比增速）。第129题以进出口金额为总量、对应的进出口台数为数量。柴油机出口和进口的金额增速分别为18.9%和41.7%，均高于对应的数量增速10.0%和7.3%，所以两项均价均上涨。汽油机出口金额增速3.4%低于数量增速6.3%，进口金额增速−28.5%也低于数量增速−28.2%，所以两项均价均下降，选D。","evidence":"分子增长率（a）>分母增长率（b），平均数上升","doubt":"","references":[]},{"origin":"k-f350778522a2f507","title":"两期平均数比较","qs":["江苏 2025 A类 行测#129"],"definition":"平均数等于总量除以对应的数量。当基期总量和两期数量均为正时，总量增速高于数量增速，平均数上升；两者相等，平均数持平；总量增速低于数量增速，平均数下降。","explanation":"本期平均数是基期平均数的（1＋总量增速）÷（1＋数量增速）倍。本题以进出口金额为总量、台数为数量，分别比较同一产品、同一进出口方向下的两个增速。柴油机出口的金额增速18.9%高于数量增速10.0%，进口的金额增速41.7%也高于数量增速7.3%，所以两项平均价格均上涨。汽油机出口的3.4%低于6.3%，进口的−28.5%低于−28.2%，两项平均价格均下降，故选D。","evidence":"分子增长率（a）>分母增长率（b），平均数上升","doubt":"","references":[]}]},"k-acc3a67b5311fce0":{"review":{"definition":"对于可以按期相加的总量指标，第二至第四季度的单季总量等于同一年、同一统计口径下本季末累计量减去上季末累计量。第一季度总量等于当年1—3月累计量。","explanation":"本季末累计量包含前几个季度及本季度的总量，减去上季末累计量就得到本季度新增的总量。第122题中，2022年第二、第三、第四季度的进出口总额分别为1600、1578、1726亿元，2023年第二季度为1472亿元。两年第一季度分别为1388和1443亿元。六个季度中，2022年第四季度的1726亿元最高，选C。","references":[],"evidence":"2022年第四季度=6292.0-4566.0","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-eb784e0d6282e0b6":{"review":{"definition":"两期总体量均为正且基期部分量为正时，现期比重与基期比重之比等于（1＋部分量增速）÷（1＋总体量增速）。因此，比重上升等价于部分量增速高于总体量增速。","explanation":"B项比较的是2023年第二季度相对第一季度的环比增速。第二季度出口额占进出口总额的比重高于第一季度的57.8%，所以同期出口额的环比增速高于进出口总额的环比增速，B项可以推出。","references":[],"evidence":"当比重上升时，a>b","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-90c98a86d3b2a861":{"review":{"title":"营业收入利润率的同比变化","type":"原理与机制","definition":"营业收入利润率是利润总额与营业收入的比值。统计口径一致且两期营业收入、利润总额均为正时，利润总额的同比增速高于、等于或低于营业收入的同比增速，营业收入利润率就相应同比上升、持平或下降。","explanation":"设利润总额和营业收入的同比增速分别为 a 和 b，现期利润率等于上年同期利润率乘以 (1＋a)/(1＋b)。遇到上年同期利润为零、亏损或盈亏转换时，可在两期营业收入均为正的条件下分别计算利润率，再比较两期数值。","basis":"据关联原题及所列出处编释。","references":[{"source":"profit","location":"附注·营业收入利润率公式；变化条件依公式推导"}],"related":["k-45392942e1591512","k-9ca0533b7efae951","k-14599d5c611e3b87"],"examFocus":{"江苏 2024 A类 行测#130":"从文字材料找出同一监管范围、同一时期的利润与营业收入同比增速，用两者的大小关系判断利润率变动方向。","江苏 2024 B类 行测#130":"从文字材料找出同一监管范围、同一时期的利润与营业收入同比增速，用两者的大小关系判断利润率变动方向。"}},"aspects":[{"title":"比较利润与营业收入的同比增速","uses":[{"unit":"Q1","role":"解题依据","use":"江苏 2024 A类 行测第130题。2023年上半年，江苏省国资委监管企业利润同比增长30.4%，营业收入同比增长4%，据此可推出A项。题干要求选出不能推出的一项，答案为D。图中2022年上半年的营业收入同比增速较前一半年下降，环比增速却上升，D项所称的趋势相同与图中数据不符。","evidence":"2023年上半年，江苏省国资委监管企业营业收入利润率同比有所提高","qids":["江苏 2024 A类 行测#130"]},{"unit":"Q2","role":"解题依据","use":"江苏 2024 B类 行测第130题。A项涉及江苏省国资委监管企业，2023年上半年利润同比增长30.4%，快于营业收入的4%，所以利润率同比提高。该题为选非题，答案同为D。","evidence":"2023年上半年，江苏省国资委监管企业营业收入利润率同比有所提高","qids":["江苏 2024 B类 行测#130"]}]}]},"k-1ee6f6eb1f817403":{"review":{"definition":"人均消费额是一定时期内某一统计人群的总消费额除以该人群人数所得的平均值。统计人群、时期和消费范围一致时，总消费额等于人数乘以人均消费额。","explanation":"第132题按表中直播电商行业的统计口径，用2021年用户数4.3亿人乘以人均年消费额4640元，估算该年交易额为19952亿元，即1.9952万亿元。以材料直接给出的2022年交易额3.5万亿元为前项，两年交易额之比约为3.5∶2，即7∶4，选D。","references":[],"evidence":"用户数为4.3亿人，人均年消费额为4640元","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d806efefaa38dd40":{"review":{"definition":"当基期量为正时，「较基期增长 n 倍」表示增长量是基期量的 n 倍，因此现期量是基期量的 n＋1 倍，基期量等于现期量除以 n＋1。","explanation":"现期量由原有的基期量和新增的 n 倍基期量构成。第135题中，2022年重点监测电商平台直播场次超过1.2亿场，较2020年增长5倍，所以2020年的场次超过1.2亿÷6＝2000万场。A项所用的交易额同理，2017年约为35000÷179＝196亿元，低于250亿元。","references":[],"evidence":"重点监测电商平台直播场次超1.2亿场，较2020年增长5倍","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e307461a0d2033c3":{"review":{"definition":"在统计时期、计数单位和口径一致，且子集计入整体的条件下，整体计数至少等于子集计数。因此，子集计数超过某一数值时，整体计数也超过该数值。","explanation":"第135题中，重点监测电商平台的直播场次属于全行业直播场次。反推得2020年重点监测平台的直播场次超过2000万场，全行业至少包含这些场次，因此B项成立。解析中的「必然多于」需要另有至少一场未纳入监测的直播，推得B项只需全行业场次大于或等于监测范围内的场次。","references":[],"evidence":"2020年我国直播电商行业直播场次超过2000万场","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d0f0b3445cf27c16":{"review":{"definition":"行政行为码是执法监管数字系统为一项行政行为自动生成的全周期唯一标识，用于关联、查询和追踪该行为的办理信息。","explanation":"材料1中，执法人员生成电子处罚决定书时，系统同步生成行政行为码。当事人扫码可查看文书、处罚内容和执法流程，执法人员扫码可查看案件办理进度。本题据此概括全流程在线运行、精准监督和留痕可溯等成效。","references":[],"evidence":"是行政行为全周期的唯一标识","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1f93edec2af3853e":{"review":{"definition":"申论材料中的C县依托智慧交通运输管理系统，将砂石运输车辆的装车称重预警与道路不停车称重、现场复查相结合，治理货运超载超限。","explanation":"装车时，平台读取源头企业的称重数据，发现疑似超载便提醒企业和驾驶员现场整改，达标后方可运输。对行驶中的货车，不停车称重筛查疑似超载超限车辆，沿线显示屏提示复检，执法人员接到通知后锁定车辆并在检测点复查。作答可把两道关口概括为加强源头监管和路面管控，并写出提高治超效率、节省驾驶员等待时间的成效。","references":[{"source":"web-098acc6525b85d4b","location":"给定资料2，C县砂石运输案例","quote":"提醒源头企业和车辆驾驶员现场整改"}],"evidence":"提高货运车辆超载超限执法能力，节约时间","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"k-8570a0eee6c1cf0a":{"review":{"definition":"人群热力图用颜色深浅表示不同位置的人群密度。实时更新的密度分布可为大型活动的拥挤和踩踏风险研判提供依据。","explanation":"秦淮灯会期间，警方对空间位置信息进行聚类分析，实时监测重点区域的人群密度，图上颜色越深表示人员越集中。本题可据此概括警方掌握人员流入流出和聚集情况，为防拥挤、防踩踏的指挥决策提供依据。","references":[],"evidence":"颜色越深代表人员越集中、颜色越浅代表人员越稀疏","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5746bc1020522763":{"review":{"definition":"材料中的视频巡逻通过巡查采集现场画面并及时回传，帮助安保指挥部掌握固定监控覆盖不足区域的情况。","explanation":"秦淮灯会安保使用4G高清无线图传，把现场高清视频传回指挥部。本题概括成效时宜写“弥补固定监控覆盖不足”。参考答案的“实现监控‘无死角全覆盖’”比材料的表述更绝对。","references":[],"evidence":"使现场高清视频能够及时回传至安保指挥部","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-87157597eea07555":{"review":{"definition":"材料中的防走失系统把寻人微信群、广播和景区大屏等信息渠道，与寻人点和现场警力联动起来，协助寻找走失儿童或走散游客。","explanation":"秦淮灯会期间，现场警力在夫子庙广场附近发现一名五六岁的走失女孩，特警借助系统在几分钟内找到她的家人。本题可据此概括智能警务如何通过信息渠道与现场力量协作加快寻人。","references":[],"evidence":"寻人微信群、寻人点、单兵组、寻人广播、智慧夫子庙大屏","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-e046ccf1dbd8f288":{"review":{"definition":"申论材料中的“AI小秘书”是S市环境执法总队开发的生态环境移动执法助手，提供企业信息协查、执法文书生成和专业知识问答。","explanation":"系统整合环评、排污许可等企业档案，便于执法人员在现场查询。检查人员录入检查过程和发现的问题后，“报告助手”结合企业档案生成文书文本。专业问答利用政策文件、裁量基准和典型案例等资料，辅助查找法规依据。这三项功能分别对应本题的三个得分点，即提高检查效率、规范执法记录、辅助学习和运用政策法规。","references":[{"source":"web-098acc6525b85d4b","location":"给定资料4，S市环境执法总队案例","quote":"提供环境执法领域专业知识问答支持"}],"evidence":"保证执法记录的规范性和准确性，帮助执法人员学习、运用政策法规","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"k-ee125cbf35796260":{"review":{"definition":"行政处罚裁量缺乏有效约束时，个人恩怨或利益可能左右处罚尺度，导致处罚畸轻畸重，或使情节相近的案件出现缺乏合理依据的处罚差异。","explanation":"材料5中，经办人利用不同时段、不同层级文件之间的漏洞，出于私人芥蒂有意加重老韩的处罚。老韩得知其他有相同违法行为者多被罚约1万元后，对自己的3.2万元罚款提出异议。本题以此说明裁量失范如何损害公平感和执法公信力。","references":[],"evidence":"畸轻畸重、类案不同罚","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3e6b893a8700fecb":{"review":{"definition":"源网荷储多元智能互动是指电源、电网、用电负荷和储能共同参与电力系统调节，通过智能调度协调发电、用电和储能充放电。","explanation":"在这种运行方式下，负荷和储能也能参与供需调节。例如，用电需求上升时，系统可以协调可调负荷和储能响应。题给《新型电力系统发展蓝皮书》将调控模式从单向计划调度转向源网荷储多元智能互动，C项的“智能协同运行”符合这一方向。","references":[],"evidence":"实现源、网、荷、储的智能协同运行","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-272b8427eb08a802":{"review":{"definition":"柔性执法可以通过说服教育、警示告诫、指导约谈等方式，引导行政相对人了解合规要求并自觉守法。","explanation":"B项所说的从事后监管向事前指导转变，体现了把合规指导前移，让相对人有机会在违法发生前调整行为。题给纲要将这些手段列为行政执法方式的创新，A项所说的“根本转变”夸大了变化程度。","references":[],"evidence":"执法监管实现从事后监管向事前指导转变","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d841877aa14843f2":{"review":{"definition":"至少一个事件发生的概率等于两个事件各自发生的概率之和减去两者同时发生的概率。这一公式对独立或不独立的事件都成立。","explanation":"财务部有员工入选包括仅小王入选、仅小李入选和两人都入选。把两人各自入选的概率0.6和0.5直接相加，会将共同入选的0.25计入两次，因此减去一次，得到0.85。","references":[],"evidence":"两人分别入选的概率包含了两人同时入选的概率","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c67ba412cda731e2":{"review":{"definition":"完成一件事需要依次完成若干步骤。若每一步在此前任意一种合法选择下都有固定数量的选法，且每组完整的选择恰好对应一种结果，总方法数就是各步选法数的乘积。","explanation":"两个二线城市各占 1 名专员，余下 3 人去两个一线城市，只能按 2 人和 1 人分配。先选接收 2 人的一线城市，再从 5 人中选 2 人去该市，从剩余 3 人中选 1 人去另一座一线城市，最后把剩余 2 人分别派往两个二线城市。各步选法数相乘为 2 × 10 × 3 × 2 = 120。","references":[],"evidence":"分步用乘法，则不同的派出方法共有60×2=120种","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-750c06ab38e39fb5":{"review":{"definition":"交集包含同时属于两个集合的元素。甲集合相对于乙集合的差集包含只属于甲集合的元素，甲集合的元素总数等于这两个互不重叠的部分的元素数之和。","explanation":"参加甲活动的共有 180 × 60% = 108 人，其中 80 人只参加甲活动，因此两项都参加的有 28 人。参加乙活动的 180 × 50% = 90 人也包含这 28 人，扣除后得到只参加乙活动的 62 人。","references":[],"evidence":"甲、乙两项活动都参加的会员人数为108-80=28人","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7f2b742cff9c09ac":{"review":{"definition":"连接正六边形上两两相隔一个顶点的三个顶点，得到等边三角形。这个三角形的内心和外心都与正六边形的中心重合。","explanation":"第65题中，弦AC、CE、EA对应的圆心角都是120°，所以三边相等。正六边形的中心到A、C、E等距，因此也是△ACE的外心。等边三角形的内心与外心重合，所以图中内切圆的圆心O就是正六边形的中心。","references":[],"evidence":"由于ABCDEF是正六边形，可得AC=CE=EA","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c60d1b1443ff8bee":{"review":{"definition":"等边三角形的内切圆半径等于外接圆半径的一半。","explanation":"等边三角形的内心、外心和重心重合。重心将中线分成长度比为2∶1的两段，顶点到重心是外接圆半径，重心到对边中点是内切圆半径。第65题中，正六边形的外接圆半径等于边长2，因此△ACE的外接圆半径AO为2，内切圆半径为1。","references":[],"evidence":"且AO=AF=2","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1aa4b03c92a338db":{"review":{"definition":"半径为r的圆的面积为S＝πr²。","explanation":"第65题要求圆O的面积。由△ACE的外接圆半径为2，得圆O的半径为1，代入得S＝π×1²＝π，对应选项A。","references":[],"evidence":"则圆O的面积是","disposition":"独立词条","basis":"据原题和解析编释。","title":"圆的面积公式","related":[],"examFocus":{"江苏 2023 A类 行测#53":"统一两类基站覆盖半径的单位，利用圆面积与半径平方的关系判断面积比的上下界。","江苏 2024 B类 行测#65":"求圆面积前，先找正六边形的边长与隔点三角形内切圆半径之间的几何关系。","江苏 2024 C类 行测#65":"把内切圆半径看作圆心到三角形一边的垂直距离，再结合正六边形的边长求圆面积。"}},"readings":[{"origin":"k-1aa4b03c92a338db","title":"圆的面积公式","qs":["江苏 2024 B类 行测#65"],"definition":"半径为r的圆的面积为S＝πr²。","explanation":"第65题要求圆O的面积。由△ACE的外接圆半径为2，得圆O的半径为1，代入得S＝π×1²＝π，对应选项A。","evidence":"则圆O的面积是","doubt":"","references":[]},{"origin":"k-865b20a3d55a6b3b","title":"圆的面积公式","qs":["江苏 2024 C类 行测#65"],"definition":"半径为 r 的圆，其面积为 S＝πr²。","explanation":"本题所求的是三角形 ACE 的内切圆面积。半径取圆心 O 到三角形一边的垂直距离 1，代入公式得 S＝π，对应选项 A。","evidence":"则圆O的面积是","doubt":"","references":[]},{"origin":"k-f008e87d4ba99227","title":"圆的面积","qs":["江苏 2023 A类 行测#53"],"definition":"圆的面积等于圆周率乘以半径的平方，即 S＝πr²。两个圆的面积之比等于半径之比的平方。","explanation":"本题把基站地面覆盖区域按圆形计算，并把A型半径换算为1000至3000米。题设允许两类半径在各自区间内独立取值，最小面积倍数取A型最小半径和B型最大半径，得（1000÷200）²＝25。最大倍数取A型最大半径和B型最小半径，得（3000÷100）²＝900，对应D项。","evidence":"一个B型5G基站的地面覆盖半径为100~200米","doubt":"","references":[]}]},"k-a7516a200b514a6b":{"review":{"definition":"央行可通过提高政策利率来应对通胀。加息若提高本币资产的相对预期回报，在汇率预期和风险等条件允许时，可能吸引资金回流。","explanation":"加息有助于抑制借贷和支出，从而缓解价格上涨压力。本题B项的两段关系依次是通胀促使央行加息、加息可能吸引资金回流，顺序对应“雷击→停电→电梯停运”。解析也认可D项的因果顺序，进一步选B的依据是“资金回流”和“电梯停运”均为主谓结构，“自立自强”为并列结构。","references":[],"evidence":"“通胀”导致“加息”，“加息”导致“资金回流”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8d17a4a60e44dd23":{"review":{"definition":"正方体的三个不同面恰有一个公共顶点，当且仅当它们两两共边。等价地，这三个面须从三对相对面中各取一个。","explanation":"三对相对面分别对应三个互相垂直的方向，从每对中各取一个面，就确定了三个方向上的位置，交于唯一一个顶点。本题从1至6中选三个不同数字，和为8的组合只有1、2、5和1、3、4。A项的两组分别含相对面2和5、1和4，C项分别含1和2、3和4，D项分别含1和5、3和4。B项的1、2、5分属三对相对面，折叠后共顶点，因此选B。","references":[],"evidence":"面1、面2和面5两两相邻，存在同一个公共顶点","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3a208c42ed1b69b4":{"review":{"title":"逆否等价","type":"原理与机制","definition":"条件命题“如果 P，那么 Q”与它的逆否命题“如果 Q 不成立，那么 P 不成立”逻辑等价。","explanation":"两者都只在 P 成立而 Q 不成立时为假。若被否定的是由“且”连接的复合条件，其否定表示其中至少一项不成立。","basis":"据关联原题和解析编释。","references":[],"related":["k-4aa308d0488924b5"],"examFocus":{"江苏 2024 B类 行测#91":"辨明“除非……否则……”中的必要条件，判断哪些陈述可由原句推出。","江苏 2025 A类 行测#91":"区分“只有……才……”和“只要……就……”的推理方向，辨清复合条件的否定范围。","江苏 2025 B类 行测#102":"将备选前提代入已知条件，用逆否推理检验能否推出指定结论。"}},"aspects":[{"title":"必要条件的逆否推理","uses":[{"unit":"Q1","role":"解题依据","use":"飞向天空以两翼健壮且共同发力为必要条件。②重述这一条件关系，③指出任一条件不满足就不能飞向天空，因此选B。","evidence":"③一只鸟若两翼不健壮或不能以共同的力量来推动身体，那么它不能飞向天空","qids":["江苏 2024 B类 行测#91","江苏 2024 C类 行测#91"]},{"unit":"Q2","role":"解题依据","use":"题干把“为了人民”设为现代化有意义的必要条件，否定这一条件即可推出A项。若未能充分调动人民积极性，只能推出“为了人民”和“依靠人民”至少有一项未坚持，C项指定前一项，超出了可推出的范围。","evidence":"只有为了人民的现代化，才有意义","qids":["江苏 2025 A类 行测#91","江苏 2025 C类 行测#91"]}]},{"title":"多条件推理中的逆否命题","uses":[{"unit":"Q3","role":"解题依据","use":"补入D项后，由小周是经济学专业的推出小赵不是哲学专业的，再推出小钱是法医专业的。由此推出小孙不是计算机专业的，结合小李和小孙至少有一人是计算机专业的，得到小李是计算机专业的。两次逆否推理分别用到条件（1）和（4）。","evidence":"根据条件①可知：想要推出“小赵不是哲学专业的”，根据“逆否等价”，需要“小周是经济学专业的”成立，对应D项。","qids":["江苏 2025 B类 行测#102"]}]}]},"k-c25743c467c5163b":{"review":{"definition":"相容析取用“或”连接分命题。至少一个分命题为真时，整个命题为真，两个分命题可以同时为真。","explanation":"按本题解析，行动方案满足某位将军的意见，就计为采纳该意见。乙、丙的意见都把“侧面奇袭”列为其中一个分支。一旦该分支为真，两人的意见同时得到满足，违反“只有一位将军的意见被统帅采纳”，所以选B。","references":[],"evidence":"乙：或者不烧敌粮草，或者侧面奇袭","disposition":"独立词条","basis":"据原题和解析编释。","title":"相容析取","related":[],"examFocus":{"江苏 2023 A类 行测#91":"先辨明“须是”所连接的条件，再用相容析取和逆否规则检验各项推论。","江苏 2024 B类 行测#92":"用合取和相容析取表示三位将军的意见，再按“恰有一条成立”的约束检验各项行动是否可能。"}},"readings":[{"origin":"k-c25743c467c5163b","title":"相容析取","qs":["江苏 2024 B类 行测#92"],"definition":"相容析取用“或”连接分命题。至少一个分命题为真时，整个命题为真，两个分命题可以同时为真。","explanation":"按本题解析，行动方案满足某位将军的意见，就计为采纳该意见。乙、丙的意见都把“侧面奇袭”列为其中一个分支。一旦该分支为真，两人的意见同时得到满足，违反“只有一位将军的意见被统帅采纳”，所以选B。","evidence":"乙：或者不烧敌粮草，或者侧面奇袭","doubt":"","references":[]},{"origin":"k-e85f38d8ca114093","title":"相容析取","qs":["江苏 2023 A类 行测#91"],"definition":"相容析取用“或”连接两个可以同时为真的命题。至少一个支项为真，整个析取式就成立。只有两个支项都为假，整个析取式才为假。","explanation":"题干以“理想信念缺失或者不坚定”为条件。C项给出“理想信念缺失”，已满足其中一个支项，因此可以推出会得“软骨病”。D项从“不容易在考验面前迷失方向”逆否推出两个支项均不成立，即理想信念既不缺失，也并非不坚定，因此按本题表述可推出有坚定的理想信念。","evidence":"理想信念缺失或者不坚定","doubt":"","references":[]}]},"k-312e1b62e4f644a3":{"review":{"definition":"人数按整数计。“至少n人”的否定是“至多n−1人”，“至多n人”的否定是“至少n＋1人”。","explanation":"题目问哪项不能推出，可以把选项否定后代入。A项的否定是陈、丁均未入选，这会使赵成为唯一入选的女性，又因陈未入选而排除张，剩余两个名额只能给王和李，违反王、李至多选一人的条件。D项的否定是李、赵均入选，此时再选陈或丁即可组成符合全部条件的三人小组，所以D不能推出。","references":[],"evidence":"且涉及“至少”“至多”，可以考虑反向代入","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4d4d6e2f1c4d44ca":{"review":{"definition":"在“如果P，那么Q”为真的前提下，只要P成立，就能推出Q成立。P是前件，Q是后件。","explanation":"若研发部录用博士生，由预测（2）可推出生产部也录用博士生，与三个部门学历各不相同的条件冲突，排除B。若财务部录用本科生，由预测（3）可推出研发部也录用本科生，同样冲突，排除A、D。C给出生产部录用博士生、研发部录用本科生，财务部录用硕士生时符合三个部门学历互异的条件及全部预测。","references":[],"evidence":"如果研发部录用博士生，那么生产部录用博士生","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-53c0718852913da6":{"review":{"definition":"在“如果P，那么Q”为真的前提下，若后件Q不成立，就能推出前件P也不成立，因为P成立必然使Q成立。","explanation":"研发部只录用一人，已知录用硕士生，就能排除录用本科生，从而否定预测（3）的后件。保持预测（3）成立时，其前件“财务部录用本科生或者硕士生”也必须为假，因此D项所说的财务部录用硕士生不符合预测。","references":[],"evidence":"否后必否前","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-46932d0b40bceb86":{"review":{"definition":"当单选题答对得满分、其余作答均得零分时，该题的答对率等于平均得分除以题目分值。","explanation":"所有考生在该题上的总得分等于答对人数乘以题目分值。总得分先除以参加测验的总人数得到平均得分，再除以题目分值，就得到答对人数占总人数的比例。这与题干对单选题难度的定义一致，因此能推出D项。","references":[],"evidence":"该题的平均得分与该题分值的比值","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a73e31fef601c55e":{"review":{"title":"年均增长率比较","type":"原理与机制","definition":"各指标的基期量和末期量均为正，且年度增长期数相同时，末期量与基期量之比越大，复合年均增长率越高。","explanation":"设基期量为 A、末期量为 B、年度增长期数为 n，则复合年均增长率为 (B/A)^(1/n)−1。n 为相同的正整数时，取 n 次方根再减 1 保持比值的大小顺序。若起始年计作第一个增长年度，基期取起始年的上一年。","basis":"据关联原题和解析编释。","references":[],"related":["k-e556a045ee04f9b4","k-17810c9f5dfc628e"],"examFocus":{"江苏 2024 B类 行测#123":"在酱油进出口表中按同一起止年份取数，比较各指标的末期值与基期值之比。","江苏 2024 C类 行测#123":"在酱油进出口表中按同一起止年份取数，比较各指标的末期值与基期值之比。"}},"aspects":[{"title":"相同期数下比较末期量与基期量之比","uses":[{"unit":"Q1","role":"直接考查","use":"本题 的酱油进出口表见《历年试卷与解析（书签版）》PDF 第 476 页。按解析口径，以 2015 年为基期、2022 年为末期，覆盖 2016—2022 年的 7 个年度增长期。按进口量、出口量、进口额、出口额的顺序，末期量与基期量之比分别约为 1.009、1.585、1.084、1.624，出口额居首，选 D。","evidence":"2016-2022年我国酱油进口量、出口量、进口额、出口额4个指标中年均增速最快的是：","qids":["江苏 2024 B类 行测#123"]},{"unit":"Q2","role":"直接考查","use":"本题 的酱油进出口表见同一 PDF 第 559 页。核对两卷表格，2015 年和 2022 年的四项数据一致，沿用 Q1 的 7 期比较结果，出口额年均增速最快，选 D。","evidence":"年份差相同时","qids":["江苏 2024 C类 行测#123"]}]}]},"k-b80df060cbca4663":{"review":{"definition":"当分子、分母在两期均为正，且按同一期间、同一口径计算增速时，分子增速高于、等于或低于分母增速，比值就分别上升、持平或下降。","explanation":"现期比值等于基期比值乘以「分子的增长倍数÷分母的增长倍数」。本题A项比较省国资委监管企业的营业收入利润率，利润同比增长30.4%，高于营业收入的4%，所以利润率提高。C项比较省国资委监管企业利润占省、设区市国资委监管企业利润的比重，前者利润同比增长30.4%，高于合计利润的16.1%，所以比重也提高。A、C均可推出。","references":[],"evidence":"若部分增长率（a）>整体增长率（b），则比重上升","disposition":"独立词条","basis":"据原题和解析编释。","title":"两期比值的升降","related":[],"examFocus":{"江苏 2024 A类 行测#130":"用两期比值的判断方法，把省国资委监管企业利润的同比增速分别与其营业收入、全省省市两级合计利润的同比增速比较。","江苏 2024 B类 行测#130":"判断利润率和利润占比的同比变化时，先确定两个比值各自的分子和分母，再比较对应的同比增速。"}},"readings":[{"origin":"k-b80df060cbca4663","title":"两期比值的升降","qs":["江苏 2024 B类 行测#130"],"definition":"当分子、分母在两期均为正，且按同一期间、同一口径计算增速时，分子增速高于、等于或低于分母增速，比值就分别上升、持平或下降。","explanation":"现期比值等于基期比值乘以「分子的增长倍数÷分母的增长倍数」。本题A项比较省国资委监管企业的营业收入利润率，利润同比增长30.4%，高于营业收入的4%，所以利润率提高。C项比较省国资委监管企业利润占省、设区市国资委监管企业利润的比重，前者利润同比增长30.4%，高于合计利润的16.1%，所以比重也提高。A、C均可推出。","evidence":"若部分增长率（a）>整体增长率（b），则比重上升","doubt":"","references":[]},{"origin":"k-c43af7aa2fe148fb","title":"两期比值的升降","qs":["江苏 2024 A类 行测#130"],"definition":"当分子基期值和两期分母均为正，且两项增速按同一时期口径计算时，分子增速高于分母增速，比值上升；分子增速低于分母增速，比值下降；两者相等，比值不变。","explanation":"现期比值等于基期比值乘以（1＋分子增速）÷（1＋分母增速），因此比较两项增速即可判断比值的升降。第130题中，2023年上半年省国资委监管企业利润同比增长30.4%，高于其营业收入增速4%，所以营业收入利润率同比提高，A项可推出。该利润增速也高于省、设区市国资委监管企业合计利润增速16.1%，所以省级利润占比同比提高，C项可推出。","evidence":"若部分增长率（a）>整体增长率（b），则比重上升","doubt":"","references":[]}]},"k-f9e936d4b487b5d1":{"review":{"definition":"年均增速是在一段时期内，使期初值按同一比率逐年复合增长后恰好达到期末值的等效年增长率。若期初值为 A、期末值为 B、相隔 n 个年度增长区间，则年均增速 r 满足 B＝A×(1＋r)ⁿ。","explanation":"2020—2022年的三个年度增长区间分别是2019年末至2020年末、2020年末至2021年末、2021年末至2022年末，因此三年累计增长倍数为2659÷2309。题设假定2023—2025年沿用同一年均增速，且同样经过三个年度增长区间，所以2025年销售收入为2659×(2659÷2309)≈3062亿元，对应C项。","references":[],"evidence":"2022年和2019年我国游戏市场销售收入分别为2659和2309亿元","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a2f9bcd1d5de1658":{"review":{"definition":"“水稻+禾虫”是在同一稻田种稻、养禾虫的绿色生态种养模式，通过禾虫的取食、钻洞等活动改善稻田生态，并通过销售稻米和禾虫获得收益。","explanation":"材料1中，老王采用的模式停用除草剂、农药和化肥。禾虫取食腐烂的稻根和茎叶，有助于减少水稻病害，钻洞可松动土壤，排泄物可作有机肥。老王的稻米产量有所降低，但凭借优质优价，稻米这一项的收益仍不低于从前，出售禾虫又增加一项收入。归纳时应同时写出生态改善和种粮增收两方面成效。","references":[],"evidence":"禾虫会吃掉腐烂的稻根和茎叶、田里的浮游生物，减少水稻病害。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3bb54269373255d0":{"review":{"definition":"农业“大托管”是把分散农户的农业生产环节集中组织起来的集约化经营模式。材料中的C村由村集体统一耕种、防治、收获和销售，并向托管农户分红。","explanation":"C村统一组织生产，在220亩玉米上开展密植滴灌分段调控示范，玉米获得丰收，村集体以收购方的预付款先行分红。归纳时，统一组织生产和销售是举措，推广增产技术、丰收分红和越来越多村民接受托管是成效。","references":[],"evidence":"村集体统一耕、种、防、收、售","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2b5d6efd6fae8313":{"review":{"definition":"在孔家湾“同心小院”，召集人由院民集体推选、村党支部同意，负责组织院民议事、协调邻里矛盾并带头参与公共事务。","explanation":"有威望、热心的退休党员老章和其他院民劝解有旧怨的三户人家，使议事会得以召开。他组织商议污水沟改造，小院汇总意见上报后，镇里决定铺设暗渠。他还与另外两名党员分别牵头负责保洁，带动院民报名加入。分析转变原因时，这些事例分别说明召集人怎样化解参与障碍、推动意见落实并以行动带动院民。","references":[],"evidence":"有威望又热心肠的退休党员老章被选为小院召集人。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-450071c7f39a8786":{"review":{"definition":"孔家湾通过“小院课堂”“小院剧场”和“小院议事会”，为院民了解政策、参加集体活动和协商公共事务提供渠道。","explanation":"课堂及时宣讲政策，剧场定期组织文娱活动，给院民提供参与集体活动的机会。小院制定院规民约，并通过议事会共商院内事务，院民可以就污水沟改造这类公共问题提出意见、形成建议。分析群众由旁观转为参与的原因时，这一项对应小院提供的活动机会和议事渠道。","references":[],"evidence":"制定院规民约，通过“小院议事会”共商院内大小事务。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-d1c6afdef8a20952":{"review":{"definition":"孔家湾以农户为单位实行积分制，每月开展积分评比，通过增强院民的荣誉感来调动参与小院事务的积极性。","explanation":"材料给出了以户为单位、每月评比的安排，并记载实施后院民荣誉感增强。参考答案据此把积分评比列为群众从“旁边看”转向“共同干”的激励因素。","references":[],"evidence":"积分制实施后，院民的荣誉感空前增强。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-f808cdc1f3231eb7":{"review":{"definition":"材料中的“水稻+”模式是在种稻的同时，在稻田养殖禾花鱼、龙虾、泥鳅等水产，实现一田多用、一季多收。","explanation":"邻村种粮大户老四介绍，水稻可为鱼遮阳，泥鳅有助于净化水质。按他介绍的邻村经验，该模式节省了农药、化肥等开支，每亩每年增收约3000元。公开信可用镇里请农技专家指导和邻村实际收益来回应F村村民对种稻收益的担忧，增收数字应明确归于邻村经验。","references":[],"evidence":"节省农药、化肥等成本不说，收入也不低，每年亩产增收3000元左右。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-359fe1d28f029670":{"review":{"definition":"水稻油菜轮作是在同一块田上按季节交替种植水稻和油菜。W镇农办雷主任根据F村的土壤条件，认为当地采用这种轮作有利于保障作物产量和品质，提高土地生产能力。","explanation":"公开信可把轮作写成适合F村的退藕还稻方案，并写明镇里承诺的技术支持。条件相似的D村在轮作之外，还与科研机构合作引进科技稻并采用绿色生产方式，稻米和菜油取得的是有机转换认证证书。这些是D村的实践和成效，可供F村借鉴。","references":[],"evidence":"你们村的土壤非常适宜水稻油菜轮作","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4eaf82f70e22cda4":{"review":{"definition":"人能够在观察和实践的基础上，通过思维加工认识客观事物之间的联系及其运动变化的规律。","explanation":"人们把观察到的蜻蜓低飞与随后出现的降雨联系起来，并将这种联系概括成可用于判断天气的经验。题干强调的是从观察到经验概括的过程，因此选C。A项把个人亲身实践说成获取信息的唯一途径，忽略了人们也能从他人传授中获得间接经验。","references":[],"evidence":"人类通过意识活动把握客观事物运动变化的规律","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5d9a5cd789e2855c":{"review":{"definition":"湿地可通过生物呼吸和有机质分解释放二氧化碳，积水缺氧时还可由微生物产生甲烷。氨挥发是氮循环过程，部分湿地在一定条件下也会向大气释放氨气。","explanation":"本题要求选出不正确项，参考答案为C。解析所说的二氧化碳和甲烷是湿地向大气释放碳的主要气体，这一判断无法排除氨排放。施氮稻田可发生氨挥发，天然潮汐盐沼的观测也表明，低潮时更多土壤裸露，氨排放可增大。C项未限定湿地类型和条件，按“湿地可以排放这些气体”理解，不能据此将C判为唯一错误项。","references":[{"source":"web-e4306d21be164793","location":"Abstract，低潮氨通量观测","quote":"The largest fluxes were observed at low tide when more soil was exposed."},{"source":"web-ec60025d93c602dd","location":"首页摘要及关键词","quote":"稻田  氨挥发  施氮量"}],"evidence":"碳释放以二氧化碳和甲烷为主","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-aa9d1c64664cf5fb":{"review":{"definition":"农业具有食品保障、生态涵养、休闲体验和文化传承等多种功能。土地能承载生产和生态等多种用途，各地的自然资源条件会影响这些功能的发挥。","explanation":"第13题解析用土地的多重效用解释A所说的功能来源，用各地土地、光热、水和地形等条件的差异解释B所说的地域差别。同一种农业功能在不同地区的发挥程度可以不同，因此A、B均符合题意中的正确表述。","references":[],"evidence":"它最终来源于土地的多效用性","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-64046876abc02a5e":{"review":{"definition":"两个物体沿同一直线或平行直线以相反方向匀速运动时，相对速度的大小等于各自速率之和。相对位移的大小等于相对速度的大小乘以经过的时间。","explanation":"忽略窗长后，车窗可视为随动车移动的一点。对向列车从车头经过车窗到车尾经过车窗，相对位移为该列车的全长420米，动车的210米车长不参与计算。两车相对速度为420÷3.6米/秒，折合420千米/小时，减去动车的180千米/小时，得240千米/小时，对应B项。","references":[],"evidence":"相遇距离即为平行列车的车长","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-747aa11a88333a59":{"review":{"definition":"有限等差数列中，距首项和末项同样远的两项之和等于首尾两项之和。四项等差数列的首尾两项与中间两项各占总和的一半。","explanation":"把配对的一项向后移一位、另一项向前移一位，两项的变化量互相抵消。本题四人的年龄总和是142岁，所以最大与最小年龄之和、第二大与第三大年龄之和均为71岁。确定47岁是第二大年龄后，可求得第三大年龄为24岁。","references":[],"evidence":"第二大和第三大的年龄和为","disposition":"独立词条","basis":"据原题和解析编释。","title":"等差数列的对称项和","related":[],"examFocus":{"江苏 2024 B类 行测#56":"利用等差数列对称项的和相等，结合已知年龄可能处在的位置判断最大项。"}},"readings":[{"origin":"k-747aa11a88333a59","title":"等差数列的对称项和","qs":["江苏 2024 C类 行测#56"],"definition":"有限等差数列中，距首项和末项同样远的两项之和等于首尾两项之和。四项等差数列的首尾两项与中间两项各占总和的一半。","explanation":"把配对的一项向后移一位、另一项向前移一位，两项的变化量互相抵消。本题四人的年龄总和是142岁，所以最大与最小年龄之和、第二大与第三大年龄之和均为71岁。确定47岁是第二大年龄后，可求得第三大年龄为24岁。","evidence":"第二大和第三大的年龄和为","doubt":"","references":[]},{"origin":"k-e498775a3e958701","title":"等差数列的对称项和","qs":["江苏 2024 B类 行测#56"],"definition":"有限等差数列中，从首项和末项分别往内数相同步数得到的两项，其和等于首项与末项的和。两端向内移动时，一项增加的量和另一项减少的量相等。","explanation":"四个年龄的首末两项之和等于中间两项之和，均为142÷2＝71岁。47岁高于平均年龄35.5岁，只可能是较大的两项之一。选项中没有47岁，按本题选项可将47岁确定为第二大，另一中间项为24岁，公差为23岁，最年长者为70岁。若允许非整数年龄且脱离选项，47岁也可为最年长者。","evidence":"年龄总和为142岁，且他们的年龄恰好成等差数列","doubt":"","references":[]}]},"k-6092f66988e1dac5":{"review":{"definition":"当某类人数占总人数的比例恰为最简分数时，分母必须整除总人数。有多个这样的比例时，总人数是各分母最小公倍数的整数倍。","explanation":"人数为整数。把比例约成最简分数后，分子和分母互质，分母只能从总人数中约去。两份公开题本均载明，50岁及以上居民占1/12，女性占7/16。12和16的最小公倍数是48，90至110之间只有96符合条件。50岁及以上有8人，30岁以下有（96－20）÷2＝38人，相差30人，选A。","references":[{"source":"web-92745d26e83e0238","location":"第57题题干","quote":"50岁及以上居民占1/12，女性占7/16"},{"source":"web-61daf72985c8ee40","location":"来源标注为2024江苏C-057的题干","quote":"50岁及以上居民占1/12，女性占7/16"}],"evidence":"居住总人数应既是12的整数倍又是16的整数倍","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-0b46f4b227013c0e":{"review":{"definition":"两个正整数的最小公倍数是它们共有的最小正倍数。它们的正公倍数恰好是最小公倍数的正整数倍。","explanation":"一个数同时被12和16整除，必须含有这两个数要求的全部质因数及各自所需的最高次数。12和16的最小公倍数为2⁴×3＝48，因此由解析给出的两项整除条件可知，总人数是48的倍数。90到110之间只有96符合。","references":[],"evidence":"48（12和16的最小公倍数）","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-aea49d91fefa42d5":{"review":{"definition":"圆柱的体积等于底面积乘以高。沿底面平行切出的任一圆柱段也适用这一公式。","explanation":"铁块高15厘米，容器高45厘米，完全淹没铁块后还需填满上方30厘米的圆柱段。这一段没有铁块占据。按水龙头匀速注水、每分钟注水量为1个体积单位计算，30厘米高的圆柱段容积为16个体积单位，整个容器的容积为16×45÷30＝24个体积单位。","references":[{"source":"geof","location":"附录 C · Cylinder"}],"evidence":"45a-15a=16","disposition":"独立词条","basis":"据原题和解析编释。","title":"圆柱体积公式","related":["k-6f0505868fc927aa","k-d9f880b35a6045f2","k-d73cb19a60baeb11"],"examFocus":{"江苏 2024 C类 行测#58":"用圆柱体积公式和两段注水时间，比较铁块淹没前后的注水量及对应圆柱段的容积。"}},"readings":[{"origin":"k-aea49d91fefa42d5","title":"圆柱体积公式","qs":["江苏 2024 C类 行测#58"],"definition":"圆柱的体积等于底面积乘以高。沿底面平行切出的任一圆柱段也适用这一公式。","explanation":"铁块高15厘米，容器高45厘米，完全淹没铁块后还需填满上方30厘米的圆柱段。这一段没有铁块占据。按水龙头匀速注水、每分钟注水量为1个体积单位计算，30厘米高的圆柱段容积为16个体积单位，整个容器的容积为16×45÷30＝24个体积单位。","evidence":"45a-15a=16","doubt":"","references":[]},{"origin":"k-04afb32e93c4eb04","title":"圆柱体积","qs":["江苏 2023 A类 行测#57","江苏 2023 B类 行测#57"],"definition":"圆柱体积等于底面积乘以高。圆形底面的半径为 r、高为 h 时，V＝πr²h。","explanation":"高指两个底面之间的垂直距离。半径翻倍且高不变时，体积变为原来的四倍。","evidence":"","doubt":"","references":[{"source":"geof","location":"附录 C · Cylinder"}]}]},"k-4b5338eef077ebf5":{"review":{"definition":"水面以下的水量等于容器在该水位以下的容积减去物体浸在水中的部分所占的体积。物体完全浸没时，扣除的是整个物体的体积。","explanation":"按容器起初无水、水龙头匀速注水且每分钟注水量为1个体积单位计算，前6分钟注入6个体积单位，此时水面恰好到达15厘米高的铁块顶部。水面上方30厘米的圆柱段容积为16个体积单位，因此下方15厘米的圆柱段容积为8个体积单位。铁块占据8−6＝2个体积单位，与容器的体积之比为2∶24＝1∶12，对应A项。","references":[],"evidence":"6分钟水面恰好淹没铁块","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-54911c38df41f3d0":{"review":{"definition":"当基本结果的个数有限且各结果等可能时，事件的概率等于符合该事件的基本结果数除以基本结果总数。","explanation":"按题意，8 个节目中任意 3 个组成的入选名单等可能。56 种名单中，有 20 种完全由其他科室的节目组成，所以小张所在科室的节目全部落选的概率为 20/56＝5/14。","references":[],"evidence":"则从另外8-2=6个节目中随机选出3个","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-38c5c64fdd1f1ab6":{"review":{"definition":"一个事件与其对立事件互斥，且二者涵盖全部可能结果，因此它们的概率之和为 1。","explanation":"小张所在科室有 2 个节目，“至少有一个被选送”包括恰好入选 1 个和两个都入选两种情形。其对立事件是这 2 个节目全部落选，概率为 5/14，所以所求概率为 1－5/14＝9/14，对应 D 项。","references":[],"evidence":"至少有一个被选送参加汇演","disposition":"独立词条","basis":"据原题和解析编释。","title":"对立事件的概率","related":[],"examFocus":{"国考 2024 副省级 行测#74":"根据人数互异、下限和倍数限制确定第二大小组的规模，再用对立事件比较相应的组员选取方式数与总方式数。","江苏 2024 A类 行测#59":"用对立事件处理“至少一个入选”，比较对立情形的节目选取组合数与总组合数。","江苏 2024 C类 行测#59":"用对立事件处理“至少一个入选”，比较对立情形的节目选取组合数与总组合数。"}},"readings":[{"origin":"k-38c5c64fdd1f1ab6","title":"对立事件的概率","qs":["江苏 2024 C类 行测#59"],"definition":"一个事件与其对立事件互斥，且二者涵盖全部可能结果，因此它们的概率之和为 1。","explanation":"小张所在科室有 2 个节目，“至少有一个被选送”包括恰好入选 1 个和两个都入选两种情形。其对立事件是这 2 个节目全部落选，概率为 5/14，所以所求概率为 1－5/14＝9/14，对应 D 项。","evidence":"至少有一个被选送参加汇演","doubt":"","references":[]},{"origin":"k-4fb53c99b56f5c77","title":"对立事件的概率","qs":["江苏 2024 A类 行测#59"],"definition":"在同一次随机试验中，事件 A 与“事件 A 不发生”互为对立事件。两者恰有一个发生，概率之和为 1。","explanation":"第 59 题中，小张所在科室的两个节目至少有一个入选，包括恰好入选一个和两个都入选。它的对立事件是两个节目都落选，即选出的 3 个节目全部来自其余 6 个节目。两个节目都落选的概率为 C(6,3)/C(8,3)=5/14，因此所求概率为 1−5/14=9/14，对应 D 项。","evidence":"反面情况为3个选送节目均不来自小张所在的科室","doubt":"","references":[]},{"origin":"k-6ab403948aa552fe","title":"对立事件的概率","qs":["国考 2024 副省级 行测#74"],"definition":"一个事件及其对立事件恰好有一个发生，因此两者的概率之和为1。对立事件更容易计数时，可用1减去其概率求原事件的概率。","explanation":"最小组若有4人，六组人数至少为4至9人，总人数至少39人。因此最小组有3人，最大组至多9人。3至9这七个人数合计42，选六个合计36须舍去6，故第二大组有8人。按解析采用的等可能分组模型，随机取这8名组员时，甲乙至少一人入组选取的对立事件是两人均未入组。所求概率为1－(28/36)×(27/35)＝40%，选B。","evidence":"反面情况为甲和乙两人均未分到人数第二多的小组","doubt":"","references":[]}]},"k-585bec9d127a9cd2":{"review":{"definition":"从均匀溶液中分取一部分时，取出部分和剩余部分的浓度都与分取前相同。含同一种溶质的溶液混合时，若无反应或溶质损失，混合后该溶质的质量等于各份所含质量之和。","explanation":"第一次倒入乙瓶的40克溶液浓度为40%，带入16克溶质。甲瓶剩下60克同浓度溶液，含溶质24克。再加40克水后，甲瓶有100克浓度为24%的溶液，第二次倒出的40克便带入9.6克溶质。乙瓶合计含溶质25.6克、溶液80克，浓度为32%，选B。","references":[],"evidence":"40克浓度为40%的溶液","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-507146993bee78cc":{"review":{"definition":"两个集合的交集包含同时属于两个集合的成员。任一集合的人数等于仅属于该集合的人数与交集人数之和。","explanation":"180名会员中，参加甲活动的有108人，其中80人只参加甲活动，因此两项都参加的有28人。这28人也计入参加乙活动的90人，从90人中扣除他们，得到只参加乙活动的有62人，选C。","references":[],"evidence":"甲、乙两项活动都参加的会员人数为108-80=28人","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-335b8ba1eafdec9b":{"review":{"definition":"在正六边形中，每隔一个顶点取一点，连接所得的三个顶点可构成等边三角形。这个三角形的内心和外心都在正六边形的中心。","explanation":"本题的 A、C、E 是交替取出的三个顶点，相邻两点所对的圆心角均为 120°，所以三条弦 AC、CE、EA 等长。正六边形的中心到 A、C、E 等距，是三角形 ACE 的外心。等边三角形的外心与内心重合，因此内切圆的圆心 O 也是正六边形的中心。","references":[],"evidence":"由于ABCDEF是正六边形，可得AC=CE=EA","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b2e53bff22725361":{"review":{"definition":"等边三角形的内切圆半径等于其高的三分之一。其内心与重心重合，重心到一边中点的距离等于对应中线长度的三分之一。","explanation":"本题正六边形的外接圆半径等于边长 2，因而三角形 ACE 的外接圆半径 AO 为 2。设 H 为 CE 的中点，则 AH 既是中线也是高。重心 O 将 AH 分成 AO 和 OH 两段，AO＝2OH，所以 OH＝1，即内切圆半径。","references":[],"evidence":"所求圆半径OH=AH-AO","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d226eb6a08404fcd":{"review":{"definition":"如果甲成立必须以乙成立为前提，乙就是甲的必要条件。甲成立可推出乙成立，乙不成立可推出甲不成立。","explanation":"第91题中，“除非……否则不能……”表示鸟能飞向天空就必须同时满足两翼健壮、以共同的力量推动身体，故②成立。①把两个必要条件当成了充分条件，④从不能飞反推至少一个条件不成立，二者均无法由题干推出。","references":[],"evidence":"除非两翼健壮并以共同的力量来推动身体，否则它不能飞向天空","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8022240ccb40c678":{"review":{"definition":"若甲成立必推出乙成立，乙成立又必推出丙成立，则甲成立必推出丙成立。串联时，前一命题的后件须与后一命题的前件一致。","explanation":"第92题中，“只有乙参加，甲才参加”给出的方向是甲参加推出乙参加。接着由乙参加推出丙参加，再由丙参加推出丁不参加。因此甲参加时丁必不参加，C项所说的甲和丁同时参加不可能为真。","references":[],"evidence":"将（1）（2）（3）串联可得","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a08a173ea435abfc":{"review":{"definition":"按题干的口径，人体总能量代谢主要受静息代谢和活动能量代谢影响。前者对应静止状态下的能量消耗，后者对应日常活动或运动时的能量消耗。","explanation":"第93题已知M市成年人总能量代谢下降。B项的日均锻炼时长增加为活动能量代谢可能上升提供了间接线索，使静息代谢下降更能解释总量变化。锻炼时长只反映部分活动信息，因此B支持该观点，尚不足以单独证实它。C项劳动强度降低和D项活动能量代谢降幅较大，都提供了总量可能因活动能耗下降而下降的解释。","references":[],"evidence":"人体总能量代谢主要由静息代谢水平和活动能量代谢水平决定。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-1640d9b392026c39":{"review":{"definition":"原题引文：所有参加100米跑的运动员都参加了跳高","explanation":"800米跑选手都在100米跑选手之中，100米跑选手都在跳高选手之中，因此A项可推出。跳远选手全都未参加跳高，因而也未参加100米跑或800米跑，C项可推出，D项与题干矛盾。B项所说的全体链球选手也超出了前提。按公开回忆版与所给题面一致的“不能推出”设问，B、D均符合。参考答案D对应的是其中必假的一项。","references":[{"source":"web-452b1a57c66d8a4d","location":"来源标注为2024江苏A-101／江苏C-095的题目，设问和参考答案","quote":"根据以上陈述，不能推出以下哪项？"}],"evidence":"所有参加100米跑的运动员都参加了跳高","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-bd26ee63feef5366":{"review":{"definition":"原题引文：“有的”无法推出“所有”","explanation":"有些跳远选手参加链球，而所有跳远选手都未参加跳高，所以至少有一名链球选手未参加跳高。另有一名运动员只参加链球和跳高，仍符合题干全部条件，却会使B项为假。因此B项不能推出。D项也不能推出，而且与800米跑选手均参加跳高、跳远选手均未参加跳高的条件矛盾。参考答案选D采取了优先选择必假项的口径，按题面“不能推出”的设问仍有两个选项。","references":[{"source":"web-452b1a57c66d8a4d","location":"来源标注为2024江苏A-101／江苏C-095的题目，B项及其解析","quote":"所有参加投掷链球的运动员都没有参加跳高"}],"evidence":"“有的”无法推出“所有”","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-9ff8c318a44234f1":{"review":{"definition":"在统计时期和用户范围一致时，消费总额等于用户数乘以人均消费额。","explanation":"人均消费额等于消费总额除以纳入统计的用户数，因此可用乘法还原总额。本题按材料口径，用2021年直播电商用户数4.3亿人乘以人均年消费额4640元，得交易额1.9952万亿元，约为2万亿元。2022年交易额为3.5万亿元，两年交易额之比约为3.5∶2，即7∶4，对应D项。","references":[],"evidence":"2021年我国直播电商行业用户数为4.3亿人，人均年消费额为4640元。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b4a4e22f3768f804":{"review":{"definition":"期初量、期末量均为正且年份差相同时，各指标年均增长率的大小顺序与期末量除以期初量所得比值的大小顺序一致。","explanation":"年均增长率的计算是将期末量与期初量的比值开 n 次方，再减 1，n 为年份差。对正数开相同次数的方根会保持原有的大小顺序。本题从 2019 年到 2022 年相隔 3 年，企业数、用户数和人均年消费额的期末期初比分别为 18700÷5684≈3.29、4.7÷2.5=1.88、7450÷1775≈4.20。因此年均增速从低到高依次为用户数、企业数、人均年消费额，即 V₂＜V₁＜V₃，符合 B 项。","references":[],"evidence":"我国直播电商行业企业数、用户数、人均年消费额的年均增速分别用","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5f2191f51d8a666c":{"review":{"definition":"在同一统计口径下，总量包含某一部分且其余部分的数量非负时，总量至少等于该部分量。如果该部分量超过某个数值，总量也超过该数值。","explanation":"材料称2022年重点监测电商平台直播场次超过1.2亿场，较2020年增长5倍，因此2022年场次是2020年的6倍，倒推2020年重点监测平台直播场次超过2000万场。同期直播电商行业的总场次包含这些场次，即使两者相等，行业总场次也超过2000万场，因此选B。","references":[],"evidence":"重点监测电商平台直播场次超1.2亿场，较2020年增长5倍","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-63a9fc5fc2cfc871":{"review":{"title":"累计值与单期值","type":"原理与机制","definition":"对可以按期相加的流量指标，在统计口径一致、累计起点相同的条件下，较晚截止的累计值减去较早截止的累计值，等于两个截止时点之间的发生量。","explanation":"两个累计截止时点相隔一个统计期时，差额就是该期的单期值。以年初为累计起点时，第一季度累计值就是第一季度的单期值。若只给出各累计期间的总体值和部分占比，应先按各期对应的占比求出部分累计值，再相减得到该部分的单期值。","basis":"据关联原题和解析编释。","references":[],"examFocus":{"江苏 2024 C类 行测#116":"用工业用电量表中两年的累计值分别还原第二季度用电量，再求同比增量。","江苏 2024 C类 行测#117":"按各自的年度累计区间还原单季进出口总额，再跨年比较。","江苏 2024 C类 行测#118":"用各期累计地区生产总值和同期第三产业占比先求累计增加值，再用相邻期的累计增加值还原单季值。"}},"aspects":[{"title":"已知累计值求单季值","uses":[{"unit":"Q1","role":"解题依据","use":"江苏 2024 C类 行测第116题。分别用2023年和2022年上半年累计工业用电量扣除各自第一季度用电量，得到第二季度用电量92亿和88.2亿千瓦时，同比增加3.8亿千瓦时，选B。","evidence":"（173.3-81.3）-（169.8-81.6）","qids":["江苏 2024 C类 行测#116"]},{"unit":"Q2","role":"解题依据","use":"江苏 2024 C类 行测第117题。将各年累计进出口总额换算为单季值后比较，2022年第四季度为6292.0减4566.0，得1726亿元，在所问区间内最高，选C。","evidence":"2022年第四季度=6292.0-4566.0","qids":["江苏 2024 C类 行测#117"]}]},{"title":"由累计总体值和占比求单季部分值","uses":[{"unit":"Q3","role":"解题依据","use":"江苏 2024 C类 行测第118题。将2023年上半年和第一季度累计地区生产总值分别乘以同期第三产业占比64.8%和65.4%，再将所得的两个累计增加值相减，得第二季度第三产业增加值约2623亿元，选A。","evidence":"8317.0×64.8%-4230.0×65.4%","qids":["江苏 2024 C类 行测#118"]}]}]},"k-860b7eaef4b8670b":{"review":{"definition":"两期整体量均为正时，合计比重是以各期整体量为权重计算的两期比重的加权平均。两期比重不同时，合计比重介于两者之间。","explanation":"2023年上半年由第一季度和第二季度组成。上半年出口额占进出口总额的比重为58.1%，高于第一季度的57.8%，因此第二季度的出口占比必高于58.1%，也就高于第一季度。这为判断B项的两种环比增速提供了依据。","references":[],"evidence":"第一季度出口额占比（57.8%）<1—6月累计出口额占比（58.1%）<第二季度出口额占比","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4fa49728ada827d8":{"review":{"definition":"年均增速是使基期量经过若干年等速复利增长后恰好达到期末量的等效年增长率。年均增速为 r 时，跨 n 个年度增长间隔的累计增长倍数为 (1+r)^n，即期末量除以基期量。","explanation":"2020—2022年的三个同比增长间隔从2019年末算起。按解析给出的收入数据，这三年的累计增长倍数为2659÷2309。题设令2023—2025年每年按同一年均增速增长，从2022年末到2025年末也有三个增长间隔，因此可直接用2022年的2659亿元乘以同一倍数，得到约3062亿元，对应C项。","references":[],"evidence":"2022年和2019年我国游戏市场销售收入分别为2659和2309亿元","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1bf3c0c29509a2ac":{"review":{"definition":"面向文创从业者的知识产权服务有助于保护创作者权益，增强其持续投入创作的意愿，从而支持文创产业创新。","explanation":"材料6提到，青年人才带来新创意，也面临知识产权保护难题。大会发布大运河青澜文创湾知识产权（版权）服务平台，正是为了回应这一难题。简讯可把平台发布写作亮点，把保护创作者权益、激发创作热情写作平台的预期作用。","references":[],"evidence":"激发他们的创作热情，推动文创产业的持续创新。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-973bc408bfbbd2a6":{"review":{"definition":"文化产业数字化转型是运用数字技术改变文化产品和服务的生产、传播与体验方式。数字技术用于远程传播或沉浸式互动时，可以扩大文化消费的覆盖范围，催生新的产品和服务形态。","explanation":"材料7中的梵高写真馆让观众用AI生成梵高风格的自画像，XR眼镜让观众在数字场景中体验盛唐风貌。申论第4题可用这些例子说明，技术怎样把文化资源转化为可参与的消费体验，进而论证文化创新如何培育发展新动能。","references":[],"evidence":"通过AI技术，现场生成梵高风格“自画像”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-fef8611099150695":{"review":{"definition":"文化产业跨界融合是把文化内容和创意融入旅游、体育等领域的产品或服务。文化内容形成有辨识度的体验时，有助于提升产品或服务的附加值，并拓展消费场景。","explanation":"范文用西安“对诗潮玩”说明诗词可以成为古城游览中的参与式体验，又用哪吒文化体育嘉年华说明赛事、文娱活动和商业消费如何联动。这一分论点从产业之间的资源组合解释新业态的形成。","references":[],"evidence":"将体育赛事、文娱活动、商业消费联动","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a397d793fcc856f9":{"review":{"definition":"系统是由相互联系、相互依赖的要素构成的有机整体。要素之间的组织和配合影响系统整体功能的发挥。","explanation":"鱼嘴、飞沙堰、宝瓶口与辅助工程相互配合，使都江堰整体具备分流、排沙和控制进水流量等功能。这些事实直接体现各部分协同形成整体功能，对应B项。C项着重于事物发生、发展和转化的历程，题干给出的是工程的组成及功能。","references":[],"evidence":"系统就是由事物诸要素或组成部分相互联系和相互依赖而构成的有机整体","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-078dfae96828102d":{"review":{"definition":"中长期发展规划通过公布发展目标和政策方向，为社会预期提供较稳定的参照。公众和市场主体可以据此安排面向未来的决策。","explanation":"五年规划等制度性安排把未来一段时期的发展方向提前传递给社会，帮助各方形成和调整预期。这一前瞻性指引说明编制中长期发展规划属于预期管理实践，支持C项。","references":[],"evidence":"形成了前瞻性指引，这些都会起到\n锚定预期的作用","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4f46e00e7a11b601":{"review":{"definition":"冻土路基热棒是一种密封的重力式热管，下部埋入土中吸热，上部露出地面散热。当外界气温低于埋地段周围土温时，热棒利用管内工质的蒸发和冷凝，将热量从土体传到空气中。","explanation":"青藏铁路安多试验段的热棒采用液氨作工质。管内液氨在下部吸热汽化，氨蒸气上升到地上冷凝段，向空气放热并凝成液体，再靠重力流回下部。原解析把上升的蒸气误写成了路基受热产生的水汽。题图中的金属管通过这一循环降低路基地温，减轻多年冻土融化引起的沉降，因此第20题选D“保护冻土层的结构”。","references":[{"source":"web-59a4b5ff76864bc5","location":"《岩土工程学报》2011年增刊1，第504页，第0节“引言”及第1节“试验工程概况”","quote":"热棒采用液氨－碳钢热棒"}],"evidence":"保护冻土层的结构","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-6f715c13c1598d1c":{"review":{"definition":"连续重复进行一项任务且每次用时固定时，耗时等于单次用时乘以完成次数。比较同一段时间内两项任务的完成次数时，可以用次数比表示速率比，前提是该时段恰好覆盖各自的整次任务。","explanation":"按题解的计数口径，基础地质实验结束时，海洋科学和地球物理恰好各完成32次和24次。同一时段的次数比为4∶3，所以海洋科学恰好完成40次时，地球物理完成30次，还需10次，对应C项。","references":[],"evidence":"3项科学实验同时开始，且各实验室单次实验时长不变","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-59b565dd08ecf729":{"review":{"definition":"两个同心圆之间的圆环面积等于外圆面积减去内圆面积。若外半径为 R、内半径为 r，则面积为 π(R²－r²)。","explanation":"本题 6.0 至 6.9 环所在的圆环，以 6 环圆的外缘为外边界，以 7 环圆的外缘为内边界。两圆直径分别为 20.5 毫米和 15.5 毫米，换算为半径后，面积为 π(10.25²－7.75²)＝45π 平方毫米，用作命中概率的分子。","references":[],"evidence":"即处在6环所在圆环中","disposition":"独立词条","basis":"据原题和解析编释。","title":"圆环面积","related":[],"examFocus":{"江苏 2025 A类 行测#57":"根据相邻同心圆的直径差确定目标环带的边界，用环带面积占整个靶面面积的比例判断命中概率。"}},"readings":[{"origin":"k-59b565dd08ecf729","title":"圆环面积","qs":["江苏 2025 A类 行测#57"],"definition":"两个同心圆之间的圆环面积等于外圆面积减去内圆面积。若外半径为 R、内半径为 r，则面积为 π(R²－r²)。","explanation":"本题 6.0 至 6.9 环所在的圆环，以 6 环圆的外缘为外边界，以 7 环圆的外缘为内边界。两圆直径分别为 20.5 毫米和 15.5 毫米，换算为半径后，面积为 π(10.25²－7.75²)＝45π 平方毫米，用作命中概率的分子。","evidence":"即处在6环所在圆环中","doubt":"","references":[]},{"origin":"k-f2b510bca02e22f6","title":"圆环面积","qs":["江苏 2025 C类 行测#57"],"definition":"圆环是两个同心圆之间的区域。外圆半径为 R、内圆半径为 r 时，圆环面积为 π(R²−r²)。","explanation":"本题的6.0至6.9环区域位于直径20.5毫米的6环边界和直径15.5毫米的7环边界之间。用外圆面积减去内圆面积，得到 π(10.25²−7.75²)=45π 平方毫米，作为计算命中概率的分子。","evidence":"即处在6环所在圆环中","doubt":"","references":[]}]},"k-0562567f71102b65":{"review":{"definition":"随机点在有限平面区域内均匀分布时，落入其中某一子区域的概率等于该子区域面积与总面积之比。","explanation":"本题按命中点在靶内均匀分布建模。“未脱靶”把分母限定为直径 45.5 毫米的最外圆面积。分子为 6.0 至 6.9 环所在的圆环面积，面积比为 (20.5²－15.5²)÷45.5²，约为 0.087，小于 0.1，选 A。","references":[],"evidence":"如果随机向靶纸射击且未脱靶","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-895563153032cfd2":{"review":{"definition":"三个集合各自的人数之和减去并集人数，等于恰属两个集合的人数加上恰属三个集合人数的两倍。逐集合计数时，这两类人员分别多计一次和两次。","explanation":"本题三项展览分别计数共 21＋22＋19＝62 人次，至少参观一项的有 45－5＝40 人，因此多计了 22 人次。设恰好参观两项和三项的分别有 x 人和 y 人，得到 x＋2y＝22。“至少参观两种”的 12 人同时包含这两类，给出 x＋y＝12。两式相减得 y＝10，选 D。","references":[],"evidence":"满足两项-2×满足三项=总数-都不","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f1024cecb86a7a82":{"review":{"title":"相似三角形的对应边成比例","type":"原理与机制","definition":"两个三角形相似时，对应角相等，三组对应边的长度之比都等于这两个三角形的相似比。","explanation":"两组对应角分别相等即可判定两个三角形相似。对应边是相等角各自所对的边。写比例式时，各边比的分子应取自同一个三角形。","basis":"据关联原题和解析编释。","references":[],"related":["k-b120634ad58217c5","k-f2b96384a4ff6acb"],"examFocus":{"江苏 2025 A类 行测#59":"根据刚好看全尖顶的条件确定视线在图中经过的位置，再用相似三角形比较高度差与水平距离。","江苏 2025 C类 行测#59":"根据刚好看全尖顶的条件确定视线在图中经过的位置，再用相似三角形比较高度差与水平距离。"}},"aspects":[{"title":"临界视线下的高度差与水平距离","uses":[{"unit":"Q1","role":"解题依据","use":"按题设以1.7米为视点高度，临界视线经过平顶和尖顶下缘。视线在两段水平距离上的竖直升高分别为23.7－1.7＝22米和133.7－22－23.7＝88米。由相似直角三角形得，小王到平顶建筑的距离与两建筑间距之比为22∶88，故所求距离为50米，选C。","evidence":"发现恰好能够看到尖顶建筑物的整个尖顶部分（如图所示）","qids":["江苏 2025 A类 行测#59"]},{"unit":"Q2","role":"解题依据","use":"与Q1同题，共用上述临界视线及对应边比例的计算，选C。","evidence":"发现恰好能够看到尖顶建筑物的整个尖顶部分（如图所示）","qids":["江苏 2025 C类 行测#59"]}]}]},"k-d3a486cb07d21b6e":{"review":{"definition":"半球的曲面面积是同半径球面面积的一半，等于 2πr²，其中 r 为半径。若求含圆形底面的总表面积，还需加上底面积 πr²。","explanation":"本题按解析采用无底保护罩，并保持青铜器的高度为 60 厘米。将球心放在长方体底面中心，到四个顶面角的距离相等。球心偏离该中心时，到至少一个顶面角的距离会增大，因此这个距离就是最小半径。由勾股定理，r²＝30²＋20²＋60²＝4900 平方厘米，故罩面面积为 0.98π 平方米，对应 C 项。","references":[],"evidence":"本题所求保护罩的表面积不包含底面","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8449a57c55ec2321":{"review":{"definition":"算术平均数等于各项之和除以项数。项数固定时，总和越大，算术平均数越大。","explanation":"7名裁判的打分项数固定，中间3项之和由66÷3.0确定为22，因此只需最大化其余4项的总和。最高两项可各取10分。中间3项的最小值至多为22÷3，又须是0.5的整数倍，因此至多为7分，最低两项也至多各取7分。按10、10、8、7、7、7、7分打分可以达到该上界，平均分为8.0分，对应C项。","references":[],"evidence":"中间三个分数之和为22","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-146465b18a7b6bbb":{"review":{"definition":"整数作带余除法时，被除数等于除数乘以商再加上余数，余数大于或等于0且小于正除数。","explanation":"设每束8枝可扎成a束，每束9枝可扎成b束，同一总枝数分别为8a+3和9b+5，因此8a=9b+2。由奇偶性可知b为偶数。b取0、2、4时，a均非整数。b取6时，a=7，得到符合两种余数条件的最小总枝数59，供下一步确定最大束的最少枝数。","references":[],"evidence":"8a+3=9b+5","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3930f0e40103d60c":{"review":{"definition":"若干互不相同的整数按从大到小排列时，相邻两项至少相差1。固定项数和最大值后，各项从最大值起依次减1时，总和达到上界。","explanation":"若最大束有x枝，另两束按枝数从多到少排列，分别至多有x−1枝和x−2枝，三束合计至多3x−3枝。花的总枝数至少为59，所以3x−3≥59，整数x至少为21。总数取59时，18、20、21枝恰好用完且互不相同，故C项的21枝可以达到。","references":[],"evidence":"制成数量各不相同的3束玫瑰花","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-24fa7513617a5170":{"review":{"definition":"星期每7天循环一次。从已知日期向后推时，将相差天数除以7，余几就将星期向后推几天。","explanation":"题中的“每隔4天”表示两次理疗之间空出4天，因此每5天理疗一次。把起始日从7月2日改到3日，6次理疗的星期均顺延一天。第二种排法没有星期六的理疗，所以第一种排法没有星期五的理疗。第一种排法只覆盖6个不同的星期，其日期相对7月2日的日差除以7后，余数依次是0、5、3、1、6、4，唯一缺少2。因此7月2日后两天是星期五，7月2日是星期三。7月31日比2日晚29天，余1，故为星期四，对应A项。","references":[],"evidence":"如果他7月3日去，则7月的理疗只有1次在星期日，其余都在工作日","disposition":"独立词条","basis":"据原题和解析编释。","title":"星期的七天周期","related":[],"examFocus":{"国考 2024 副省级 行测#75":"把9月和10月各拆成整周与余天，比较余天的活动次数，再利用星期周期推算年末的活动日期。","国考 2025 副省级 行测#75":"把前16天拆成整周与余天，结合工作日和周末的日营业额判断余天的星期分布。","江苏 2025 A类 行测#69":"先弄清“每隔4天”的计数口径，再按七天周期比较两种起始日期下落在周六和周日的理疗次数。"}},"readings":[{"origin":"k-24fa7513617a5170","title":"星期的七天周期","qs":["江苏 2025 A类 行测#69"],"definition":"星期每7天循环一次。从已知日期向后推时，将相差天数除以7，余几就将星期向后推几天。","explanation":"题中的“每隔4天”表示两次理疗之间空出4天，因此每5天理疗一次。把起始日从7月2日改到3日，6次理疗的星期均顺延一天。第二种排法没有星期六的理疗，所以第一种排法没有星期五的理疗。第一种排法只覆盖6个不同的星期，其日期相对7月2日的日差除以7后，余数依次是0、5、3、1、6、4，唯一缺少2。因此7月2日后两天是星期五，7月2日是星期三。7月31日比2日晚29天，余1，故为星期四，对应A项。","evidence":"如果他7月3日去，则7月的理疗只有1次在星期日，其余都在工作日","doubt":"","references":[]},{"origin":"k-2c9c51b05f428381","title":"星期的七天周期","qs":["国考 2024 行政执法 行测#68"],"definition":"星期每七天循环一次，任意连续七天各包含一次星期一至星期日。两日期的星期偏移由相隔天数除以7的余数决定。","explanation":"每连续28天，小张都参加12次活动。9月前28天之外的两天须参加1次，10月后28天之外的三天须参加2次。因此9月29日至10月3日这连续五天必须同时包含周二、周五和周日，只有从周五开始才满足。9月30日是周六，12月31日在其后92天，92除以7余1，所以12月31日是周日，也是当年最后一次活动日。","evidence":"小张连续7天参加3次社团活动","doubt":"","references":[]},{"origin":"k-365f51843437bcd8","title":"星期的七天周期","qs":["国考 2025 副省级 行测#75"],"definition":"星期按七天循环。任意连续七天中，星期一到星期日各出现一次，相差整七天的日期对应同一星期几。","explanation":"本题每个七天周期的营业额为5×1＋2×2＝9万元。3日至16日恰好覆盖两个周期，共18万元，因此1日和2日合计4万元，两天都必须是周末。连续两天同为周末只能是星期六接星期日，所以1日是星期六，相隔七天的8日也是星期六。","evidence":"连续的14天（3日至16日）包含星期一至星期日各2个","doubt":"","references":[]},{"origin":"k-94610e175b3e4f5a","title":"星期的七天周期","qs":["国考 2024 副省级 行测#75"],"definition":"星期按七天循环，任意连续七天各包含一次周一至周日。按固定星期几重复的活动，在每个连续七天内发生的次数相同。","explanation":"小张每周二、周五、周日骑行，连续28天必有12次。扣除9月前28天和10月后28天，9月末两天须有1次，10月初三天须有2次。满足这两个条件的五天依次是周五、周六、周日、周一、周二，因此9月30日为周六。12月31日距这天92天，比13整周多1天，恰逢周日，选A。","evidence":"小张连续7天参加3次社团活动","doubt":"","references":[]},{"origin":"k-efb76cdb22a3b5f1","title":"星期的七天周期","qs":["国考 2024 地市级 行测#69"],"definition":"星期按七天循环，任意连续七天恰好包含一次星期一至星期日。若活动固定在每周的若干天举行，每段完整的七天内，活动次数都等于固定活动日的天数。","explanation":"本题固定在周二、周五和周日骑行，每28天正好骑行12次。扣除9月前28天和10月后28天后，9月末两天需骑行1次，10月初三天需骑行2次。合起来，9月29日至10月3日这连续五天必须同时覆盖周五、周日和周二，只有从周五开始才满足，因此9月29日是周五。","evidence":"小张连续7天参加3次社团活动","doubt":"","references":[]}]},"k-dd01da0b0707888a":{"review":{"definition":"法律制度通过规定权利、义务和责任来规范社会行为，并为处理社会纠纷提供依据。","explanation":"代入A项时，法制是发挥约束和调节作用的一方，社会是受其作用的一方，和“森林调节气候”的方向一致。D项虽然前后都有整体与部分的关系，但“森林—树木”是整体在前，“家庭—社会”是部分在前。","references":[],"evidence":"法制会约束或调节社会","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d2546b3734862e35":{"review":{"definition":"“只有P，才Q”表示P是Q的必要条件，即Q成立必有P成立。因此，P不成立时，Q也不成立。","explanation":"条件（1）说小全练游泳就要求大陈不练跳水。选A后，由条件（4）推出大刘练水球，再由条件（2）推出大陈练跳水。此时小全练游泳所需的条件不成立，依逆否推理可知小全不练游泳，再由条件（3）推出小吴练游泳。","references":[],"evidence":"只有大陈不练跳水，小全才练游泳","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4d43cd7b1b0171c1":{"review":{"definition":"两项不相容选言命题要求恰有一项为真。一项为假，另一项必为真。一项为真，另一项必为假。","explanation":"条件（4）的第一项是“小全不练赛艇”。选A“小全练赛艇”使第一项为假，因此第二项“大刘练水球”为真。再由条件（2）和条件（1）推出小全不练游泳，于是条件（3）中“小全练游泳”为假，“小吴练游泳”为真。","references":[],"evidence":"或者小吴练游泳，或者小全练游泳，二者仅有其一","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a92344a2c1bd915e":{"review":{"definition":"当某指标的年增长率固定为 r 时，每年的增长额以上一年的指标值为基数。若起始值为 X，则 n 年后的指标值为 X×(1+r)^n。","explanation":"本题从2023年起算，用各指标2023年相对2022年的同比增长率作为以后每年的固定增长率，分别以各自2019年数值的2倍为目标。中医药从业人员数的年增长率约为10.15%，高于医院数和实有床位数，且其目标值相对于2023年值所需的倍数也更小，因此先于这两项达标。从50623人起算，第4年仍低于80100人，第5年达到目标。中医医院患者门诊次均费用按约3.89%的年增长率推算，第5年约为468元，仍低于目标559.8元。因此率先达标的是B项。","references":[],"evidence":"按2023年的增长率估算，江苏省中医服务的下列指标率先达到2019年水平2倍的是","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b99424ebd03678ec":{"review":{"definition":"在基期部分量、基期和现期整体量均为正且统计口径一致时，部分增速高于、等于或低于整体增速，现期比重相应上升、持平或下降。","explanation":"现期比重等于基期比重乘以 (1＋部分增速)÷(1＋整体增速)。2023 年我国内燃机产品进口额下降 1.4%，机电产品进口额下降 5.5%，前者降幅较小，商值 0.986÷0.945 大于 1，因此内燃机产品进口额占机电产品进口额的比重上升，C 项可以推出。","references":[],"evidence":"部分增长率a＞整体增长率b时，比重上升。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1f51a5d380065a13":{"review":{"definition":"当各项可以相加且基期量均为正时，合计增长率是各项增长率以各自的基期量占合计基期量的比重为权重所得的加权平均值。","explanation":"各项的增长量等于基期量乘以各自增速，合计增长率等于这些增长量之和除以合计基期量。发电机组和内燃机零部件的出口额增速分别为 5.1% 和 6.7%，中点是 5.9%。两项基期出口额分别约为 52.9÷1.051＝50.33 亿美元和 118.3÷1.067＝110.87 亿美元，因此增速较高的内燃机零部件权重更大，合计增速约为 6.20%，D 项可以推出。","references":[],"evidence":"混合后居中，偏向基期量大的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ca50862d59c3c6c0":{"review":{"definition":"以同一总体为分母，互不重叠的类别占比可以相加。扣除这些类别后，剩余部分中任一类别的占比至多等于剩余部分的占比。","explanation":"第135题以2023年末全国公共图书馆全体从业人员为总体。中级、高级职称人员占比分别为31.2%和13.0%，合计44.2%，剩余人员占55.8%。初级职称人员属于这部分，只有当剩余人员全为初级职称人员时才达到55.8%，因此可推出D项的上限判断。","references":[],"evidence":"中、高级职称从业人员占比=13.0%+31.2%=44.2%","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f6369fc573ef9e16":{"review":{"definition":"原题引文：在司法活动中，应重视发挥司法政策的导向作用和解释功能","explanation":"本题C项可由最高人民法院的类案检索规则说明。检索到适用的指导性案例时应当参照，其他类案可以作为裁判参考，二者的作用不同。解析还用2008年举证时限通知说明解释功能。2019年修订的民事证据规定自2020年5月1日起施行，其第一百条明确此前司法解释与新规定冲突时停止适用。2008年通知各条在修订后的具体适用范围仍需核实。","references":[{"source":"web-50b02cfee6c80894","location":"正文关于类案检索结果如何使用的段落","quote":"人民法院应当参照作出裁判"},{"source":"web-1f43b6e9ac832e58","location":"修订后的《最高人民法院关于民事诉讼证据的若干规定》第一百条","quote":"与本规定不一致的，不再适用"}],"evidence":"在司法活动中，应重视发挥司法政策的导向作用和解释功能","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-0aabf2fdef441b0f":{"review":{"definition":"原题引文：海洋科学实验还有8次未进行，地球物理实验还有16次未进行","explanation":"本题解析把基础地质实验结束时的32次和24次当作海洋科学、地球物理的精确进度，得速率比4∶3。按这个前提，海洋科学完成40次时，地球物理完成30次，还需10次，对应C。若32和24只是已经做完的整次数，第33次和第25次可能正在进行，精确速率比便无法由这两个计数确定。","references":[{"source":"web-1e5012de0960d88c","location":"第56题题干","quote":"且各实验室单次实验时长不变"}],"evidence":"海洋科学实验还有8次未进行，地球物理实验还有16次未进行","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-e41b5822dc3d26df":{"review":{"definition":"直径为d的圆面积是πd²/4，因此两个圆的面积之比等于它们的直径之比的平方。","explanation":"题中从最外侧的1环圆到6环圆，直径递减5次，每次减5毫米，得到6环圆的直径为45.5−5×5＝20.5毫米。6环及以上区域占最大圆的面积比例为(20.5÷45.5)²，约为0.203，对应B。","references":[],"evidence":"直径为45.5+（6-1）×（-5）=20.5mm","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d05b607abd4c3f3f":{"review":{"definition":"将开业后的各期纯利润累计起来，并扣除尚未计入各期纯利润的开业前支出，差额首次大于零时，项目开始累计盈利。","explanation":"按题中纯利润的口径，开业前支出包括3月、4月各1万元租金和11万元装修费，共13万元。5月纯利润为3万元，之后每月按上月的1.1倍计算。截至7月累计9.93万元，截至8月累计13.923万元，首次超过13万元，因此选C。","references":[],"evidence":"3+3.3+3.63+3.993=13.923万元>13万元","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0d91e16e2bae11d5":{"review":{"definition":"车队保持总长度不变时，从车头进入桥梁或隧道到车尾完全离开，车头行驶的距离等于通道长度加车队长度。","explanation":"车头抵达出口时，车尾还需前进一个车队长度。本题引导车的长度忽略不计，过桥用时36秒，车队的45秒中多出的9秒对应车队长度。隧道内车速是桥上车速的75%，走完同一个车队长度需9÷0.75=12秒，因此车队通过隧道需60+12=72秒。","references":[],"evidence":"引导车需36秒，运输车队需45秒","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f465cc5ea9fa9db1":{"review":{"definition":"效率恒定时，工作量等于效率乘以时间。各方同时工作且完成量可以直接相加时，合作效率等于各方效率之和。","explanation":"设两架无人机的每小时效率分别为m、n。合做1小时后尚余三分之二，说明m+n等于总工作量的三分之一。先由M飞2小时、再由N飞5小时完成全部，故2m+5n=3(m+n)，得m=2n。取m=2、n=1，总工作量为9，M单独完成需9÷2=4.5小时。","references":[],"evidence":"两架无人机同时工作1小时后，有三分之二的农田尚未喷洒","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d08ff6657578eeeb":{"review":{"definition":"原题引文：其服务的范围为正方形AEOF的外接圆","explanation":"公开回忆版给出的最大服务半径是50√2米。若允许指定站位，且各人的服务半径均可达到上限，把边长200米的广场分成四个边长100米的小正方形，各派一人站在中心即可全覆盖。由于单个服务圆的直径仅为100√2米，小于广场任意两个角点的距离，每人至多覆盖一个角点，所以至少4人，对应A。若允许所有人随机集中在广场中央附近，角点仍可能无人覆盖，任何有限人数都无法保证全覆盖。","references":[{"source":"web-1e5012de0960d88c","location":"第62题题干","quote":"随机站在一个位置上，其服务半径不超过50√2米"}],"evidence":"其服务的范围为正方形AEOF的外接圆","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-c8b62def3afb5717":{"review":{"definition":"三集合的并集人数等于三个集合人数之和，减去恰好属于两个集合的人数，再减去同时属于三个集合的人数的两倍。","explanation":"分别统计三个集合时，恰属两个集合者多计1次，恰属三个集合者多计2次。本题三项人次合计62，实际至少参观一项的有45−5=40人，多计22人次。至少参观两项的12人各对应一次多计，剩余22−12=10人次来自参观三项者的第二次多计，所以三项都参观的有10人。","references":[],"evidence":"21+22+19-x-2y=45-5","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-90e83d62120705c9":{"review":{"definition":"整数N除以正整数d所得的余数为r，当且仅当0≤r<d，且N−r能被d整除。","explanation":"带余除法可写成N=dq+r。本题货箱总数减3后须能被6整除，原数须能被11整除，减2后须能被13整除。四个选项都满足前两项，只有561减2后得559，恰为13×43，因此选561个。","references":[],"evidence":"货箱总数减3后是6的整数倍，又是11的整数倍，减2后是13的整数倍","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-335321b0fefa406d":{"review":{"definition":"三个互不相同的正整数中，若最大数为x，则三数之和至多为3x−3。其余两数分别为x−1和x−2时取到上界。","explanation":"另外两束各少于最大束，枝数又互不相同，因此至多分别为x−1和x−2。由每8枝余3、每9枝余5可得总数至少为59枝，所以3x−3≥59，得x至少为21。取最小可行总数59枝，分成18、20、21枝即可达到这个下界。","references":[],"evidence":"3束玫瑰花枝数各不相同","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d9f880b35a6045f2":{"review":{"title":"半球的曲面面积","type":"原理与机制","definition":"半径为 r 的半球，其曲面面积是同半径球的球面面积的一半，等于 2πr²。","explanation":"若所求面积包含圆形底面，再加 πr²，总表面积为 3πr²。两题均按 60 cm 为竖直高度、长方体底面与罩口共面计算。若允许将 40 cm 的棱竖直放置，同样的几何模型可得到 0.68π m² 的罩面面积，对应 D。","basis":"据关联原题及所列出处编释。","references":[{"source":"geof","location":"附录 C · Sphere，曲面取一半"}],"related":["k-6f0505868fc927aa","k-aea49d91fefa42d5","k-d73cb19a60baeb11"],"examFocus":{"江苏 2025 B类 行测#67":"根据器物的尺寸确定半球罩的最小半径，再辨明所求面积的范围。","江苏 2025 C类 行测#65":"根据器物的尺寸确定半球罩的最小半径，再辨明所求面积的范围。"}},"aspects":[{"title":"固定摆放时半球罩的最小曲面面积","uses":[{"unit":"Q1","role":"解题依据","use":"按解析取 60 cm 为高度，以 60 cm×40 cm 底面的中心为球心。由勾股定理得最小半径的平方为 4900 cm²。保护罩只计曲面，面积为 0.98π m²，对应 C。","evidence":"本题所求保护罩的表面积不包含底面。","qids":["江苏 2025 B类 行测#67"]},{"unit":"Q2","role":"解题依据","use":"同题复用上述计算。该卷解析也将青铜器的竖直高度固定为 60 cm，按此条件求得最小罩面面积，对应 C。","evidence":"即不能以40cm为高算最值","qids":["江苏 2025 C类 行测#65"]}]}]},"k-bc15b4268ad1fcac":{"review":{"definition":"沿一条线段植树且两端各有一棵树时，相邻两树形成的间隔数比树的棵数少1。","explanation":"从起点的树开始，每新增一棵树就增加一个间隔。本题与围墙平行的外侧边两端都有树，若该边有k棵树，边长最多为4(k−1)米。两条垂直边还各有一个从最东边的树到围墙的间隔，所以每条垂直边若有x棵树，边长最多为4x米。统计三边总棵数时，外侧两棵角树各被计入两条边，要各扣一次。","references":[],"evidence":"远离围墙的两个角上都植树","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7b9c4966a47e8c05":{"review":{"definition":"开口向下的二次函数在顶点取最大值。用于有约束的实际问题时，须检查顶点对应的取值是否满足约束。","explanation":"设两条垂直于围墙的边各有x棵树。扣除两棵角树的重复计数后，外侧平行边有65−2x棵树。各间隔取4米时，面积为4x×4(64−2x)=8192−32(x−16)²。顶点对应的x=16是可行整数，此时外侧平行边有33棵树，两条相邻边长分别为64米、128米，最大面积为8192平方米。","references":[],"evidence":"与围墙相平行的边植树63-2x+2=（65-2x）棵","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-21fbd4a964af00cb":{"review":{"definition":"条件命题“若P，则Q”与其逆否命题“若非Q，则非P”等价。因为只要P成立，Q就必须成立，所以Q不成立时，P也不成立。","explanation":"题干的“只有为了人民的现代化，才有意义”把“为了人民”设为“现代化有意义”的必要条件。否定这一必要条件，即可推出“没有意义”，对应A项。C项涉及两个条件的合取，未能充分调动积极性时，只能推出“一切为了人民”与“一切依靠人民”中至少一项未坚持，无法单独否定前一项。","references":[],"evidence":"只有为了人民的现代化，才有意义","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ab9d38d697b4d040":{"review":{"definition":"原题引文：海草床是最高效的碳捕获和碳封存系统之一","explanation":"海草床可积累自身产生的有机物，也能截留外来颗粒物。题干以固碳价值和退化趋势作为修复依据。A补充了气候变暖加剧这一背景，解释了为什么保护固碳功能具有紧迫性。B所述光合作用补充了固碳机制，但主要是在解释题干已有的固碳价值。题干所称“比森林高90倍”缺少可核实的比较口径。","references":[{"source":"web-d397b14009176341","location":"固碳本领高超","quote":"其贮存碳的效率比森林高出90倍"},{"source":"web-09efa2f906850049","location":"第1节，引言","quote":"centuries or even millennia in some species"},{"source":"web-fe993aa36bd0b61c","location":"讨论，图3b相关段落","quote":"approximately six to eight times higher than that of terrestrial forest soils"}],"evidence":"海草床是最高效的碳捕获和碳封存系统之一","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-f1a3cef49bf083e6":{"review":{"definition":"如果A成立就能推出B成立，且B成立就能推出C成立，那么A成立就能推出C成立。","explanation":"条件（2）给出“参加读书会→没参加敬老院义工活动”，条件（1）给出“没参加敬老院义工活动→没参加运动会”。以“没参加敬老院义工活动”为中间条件串联即可推出C项。张梅参加了义工活动，条件（1）因此无法确定她是否参加运动会。","references":[],"evidence":"将（1）（2）串联可得","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e81dc80d81cd418b":{"review":{"definition":"如果两个命题至少有一个成立，否定其中一个就能推出另一个成立。两个命题可以同时成立，因此仅凭一个成立无法判定另一个的真假。","explanation":"加入D项“小周是经济学专业的”，由条件（1）的逆否可知小赵不是哲学专业的，再由条件（2）排除这一分支，推出小钱是法医专业的。由条件（4）的逆否可知小孙不是计算机专业的，再由条件（3）排除这一分支，推出小李是计算机专业的。","references":[],"evidence":"根据“否一推一”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-67e25d7dcabb7f0b":{"review":{"definition":"若指标从起点值 P 出发，每年均按同一增长率 r 相对上年增长，则 n 年后的数值为 P×(1+r)ⁿ。比较各指标何时达标，应分别求使预测值达到或超过各自目标的最小整年数。","explanation":"本题以2023年数值为起点，用各指标的2023年同比增长率逐年推算，目标是各自2019年数值的2倍。中医药从业人员数从2022年的45957人增至2023年的50623人，增长率约为10.15%，目标为80100人。用未四舍五入的增长率推算，4年后约74530人，5年后约82097人，因此第5年达标。同法算得中医类医院数、实有床位数和中医医院患者门诊次均费用分别在第43年、第30年和第10年达标，故选B。","references":[],"evidence":"按2023年的增长率估算，江苏省中医服务的下列指标率先达到2019年水平2倍的是","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-797b213bf1ac2fcb":{"review":{"definition":"在统计口径一致、部分的基期量及整体的两期量均为正的条件下，部分占整体的比重上升，当且仅当部分增长率高于整体增长率。","explanation":"现期比重等于基期比重乘以（1＋部分增长率）÷（1＋整体增长率）。题中，M市旅游及相关产业增加值占地区生产总值的比重由3.7%升至4.0%，因此前者的增速高于后者，C项可以推出。本题问的是“不能推出”的选项，答案为B，因为材料没有给出A级景区接待的游客中有多少人次在M市过夜。","references":[],"evidence":"比重为4.0%，比上年提高0.3个百分点。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-11f1ec7cdbac02f0":{"review":{"definition":"年均增长率是使基期值按同一比率逐年复合增长至末期值的年增长率。基期值和末期值均为正时，年均增长率等于末期值与基期值之比的 n 次方根减 1，n 为两期之间的年度间隔数。","explanation":"第129题按2016年至2023年各年的同比增长计算，以2015年为基期、2023年为末期，共8个年度间隔。三项指标的间隔数相同，开同次方根再减1会保持比值的大小顺序。应缴税费的末期值与基期值之比为5.9÷3.9，营业收入为85.7÷45.5，利润总额为4.6÷2.3，三者依次增大，因此 V₃＜V₁＜V₂，选A。","references":[],"evidence":"我国国有企业营业收入、利润总额和应缴税费年均增速","disposition":"独立词条","basis":"据原题和解析编释。","title":"年均增长率","related":[],"examFocus":{"江苏 2024 A类 行测#133":"增长年数相同，比较企业数、用户数和人均年消费额各自的末期量与基期量之比即可判断年均增速的高低。","江苏 2025 B类 行测#129":"核对年均增速所用的基期和末期，再比较营业收入、利润总额和应缴税费各自的末期量与基期量之比。"}},"readings":[{"origin":"k-11f1ec7cdbac02f0","title":"年均增长率","qs":["江苏 2025 B类 行测#129"],"definition":"年均增长率是使基期值按同一比率逐年复合增长至末期值的年增长率。基期值和末期值均为正时，年均增长率等于末期值与基期值之比的 n 次方根减 1，n 为两期之间的年度间隔数。","explanation":"第129题按2016年至2023年各年的同比增长计算，以2015年为基期、2023年为末期，共8个年度间隔。三项指标的间隔数相同，开同次方根再减1会保持比值的大小顺序。应缴税费的末期值与基期值之比为5.9÷3.9，营业收入为85.7÷45.5，利润总额为4.6÷2.3，三者依次增大，因此 V₃＜V₁＜V₂，选A。","evidence":"我国国有企业营业收入、利润总额和应缴税费年均增速","doubt":"","references":[]},{"origin":"k-3a09f60b7757a85b","title":"年均增长率","qs":["国考 2023 行政执法 行测#114"],"definition":"年均增长率是从基期到末期按复合增长折算的等效年度增长率。基期量和末期量均为正时，年均增长率等于（末期量÷基期量）的 1/n 次方减 1，其中 n 为末期与基期相隔的年数。","explanation":"把基期量连续 n 年按同一增长率折算，就得到末期量，因此由首末期量之比开 n 次方可得每年的增长倍数。本题以 2016 年为基期、2021 年为末期，经历 5 个年度增长间隔，n 取 5。","evidence":"（n为年份差）","doubt":"","references":[]},{"origin":"k-ca7cacfa5486b222","title":"年均增长率","qs":["江苏 2024 A类 行测#133"],"definition":"年均增长率是使基期量经过若干年按同一比例复合增长后达到末期量的增长率。基期量和末期量均为正时，将末期量除以基期量，取两期年份差次方根，再减去 1。","explanation":"2019 年到 2022 年相隔 3 年。三个指标都取三次方根再减 1，这两步都保持大小顺序，因此直接比较末期量与基期量之比即可。企业数之比约为 3.29（18700÷5684），用户数之比为 1.88（4.7÷2.5），人均年消费额之比约为 4.20（7450÷1775）。所以用户数年均增速最低，人均年消费额年均增速最高，即 V₂＜V₁＜V₃，符合 B 项。","evidence":"当年\n\n份差相同时，直接比较","doubt":"","references":[]}]},"k-ac3a95a6c705c715":{"review":{"definition":"在同一总体中，若目标类别与各已知类别互斥，且各已知类别之间也互斥，则目标类别的占比至多等于100%减去各已知类别的占比之和。只有剩余成员全部属于目标类别时，才达到这个上限。","explanation":"第135题以2023年末全国公共图书馆从业人员为总体，高级和中级职称人员分别占13.0%和31.2%，合计44.2%。初级职称人员只能来自其余55.8%的从业人员。材料未说明其余人员是否都具有初级职称，因此只能推出初级职称从业人员占比不超过55.8%，对应D项。","references":[],"evidence":"中、高级职称从业人员占比=13.0%+31.2%=44.2%","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e59e53c80833bd3e":{"review":{"definition":"“百姓提案”是水秀社区让居民经常性提出公共问题和建议、由社区逐项回应的参与机制。","explanation":"水秀社区从2017年的“百姓提案大赛”起步，后来把提案变成日常工作。停车紧张、房屋渗水和环卫设施改造都能进入提案渠道。居民提出问题，社区逐项回应，这一做法在本题中同时体现了回应服务需求和依靠居民发现治理问题。","references":[],"evidence":"如今“百姓提案”已经成为水秀社区的常态化机制。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-41d7650e2bf9e3b5":{"review":{"definition":"当居民的参与转化为看得见、用得上的社区改善时，改造成效可以增强居民继续参与治理的意愿。","explanation":"水秀社区的楼道挂钩方便提着东西的居民开门，花坛改造也有居民从家中搬来花草。这些变化让居民切实看到自己的建议和行动可以改善生活环境。本题用这种反馈说明，服务改善能够进一步带动居民参与治理。","references":[],"evidence":"参与治理的积极性大大提高","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e955a9efc46a5909":{"review":{"definition":"“百姓议事点”是单圩村干部和村民协商公共事务的场所，也是通过公开办理、走访回访推动议事结果落实的做法。","explanation":"单圩村公开议事安排、解决方案、办理过程和最终结果，再通过走访询问、电话回访跟踪落实。公开让村民能了解诉求如何处理，回访让村干部能核实问题是否得到回应。这是请示正文中说明单圩村如何把听取民意落实为办理行动的依据。","references":[],"evidence":"办理过程、最终结果全程向村民公开","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-118c544df1d44437":{"review":{"definition":"材料中的兴化智慧稻作，是兴化市与农业高校合作，建立适宜当地的稻作模式，并推广水稻机插缓混一次施肥和绿色防控等技术的实践。","explanation":"宣传稿可用校地共建说明技术从何而来，用兴化钓鱼村核心试验区的产量和品质表现说明技术成效。材料所说的产量领先，比较范围是全国各试验区。","references":[],"evidence":"建立适宜兴化的智慧稻作模式","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-5facd10c57465db7":{"review":{"definition":"在戴窑镇小马哥的案例中，道路和桥梁改善了农资、农机和粮食的运输条件，土地流转使他能够承包较大面积的农田。","explanation":"修路建桥前，播种和收获时往往要靠船运。2018年村里通水泥路、建桥后，小马哥重拾种粮信心，借村里土地流转承包600亩农田，还研究起数字化种植技术。宣传稿可用他的经历说明生产条件改善后，新农人怎样进入规模种植。","references":[],"evidence":"借着村里土地流转的机会，他包下了600亩农田","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-2d8bbc68e8ab0503":{"review":{"definition":"材料中的戴窑稻米产业，以行业协会制定的大米行业标准和质量安全标准引导精深加工，以粮食市场和加工企业集聚衔接原粮生产、稻米加工和贸易。","explanation":"协会制定标准，体现戴窑怎样引导加工企业升级。“米企一条街”则展示生产、加工和贸易环节怎样在当地衔接。两项事实分别支撑宣传稿的标准引领和全产业链发展。","references":[],"evidence":"制定大米行业标准和质量安全标准","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-cdb2446778680ce0":{"review":{"definition":"万家福米业在大米加工旺季通过网络平台临时找车，补充固定合作车辆的运力，用于运入原粮、运出成品米。","explanation":"材料中的旺季从每年11月持续到次年1月。企业销售从长三角向全国拓展后，旺季短期运输需求上升。据企业办公室韦主任介绍，平台找车省时又省钱。这一案例可支撑宣传稿中数字物流如何助力稻米外销的段落。","references":[],"evidence":"除了跟我们厂合作的车辆，我们还通过网络平台找车","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-fe9eb39e10d30307":{"review":{"definition":"网格化管理是将管理辖区按一定标准划分为若干单元网格，以网格为基本单位开展巡查和协调处置的基层治理方式。","explanation":"本题的对应关系是把一个整体划分成若干单元。七巧板由一个正方形切分为七块，网格化管理则把一个辖区划分为多个基层治理单元，因此选A。社区服务外包着眼于由谁提供服务，河湖长制着眼于落实河湖治理保护责任，首问责任制着眼于明确谁负责首次接待和答复。","references":[],"evidence":"将城市管理辖区按照一定的标准划分成为单元网格。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-eb82a615de93c92b":{"review":{"definition":"青藏铁路热棒是用于冷却多年冻土路基的装置。当地上空气比地下土体冷时，热棒把地下的热量传到地上并散入空气。","explanation":"第17题图中，路基两旁的金属管下段埋入地下吸热，上段露出地面散热。热棒降低路基土体的温度，减轻冻土融化造成的路基沉降，因此对应D项“保护冻土层的结构”。","references":[],"evidence":"需要在路基沿线架设热棒。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9c7a70955330edf5":{"review":{"definition":"原题引文：海洋科学实验还有8次未进行，地球物理实验还有16次未进行","explanation":"若基础地质实验结束时，海洋科学和地球物理恰好分别完成32次和24次，两项实验的效率比就是4∶3。海洋科学做完40次时，地球物理恰好做完30次，还需10次，对应C。若“未进行”只数尚未开始的实验，海洋科学也可能正在做第32次，直接用32∶24就无法确定准确的效率比。","references":[{"source":"web-c724397a3a8ab268","location":"第11页，第56题题干","quote":"还有8次未进行"}],"evidence":"海洋科学实验还有8次未进行，地球物理实验还有16次未进行","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-2c381f66037018db":{"review":{"definition":"落点在给定平面区域内均匀分布时，落入目标区域的概率等于目标区域面积除以整个样本区域的面积。","explanation":"按本题采用的均匀落点模型，“未脱靶”将样本区域限定在直径45.5毫米的最外圆内。6.0至6.9环对应的圆环面积为45π平方毫米，所以所求概率为45÷22.75²≈0.087，小于0.1，选A。","references":[],"evidence":"随机向靶纸射击且未脱靶","disposition":"独立词条","basis":"据原题和解析编释。","title":"面积型几何概率","related":[],"examFocus":{"江苏 2025 B类 行测#57":"用相邻环线的直径差确定“6环及以上”的边界，再用目标区域与非零成绩区域的面积比判断概率。","江苏 2025 C类 行测#57":"根据相邻环线的直径确定6至6.9环所对应的圆环，用圆环面积与未脱靶区域的面积比判断概率。"}},"readings":[{"origin":"k-2c381f66037018db","title":"面积型几何概率","qs":["江苏 2025 C类 行测#57"],"definition":"落点在给定平面区域内均匀分布时，落入目标区域的概率等于目标区域面积除以整个样本区域的面积。","explanation":"按本题采用的均匀落点模型，“未脱靶”将样本区域限定在直径45.5毫米的最外圆内。6.0至6.9环对应的圆环面积为45π平方毫米，所以所求概率为45÷22.75²≈0.087，小于0.1，选A。","evidence":"随机向靶纸射击且未脱靶","doubt":"","references":[]},{"origin":"k-f109c85e46305f68","title":"面积型几何概率","qs":["江苏 2025 B类 行测#57"],"definition":"落点在给定平面样本区域内均匀分布时，落在目标区域内的概率等于目标区域面积除以样本区域面积。","explanation":"按题目的均匀随机落点模型，“成绩不为零”把样本区域限定在直径45.5毫米的最大圆内。6环及以上包括6环和所有更靠内的环，目标区域是直径20.5毫米的整个圆。用两圆面积相除得约0.203，落在B项区间。","evidence":"总情况为随机向靶纸射击且未脱靶","doubt":"","references":[]}]},"k-37b000eb9fe3ef85":{"review":{"definition":"三个集合的人数相加时，恰好属于两个集合的人多计一次，属于全部三个集合的人多计两次。扣除这些重复计数，得到至少属于一个集合的人数。","explanation":"三种展览分别有21、22、19人参观，合计62人次。至少参观一种的有45−5=40人，因此重复计数为22人次。至少参观两种的12人都各贡献一次重复计数，余下22−12=10人次来自三种都参观的人，所以三种都参观的有10人。","references":[],"evidence":"至少参观两种的有12人","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-87ad3280ba303147":{"review":{"definition":"工作效率恒定时，工作量等于工作效率乘以工作时间。多方同时作业且各自完成的工作量可以相加时，合计效率等于各方效率之和。","explanation":"设两架无人机每小时的工作量分别为 M、N。先后作业完成整片农田，工作量为2M+5N。合做1小时完成三分之一，所以3(M+N)=2M+5N，得 M=2N。以 N 为1个工作量单位每小时，整片农田的工作量为9个单位，M 单独完成需9÷2=4.5小时。","references":[],"evidence":"两架无人机同时工作1小时后，有三分之二的农田尚未喷洒","disposition":"独立词条","basis":"据原题和解析编释。","title":"工作量、工作效率与时间","related":[],"examFocus":{"江苏 2024 C类 行测#61":"用工作量等于效率乘时间，比较乙独做和甲乙合做的累计工作量与丙完成的剩余工作量。","江苏 2025 C类 行测#61":"用工作量等于效率乘时间，把两机先后喷完整片农田的总工作量与合做一小时的已完成工作量联系起来。"}},"readings":[{"origin":"k-87ad3280ba303147","title":"工作量、工作效率与时间","qs":["江苏 2025 C类 行测#61"],"definition":"工作效率恒定时，工作量等于工作效率乘以工作时间。多方同时作业且各自完成的工作量可以相加时，合计效率等于各方效率之和。","explanation":"设两架无人机每小时的工作量分别为 M、N。先后作业完成整片农田，工作量为2M+5N。合做1小时完成三分之一，所以3(M+N)=2M+5N，得 M=2N。以 N 为1个工作量单位每小时，整片农田的工作量为9个单位，M 单独完成需9÷2=4.5小时。","evidence":"两架无人机同时工作1小时后，有三分之二的农田尚未喷洒","doubt":"","references":[]},{"origin":"k-93f338f228045428","title":"工作量、工作效率与时间","qs":["江苏 2024 C类 行测#61"],"definition":"效率恒定时，工作量等于工作效率乘以工作时间。多人同时工作且各自效率保持不变、完成的工作量可以相加时，合做效率等于各人效率之和。","explanation":"设甲、乙、丙的效率分别为a、b、c。乙单做9天、再与甲合做6天，完成的工作量为9b＋6(a＋b)，占总量的60%。丙10天完成剩下的40%，工作量为10c。两段工作量之比为3∶2，化简得2a＋5b＝5c。只有A项的5∶4∶6满足这个关系。","evidence":"9×乙+6×（甲+乙）=60%×工作总量","doubt":"","references":[]}]},"k-c16c7013ded1b2d2":{"review":{"definition":"算术平均数等于各项数值的总和除以项数。项数固定时，总和越大，平均数越大。","explanation":"本题求七名裁判原始打分的平均数。去掉最高两分和最低两分后，中间三分之和为66÷3=22。最高两分各至多10分，最低两分都不能超过中间三分中的最低分。中间三分的平均值为22÷3，结合0.5分的计分间隔可知其中最低分至多为7分。取10、10、7.5、7.5、7、7、7分可以达到总和上界56分，因此平均数最多为8.0分。","references":[],"evidence":"剩下的3个分数之和乘以难度系数","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e215c10238357d28":{"review":{"definition":"若 k 个互不相同的正整数都不超过整数 x，且 x≥k，则它们的和最多为 x+(x−1)+⋯+(x−k+1)，由最大的 k 个可取整数达到。","explanation":"设按每束9枝可扎 b 束。由总枝数除以8余3、除以9余5，得到9b+2是8的倍数，故 b 除以8余6，总枝数至少为59。若三束中最多的一束只有20枝，三束互异时总数至多为20+19+18=57。59枝可以分成21、20、18枝，所以最多的一束至少有21枝。","references":[],"evidence":"制成数量各不相同的3束玫瑰花","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-59e47933f103f954":{"review":{"definition":"星期每七天循环一次。两个日期相隔的天数除以7，所得余数就是从较早日期向后推算的星期偏移量。","explanation":"“每隔4天”表示两次理疗相差5天。从7月3日起，理疗日期为3、8、13、18、23、28日，分别落在六个不同的星期位置，与这六天均不在同一星期位置的是7月5日。题设这六次包含一次星期日，其余都在工作日，所以7月5日是星期六，7月3日和相隔28天的7月31日都是星期四。另从7月2日开始时，12日和27日分别是星期六和星期日，也符合题意。","references":[],"evidence":"如果他7月3日去，则7月的理疗只有1次在星期日","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4035691e9ca4d448":{"review":{"definition":"在连通的无向带权图中，最小生成树是连接全部顶点且边权总和最小的生成树。包含 n 个顶点的生成树恰有 n−1 条边。","explanation":"本题的线路长度均为正数。若所选线路形成回路，删去回路中的任意一条边仍能连通六栋楼，并可缩短总长度，因此最优方案恰有 5 条边。按长度从小到大选边，每次只加入连接两个尚未连通部分的边。先选 AB（4）和 AC（5），此时再选 BC（6）会形成回路，所以跳过 BC，选 CF（6），再加入 AD（7）和 BE（7）。总长度为（4＋5＋6＋7＋7）×10＝290 米，选 B。","references":[],"evidence":"六栋办公楼，最少需要5条线路即可\n联通。","disposition":"独立词条","basis":"据原题和解析编释。","title":"最小生成树","related":[],"examFocus":{"江苏 2025 A类 行测#70":"用最小生成树比较连通六栋楼的线路总长，注意图上每个长度单位代表10米。","江苏 2025 B类 行测#70":"用最小生成树比较连通六栋楼的线路总长，注意图上每个长度单位代表10米。","江苏 2025 C类 行测#70":"用最小生成树比较连通六栋楼的线路总长，注意图上每个长度单位代表10米。"}},"readings":[{"origin":"k-4035691e9ca4d448","title":"最小生成树","qs":["江苏 2025 C类 行测#70"],"definition":"在连通的无向带权图中，最小生成树是连接全部顶点且边权总和最小的生成树。包含 n 个顶点的生成树恰有 n−1 条边。","explanation":"本题的线路长度均为正数。若所选线路形成回路，删去回路中的任意一条边仍能连通六栋楼，并可缩短总长度，因此最优方案恰有 5 条边。按长度从小到大选边，每次只加入连接两个尚未连通部分的边。先选 AB（4）和 AC（5），此时再选 BC（6）会形成回路，所以跳过 BC，选 CF（6），再加入 AD（7）和 BE（7）。总长度为（4＋5＋6＋7＋7）×10＝290 米，选 B。","evidence":"六栋办公楼，最少需要5条线路即可\n联通。","doubt":"","references":[]},{"origin":"k-e85f398248fcc848","title":"最小生成树","qs":["江苏 2025 A类 行测#70"],"definition":"在连通的加权无向图中，最小生成树是连接全部顶点、没有回路且边权总和最小的树。含有 n 个顶点的生成树恰有 n−1 条边。","explanation":"本题把六栋楼看作顶点，把可铺设的线路看作边，边权为线路长度。线路长度均为正，若铺设方案中有回路，去掉回路中的任一条边仍能保持连通，并可缩短总长度。按边权从小到大选边，每次跳过会形成回路的边。选入 AB 和 AC 后，BC 会形成回路，因此跳过。再选入 CF、BE、AD，共五条边连通六栋楼，总长度为 (4+5+6+7+7)×10＝290 米，对应 B 项。","evidence":"则铺设电缆的总长度最短是","doubt":"","references":[]},{"origin":"k-eda227e3b8a0ec97","title":"最小生成树","qs":["江苏 2025 B类 行测#70"],"definition":"在带权无向连通图中，连接全部顶点且边权之和最小的生成树称为最小生成树。含有 n 个顶点的生成树恰有 n−1 条边。","explanation":"本题各线路长度均为正，若方案中有环，删去环上一条边仍能连通六栋楼，并能缩短电缆总长度，因此最优方案恰选5条边。按边长从小到大选边，每次只选连接两个尚未连通部分的边。选入AB和AC后，BC会形成环，应跳过。再选CF、BE和AD，总长度为（4＋5＋6＋7＋7）×10＝290米，对应B项。","evidence":"选择AB、AC、CF、BE、AD","doubt":"","references":[]}]},"k-2ccdb71abd496d91":{"review":{"definition":"森林通过蒸腾、遮阴和改变地表与大气之间的水热交换，影响气温和空气湿度，从而调节气候。","explanation":"第79题中，森林是发挥调节作用的主体，气候是受其作用的对象，与A项后半组“法制调节社会”的方向一致。B项的“森林—氧气”侧重产生与产物的关系。","references":[],"evidence":"森林会调节气候","disposition":"独立词条","basis":"据原题和解析编释。","title":"森林调节气候","related":[],"examFocus":{"江苏 2025 A类 行测#79":"将候选词代入后，比较两组词之间的关系类型，并检查前后位置所体现的方向是否一致。"}},"readings":[{"origin":"k-2ccdb71abd496d91","title":"森林调节气候","qs":["江苏 2025 C类 行测#79"],"definition":"森林通过蒸腾、遮阴和改变地表与大气之间的水热交换，影响气温和空气湿度，从而调节气候。","explanation":"第79题中，森林是发挥调节作用的主体，气候是受其作用的对象，与A项后半组“法制调节社会”的方向一致。B项的“森林—氧气”侧重产生与产物的关系。","evidence":"森林会调节气候","doubt":"","references":[]},{"origin":"k-7d4b9b04b5e0d93a","title":"森林调节气候","qs":["江苏 2025 A类 行测#79"],"definition":"森林可通过树冠遮阴、植物蒸腾等过程影响局地气温和空气湿度，从而发挥气候调节作用。","explanation":"树冠遮阴能减少到达地面的太阳辐射，植物蒸腾消耗热量并向空气释放水汽。代入A项后，森林是发挥调节作用的一方，气候是受影响的一方，与后半组“法制调节社会”的方向一致。B项的“森林释放氧气”体现的是生成产物的关系。","evidence":"森林会调节气候","doubt":"","references":[]}]},"k-709f120908f9c10b":{"review":{"definition":"法制通过确立和实施法律规范，为社会行为划定边界，并为处理社会关系提供规则。","explanation":"第79题中，法制是发挥规范作用的主体，社会是受其约束或调节的对象，与“森林调节气候”的方向一致。D项前半组是森林包含树木，后半组是家庭属于社会，组成关系的方向相反。","references":[],"evidence":"法制会约束或调节社会","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cc957239a51160c0":{"review":{"definition":"原题引文：若丙班车不在行政楼、教学楼和图书馆停靠，则仅有乙班车在宿舍楼停靠","explanation":"本题共有9次停靠，校门口最少且各点最多2趟，所以校门口1趟，其余各2趟。由此可否定“仅有乙班车在宿舍楼停靠”。若条件（3）的前件是“丙未同时在三处停靠”，逆否可推出丙在三处都停靠，宿舍楼两趟就是甲、乙，对应C。若读作“丙在三处都不停靠”，逆否只推出丙至少在其中一处停靠。例如甲停校门口、行政楼、教学楼，乙停教学楼、图书馆、宿舍楼，丙停行政楼、图书馆、宿舍楼，就满足该读法下的各项条件，宿舍楼停靠的是乙、丙。","references":[{"source":"web-c724397a3a8ab268","location":"第17页，第93题条件（3）","quote":"不在行政楼、教学楼和图书馆停靠"}],"evidence":"若丙班车不在行政楼、教学楼和图书馆停靠，则仅有乙班车在宿舍楼停靠","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-54e18216182a01dd":{"review":{"definition":"原题引文：贮存碳的效率比森林高90倍，碳封存时间可达上千年","explanation":"题干以海草床能长期固碳且正在退化为依据，提出应尽快保护和修复。B项补充了海草光合作用固定无机碳的机制，A项则以气候变暖加剧说明为什么眼下尤其需要保护这类碳汇，因此更直接支持“亟需”。题干的“比森林高90倍”见于《人民日报》科普原文，该文未交代比较指标、森林类型或测算口径。","references":[{"source":"web-1d3e8786314607f4","location":"2024年7月8日，第14版，固碳段","quote":"贮存碳的效率比森林高90倍"},{"source":"web-00b29bb4cb7d015f","location":"第80页，附录“三、海草床的生态系统服务”（2）固碳储碳","quote":"在缺氧、厌氧环境下有机碳分解速率慢"},{"source":"web-7f3aaff2799d272b","location":"Summary，第1点","quote":"It grows for millennia, accumulating organic-rich soils (mats) beneath the meadows."}],"evidence":"贮存碳的效率比森林高90倍，碳封存时间可达上千年","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-904536c49855e5e7":{"review":{"definition":"人类活动排放的二氧化碳、甲烷等温室气体在大气中增加，会增强温室效应。人为温室气体排放是近现代全球变暖的主要驱动因素。","explanation":"第95题A项用“碳化合物”概括相关排放，在该论证中具体指二氧化碳、甲烷等会加剧变暖的温室气体。假定A项为真，变暖加剧就为维持和恢复海草床的固碳功能提供了紧迫性理由。B项只补充海草床怎样固碳，对“亟需”的支持较弱。","references":[],"evidence":"当前全球气候变暖日益加剧，科学家已发现人类生产生活排放的碳化合物是变暖的主要元凶","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1dbdcdd3dcc77073":{"review":{"definition":"虚假或低质量的AI生成内容回流互联网后，如果被纳入后续模型的训练数据，就可能降低训练数据的质量，并影响模型后续输出的可靠性。","explanation":"题干用AI谣言和生成虚假文章的网站快速增长作为论据，专家据此预测AI输出质量会断崖式下降。C项补上了因果链条中缺失的一环：虚假内容可能经由训练数据影响后续输出。D项只进一步说明信息垃圾正在增多。C项说明了输出质量可能下降的机制，下降幅度仍是专家的预测。","references":[],"evidence":"回流互联网，“污染”训练AI模型的数据","disposition":"独立词条","basis":"据原题和解析编释。","title":"AI训练数据污染","related":[],"examFocus":{"江苏 2025 B类 行测#101":"比较各项能否说明AI虚假内容增多与后续输出质量下降之间的联系。"}},"readings":[{"origin":"k-1dbdcdd3dcc77073","title":"AI训练数据污染","qs":["江苏 2025 C类 行测#97"],"definition":"虚假或低质量的AI生成内容回流互联网后，如果被纳入后续模型的训练数据，就可能降低训练数据的质量，并影响模型后续输出的可靠性。","explanation":"题干用AI谣言和生成虚假文章的网站快速增长作为论据，专家据此预测AI输出质量会断崖式下降。C项补上了因果链条中缺失的一环：虚假内容可能经由训练数据影响后续输出。D项只进一步说明信息垃圾正在增多。C项说明了输出质量可能下降的机制，下降幅度仍是专家的预测。","evidence":"回流互联网，“污染”训练AI模型的数据","doubt":"","references":[]},{"origin":"k-e0ecadcfb196062a","title":"AI训练数据污染","qs":["江苏 2025 B类 行测#101"],"definition":"AI生成的虚假或低质量内容回流互联网后，若被纳入后续模型的训练数据，就可能降低训练数据的质量，进而影响模型输出。","explanation":"题干报告了AI谣言和生成虚假文章的网站数量快速增长。C项给出从虚假内容扩散到未来输出质量下降的中间环节，即回流内容进入训练数据。D项只补充了信息垃圾增多的现象。C项使专家的预测更有依据，下降幅度仍是专家的预测。","evidence":"回流互联网，“污染”训练AI模型的数据","doubt":"","references":[]}]},"k-61c3300d8176cfca":{"review":{"definition":"两个部分以同一个非零总量为分母计算比重时，两个部分量之比等于各自的比重之比。已知其中一个部分量和两个比重，就可以求出另一个部分量。","explanation":"江苏 2025 C类行测第111题中，工业增加值和制造业增加值的比重都以2023年我国GDP为分母。两项比重相除时，GDP约去。因此，制造业增加值约为39.9×（26.2%÷31.7%）≈33.0万亿元，对应C项。","references":[],"evidence":"我国工业增加值占GDP比重为31.7%，制造业增加值占GDP比重为26.2%","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2740a51c095433e6":{"review":{"definition":"增长倍数是增长量与基期量的比值。若现期量比基期量增长 n 倍，则现期量是基期量的 n＋1 倍。","explanation":"现期量包含基期量和新增量，所以反推基期量时，应将现期量除以增长倍数加 1。材料给出 2023 年平板玻璃产量为 9.7 亿重量箱，比 1949 年增长 897 倍。将 9.7 亿换算为 97,000 万，再除以 898，得到 1949 年产量约为 108.0 万重量箱，低于 110 万重量箱，因此 A 项能够推出。","references":[{"source":"web-2520694c743f755f","location":"第10页，图表1，2014年和2022年的柱形标注，图源为中国音数协游戏工委","quote":"中国游戏市场实际销售收入及增长率"}],"evidence":"平板玻璃产量9.7亿重量箱，增长897倍","disposition":"独立词条","basis":"据原题和解析编释。","title":"增长倍数","related":[],"examFocus":{"江苏 2024 B类 行测#133":"区分“增长了几倍”和“是原来的几倍”，看应把哪一个量与2014年游戏市场销售收入相比。","江苏 2024 C类 行测#128":"在游戏市场销售收入数据中找出2014年和2022年的数值，用销售收入的增量与2014年的收入相比。","江苏 2025 A类 行测#120":"用现期产量和增长倍数反推1949年平板玻璃产量，统一单位后与题设上限比较。","江苏 2025 C类 行测#115":"反推1949年平板玻璃产量时，区分增长倍数与现期量相对基期量的倍数，再按同一单位核对题设上限。"}},"readings":[{"origin":"k-2740a51c095433e6","title":"增长倍数","qs":["江苏 2025 C类 行测#115"],"definition":"增长倍数是增长量与基期量的比值。若现期量比基期量增长 n 倍，则现期量是基期量的 n＋1 倍。","explanation":"现期量包含基期量和新增量，所以反推基期量时，应将现期量除以增长倍数加 1。材料给出 2023 年平板玻璃产量为 9.7 亿重量箱，比 1949 年增长 897 倍。将 9.7 亿换算为 97,000 万，再除以 898，得到 1949 年产量约为 108.0 万重量箱，低于 110 万重量箱，因此 A 项能够推出。","evidence":"平板玻璃产量9.7亿重量箱，增长897倍","doubt":"","references":[]},{"origin":"k-4b4c8b52e4192e0d","title":"增长倍数","qs":["江苏 2024 B类 行测#133"],"definition":"增长倍数是增长量相当于基期量的倍数，等于（现期量－基期量）÷基期量。现期量是基期量的多少倍，则用现期量直接除以基期量。","explanation":"第133题问2022年我国游戏市场销售收入比2014年增长多少倍，以2014年的1145亿元为基期量。按图中数据计算，（2659－1145）÷1145≈1.32，最接近A项的1.3倍。直接用2659÷1145得到约2.32，表示2022年收入是2014年的约2.32倍，对应干扰项C。原解析写成1.38倍，计算有误，正确选项仍为A。","evidence":"2022年我国游戏市场销售收入比2014年增长：","doubt":"","references":[]},{"origin":"k-7ba9e03de060545e","title":"增长倍数","qs":["江苏 2025 A类 行测#120"],"definition":"增长倍数是增长量除以基期量所得的倍数。某指标比基期增长 n 倍，现期量就是基期量的 n＋1 倍。","explanation":"第120题材料给出，2023年我国平板玻璃产量为9.7亿重量箱，比1949年增长897倍。现期量还包含原有的1倍，因此1949年产量约为97000÷898＝108.0万重量箱，低于110万重量箱，故A项可以推出。","evidence":"平板玻璃产量9.7亿重量箱，增长897倍","doubt":"","references":[]},{"origin":"k-c8a42838be4b872f","title":"增长倍数","qs":["江苏 2024 C类 行测#128"],"definition":"基期量为正时，现期量比基期量增长的倍数等于（现期量－基期量）÷基期量。现期量是基期量的倍数等于现期量÷基期量，比增长倍数多1。","explanation":"第128题以2014年为基期、2022年为现期。所附图片是酱油进出口表。顺网科技年报转载的中国音数协游戏工委图表显示，两年游戏市场实际销售收入分别为1144.81亿元和2658.84亿元，取整后与题解所列的1145亿元和2659亿元一致。按题解数据复算，（2659－1145）÷1145≈1.32，最接近A项的1.3倍。题解中的“增长1.38倍”应改为“增长约1.32倍”。","evidence":"2022年我国游戏市场销售收入比2014年增长","doubt":"","references":[{"source":"web-2520694c743f755f","location":"第10页，图表1，2014年和2022年的柱形标注，图源为中国音数协游戏工委","quote":"中国游戏市场实际销售收入及增长率"}]}]},"k-4e76244fcace718e":{"review":{"definition":"在统计口径一致、部分和整体的基期量及整体的现期量均为正时，部分占整体的比重上升，说明部分增长率高于整体增长率。比重下降则说明部分增长率低于整体增长率。","explanation":"现期比重除以基期比重，等于部分的增长倍数（1＋部分增长率）除以整体的增长倍数（1＋整体增长率）。第120题中，M市旅游及相关产业增加值占地区生产总值的比重由2022年的3.7%升至2023年的4.0%，因此该产业增加值增速高于全市地区生产总值增速，C项可以推出。题目要求选出不能推出的一项，B项所需的A级景区游客中的过夜人次未在材料中给出。","references":[],"evidence":"当比重上升时，部分增长率>整体增长率","disposition":"独立词条","basis":"据原题和解析编释。","title":"两期比重与增长率","related":[],"examFocus":{"江苏 2024 C类 行测#120":"先区分单季出口占比与累计出口占比，再用单季占比的变化判断出口额与进出口总额的环比增速关系。","江苏 2025 C类 行测#120":"比较旅游及相关产业增加值与地区生产总值的增速时可看两期比重，核验游客占比时则需确认分子和分母属于同一统计范围。"}},"readings":[{"origin":"k-4e76244fcace718e","title":"两期比重与增长率","qs":["江苏 2025 C类 行测#120"],"definition":"在统计口径一致、部分和整体的基期量及整体的现期量均为正时，部分占整体的比重上升，说明部分增长率高于整体增长率。比重下降则说明部分增长率低于整体增长率。","explanation":"现期比重除以基期比重，等于部分的增长倍数（1＋部分增长率）除以整体的增长倍数（1＋整体增长率）。第120题中，M市旅游及相关产业增加值占地区生产总值的比重由2022年的3.7%升至2023年的4.0%，因此该产业增加值增速高于全市地区生产总值增速，C项可以推出。题目要求选出不能推出的一项，B项所需的A级景区游客中的过夜人次未在材料中给出。","evidence":"当比重上升时，部分增长率>整体增长率","doubt":"","references":[]},{"origin":"k-d5b1bb8023a919ec","title":"两期比重与增长率","qs":["江苏 2024 C类 行测#120"],"definition":"基期部分量和两期整体量均为正时，部分量与整体量的增长率按同一基期计算。部分量增速高于、等于或低于整体量增速时，部分所占比重分别上升、持平或下降，反过来也成立。","explanation":"现期比重与基期比重之比，等于（1＋部分量增速）除以（1＋整体量增速）。本题以2023年第一季度为环比基期，第二季度出口额占进出口总额的比重上升，说明出口额的环比增速高于进出口总额的环比增速，因此B项成立。","evidence":"当比重上升时，a>b","doubt":"","references":[]}]},"k-263265e6cb58580a":{"review":{"definition":"基期值和末期值均为正、增长期数相同时，末期值与基期值之比越大，年均增速越高。","explanation":"年均增速等于末期值与基期值之比开增长期数次方后减 1。开同次方再减 1 保持比值的大小顺序。本题比较 2016 至 2023 年逐年相对上一年的增长，以 2015 年为基期、2023 年为末期，三项指标均经历 8 个增长期。应缴税费 5.9÷3.9≈1.51，营业收入 85.7÷45.5≈1.88，利润总额 4.6÷2.3＝2.00，因此 V₃＜V₁＜V₂，对应 A 项。","references":[],"evidence":"（n为年份差），当年份差相同时，直接比较","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-26362ad0ed6d17bc":{"sources":[{"id":"5cec7f58a6753672","label":"总论 · 哲学的基本问题","topic":"马克思主义哲学","category":"非时政","text":"二、哲学的基本问题\n哲学的基本问题是思维和存在的关系问题。这个问题包括以下两个方面：\n第一方面：思维和存在何者是本原的问题，即何者是第一性的问题。对这个问题的不同\n回答，是划分唯物主义和唯心主义两大派别的唯一标准。\n唯物主义认为世界的本原是物质，物质第一性；唯心主义认为世界的本原是意识，意识\n第一性。\n第二方面：思维和存在有无同一性的问题，即人的思维能否正确认识存在的问题。根据\n对这个问题的不同回答，可以将哲学划分为可知论和不可知论。\n（粉笔敲黑板：本考点重点在于区分唯物主义与唯心主义，考试极有可能给一段事例、\n讲话或者古语，要求辨析体现的是唯物主义还是唯心主义）","source":{"doc":"3ccc56f4000d1642c2d1","first":1,"last":1,"page":1,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-dacec279a5e3bc0b":{"sources":[{"id":"3112b0a4ec0af017","label":"辩证法 · 两大特征","topic":"马克思主义哲学","category":"非时政","text":"一、两大特征\n1.联系\n（1）含义：联系是指一切事物之间和事物内部各要素之间的相互依赖、相互影响、相\n互制约和相互作用。\n（2）特征：普遍性、客观性、多样性、条件性。\n（粉笔敲黑板：本考点重点要做好对四个特征的区分，常结合案例考查体现或违背联系\n的某个特征）\n（3）整体和部分的关系\n整体对部分起支配、统率、决定的作用。\n部分影响整体，关键部分对整体起决定性作用。\n整体是各个部分的有机结合，整体具有部分所没有的新功能。\n2.发展\n（1）含义：发展是前进的、上升的运动。\n（2）实质：发展的实质是新事物的产生和旧事物的灭亡。\n新旧事物区别的根本标志：是否同事物发展的必然趋势相符合。\n（粉笔敲黑板：判断一个事物是新事物还是旧事 物，并不取决于其形式的新旧与出现\n时间的先后）\n3.联系和发展具有规律性\n规律是客观存在的，是不以人的意志为转移的。","source":{"doc":"3ccc56f4000d1642c2d1","first":2,"last":3,"page":2,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-eca13343966964aa":{"sources":[{"id":"212adcd5dd01c1e7","label":"认识论 · 认识过程的两个阶段","topic":"马克思主义哲学","category":"非时政","text":"二、认识过程的两个阶段\n感性认识和理性认识。感性认识包括感觉、知觉和表象三种形式，是认识的低级阶段。\n理性认识包括概念、判断和推理三种形式，是认识的高级阶段。\n认识的过程是从感性认识到理性认识，再从理性认识到实践的两次飞跃。","source":{"doc":"3ccc56f4000d1642c2d1","first":5,"last":5,"page":5,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-a15abd6c20b30588":{"sources":[{"id":"9e62b2622b12e9cc","label":"历史唯物主义 · 社会的基本矛盾","topic":"马克思主义哲学","category":"非时政","text":"二、社会的基本矛盾\n社会基本矛盾包括两方面，即生产力和生产关系之间的矛盾、经济基础和上层建筑之间\n的矛盾。\n生产力决定生产关系。生产关系反作用于生产力。生产关系对生产力反作用的性质取决\n于生产关系是否适应生产力的状况。\n◎粉笔拓展\n2023 年 9 月，习近平总书记在黑龙江考察调研期间首次提到“新质生产力”。\n新质生产力是创新起主导作用，摆脱传统经济增长方式、生产力发展路径，具有高科技、\n高效能、高质量特征，符合新发展理念的先进生产力质态。它由技术革命性突破、生产要素\n创新性配置、产业深度转型升级而催生，以劳动者、劳动资料、劳动对象及其优化组合的跃\n升为基本内涵，以全要素生产率大幅提升为核心标志，特点是创新，关键在质优，本质是先\n进生产力。\n经济基础决定上层建筑。上层建筑反作用于经济基础，这种反作用集中体现在为自己的\n经济基础服务。\n（粉笔敲黑板：明确社会基本矛盾包括什么，其次做题时注意判断这两方面矛盾贯穿于\n社会发展的始终，并不能进行消除）","source":{"doc":"3ccc56f4000d1642c2d1","first":6,"last":6,"page":6,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-16bb8bc049ced7b6":{"sources":[{"id":"9ec7d9223ff326b6","label":"历史唯物主义 · 社会发展的动力","topic":"马克思主义哲学","category":"非时政","text":"三、社会发展的动力\n社会基本矛盾是社会发展的根本动力；\n阶级斗争是阶级社会发展的直接动力；\n改革是社会发展的重要动力；\n科技革命是推动社会发展的强大杠杆。","source":{"doc":"3ccc56f4000d1642c2d1","first":6,"last":7,"page":6,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-0f6a76a4d981c768":{"sources":[{"id":"9797b4728bd5c89f","label":"商品经济理论 · 价值规律","topic":"马克思主义政治经济学","category":"非时政","text":"四、价值规律\n1.基本内容：价值规律是商品经济的基本规律。它的基本内容是：商品的价值量由生产\n该商品的社会必要劳动时间决定；商品交换以价值量为基础实行等价交换。\n2.表现形式：价格围绕价值上下波动。","source":{"doc":"3ccc56f4000d1642c2d1","first":9,"last":9,"page":9,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-1001a012a16c3b9c":{"sources":[{"id":"76a25bf74326334c","label":"剩余价值理论 · 经济危机","topic":"马克思主义政治经济学","category":"非时政","text":"四、经济危机\n根本原因：资本主义经济危机爆发的根本原因，在于资本主义固有的基本矛盾，即生产\n资料资本主义私人占有和生产社会化之间的矛盾。\n本质特征：生产相对过剩。","source":{"doc":"3ccc56f4000d1642c2d1","first":10,"last":10,"page":10,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-47400b475fbe4398":{"sources":[{"id":"029304ab608f49e2","label":"社会主义的产生和发展 · 空想社会主义的进步性和局限性","topic":"科学社会主义","category":"非时政","text":"一、空想社会主义的进步性和局限性\n19 世纪初期以圣西门、傅立叶、欧文为代表的空想社会主义是科学社会主义的直接思\n想来源。\n1.空想社会主义的进步性：\n（1）在理论上致力于社会制度的分析；\n（2）对资本主义旧制度的批判包含着许多击中要害的见解；\n（3）对社会主义新制度的描绘，闪烁着诸多天才的火花。\n2.空想社会主义的局限性：\n（1）看到了资本主义必然灭亡的命运，却未能揭示资本主义必然灭亡的经济根源；\n（2）要求埋葬资本主义，却看不到埋葬资本主义的力量；\n（3）憧憬取代资本主义的理想社会，却找不到通往理想社会的现实道路。","source":{"doc":"3ccc56f4000d1642c2d1","first":11,"last":11,"page":11,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-c17e3a0ec3665227":{"sources":[{"id":"2ff92042ed2ab285","label":"科学社会主义的基本原则 · 科学社会主义基本原则的主要内容","topic":"科学社会主义","category":"非时政","text":"一、科学社会主义基本原则的主要内容\n1.人类社会发展规律和资本主义基本矛盾是“资本主义必然灭亡、社会主义必然胜利的”\n根本依据。\n2.无产阶级是最先进最革命的阶级，肩负着推翻资本主义旧世界、建立社会主义和共产\n主义新世界的历史使命。\n3.无产阶级革命是无产阶级进行斗争的最高形式，以建立无产阶级专政的国家为目的。\n4.在生产资料公有制基础上组织生产，满足全体社会成员的需要是社会主义生产的根本\n目的。\n5.对社会生产进行有计划的指导和调节，实行等量劳动领取等量产品的按劳分配原则。\n6.社会主义社会要合乎自然规律地改造和利用自然，努力实现人与自然的和谐共生。\n7. 社会主义必须坚持科学理论指导，发展先进文化。\n8.无产阶级政党是无产阶级的先锋队，社会主义事业必须始终坚持无产阶级政党的领导。\n9.通过无产阶级专政和社会主义高度发展，最终实现向消灭阶级、消灭剥削、实现人的\n而自由发展的共产主义社会的过渡。","source":{"doc":"3ccc56f4000d1642c2d1","first":12,"last":12,"page":12,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-160eccd1564c1646":{"sources":[{"id":"6eecb3118a2cd503","label":"逆周期调节","topic":"经济指标与宏观调控","category":"非时政","text":"1.逆周期调节\n逆周期调节，是一种针对经济周期波动进行反向调节的政策手段。从具体思路看，逆周\n期调节主要是针对影响经济趋势的短期负面因素，通过及时采取逆向举措来对冲和消除负面\n影响，进而实现稳定经济目标的调控模式。\n跨周期调节则是立足于系统思维，更加注重经济的长期健康运行和有序增长，强调宏观\n调控应围绕影响周期的长期因素来持续发力。\n——人民日报","source":{"doc":"6cbfb01fe723bba64b75","first":5,"last":5,"page":5,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-1df406177f284636":{"sources":[{"id":"094aafde10da7bfb","label":"扩大内需这个战略基点","topic":"经济指标与宏观调控","category":"非时政","text":"2.扩大内需这个战略基点\n扩大内需是开新局之要，是大国经济发展到特定阶段的必然选择。我国已经成长为世界\n第二大经济体、第一制造业大国，2025 年工业增加值 41.7 万亿元，约为 2000 年的 10 倍、\n1985 年的 120 倍，制造业大国的发展后劲需要强大的国内需求支撑。大国经济优势之一是\n内部可循环，扩大内需的重要意义就在于把大国这一优势充分发挥出来。\n扩大内需是激发超大规模市场潜能的必然要求。我国拥有 14 亿多人口的超大规模市场，","source":{"doc":"6cbfb01fe723bba64b75","first":17,"last":17,"page":17,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-57c333f04147a28f":{"sources":[{"id":"13db55925b136dac","label":"普惠性、基础性、兜底性民生建设","topic":"就业、社保与公共服务","category":"非时政","text":"1.普惠性、基础性、兜底性民生建设\n实现人民对美好生活的向往是中国式现代化的出发点和落脚点。坚持尽力而为、量力而\n行，加强普惠性、基础性、兜底性民生建设，解决好人民群众急难愁盼问题，畅通社会流动\n渠道，提高人民生活品质。\n——《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》\n以普惠性民生建设为发展方向。普惠性，强调保障对象的普遍性。\n以基础性民生建设为主要内容。基础性，强调以人民群众的基本需求为保障内容。\n以兜底性民生建设为基本职责。兜底性，强调政府必须承担民生兜底保障责任。\n普惠性、基础性、兜底性三者有机联系、相互衔接、相辅相成，体现了以人民为中心的\n发展思想，体现了整体和重点、当前和长远、目标和方法的有机统一，是习近平总书记关于\n保障和改善民生的重要论述的重要内容，是在结合我国国情、吸纳人类优秀文明成果基础上\n的重大创新。\n——《求是》杂志文章《加强普惠性、基础性、兜底性民生建设》","source":{"doc":"6cbfb01fe723bba64b75","first":39,"last":40,"page":39,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"},{"id":"1edd4269071575b8","label":"普惠性、基础性、兜底性民生建设","topic":"就业、社保与公共服务","category":"非时政","text":"3.普惠性、基础性、兜底性民生建设\n“普惠性、基础性、兜底性民生建设”是当前我国保障和改善民生的核心工作思路，\n强调以人民为中心，解决好群众最关心最直接最现实的利益问题。\n普惠性，强调保障对象的普遍性。习近平总书记强调，中国式现代化是全体人民共同\n富裕的现代化；让广大人民群众共享改革发展成果，是社会主义的本质要求，是社会主义\n制度优越性的集中体现，是我们党坚持全心全意为人民服务根本宗旨的重要体现。\n基础性，强调以人民群众的基本需求为保障内容。涵盖教育、医疗、养老、就业、住\n房等领域。习近平总书记强调，健全基本公共服务体系，提高公共服务水平，增强均衡性\n和可及性；在幼有所育、学有所教、劳有所得、病有所医、老有所养、住有所居、弱有所\n扶上持续用力。\n兜底性，强调政府必须承担民生兜底保障责任。习近平总书记指出，社会政策要托底，\n就是要守住民生底线；对各类困难群众，我们要格外关注、格外关爱、格外关心，时刻把\n他们的安危冷暖放在心上，关心他们的疾苦，千方百计帮助他们排忧解难。","source":{"doc":"41195a191a57c1c36332","first":22,"last":22,"page":22,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-ca4cde0e591f10d3":{"sources":[{"id":"592c6e8da8879b01","label":"加快推动全面绿色转型","topic":"生态环境与能源","category":"非时政","text":"1.加快推动全面绿色转型\n绿色发展是中国式现代化的鲜明底色。牢固树立和践行绿水青山就是金山银山的理念，\n以碳达峰碳中和为牵引，协同推进降碳、减污、扩绿、增长，筑牢生态安全屏障，增强绿色\n发展动能。\n——《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》","source":{"doc":"6cbfb01fe723bba64b75","first":46,"last":46,"page":46,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-d0cc70f593898731":{"sources":[{"id":"c16f4ec02a3b3033","label":"“让人民来监督政府”和“自我革命”","topic":"党政制度与理论","category":"非时政","text":"3.“让人民来监督政府”和“自我革命”\n1945 年 7 月，在延安一孔窑洞里，面对黄炎培提出的如何跳出“其兴也勃焉，其\n亡也忽焉”的历史周期率的问题，毛泽东同志给出第一个答案：“让人民来监督政\n府”。以习近平同志为核心的党中央在新时代全面从严治党伟大实践中给出第二个答\n案：自我革命。\n习近平总书记强调，一百年来，党外靠发展人民民主、接受人民监督，内靠全面\n从严治党、推进自我革命，勇于坚持真理、修正错误，勇于刀刃向内、刮骨疗毒，保\n证了党长盛不衰、不断发展壮大，这一重要论述深刻揭示了跳出历史周期率两个答案\n的相互关系。自我监督和人民监督相辅相成、相互促进，体现了内因和外因关系的深\n刻辩证法，两者都源于党的初心使命。\n——《中央纪委国家监委网站》","source":{"doc":"41195a191a57c1c36332","first":7,"last":7,"page":7,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]}}};
